  Event_116431_Name = {
    Text = "랜덤 이벤트 2"
  },
  Event_117279_ChoiceDesc1 = {
    Text = "【한때 갈망했던 순수함】 「(Skill.Arg1)」 3장을 덱에 추가."
  },
  Event_117279_Desc = {
    Text = "\n수평선 위로 연한 흰 안개가 올라와 만물을 흐릿한 상태로 감싸고 있습니다.\n삶과 죽음의 경계를 넘어, 문 안팎의 거리를 넘어, 오랫동안 색이 바랜 기억을 넘어서, 당신은 양산을 쓴 숙녀의 역광에서의 모습을 봅니다.\n그녀와 함께한 시간은 이미 사라졌고, 마치 그녀의 얇지만 찬란한 청춘처럼.\n가짜의 일륜이 떠오르기를 기다리며, 연무가 보이지 않게 부서지고, 그녀의 측면도 꿈에서 흔들리며 가벼운 환영의 거품으로 변해 당신에게 무성의 작별 인사를 전합니다."
  },
  Event_117279_Name = {
    Text = "머피의 환영"
  },
  Event_117280_ChoiceDesc1 = {
    Text = "【한때 갈망했던 순진함】 카드 2장을 선택하여 「심해의 반향」 각인을 부여."
  },
  Event_117280_Desc = {
    Text = "\n수평선 위로 연한 흰 안개가 올라와 만물을 흐릿한 상태로 감싸고 있습니다.\n삶과 죽음의 경계를 넘어, 문 안팎의 거리를 넘어, 오랫동안 색이 바랜 기억을 넘어서, 당신은 양산을 쓴 숙녀의 역광에서의 모습을 봅니다.\n그녀와 함께한 시간은 이미 사라졌고, 마치 그녀의 얇지만 찬란한 청춘처럼.\n가짜의 일륜이 떠오르기를 기다리며, 연무가 보이지 않게 부서지고, 그녀의 측면도 꿈에서 흔들리며 가벼운 환영의 거품으로 변해 당신에게 무성의 작별 인사를 전합니다."
  },
  Event_117280_Name = {
    Text = "머피의 환영"
  },
  Event_118414_ChoiceDesc1 = {
    Text = "【세 점】"
  },
  Event_118414_ChoiceDesc2 = {
    Text = "【여섯 시】"
  },
  Event_118414_ChoiceDesc3 = {
    Text = "【한 점】"
  },
  Event_118414_Desc = {
    Text = "주사위가 굴러가며 데구르르 소리를 낸다.\n언제 멈출까?\n알 수 없지만, 답을 내놓아야 한다."
  },
  Event_118414_Name = {
    Text = "운명의 도박"
  },
  Event_118415_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118415_Desc = {
    Text = "당신의 응답에 「하늘」은 더욱 부드러워졌다.\n그것은 가볍게 당신의 이마에 입맞춤을 내렸다.\n그리고, 당신의 이마에서 물보라 한 송이가 피어났다."
  },
  Event_118415_Name = {
    Text = "바다의 포옹"
  },
  Event_118416_ChoiceDesc1 = {
    Text = "[환상에 빠지다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_118416_ChoiceDesc2 = {
    Text = "[합주]광기치가 50 이상인 깨어남체마다 15 검은 인장을 획득합니다"
  },
  Event_118416_ChoiceDesc3 = {
    Text = "[강제 퇴장]3개 중에서 1개의 각인을 획득"
  },
  Event_118416_Desc = {
    Text = "아마도 오랜 전투가 당신을 몽롱하게 만든 것일 수도 있고, 단지 당신의 뇌가 몸을 배신한 것일 수도 있습니다.\n어떤 무중력감이 당신의 머릿속에 나타납니다.\n순간, 당신의 머릿속이 갑자기 만회경으로 변하며, 찬란하고, 화려하며, 오색찬란한 빛이 반짝입니다.\n셀 수 없는 영감, 미혹, 광상이 뇌 속으로 밀려들어, 당신 뇌의 구석구석을 차지합니다.\n이대로 계속되면, 당신의 머리는 곧 이 뒤죽박죽인 것들로 터져버릴 것입니다."
  },
  Event_118416_Name = {
    Text = "사고 만회경"
  },
  Event_118417_ChoiceDesc1 = {
    Text = "[도박에 참여]\"(Skill.Arg1)\" 감염, 도박에 참여하기"
  },
  Event_118417_ChoiceDesc2 = {
    Text = "[아니면]25 검은 인장을 획득"
  },
  Event_118417_Desc = {
    Text = "한순간의 아찔함 속에서, 당신의 의식은 겹겹이 쌓인 안개를 뚫고 미지의 공간으로 흩어졌다.\n두 개의 주사위가 당신 앞에 던져졌지만, 당신을 강제로 이곳에 데려온 미지의 존재는 여전히 모습을 드러내지 않았다.\n사방에서 들려오는 그 존재의 혼돈스러운 목소리만 들을 수 있었다.\n「돌아가고 싶나? 그럼 한 판 하지.」\n「네 생명을 판돈으로, 운명과 한 번 겨뤄봐.」"
  },
  Event_118417_Name = {
    Text = "운명의 도박"
  },
  Event_118418_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118418_Desc = {
    Text = "초탈의 경험은 언제나 짧다. 소리 없이 찾아왔다가 갑자기 사라진다.\n하지만 적어도 당신의 머리는 아직 여기 있고, 진짜로 폭발하지는 않았다."
  },
  Event_118418_Name = {
    Text = "사고 만회경"
  },
  Event_118419_ChoiceDesc1 = {
    Text = "[떠나기]획득 백은 유물 “(RelicConfig.Arg1)”"
  },
  Event_118419_Desc = {
    Text = "당신은 지지 않았지만, 이기지도 못했다. 결과는 좋지도 나쁘지도 않다.\n「무승부……」\n미지의 존재가 한숨을 내쉬었지만, 그 목소리에서 아쉬움은 느껴지지 않았다.\n「꽤 재미있는 놀이였군.」"
  },
  Event_118419_Name = {
    Text = "운명의 도박"
  },
  Event_118420_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118420_Desc = {
    Text = "점차, 그 광란의 음률이 네 귀에 조화롭고 성스럽게 들리기 시작했다.\n너는 마침내 깨달았다. 왜 그것이 「완벽한 성가」라 불리는지를.\n그것은 진정으로 「완벽무결」하기 때문이다."
  },
  Event_118420_Name = {
    Text = "「완벽한」 성가"
  },
  Event_118421_ChoiceDesc1 = {
    Text = "[뇌를 감지]3장의 명령 카드 중 1장을 선택하여 각인 획득:「(EnchantConfig.Arg1)」"
  },
  Event_118421_ChoiceDesc2 = {
    Text = "[영혼 감지]감염「(Skill.Arg1)」, 재각인, 최대 2회 수행"
  },
  Event_118421_Desc = {
    Text = "인간의 첫 번째 감옥은 자신의 육체이다.\n이 육체라는 감옥 안에서, 뇌는 마지막이자 가장 중요한 감옥이다.\n「자기야, 네가 살아 있고, 아직 숨을 쉬고 있으면 안전하다고 생각하니?」\n네 뇌가 네 영혼을 배신할 때, 너는 세상에서 가장 고통스러운 고문을 겪게 될 것이다.\n그리고 그 고문은 평생 너를 따라다닐 것이다."
  },
  Event_118421_Name = {
    Text = "뇌의 감옥"
  },
  Event_118422_ChoiceDesc1 = {
    Text = "[나비를 만지다]2개의 카드 삭제"
  },
  Event_118422_ChoiceDesc2 = {
    Text = "【계속 읽기】저주받은 유물「(RelicConfig.Arg1)」을 획득하고, 「(Skill.Arg2)」에 감염됩니다"
  },
  Event_118422_ChoiceDesc3 = {
    Text = "[떠나다]Arg1 검은 인장 획득"
  },
  Event_118422_Desc = {
    Text = "심해에는 나비가 없다. 방 안에 갇힌 소녀가 이 생명들을 상상해낸 것이다.\n그것들은 너무나 아름답고, 공중에서 자유롭게 날아다닌다.\n「만약……만약 나도 그들처럼, 여기서 날아갈 수 있다면 좋을 텐데……」\n한 마리 나비가 흐느끼는 소리를 냈지만, 그 소리는 무수한 날갯짓 소리에 묻히고, 딸깍거리는 타자기 소리에 묻혀, 거의 들리지 않았다."
  },
  Event_118422_Name = {
    Text = "나비처럼 날아오르는 영혼"
  },
  Event_118423_ChoiceDesc1 = {
    Text = "【그들을】감염「(Skill.Arg1)」, 저주된 유물「(RelicConfig.Arg2)」를 획득합니다"
  },
  Event_118423_ChoiceDesc2 = {
    Text = "【그들을 쫓아내기】두 번 감염「(Skill.Arg1)」하고, 은색 유물「(RelicConfig.Arg2)」와「(RelicConfig.Arg3)」획득"
  },
  Event_118423_ChoiceDesc3 = {
    Text = "【그들을 공격하기】은색 유물「(RelicConfig.Arg1)」를 획득"
  },
  Event_118423_Desc = {
    Text = "「누군가는 말했지, 끝없는 욕망이야말로 사람을 전진하게 하는 원동력이라고.」\n「하지만 그 욕망이 무시할 수도, 끊어낼 수도 없을 만큼 강해졌을 때, 나는 자신에게서 비롯된 이 욕망이 나를 가두는 감옥이 되었음을 느낄 뿐이었어.」\n어둠 속에서 기력 없는 목소리가 들려왔다. 상대의 얼굴은 보이지 않고, 묶인 두 손만이 보일 뿐이었다.\n「이 욕망들은 나의 공포, 비겁함, 희망, 고통을 먹고 자라며, 다시 나의 욕망을 키워냈어.」\n그 기력 없는 목소리가 마지막 애원을 내뱉었다.\n「나는 모든 것을 바칠 의향이 있어! 착한 사람이여, 나를 구해줘… 아니면 해방을 내려줘…」"
  },
  Event_118423_Name = {
    Text = "속박의 욕망"
  },
  Event_118424_ChoiceDesc1 = {
    Text = "[뇌를 감지]3장의 명령 카드 중 1장을 선택하여 각인 획득:「(EnchantConfig.Arg1)」"
  },
  Event_118424_Desc = {
    Text = "당신은 자신의 뇌수가 한 번 경련한 것을 느꼈다.\n「이것에 무슨 특별한 의미가 있을까?」\n당신은 스스로에게 물었지만, 뇌는 침묵으로 일관했다.\n자신에 대한 모든 질문이 답을 얻을 수 있는 것은 아니다."
  },
  Event_118424_Name = {
    Text = "뇌의 감옥"
  },
  Event_118425_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118425_Desc = {
    Text = "당신은 힘차게 수영하여 마침내 수면 위로 뛰어올랐다.\n바다 냄새가 섞인 공기가 당신의 폐에 쏟아져 들어오고, 당신은 위험에서 진정으로 벗어나지 못했음을 상기시킨다.\n하지만 당신은 진정한 하늘이 당신의 머리 위에 있다는 것을 안다.\n진실타래처럼, 결코 부드러운 거짓말로 가릴 수 없는 것이다."
  },
  Event_118425_Name = {
    Text = "바다의 포옹"
  },
  Event_118426_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118426_Desc = {
    Text = "당신이 그 욕망의 밧줄을 만지는 순간, 영혼 깊은 곳에서 찌르는 듯한 통증이 밀려왔다.\n당신의 공포, 비겁함, 희망, 고통이 모두 몸에서 쏟아져 나와, 피로 물든 밧줄로 변해 당신의 두 손을 묶었다.\n그때, 악의에 찬 환호를 담은 그 목소리가 들려왔다.\n「친절한 분이여, 보답을 받게 될 거야……물론, 저주도 함께.」"
  },
  Event_118426_Name = {
    Text = "속박의 욕망"
  },
  Event_118427_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118427_Desc = {
    Text = "당신의 손길에 나비들이 떨었다.\n태어난 이래로, 그들은 이렇게 부드러운 대우를 받아본 적이 없었다.\n나비들은 어찌할 바를 모르는 감정에 사로잡혀, 날아오르는 것조차 잊었다.\n그리하여, 셀 수 없이 많은 나비가 떨어지며, 무수한 날개에 가려져 있던 타자기가 드러났다.\n이미 생명을 잃은 그 가련한 것이, 마지막 힘을 다해 「자유」라는 두 글자를 쳤다."
  },
  Event_118427_Name = {
    Text = "나비처럼 날아오르는 영혼"
  },
  Event_118428_ChoiceDesc1 = {
    Text = "[전투 준비]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_118428_ChoiceDesc2 = {
    Text = "[출성 문의]25개의 검은 인장 획득"
  },
  Event_118428_Desc = {
    Text = "별빛이 드리우는 심해 속에서, 답해자들은 수천 년의 세월을 잠복해왔다.\n무한한 바닷물은 그들의 광기를 목격했고, 그들의 인내를 목격했으며, 신에 대한 가장 경건한 신앙도 목격했다.\n아무도 신의 위대한 강림을 막을 수 없다.\n방해하는 자는 모두 답해자의 분노 속에서 잿더미로 변할 것이다."
  },
  Event_118428_Name = {
    Text = "별빛 아래의 기다림"
  },
  Event_118429_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118429_Desc = {
    Text = "당신은 무의식적으로 귀를 막았습니다.\n불가사의하게도, 영혼 깊은 곳에서 들려오던 선율이 사라졌습니다.\n물론, 일시적일 뿐입니다."
  },
  Event_118429_Name = {
    Text = "모독의 선율"
  },
  Event_118430_ChoiceDesc1 = {
    Text = "[과거 회상]3개 중 1개 고급 각인 선택하여 획득"
  },
  Event_118430_ChoiceDesc2 = {
    Text = "【벨 소리 무시】황금 유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_118430_ChoiceDesc3 = {
    Text = "[떠나다]50 검은 인장을 획득"
  },
  Event_118430_Desc = {
    Text = "세상에 영원히 변하지 않는 것은 없다.\n신모가 만든 낙원이라 해도 마찬가지다.\n짧은 찰나, 당신은 시공 균열 속에서 무언가를 엿보았다.\n과거, 현재, 미래가 균열로 가득한 틈새 속에서 뒤얽히며 끊임없이 변화하고 있었다.\n당신의 호기심 어린 엿봄을 기다리며."
  },
  Event_118430_Name = {
    Text = "시공 균열"
  },
  Event_118431_ChoiceDesc1 = {
    Text = "[획득 100개의 검은 인장]"
  },
  Event_118431_ChoiceDesc2 = {
    Text = "[무작위 2장의 커맨드 카드가 각인 획득: \"(EnchantConfig.Arg1)\"]"
  },
  Event_118431_Desc = {
    Text = "무형의 의지는 너의 선택을 받아들이지 않는다. 그것은 너에게 한 번 더 기회를 주어, 변화를 이끌어내려 한다——\n조심하라, 음악이 무형이라 해도 생명을 거둘 수 있다."
  },
  Event_118431_Name = {
    Text = "「완벽한」 성가"
  },
  Event_118432_ChoiceDesc1 = {
    Text = "[반박하기]백은 유물「(RelicConfig.Arg1)」을 획득하고, 1번 증상을 선택하여 감염합니다"
  },
  Event_118432_ChoiceDesc2 = {
    Text = "[쥐를 쫓아내기]3장의 명령 카드 중 1장을 선택하여 각인:「(EnchantConfig.Arg1)」을 획득하고, 「(Skill.Arg2)」에 감염됩니다"
  },
  Event_118432_ChoiceDesc3 = {
    Text = "[새로운 의견 제시]25 검은 인장 획득"
  },
  Event_118432_Desc = {
    Text = "이 배 위의 모든 것은 윤회하고 있다.\n배 위에서 살아가는, 혐오스럽고 더러운 솜털로 뒤덮인 작은 것들도 자연히 이런 운명을 피할 수 없었다.\n한 번 또 한 번의 윤회 속에서, 그것들은 눈에 보이는 모든 것을 먹어치웠지만, 여전히 만족할 수 없었다.\n「배……고파……」\n쥐떼가 병적이고 귀를 찢는 듯한 비명을 질렀다.\n거듭되는 윤회가 그것들을 참을 수 없이 굶주리게 만들었고, 무언가를 먹어야만 했다.\n당장, 지금 즉시!"
  },
  Event_118432_Name = {
    Text = "굶주린 쥐떼"
  },
  Event_118433_ChoiceDesc1 = {
    Text = "【직시 눈】황금 유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_118433_ChoiceDesc2 = {
    Text = "【저항 포기】무작위로 2명의 깨어남체를 깨어남시키고, (Skill.Arg1)로 두 번 감염시킵니다"
  },
  Event_118433_ChoiceDesc3 = {
    Text = "[떠나다]50 검은 인장을 획득"
  },
  Event_118433_Desc = {
    Text = "하늘의 별들과 마찬가지로, 심해에도 당연히 많은 눈이 있습니다.\n그 눈들은 해저에 사는 물고기에게서, 모독의 아가미류에게서, 그리고 바다 그 자체에게서 옵니다.\n쉿, 그들을 놀라게 하지 마세요.\n놀라게 하지 마세요, 심해의 광기를."
  },
  Event_118433_Name = {
    Text = "심해의 눈"
  },
  Event_118434_ChoiceDesc1 = {
    Text = "[속삭임을 무시한다]"
  },
  Event_118434_ChoiceDesc2 = {
    Text = "[속삭임에 귀를 기울인다]"
  },
  Event_118434_ChoiceDesc3 = {
    Text = "[역선전을 한다]"
  },
  Event_118434_Desc = {
    Text = "「신명의 은총을 갈망하는가? 자신의 존재 의미를 알고 싶은가?」\n한 줄기 탄식이 귀 옆에서 울려 퍼졌다. 마치 정신병 환자의 자기 중얼거림 같기도 하고, 무형의 존재가 속삭이는 것 같기도 했다.\n이성과 경계심 속에서, 당신은 거절의 말을 내뱉었지만, 그 목소리는 여전히 혼잣말을 이어갔다.\n「인내심을 갖고 들어보시오. 당신이 알게 될 것은, 세계의 운명에 관한 진실타래이니……」"
  },
  Event_118434_Name = {
    Text = "무형자의 설교"
  },
  Event_118435_ChoiceDesc1 = {
    Text = "[뇌를 감지]3장의 명령 카드 중 1장을 선택하여 각인 획득:「(EnchantConfig.Arg1)」"
  },
  Event_118435_ChoiceDesc2 = {
    Text = "[영혼을 감지]\"(Skill.Arg1)\" 감염, 다시 무작위로 각인"
  },
  Event_118435_Desc = {
    Text = "두개골 안에 안전하게 보호된 뇌가 당신에게 어떤 정보를 전달했다.\n이 정보가 신경전달물질의 변환과 생체전류의 전달 과정에서 손상되었는지는 알 수 없다.\n유일하게 확실타래한 사실타래은, 당신이 이 정보를 수신했으며, 육체의 객관적 존재 속에서 자신의 생존을 감지했다는 것이다."
  },
  Event_118435_Name = {
    Text = "뇌의 감옥"
  },
  Event_118436_ChoiceDesc1 = {
    Text = "[떠나다]50 검은 인장을 획득"
  },
  Event_118436_Desc = {
    Text = "「나쁘지 않은 답이야. 하지만 아쉽게도, 정답은 아니지.」\n「그럼 정답이 뭔데?」\n미지의 존재는 당신의 질문에 답하지 않고, 비웃음만 흘렸다.\n「누가 운명에 정답이 있다고 했어?」"
  },
  Event_118436_Name = {
    Text = "운명의 도박"
  },
  Event_118437_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118437_Desc = {
    Text = "「내가 그것들을 잘라내려 시도하지 않았을 것 같나? 아니, 욕망에 저항할수록 그것들은 더욱 강해질 뿐이야!」\n욕망이 변한 밧줄이 점점 더 조여오며, 심지어 살 속으로 파고드는 것을 느끼며, 그 목소리는 절망적인 광기의 외침을 내뱉었다.\n「나는 영원히 그것들에서 벗어날 수 없어……영원히!」"
  },
  Event_118437_Name = {
    Text = "속박의 욕망"
  },
  Event_118438_ChoiceDesc1 = {
    Text = "[까마귀를 누르기]25개의 검은 인장 획득, 감염“(Skill.Arg2)”, 계속 선택"
  },
  Event_118438_ChoiceDesc2 = {
    Text = "【무시하고】떠나다"
  },
  Event_118438_Desc = {
    Text = "칠흑의 까마귀가 울고 있다.\n칠흑의 까마귀가 부르짖고 있다.\n칠흑의 까마귀가 미친 듯이 울부짖고 있다.\n그러나 사람들에게는 그저 노래하는 것으로 들릴 뿐이다.\n「아, 얼마나 근심 없는 노랫소리인가. 나도 까마귀가 되어 세상의 번뇌에서 벗어나고 싶구나.」"
  },
  Event_118438_Name = {
    Text = "감지되지 않는 원탄"
  },
  Event_118439_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118439_Desc = {
    Text = "나비들이 흩어지고, 당신은 마침내 아래에 있는 타자기를 또렷이 볼 수 있었다.\n이미 생명을 잃은 그 가련한 것이, 마지막 힘을 다해 「떠나다」라는 두 글자를 쳤다."
  },
  Event_118439_Name = {
    Text = "나비처럼 날아오르는 영혼"
  },
  Event_118440_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118440_Desc = {
    Text = "과거의 영상 속에서, 모피 코트를 걸친 소녀가 당신을 향해 손을 흔들었다.\n그녀가 무슨 말을 했는지 들리지 않았지만, 당신은 소녀의 미소를 보았다."
  },
  Event_118440_Name = {
    Text = "시공 균열"
  },
  Event_118441_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118441_Desc = {
    Text = "심해는 다시 칠흑과 적막으로 돌아왔다.\n이 칠흑과 적막 속에서, 당신은 다시 심장 박동 소리를 들었다.\n그 소리는 당신의 체내에서 나왔다.\n다른 이들의 눈에, 당신도 칠흑 같은 심해를 유영하는 뛰는 심장에 불과하다."
  },
  Event_118441_Name = {
    Text = "약육강식"
  },
  Event_118442_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118442_Desc = {
    Text = "이번에 잿더미로 변한 것은 방해자가 아니라 답해자였다.\n별들은 이 광경을 소리 없이 내려다보았다. 지난 수천 년 그래왔듯이, 침묵을 지키며."
  },
  Event_118442_Name = {
    Text = "별빛 아래의 기다림"
  },
  Event_118443_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118443_Desc = {
    Text = "수적 우위를 점하고 있음에도, 그 더러운 쥐들의 담력은 그들의 몸집보다도 작았다.\n그들은 너의 강경한 태도에 겁을 먹고 뿔뿔이 흩어졌다."
  },
  Event_118443_Name = {
    Text = "굶주린 쥐떼"
  },
  Event_118444_ChoiceDesc1 = {
    Text = "【그에게 진실타래을 말해주세요】무작위로 1명의 깨어남체를 깨어남시키고, “(Skill.Arg1)”에 감염됩니다"
  },
  Event_118444_ChoiceDesc2 = {
    Text = "[침묵하며 방관]3개 중에서 1개의 각인 획득"
  },
  Event_118444_Desc = {
    Text = "뛰고 있는 심장 하나가 칠흑 같은 심해를 유영하고 있다.\n그것은 어쩌면 물고기의 것일 수도, 아가미를 가진 어떤 생물의 것일 수도 있다.\n당신은 분간할 수 없다. 유일하게 볼 수 있는 것은 끊임없이 뛰는 심장과, 그 심장 뒤에서 서서히 벌어지는 거대한 입뿐이다.\n사냥하거나, 사냥당하거나—이것이 자연의 법칙이다.\n육지에서든, 바다에서든."
  },
  Event_118444_Name = {
    Text = "약육강식"
  },
  Event_118445_ChoiceDesc1 = {
    Text = "[손을 흔들어 쫓기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_118445_ChoiceDesc2 = {
    Text = "[임의로 머물기]백은 유물 “(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염됩니다"
  },
  Event_118445_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_118445_Desc = {
    Text = "어둠 속에서 가벼운 소리가 들려왔다.\n그것은 한 마리 나비가 예의 바르게 묻는 소리였다.\n「당신의 손바닥에 내려앉아도 될까요?」\n「너무 지쳐서, 잠시 쉬고 싶을 뿐이에요……」\n그렇게 묻는 나비는 어둠을 뚫고 당신의 앞에서 맴돌았다.\n칠흑의 점액이 나비의 날개에서 떨어졌다—그것은 나비가 어둠을 통과할 때, 어둠이 준 선물이었다."
  },
  Event_118445_Name = {
    Text = "나비의 부탁"
  },
  Event_118446_ChoiceDesc1 = {
    Text = "【떠나다】황금 유물 “(RelicConfig.Arg1)” 획득"
  },
  Event_118446_Desc = {
    Text = "잠시 침묵 후, 무언가가 당신의 품에 던져졌다.\n「이걸 가지고 떠나.」\n「운명은 행운아에게 언제나 관대하지.」"
  },
  Event_118446_Name = {
    Text = "운명의 도박"
  },
  Event_118447_ChoiceDesc1 = {
    Text = "[지침을 따르다]3장의 커맨드 카드 중 1장을 선택해 각인 획득: \"(EnchantConfig.Arg1)\", 감염 \"(Skill.Arg2)\""
  },
  Event_118447_ChoiceDesc2 = {
    Text = "[지침을 무시하다]3장의 커맨드 카드 중 1장을 선택해 각인 획득: \"(EnchantConfig.Arg1)\", 감염 \"(Skill.Arg2)\""
  },
  Event_118447_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_118447_Desc = {
    Text = "제전이 이미 시작되었다.\n영의 불꽃과 피의 축도 아래, 셀 수 없는 신도들의 영혼이 항로표로 변했다——\n아련한 영들이 당신 주위에 흩어져, 마치 길을 인도하는 정령처럼 빛을 내며 당신의 선택을 기다린다."
  },
  Event_118447_Name = {
    Text = "영혼 항로표"
  },
  Event_118448_ChoiceDesc1 = {
    Text = "[떠나다]“(Skill.Arg1)” 감염, 50개 검은 인장 획득"
  },
  Event_118448_Desc = {
    Text = "「무지한 인간이여!」\n그 목소리는 짜증 섞인 불평을 내뱉었지만, 분노에까지 이르지는 않았다.\n무지한 자에게도 깨달음의 순간이 있음을 알고 있기 때문이다.\n그것은 그 날이 오기만을 기다리면 된다.\n그리고 그 날이 오기 전에, 당신의 몸에 신명의 낙인을 새기고, 당신 영혼의 귀속을 확인해 둘 것이다."
  },
  Event_118448_Name = {
    Text = "무형자의 설교"
  },
  Event_118449_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118449_Desc = {
    Text = "「@2의 @3……」\n방대한 지식이 모독의 선율과 함께 당신의 대뇌에 쏟아져 들어옵니다.\n하지만 인간의 육체가 당신을 제한하여, 우주로부터 온 학식을 이해할 수 없게 합니다.\n참으로 비참한 유감입니다."
  },
  Event_118449_Name = {
    Text = "모독의 선율"
  },
  Event_118450_ChoiceDesc1 = {
    Text = "[떠나다]“(Skill.Arg1)” 감염, 50개 검은 인장 획득"
  },
  Event_118450_Desc = {
    Text = "「사실타래, 나도 세계의 진실타래 하나를 알려주고 싶은데……」\n「세계는 두 개의 지혜로운 미트볼 눈과 무한한 능력을 상징하는 면발로 이루어진 날아다니는 스파게티 괴물 신이 창조한 것이라네……」\n당신은 진지하게 어디선가 들은 재미있는 이야기를 지어내며, 상대의 반응을 기다렸다.\n하지만 한참이 지나도, 상대편에서는 아무런 반응이 없었다.\n「에휴, 역시 광신자는 유머를 모르는군.」\n당신은 한숨을 내쉬며, 떠날 수밖에 없었다."
  },
  Event_118450_Name = {
    Text = "무형자의 설교"
  },
  Event_118451_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118451_Desc = {
    Text = "너의 조율은 이 혼란스러운 음절을 조화롭게 만들지 못했다.\n하지만 적어도, 무형의 의지는 너의 시도를 보았다.\n이것은 좋은 시작이다."
  },
  Event_118451_Name = {
    Text = "「완벽한」 성가"
  },
  Event_118452_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118452_Desc = {
    Text = "세 개의 인영이 떨며, 소리 없이 흐느끼고 있다.\n그들의 신앙이 당신에게 의심받았고, 이것이야말로 광신자가 가장 용납할 수 없는 모욕이다."
  },
  Event_118452_Name = {
    Text = "최고의 제물"
  },
  Event_118453_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118453_Desc = {
    Text = "미래의 영상 속에서, 완족이 자라난 소녀가 오만하게 당신을 흘끗 보며 꾸짖었다.\n「신모의 진용은 모독할 수 없다.」\n그러자 영상이 사라지고, 시공의 균열도 순식간에 닫혔다. 방금의 광경을 회상하는 당신만이 남겨졌다."
  },
  Event_118453_Name = {
    Text = "시공 균열"
  },
  Event_118454_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118454_Desc = {
    Text = "당신은 성공적으로 답해자를 따돌리고 계속 앞으로 질주했다.\n당신의 머리 위에서 별들이 조용히 빛나고 있었다. 지난 수천 년 그래왔듯이."
  },
  Event_118454_Name = {
    Text = "별빛 아래의 기다림"
  },
  Event_118455_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118455_Desc = {
    Text = "미지의 존재는 당신을 막지 않았다.\n「언젠가, 넌 다시 돌아오게 될 거야.」\n「아무도, 운명을 거부할 수는 없으니까.」"
  },
  Event_118455_Name = {
    Text = "운명의 도박"
  },
  Event_118456_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118456_Desc = {
    Text = "깔끔하고 단호한 동작 아래, 그 두 손이 힘없이 늘어졌다.\n하지만 당신은 상대의 마지막 한숨을 놓치지 않았다.\n그는 마침내 자신의 끝없는 욕망에서 진정으로 해방되었다."
  },
  Event_118456_Name = {
    Text = "속박의 욕망"
  },
  Event_118457_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118457_Desc = {
    Text = "감지되지 않는 것은 세상의 필연적인 숙명이다.\n그 누구도 다른 생명에 완전히 공감할 수는 없다."
  },
  Event_118457_Name = {
    Text = "감지되지 않는 원탄"
  },
  Event_118458_ChoiceDesc1 = {
    Text = "[까마귀를 누르면]35개의 검은 인장 획득, 감염“(Skill.Arg2)”, 계속 선택"
  },
  Event_118458_ChoiceDesc2 = {
    Text = "【무시하고】떠나다"
  },
  Event_118458_Desc = {
    Text = "칠흑의 까마귀가 울고 있다.\n칠흑의 까마귀가 부르짖고 있다.\n칠흑의 까마귀가 미친 듯이 울부짖고 있다.\n그러나 사람들에게는 그저 노래하는 것으로 들릴 뿐이다.\n「아, 얼마나 근심 없는 노랫소리인가. 나도 까마귀가 되어 세상의 번뇌에서 벗어나고 싶구나.」"
  },
  Event_118458_Name = {
    Text = "감지되지 않는 원탄"
  },
  Event_118459_ChoiceDesc1 = {
    Text = "[귀를 기울여 듣다]백은 유물“(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_118459_ChoiceDesc2 = {
    Text = "【귀를 막다】3개 중 1개의 각인 선택"
  },
  Event_118459_Desc = {
    Text = "무형의 광란 속에서, 당신은 피아노 한 대를 본 것 같았습니다.\n형체를 알 수 없는 한 쌍의 손이, 이 무형의 건반 위에서 뛰놀며, 모독의 선율을 연주하고 있습니다.\n기괴한 음악이 당신의 영혼 깊은 곳에서 울려 퍼지며, 혈관의 회로를 통해, 떨리는 대뇌에 직접 도달합니다."
  },
  Event_118459_Name = {
    Text = "모독의 선율"
  },
  Event_118460_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118460_Desc = {
    Text = "영감, 미혹, 광상이 뒤섞여 세상에서 가장 찬란한 색으로 조화됩니다．\n공간이 당신의 몸 안에서 접히고, 시간이 당신의 의지에 따라 맴도는 것이 보입니다．\n이 순간, 당신은 시공을 꿰뚫어 보며, 전지전능합니다．\n물론, 당신은 대가를 치렀습니다．"
  },
  Event_118460_Name = {
    Text = "사고 만회경"
  },
  Event_118461_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118461_Desc = {
    Text = "혼돈의 영혼이 날카로운 울부짖음으로 당신에게 앞길을 인도한다.\n그것이 안전한 앞길인가? 당신은 알 수 없다.\n당신의 유일한 선택은, 계속 앞으로 나아가는 것뿐이다."
  },
  Event_118461_Name = {
    Text = "영혼 항로표"
  },
  Event_118462_ChoiceDesc1 = {
    Text = "[우리를 누르세요]40개의 검은 인장 획득, 감염「(Skill.Arg2)」, 계속 선택"
  },
  Event_118462_ChoiceDesc2 = {
    Text = "[무관심하게 하기] 25개의 검은 인장을 획득하고, 떠나다"
  },
  Event_118462_Desc = {
    Text = "칠흑의 까마귀가 울고 있다.\n칠흑의 까마귀가 부르짖고 있다.\n칠흑의 까마귀가 미친 듯이 울부짖고 있다.\n그러나 사람들에게는 그저 노래하는 것으로 들릴 뿐이다.\n「아, 얼마나 근심 없는 노랫소리인가. 나도 까마귀가 되어 세상의 번뇌에서 벗어나고 싶구나.」"
  },
  Event_118462_Name = {
    Text = "감지되지 않는 원탄"
  },
  Event_118463_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118463_Desc = {
    Text = "혼돈의 영혼이 애원하는 한숨을 내뱉었습니다.\n그것은 점차 사라져갔지만, 그 애원하는 한숨은 실타래체가 있는 것처럼 당신의 심장 위에 내려앉았습니다.\n쿵쿵, 당신의 심장 박동이 제전의 음악과 같은 박자로 울려 퍼집니다."
  },
  Event_118463_Name = {
    Text = "영혼 항로표"
  },
  Event_118464_ChoiceDesc1 = {
    Text = "[떠나기]획득 백은 유물 “(RelicConfig.Arg1)”"
  },
  Event_118464_Desc = {
    Text = "「아아, 이 얼마나 경건한 어린 양인가!」\n그 목소리는 감탄하며, 찬사의 환희로 가득 차 있었다.\n「우리 주님이 깨어나실타래 때, 너와 같은 어린 양은 반드시 그 숭고하고 위대한 신국에서 한 자리를 얻게 될 것이니……」"
  },
  Event_118464_Name = {
    Text = "무형자의 설교"
  },
  Event_118465_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118465_Desc = {
    Text = "「하늘」은 당신의 고집을 포용한다.\n언젠가, 길 잃은 아이는 어머니의 품으로 돌아올 것이다.\n왜냐하면, 당신은 도망칠 곳이 없으니까."
  },
  Event_118465_Name = {
    Text = "바다의 포옹"
  },
  Event_118466_ChoiceDesc1 = {
    Text = "[찬성 표시]백은 유물 「(RelicConfig.Arg1)」을 획득하고, 「(Skill.Arg2)」에 감염되었습니다"
  },
  Event_118466_ChoiceDesc2 = {
    Text = "[선물 보내기]백은 유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_118466_ChoiceDesc3 = {
    Text = "[돌아서 떠나다]획득 25 검은 인장"
  },
  Event_118466_Desc = {
    Text = "세계가 당신의 눈앞에서 기울어진다.\n이 순간, 당신을 감싸는 심해야말로 「하늘」이다.\n거의 익사할 듯한 고통 속에서, 이 짙푸른 「하늘」이 부드럽게 다가와 당신을 품에 안으려 한다.\n그것은 심판하지 않고, 오직 베풀 뿐이다."
  },
  Event_118466_Name = {
    Text = "바다의 포옹"
  },
  Event_118467_ChoiceDesc1 = {
    Text = "【가수의 목을 조르다】저주받은 유물“(RelicConfig.Arg1)”을 획득, “(Skill.Arg2)”에 감염"
  },
  Event_118467_ChoiceDesc2 = {
    Text = "[그것들에 응답하다]3장의 커맨드 카드 중 1장을 선택해 각인 획득: \"(EnchantConfig.Arg1)\""
  },
  Event_118467_ChoiceDesc3 = {
    Text = "[시인의 원고지 빼앗기]검은 인장 50개 획득"
  },
  Event_118467_Desc = {
    Text = "형체가 흐릿한 세 영혼이 당신의 앞길을 막았습니다.\n한 인영이 경건하게 당신에게 예를 올리며, 피를 내려달라고 간청합니다. 당신의 흐르는 피야말로 신에게 바치는 최고의 제물이라고.\n한 인영이 냉담하게 당신에게 칼을 들이대며, 당신의 살점을 베어내려 합니다. 변이되지 않은 인육이라면 반드시 신의 총애를 얻을 수 있을 거라고.\n마지막 하나는 무언으로 당신을 응시하며, 자신의 생명을 거두어 달라고 바랍니다. 이로써 가장 경건한 신앙을 증명하겠다고."
  },
  Event_118467_Name = {
    Text = "최고의 제물"
  },
  Event_118468_ChoiceDesc1 = {
    Text = "[까마귀를 누르세요]30개의 검은 인장 획득, 감염 “(Skill.Arg2)”, 계속 선택"
  },
  Event_118468_ChoiceDesc2 = {
    Text = "【무시하고】떠나다"
  },
  Event_118468_Desc = {
    Text = "칠흑의 까마귀가 울고 있다.\n칠흑의 까마귀가 부르짖고 있다.\n칠흑의 까마귀가 미친 듯이 울부짖고 있다.\n그러나 사람들에게는 그저 노래하는 것으로 들릴 뿐이다.\n「아, 얼마나 근심 없는 노랫소리인가. 나도 까마귀가 되어 세상의 번뇌에서 벗어나고 싶구나.」"
  },
  Event_118468_Name = {
    Text = "감지되지 않는 원탄"
  },
  Event_118469_ChoiceDesc1 = {
    Text = "【떠나다】감염“(Skill.Arg1)”"
  },
  Event_118469_ChoiceDesc2 = {
    Text = "【떠나다】감염“(Skill.Arg1)”"
  },
  Event_118469_ChoiceDesc3 = {
    Text = "【떠나다】감염“(Skill.Arg1)”"
  },
  Event_118469_Desc = {
    Text = "「안 돼! 우리는 이런 건 필요 없어! 우리는 더… 맛있는 것을 원해.」\n「그건 바로… 네 살과 피야!」\n쥐떼가 날카로운 비명을 지르며 너에게 몰려온다.\n넘치는 선의가 때로는 오히려 화를 부르는 법이다."
  },
  Event_118469_Name = {
    Text = "굶주린 쥐떼"
  },
  Event_118470_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118470_Desc = {
    Text = "당신의 존중이 그 눈들의 호감을 얻었습니다.\n사라지기 전에, 그것들은 밀려드는 해수를 통해 당신에게 선물 하나를 보냈습니다.\n그것은 심해가 당신을 길들인 증거물입니다."
  },
  Event_118470_Name = {
    Text = "심해의 눈"
  },
  Event_118471_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118471_Desc = {
    Text = "당신의 거리낌 없는 시선 아래, 심해가 천천히 깨어납니다.\n해수가 당신 주위에서 미친 듯이 밀려들며, 형언할 수 없는 헛소리를 가져옵니다.\n심해의 분노를 느껴보세요, 이것은 축복이자 저주입니다."
  },
  Event_118471_Name = {
    Text = "심해의 눈"
  },
  Event_118472_ChoiceDesc1 = {
    Text = "[까마귀를 누르기]20개의 검은 인장 획득, 감염 “(Skill.Arg2)”"
  },
  Event_118472_ChoiceDesc2 = {
    Text = "【무시하고】떠나다"
  },
  Event_118472_Desc = {
    Text = "칠흑의 까마귀가 울고 있다.\n칠흑의 까마귀가 부르짖고 있다.\n칠흑의 까마귀가 미친 듯이 울부짖고 있다.\n그러나 사람들에게는 그저 노래하는 것으로 들릴 뿐이다.\n「아, 얼마나 근심 없는 노랫소리인가. 나도 까마귀가 되어 세상의 번뇌에서 벗어나고 싶구나.」"
  },
  Event_118472_Name = {
    Text = "감지되지 않는 원탄"
  },
  Event_118473_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118473_Desc = {
    Text = "선혈, 살점, 생명.\n제물은 이미 준비되었고, 이제 신의 향연을 조용히 기다리기만 하면 된다."
  },
  Event_118473_Name = {
    Text = "최고의 제물"
  },
  Event_118474_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118474_Desc = {
    Text = "나비는 당신의 거절을 이해했다.\n칠흑의 점액으로 뒤덮인 날개가 다시 떨리며, 어둠 속에서 비틀비틀 날아갔다.\n곧, 어둠이 다시 나비를 삼켰다. 이번에는, 나비에게 발버둥칠 힘이 남아 있지 않았다."
  },
  Event_118474_Name = {
    Text = "나비의 부탁"
  },
  Event_118475_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118475_Desc = {
    Text = "나비가 당신의 손바닥에 내려앉았고, 함께 내려앉은 것은 그 화려한 날개 위의 칠흑 점액이었다.\n당신의 탄식 속에서, 화려한 날개는 점점 녹아내리며, 칠흑의 점액과 뒤엉켜 알 수 없는 혼돈의 형상이 되었다.\n이 나비는 더 이상 어둠을 겪지 않아도 된다.\n그것은 당신의 손바닥에서 편히 잠들었다."
  },
  Event_118475_Name = {
    Text = "나비의 부탁"
  },
  Event_118477_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118477_Desc = {
    Text = "목이 쉬도록 울부짖던 까마귀가 마침내 눈을 감았다.\n아무도 알지 못하고, 감지되지 않는 원한 속에서, 그것은 마지막 숨을 삼키고 한 웅덩이의 검은 농장으로 변해버렸다."
  },
  Event_118477_Name = {
    Text = "감지되지 않는 원탄"
  },
  Event_118478_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118478_Desc = {
    Text = "「고마워……」\n뛰는 심장이 기쁘게 먼 곳을 향해 달려갔다.\n얼마 지나지 않아, 칠흑 같은 심해에서 살과 피를 씹는 소리가 들려왔다."
  },
  Event_118478_Name = {
    Text = "약육강식"
  },
  Event_118479_ChoiceDesc1 = {
    Text = "【귀를 기울여 듣다】“(Skill.Arg1)” 감염, “(RelicConfig.Arg2)” 저주받은 유물 획득"
  },
  Event_118479_ChoiceDesc2 = {
    Text = "[변화를 이루어내기] 1개의 유물을 파괴하고 1개의 보상을 획득"
  },
  Event_118479_ChoiceDesc3 = {
    Text = "[떠나다]50 검은 인장을 획득"
  },
  Event_118479_Desc = {
    Text = "「이 배 위의 모든 것은, 끊임없이 붕괴하고 다시 시작되는 순환 낙원의 일부가 되어야 한다.」\n광란의 음률이 네 뇌리에 울려 퍼진다. 그것은 무형의 의지가 너에게 내리는 계시이다.\n「이곳에는 울음도, 슬픔도 없다. 오직 순결한 성악과 영원한 웃음만이 있을 뿐.」\n「너는 낙원에 합류하여, 이 완벽한 음률의 일부가 되겠는가?」"
  },
  Event_118479_Name = {
    Text = "「완벽한」 성가"
  },
  Event_118480_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_118480_Desc = {
    Text = "당신의 침묵 속에서, 영혼들은 소리 없이 흩어졌다.\n신앙을 이해하지 못하는 자에게는, 시간을 낭비할 가치가 없다."
  },
  Event_118480_Name = {
    Text = "최고의 제물"
  },
  Event_123616_ChoiceDesc1 = {
    Text = "[표준 유물 수령]"
  },
  Event_123616_Desc = {
    Text = "모든 깨어남체의 광기를 100으로 설정하고, 은 열쇠를 1000으로 설정하며, HP를 80%로 설정합니다.\n카드 2장을 제거하고 증상 카드를 3장 넣습니다.\n핏빛 용광로를 12.5%로 설정하고, 카드 4장을 초원공간에 넣습니다.\n표준 유물 팩을 획득합니다."
  },
  Event_123616_Name = {
    Text = "한 번의 클릭으로 중간 건너뛰기"
  },
  Event_125696_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125696_Desc = {
    Text = "이유 없는 분노가 당신을 이끌었고, 당신은 손을 들어 힘껏 쫓아냈다. 수수께끼 속에 너무 오래 머물렀기에, 어쩌면 당신이 갈망한 것은 통쾌한 전투, 혹은 단지 끝맺음이었을지도……\n하지만 까마귀 떼는 아무것도 하지 않았다. 당신의 시선 아래 심연이 흩어졌다.\n까마귀 떼는 무대의 끝으로 사라졌다, 당신이 향해야 할 그곳으로."
  },
  Event_125696_Name = {
    Text = "까마귀 심연"
  },
  Event_125697_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125697_Desc = {
    Text = "「겁쟁이.」 여성의 목소리는 비웃음을 조금도 숨기지 않았다.\n「가렴, 멀리 갈수록 좋아.」"
  },
  Event_125697_Name = {
    Text = "운명의 자물쇠"
  },
  Event_125698_ChoiceDesc1 = {
    Text = "[쫓아내기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_125698_ChoiceDesc2 = {
    Text = "[경청]백은 유물 「(RelicConfig.Arg1)」 획득, 「(Skill.Arg2)」에 감염"
  },
  Event_125698_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_125698_Desc = {
    Text = "다크 속에서 미세한 소리가 들려왔다. 한 마리 나비가 너의 손바닥에 떨어졌다. 너는 그것을 기억한다.\n\"아라크네 씨…… 너는 우리를 버리지 않았지, 그렇지?\"\n나비의 아름다운 무늬, 너의 곁에 있는 사람을 바라본다."
  },
  Event_125698_Name = {
    Text = "나비의 여생"
  },
  Event_125699_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125699_Desc = {
    Text = "그 소리와 문자가 벌떼처럼 네 머릿속으로 파고든다. 숨을 죽이고 정신을 집중하여 쓸모없는 잡념을 머리 밖으로 몰아낸다.\n무시하는 것이 읽는 것보다 훨씬 어렵지만, 너는 해냈다."
  },
  Event_125699_Name = {
    Text = "차원 전보"
  },
  Event_125700_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125700_Desc = {
    Text = "그것은 적이 만들어낸 환각이었다!\n당신은 고개를 흔들고 정신을 차린 뒤, 다시 손에 쥔 은열쇠를 꽉 움켜쥐었다."
  },
  Event_125700_Name = {
    Text = "술잔 속 그림자"
  },
  Event_125701_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125701_Desc = {
    Text = "당신은 그 눈을 진지하게 바라보며, 열심히 주시하고 귀 기울였다. 배우의 내면으로 들어가 그가 겪고 있는 고통을 헤아리려 했다.\n다가가고, 또 다가갔다. 그의 몸을 관통해 그의 영혼에 닿았다……\n당신은 번쩍 눈을 떴고, 자신이 무대 한가운데 서 있음을 깨달았다. 눈물이 손끝을 따라 흘러내리고 있었다.\n그것은 당신이 관객에게 바친 고백이었다."
  },
  Event_125701_Name = {
    Text = "배우의 고백"
  },
  Event_125702_ChoiceDesc1 = {
    Text = "[그녀와 토론하기] 명령 카드 1장을 삭제하고, 검은 인장 Arg1 획득하기"
  },
  Event_125702_ChoiceDesc2 = {
    Text = "[침묵한다]"
  },
  Event_125702_Desc = {
    Text = "「행복한 결말은 물론 아름답지만, 그 거짓된 기쁨은 결코 관객의 마음에 닿을 수 없어요……」\n극작가는 눈을 감고 깊이 생각했다. 그녀는 이 결말에 만족하지 않았다."
  },
  Event_125702_Name = {
    Text = "극작의 결말"
  },
  Event_125703_ChoiceDesc1 = {
    Text = "[노래 듣기]35개의 검은 인장 획득, 감염「(Skill.Arg2)」, 계속 선택"
  },
  Event_125703_ChoiceDesc2 = {
    Text = "【무시하고】떠나다"
  },
  Event_125703_Desc = {
    Text = "「삐걱——삐걱——운명의 여신이 물레를 돌린다.\n삐걱——삐걱——운명의 실타래이 그녀의 손에서 모인다.」"
  },
  Event_125703_Name = {
    Text = "마지막 예언"
  },
  Event_125704_ChoiceDesc1 = {
    Text = "[자기 자신]덱에서 무작위로 3장의 지령 카드를 뽑아 1장을 선택하여 복제"
  },
  Event_125704_ChoiceDesc2 = {
    Text = "[윌리엄]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_125704_ChoiceDesc3 = {
    Text = "[아무도 아님]검은 인장 25 획득"
  },
  Event_125704_Desc = {
    Text = "분명 취하지 않았건만, 술을 바라보는 순간 당신은 고요한 호수 속으로 빠져들었다.\n우아한 잔 속에 한 그림자가 비쳤다. 그것은 누구인가?"
  },
  Event_125704_Name = {
    Text = "술잔 속 그림자"
  },
  Event_125705_ChoiceDesc1 = {
    Text = "[경청]백은 유물 [(RelicConfig.Arg1)] 획득"
  },
  Event_125705_ChoiceDesc2 = {
    Text = "[쫓아내기]75 검은 인장 획득, 감염 [(Skill.Arg2)]"
  },
  Event_125705_Desc = {
    Text = "체내 플라스미드의 힘에 가까워질 때, 한 무리의 까마귀가 당신의 머릿속에 나타나 혼란스러운 정신의 공간 속을 맴돌기 시작한다.\n\n까마귀 떼가 당신을 에워싸고, 심연 하나가 머리 위에서 거꾸로 흘러 돌아간다.\n십만 마리의 까마귀가 일제히 울부짖으며, 마치 조롱하는 예언처럼 울려 퍼진다."
  },
  Event_125705_Name = {
    Text = "까마귀 심연"
  },
  Event_125706_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125706_Desc = {
    Text = "너는 아라크네와 함께 옆에서 무너진 운명을 안정시키려 한다. 너희의 노력은 미미한 성과를 거두었지만, 그것으로 충분하다. 얻은 시간을 이용해 너희는 네프레아에게 계속 다가간다.\n 너는 그녀에게 해방을 가져주기 위해 여기에 왔다."
  },
  Event_125706_Name = {
    Text = "운명의 거미줄 막이 내리다"
  },
  Event_125707_ChoiceDesc1 = {
    Text = "[노래 듣기]20개의 검은 인장 획득, 감염 \"(Skill.Arg2)\""
  },
  Event_125707_ChoiceDesc2 = {
    Text = "【무시하고】떠나다"
  },
  Event_125707_Desc = {
    Text = "「그것들은 거대한 그물과 함께 죽어간다, 소리 없이.」"
  },
  Event_125707_Name = {
    Text = "마지막 예언"
  },
  Event_125708_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125708_Desc = {
    Text = "그것은 심연옥에 보내는 전보였다.\n「서두르지 마, 내 아이들아. 감옥의 문이 곧 열리고, 너희의 자유가 다가오고 있다.」"
  },
  Event_125708_Name = {
    Text = "차원 전보"
  },
  Event_125709_ChoiceDesc1 = {
    Text = "[쫓아내다]무작위 1장의 커맨드 카드가 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_125709_ChoiceDesc2 = {
    Text = "[경청]지령 카드 3장 중 1장을 선택하여 각인 획득: [(EnchantConfig.Arg1)]"
  },
  Event_125709_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_125709_Desc = {
    Text = "나비 한 마리가 가볍게 네 손 위에 내려앉는다. 아름다운 무늬가 마치 눈처럼 조용히 너를 바라본다.\n어쩌면, 무언가를 전하고 싶은 걸까?"
  },
  Event_125709_Name = {
    Text = "나비의 휴식"
  },
  Event_125710_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125710_Desc = {
    Text = "스무 쌍의 슬픈 눈이 당신을 바라보았다. 까마귀는 노래를 멈추고, 마지막 예언을 품은 채 흔들리는 이 그물을 떠났다."
  },
  Event_125710_Name = {
    Text = "마지막 예언"
  },
  Event_125711_ChoiceDesc1 = {
    Text = "【몸을 숙여 탐색】(Skill.Arg1) 감염, 황금 유물 “(RelicConfig.Arg2)” 획득"
  },
  Event_125711_ChoiceDesc2 = {
    Text = "[포기 확인]50 검은 인장 획득"
  },
  Event_125711_Desc = {
    Text = "거리 모퉁이를 돌았을 때, 소박한 상영관 하나가 눈에 들어왔다. 론디니움에 이런 가게가 있었는지 기억나지 않는다."
  },
  Event_125711_Name = {
    Text = "기억 상영관"
  },
  Event_125712_ChoiceDesc1 = {
    Text = "[운명을 수용]3장의 지령 카드 중 1장을 선택하여 각인 획득: [(EnchantConfig.Arg1)]"
  },
  Event_125712_ChoiceDesc2 = {
    Text = "[운명에 저항][(Skill.Arg1)]에 감염, 다시 각인, 최대 2회 진행"
  },
  Event_125712_Desc = {
    Text = "「아, 또 만났군요, 자기.」\n당신은 뇌리에 울려 퍼지는 젊은 여성의 목소리를 즐기기 시작했다. 부드럽고 유혹적이며, 마치 벌레를 잡는 그물 같았다.\n「자, 말해봐요. 당신의 운명을 받아들일 의향이 있나요?」"
  },
  Event_125712_Name = {
    Text = "숙명의 새장"
  },
  Event_125713_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125713_Desc = {
    Text = "「어리석은 인간, 나랑 친한 줄 알아?」\n검은 고양이가 못마땅한 눈으로 당신을 흘겨보더니 돌아섰다.\n「여기서 떠나. 다음에는 이런 멍청한 짓 하지 마.」"
  },
  Event_125713_Name = {
    Text = "환화역형"
  },
  Event_125714_ChoiceDesc1 = {
    Text = "[사진 찍기] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_125714_ChoiceDesc2 = {
    Text = "[포즈 취하기] 「(Skill.Arg1)」에 감염되고, 선택지 1에서 획득한 각인으로 변경하기, 2회 사용 가능"
  },
  Event_125714_Desc = {
    Text = "카메라 한 대가 홀로 덩그러니 무대에 서 있다. 칠흑 같은 렌즈가 당신을 바라보는데, 이 렌즈는 마치 기계의 신이 창조한 신비로운 겹눈같이 보였다.\n「이 극장엔 오랫동안 관객의 발길이 끊겨있었어요…… 어서 오세요! 환영합니다! 사진 한 장 찍고 가세요! 완전 공짜, 거저예요!」\n카메라가 흥분하며 외쳤다. 아무도 관심을 두지 않는 처량한 무대의 유일한 주인공이었다."
  },
  Event_125714_Name = {
    Text = "관객석의 사진"
  },
  Event_125715_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125715_Desc = {
    Text = "「운명에 의문이 없는 자가, 어찌 운명의 답을 기대할 수 있겠는가?」"
  },
  Event_125715_Name = {
    Text = "운명의 자물쇠"
  },
  Event_125716_ChoiceDesc1 = {
    Text = "[돌파구 모색]백은 유물 「(RelicConfig.Arg1)」 획득, 「(Skill.Arg2)」 감염"
  },
  Event_125716_ChoiceDesc2 = {
    Text = "[순리에 맡기기]황금 유물 「(RelicConfig.Arg1)」 획득, 「(Skill.Arg2)」, 「(Skill.Arg3)」 감염"
  },
  Event_125716_ChoiceDesc3 = {
    Text = "[물 위로 떠오르기]검은 인장 25개 획득"
  },
  Event_125716_Desc = {
    Text = "새로운 춤, 두 개의 겹치는 인생… 경찰을 피하는 길 위에서, 너는 아라크네가 너에게 말해준 것들을 정리하고 있다.\n 복잡한 생각들 속에서, 너는 고요한 심해로 빠져든다."
  },
  Event_125716_Name = {Text = "평온"},
  Event_125717_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125717_Desc = {
    Text = "나비가 네 어깨 위로 날아와 귀에 다가온다. 진지하게 귀를 기울이지만, 들리는 것은 날개의 떨림뿐, 마치 무성의 한숨 같다.\n네가 경청하는 동안, 그 찬란한 날개가 서서히 녹아내리고, 나비는 네 어깨 위에서 잠든다.\n너는 그것이 전하려 했던 말을 더 이상 알 수 없다."
  },
  Event_125717_Name = {
    Text = "나비의 여생"
  },
  Event_125718_ChoiceDesc1 = {
    Text = "[음미해볼까?] 랜덤으로 깨어남체 1명을 깨어남시키고, 「(Skill.Arg1)」에 감염되기"
  },
  Event_125718_ChoiceDesc2 = {
    Text = "[거부하기] 각인 3개 중 1개 획득하기"
  },
  Event_125718_Desc = {
    Text = "「우리 소중한 고객님, 배고프시지 않나?」\n끈적한 목소리가 바 뒤편에서 들려오고 있다. 뒤를 돌아보지만은 역시 아무것도 보이지 않는다.\n「자정이 되면 술집의 안줏거리도 꽤나 별미거든. 어때, 하나 잡숴볼래?」"
  },
  Event_125718_Name = {
    Text = "운명의 맛"
  },
  Event_125719_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125719_Desc = {
    Text = "당신은 위의 글자를 함부로 읽지 않고, 그저 정교한 봉투를 자세히 살펴본다.\n봉투의 밀랍 인장에는 흐릿한 문장 문장이 새겨져 있고, 그 위에는 아름다운 서체로 적혀 있다:\n\"신생의 아라크네 양께.\"\n\"당신의 충성스러운 집사, 에드가.\""
  },
  Event_125719_Name = {
    Text = "안녕히, 에드가 씨"
  },
  Event_125720_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125720_Desc = {
    Text = "「그렇군요, 알겠어요, 언니……」\n「극작가는 결코 등장인물의 결말을 바꿀 수 없어요. 그 비참한 운명은 이미 정해져 있고, 언니라 해도 결코 바꿀 수 없었던 거예요……」\n슬픈 흐느낌이 사라졌다. 극작가의 타자기가 나비들로 변해 텅 빈 운명의 극장 속으로 흩어지며, 더 이상 흔적을 찾을 수 없었다."
  },
  Event_125720_Name = {
    Text = "극작의 결말"
  },
  Event_125721_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125721_Desc = {
    Text = "이름 모를 배우, 위험한 춤사위……그게 무슨 상관이란 말인가? 운명 자체보다 더 나쁜 것은 없을 테니.\n당신은 손을 내밀고 무대에 올랐다. 인형이 당신의 손을 잡고 경쾌한 춤을 추기 시작했다.\n박수 소리가 들렸다."
  },
  Event_125721_Name = {Text = "3인무"},
  Event_125722_ChoiceDesc1 = {
    Text = "[노래 듣기]25개의 검은 인장 획득, 감염「(Skill.Arg2)」, 계속 선택"
  },
  Event_125722_ChoiceDesc2 = {
    Text = "【무시하고】떠나다"
  },
  Event_125722_Desc = {
    Text = "「그것들이 춤춘다. 그것들이 노래한다. 삐걱——삐걱——」"
  },
  Event_125722_Name = {
    Text = "마지막 예언"
  },
  Event_125723_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125723_Desc = {
    Text = "인도자, 전우, 고독한 차원에서 유일한 동반자.\n당신들은 함께 이곳의 모든 것을 해결하고 카다스로 돌아갈 것이다. 당신은 이 점을 한 번도 의심한 적이 없었다."
  },
  Event_125723_Name = {
    Text = "술잔 속 그림자"
  },
  Event_125724_ChoiceDesc1 = {
    Text = "【한 번 도전해볼까】“(Skill.Arg1)” 감염, 도박에 참여하기"
  },
  Event_125724_ChoiceDesc2 = {
    Text = "[아니면]25 검은 인장을 획득"
  },
  Event_125724_Desc = {
    Text = "골목 모퉁이에서, 더러운 한 쌍의 손이 당신을 가로막았다.\n누더기를 걸친 거지가 슬그머니 다가왔다. 그의 눈빛은 썩은 고기를 발견한 하이에나처럼 욕심스러웠다.\n「이리 와! 한판 하자고! 네가 알고 싶은 것 전부 알려줄게! 이기기만 하면 돼……」"
  },
  Event_125724_Name = {
    Text = "거리의 도박"
  },
  Event_125725_ChoiceDesc1 = {
    Text = "[무시]지령 카드 1장 삭제, 검은 인장 25 획득"
  },
  Event_125725_ChoiceDesc2 = {
    Text = "[읽기]덱에 있는 카드 1장 복제, [(Skill.Arg1)]에 감염"
  },
  Event_125725_Desc = {
    Text = "딱딱딱, 딱딱딱……\n술집 구석에는 아무도 없고, 전신 타자기가 맑은 소리를 내며 울린다. 마치 아름다운 피아노 곡처럼."
  },
  Event_125725_Name = {
    Text = "차원 전보"
  },
  Event_125726_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125726_Desc = {
    Text = "「닥쳐, 나는 고양이야, 너희들의 어리석은 이야기 따위 듣고 싶지 않아.」\n검은 고양이가 한숨을 쉬며 돌아섰다.\n「여기서 떠나. 다음에는 이런 멍청한 짓 하지 마.」"
  },
  Event_125726_Name = {
    Text = "환화역형"
  },
  Event_125727_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125727_Desc = {
    Text = "그녀의 말이 틀리지 않았을지도 모른다. 그것이 바로 너, 네 마음 깊은 곳에 숨겨진 가장 은밀하고 더러운 생각이다.\n모든 사람은 이기적이며, 너는 결코 타인이 생각하는 것처럼 고결하지 않았다.\n너는 그 비열한 고통을 음미한다. 지나간 것은 이미 지나갔고, 너의 구원은 앞에 있음을 알고 있다."
  },
  Event_125727_Name = {
    Text = "고통의 만연"
  },
  Event_125728_ChoiceDesc1 = {
    Text = "[그녀와 토론하기] 명령 카드 1장을 삭제하고, 검은 인장 Arg1 획득하기"
  },
  Event_125728_ChoiceDesc2 = {
    Text = "[침묵한다]"
  },
  Event_125728_Desc = {
    Text = "「장렬한 결말은 얼마나 진실타래한가, 하지만 우리의 현실타래이 이토록 비참한데, 이야기 속에서조차 그녀에게 아름다운 안식처를 줄 수 없단 말인가……」\n극작가는 눈을 감고 깊이 생각했다. 그녀는 이 결말에 만족하지 않았다."
  },
  Event_125728_Name = {
    Text = "극작의 결말"
  },
  Event_125729_ChoiceDesc1 = {
    Text = "【떠나다】황금 유물 “(RelicConfig.Arg1)” 획득"
  },
  Event_125729_Desc = {
    Text = "데구르르, 주사위가 주사위통 안에서 신나게 춤을 추다가, 기진맥진해질 때까지 굴렀다.\n\n「왜……왜 아무도 이길 수 없는 거야!……」"
  },
  Event_125729_Name = {
    Text = "거리의 도박"
  },
  Event_125730_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125730_Desc = {
    Text = "너는 최대한 가까이 다가가 진지하게 귀를 기울인다.\n나비가 날개를 펄럭이며 네 손바닥을 떠난다.\n아무것도 들리지 않았다."
  },
  Event_125730_Name = {
    Text = "나비의 휴식"
  },
  Event_125731_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125731_Desc = {
    Text = "네가 쫓아내려 해도 나비는 꿈쩍도 하지 않는다.\n집요하게 네 손바닥을 쫓아다니다가, 네가 마지막으로 팔을 휘두르자 마침내 떠나기로 한다.\n약간 후회가 된다. 어쩌면, 그 말을 들어볼 걸 그랬나?"
  },
  Event_125731_Name = {
    Text = "나비의 휴식"
  },
  Event_125732_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125732_Desc = {
    Text = "검은 연기가 실타래의에 찬 듯 떨렸고, 거지의 고통스러운 울부짖음은 목이 쉴 때까지 이어졌다.\n한 번 눈을 깜빡이자 주사위와 거지는 사라져 있었다. 낡은 모자 안에 게임의 보상이 남아 있었다."
  },
  Event_125732_Name = {
    Text = "거리의 도박"
  },
  Event_125733_ChoiceDesc1 = {
    Text = "[광란에 합류]「(Skill.Arg1)」 감염, 저주 유물-「(RelicConfig.Arg2)」 획득"
  },
  Event_125733_ChoiceDesc2 = {
    Text = "[연주 저지]유물 1개를 선택하여 파괴, 보상 1개 획득"
  },
  Event_125733_ChoiceDesc3 = {
    Text = "[귀를 막기]검은 인장 50 획득"
  },
  Event_125733_Desc = {
    Text = "「아! 음악! 위대한 극에 어찌 음악이 없을 수 있겠는가!!」\n불협화음의 교향곡이 부서진 극장에 울려 퍼지며, 마치 혼돈의 광란과도 같다. 연옥에서 온 배우들이 이 무질서한 송가 속에서 춤추고 환호한다, 그것은 그들이 살아가는 음표이다."
  },
  Event_125733_Name = {
    Text = "운명의 송가"
  },
  Event_125734_ChoiceDesc1 = {
    Text = "[획득 100개의 검은 인장]"
  },
  Event_125734_ChoiceDesc2 = {
    Text = "[무작위 2장의 커맨드 카드가 각인 획득: \"(EnchantConfig.Arg1)\"]"
  },
  Event_125734_Desc = {
    Text = "보이지 않는 운명의 실타래이 음표 속에서 춤춘다. 그 혼란스러운 소리 속에서, 당신은 점차 그 매혹적인 선율을 포착했다—그렇다, 그것이야말로 운명이 내야 할 소리.\n연옥의 버림받은 자들이 당신을 향해 환호하며, 당신을 둘러싸고 그들의 무질서한 광란 속으로 이끈다.\n축하한다, 행운의 관객이여! 이제, 당신은 배우들과 함께 운명에게 커튼콜을 올릴 것이다."
  },
  Event_125734_Name = {
    Text = "운명의 송가"
  },
  Event_125735_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125735_Desc = {
    Text = "당신은 이 소리의 의미를 분별할 수 없지만, 멈춰야 한다는 것은 안다.\n은빛이 미친 칼날처럼 휘둘러지고, 그 리듬은 놀랍게도 음표와 완벽히 맞아떨어졌다.\n정신을 차렸을 때, 음표는 어느새 멈춰 있었다. 더 이상 아무 소리도 들리지 않는다. 보이는 것은 오직 어둠뿐, 들리는 것은 오직 적막뿐.\n무질서한 소음과 절대적인 적막, 과연 어느 쪽이 더 무서운 것일까……비밀 수호자여?"
  },
  Event_125735_Name = {
    Text = "운명의 송가"
  },
  Event_125736_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125736_Desc = {
    Text = "너는 손을 내밀고, 나비 한 마리가 가볍게 네 손 위에 내려앉는다.\n그래. 죽음, 소멸, 흘러감……나비는 고치 속에서 태어나고, 고통은 예술의 영원한 토양이다.\n훌륭한 관객으로서, 이것은 네가 반드시 깨달아야 할 진리다."
  },
  Event_125736_Name = {
    Text = "소멸 속에서 피어나다"
  },
  Event_125737_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125737_Desc = {
    Text = "이것은 아마도 네프레아의 어떤 속임수일 것이다.\n나비는 너의 말을 이해했고, 다크 속에서 그것의 무언의 한숨이 울려 퍼졌다. 칠흑 같은 끈적한 액체가 흐르는 날개가 진동했고, 곧 나비의 무거운 형체는 끝없는 다크 속에 잠겼다.\n너는 더 이상 그것이 너에게 전하고 싶었던 말을 알 수 없다."
  },
  Event_125737_Name = {
    Text = "나비의 여생"
  },
  Event_125738_ChoiceDesc1 = {
    Text = "[떠나다]50 검은 인장을 획득"
  },
  Event_125738_Desc = {
    Text = "데구르르, 주사위가 주사위통 안에서 신나게 춤을 추다가, 기진맥진해질 때까지 굴렀다.\n\n「왜……왜 아무도 이길 수 없는 거야!……」"
  },
  Event_125738_Name = {
    Text = "거리의 도박"
  },
  Event_125739_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125739_Desc = {
    Text = "지금 생각을 마구 흘려보내는 것은 위험하다. 당신은 고개를 저으며, 서둘러 수면 위로 떠올랐다……"
  },
  Event_125739_Name = {Text = "평온"},
  Event_125740_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125740_Desc = {
    Text = "모든 음표에 청중이 필요한 것은 아니며, 모든 운명에 답이 필요한 것은 아니다.\n당신은 꽉 귀를 막고, 이 시끄러운 무대를 떠났다.\n여전히 그 불협화음의 의미가 궁금하겠지만, 당신은 안다, 유일하게 올바른 선택을 했다는 것을."
  },
  Event_125740_Name = {
    Text = "운명의 송가"
  },
  Event_125741_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125741_Desc = {
    Text = "은빛이 환영을 꿰뚫자, 검은 고양이들은 검은 점액 웅덩이로 변했다.\n검은 고양이로 변신해 숨으려 했지만, 당신의 눈은 속일 수 없다."
  },
  Event_125741_Name = {
    Text = "환화역형"
  },
  Event_125742_ChoiceDesc1 = {
    Text = "[운명을 수용]3장의 지령 카드 중 1장을 선택하여 각인 획득: [(EnchantConfig.Arg1)]"
  },
  Event_125742_Desc = {
    Text = "「아무도 진정으로 운명에 저항할 수 없어, 자기야. 우리에게는 애초에 선택할 권리 같은 건 없었으니까.」\n여성의 목소리가 쓸쓸하고 아득해진다. 그녀가 대화하고 싶은 상대가 너인지, 아니면 다른 무언가인지 확신할 수 없다."
  },
  Event_125742_Name = {
    Text = "숙명의 새장"
  },
  Event_125743_ChoiceDesc1 = {
    Text = "[노래 듣기]30개의 검은 인장 획득, 감염「(Skill.Arg2)」, 계속 선택"
  },
  Event_125743_ChoiceDesc2 = {
    Text = "【무시하고】떠나다"
  },
  Event_125743_Desc = {
    Text = "「인형들이 줄지어 입장하여 운명의 거대한 그물에 발을 들인다.」"
  },
  Event_125743_Name = {
    Text = "마지막 예언"
  },
  Event_125744_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125744_Desc = {
    Text = "당신은 고개를 들어 소용돌이치는 심연을 올려다보며 까마귀 떼의 신탁을 들으려 했다.\n하지만 까마귀 떼는 아무 말도 하지 않았다. 당신의 시선 아래 심연이 흩어졌다.\n까마귀 떼는 무대의 끝으로 사라졌다, 당신이 향해야 할 그곳으로."
  },
  Event_125744_Name = {
    Text = "까마귀 심연"
  },
  Event_125745_ChoiceDesc1 = {
    Text = "[나비에 동의]카드 2장 삭제"
  },
  Event_125745_ChoiceDesc2 = {
    Text = "[나비에 반대]저주 유물 「(RelicConfig.Arg1)」 획득, 「(Skill.Arg2)」에 감염"
  },
  Event_125745_ChoiceDesc3 = {
    Text = "[떠나다]Arg1 검은 인장 획득"
  },
  Event_125745_Desc = {
    Text = "무대의 장막이 바람에 나부끼고, 시체에서 흘러내린 검은 점액 속에서 나비 떼가 보인다.\n「진정한 예술은 언제나 소멸 속에서 피어나는 법……그렇지, 비밀지기?」\n무용수의 시체가 너를 향해 미소 짓고 있다. 나비가 날갯짓하는 소리가 들린다."
  },
  Event_125745_Name = {
    Text = "소멸 속에서 피어나다"
  },
  Event_125746_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125746_Desc = {
    Text = "궤변은 결코 너를 흔들 수 없다. 너는 자신이 어떤 길을 걷고 있는지, 종착점이 어디인지 명확히 알고 있다.\n가시가 네 몸속에서 사라진다. 너는 언제나처럼 길 위에 오른다."
  },
  Event_125746_Name = {
    Text = "고통의 만연"
  },
  Event_125747_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125747_Desc = {
    Text = "너는 몸을 돌려 등 뒤의 눈들을 잊으려 한다. 하지만 몸이 평소처럼 제어되지 않는 것을 깨닫는다.\n너는 안다. 그 응시하는 시선들로부터 결코 도망칠 수 없다는 것을."
  },
  Event_125747_Name = {Text = "관객"},
  Event_125748_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125748_Desc = {
    Text = "존경이든 두려움이든, 너는 쉽게 건드리기를 원하지 않고, 봉투를 원래 자리로 놓았다. 너가 떠나려 할 때, 봉투 뒤의 다크에서 흐릿하지만 부드러운 목소리가 들려왔다.\n \"나를 기억해 주셔서 감사합니다, 아라크네 씨……\""
  },
  Event_125748_Name = {
    Text = "안녕히, 에드가 씨"
  },
  Event_125749_ChoiceDesc1 = {
    Text = "[수호의 힘]백은 유물 [(RelicConfig.Arg1)] 획득"
  },
  Event_125749_ChoiceDesc2 = {
    Text = "[도주의 자유]무작위 카드 1장에 각인 부여: [(EnchantConfig.Arg1)]"
  },
  Event_125749_ChoiceDesc3 = {
    Text = "[대답 거부]검은 인장 50 획득"
  },
  Event_125749_Desc = {
    Text = "한밤의 가면무도회의 술기운이 머릿속으로 스며들어, 마치 쇠사슬처럼 당신을 옭아맨다. 차가운 사슬을 따라, 젊은 여성의 목소리가 뇌리에 맴돈다.\n「말해봐, 자기야. 네가 원하는 운명이란, 대체 무엇이지?」"
  },
  Event_125749_Name = {
    Text = "운명의 자물쇠"
  },
  Event_125750_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125750_Desc = {
    Text = "아무리 복잡한 일이라도, 결국 당신들이 해결해야 한다.\n점점 무거워지는 것을 느끼는 동시에, 새로운 힘도 느껴진다."
  },
  Event_125750_Name = {Text = "평온"},
  Event_125751_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125751_Desc = {
    Text = "이름 모를 배우, 위험한 춤사위. 맞다, 도망치는 것이 항상 가장 안전하다.\n당신은 몸을 돌려 달렸고, 극장의 장막을 젖혔다. 그리고, 당신은 무대 위에 서 있었다. 인형이 당신의 손을 잡고 경쾌한 춤을 추기 시작했다.\n운명의 무대에는 애초에 선택이란 없었다."
  },
  Event_125751_Name = {Text = "3인무"},
  Event_125752_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125752_Desc = {
    Text = "지금은 영화를 볼 때가 아니다."
  },
  Event_125752_Name = {
    Text = "기억 상영관"
  },
  Event_125753_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125753_Desc = {
    Text = "길 위의 위험은 조금도 너의 뇌리에 들어오지 않았다. 너는 옆에서 무너진 운명을 지나쳐 네프레아에게 계속 다가갔다.\n 너는 그녀에게 해방을 가져주기 위해 여기에 왔다."
  },
  Event_125753_Name = {
    Text = "운명의 거미줄 막이 내리다"
  },
  Event_125754_ChoiceDesc1 = {
    Text = "[봉투 읽기]황금 유물 「(RelicConfig.Arg1)」 획득, 「(Skill.Arg2)」 감염"
  },
  Event_125754_ChoiceDesc2 = {
    Text = "[편지 읽기]지령 카드 3장 중 1장을 선택하여 각인 부여: [(EnchantConfig.Arg1)]"
  },
  Event_125754_ChoiceDesc3 = {
    Text = "[제자리로 돌려놓기]50 검은 인장 획득"
  },
  Event_125754_Desc = {
    Text = "당신들의 움직임에 빽빽한 거미줄이 찢어지고, 낡은 편지 한 통이 거미줄 사이에서 떨어졌다.\n그 무게는 얇은 종이 한 장보다 훨씬 무겁다."
  },
  Event_125754_Name = {
    Text = "안녕히, 에드가 씨"
  },
  Event_125755_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125755_Desc = {
    Text = "까마귀의 눈에서 눈물이 흘러내렸다. 까마귀의 입가에서 선혈이 흘렀다. 까마귀는 모든 생명을 다해 당신에게 마지막 예언을 노래했다."
  },
  Event_125755_Name = {
    Text = "마지막 예언"
  },
  Event_125756_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125756_Desc = {
    Text = "「흐흐……하하하하!」\n「어때, 내 손님? 운명의 맛, 미칠 듯이 그리워하게 될 거야……」"
  },
  Event_125756_Name = {
    Text = "운명의 맛"
  },
  Event_125757_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125757_Desc = {
    Text = "「재미없군.」 여성의 목소리가 나른한 하품을 했다.\n「네 힘을 가지고, 클럽에 가서 격투나 해.」"
  },
  Event_125757_Name = {
    Text = "운명의 자물쇠"
  },
  Event_125758_ChoiceDesc1 = {
    Text = "[운명의 그물 안정화]3택 1 고급 각인 획득"
  },
  Event_125758_ChoiceDesc2 = {
    Text = "[위험 무시]황금 유물 「(RelicConfig.Arg1)」 획득, 「(Skill.Arg2)」 감염"
  },
  Event_125758_ChoiceDesc3 = {
    Text = "[떠나다]50 검은 인장을 획득"
  },
  Event_125758_Desc = {
    Text = "그녀는 아름다운 애완동물이다. 그녀는 운명의 버림받은 아이이다. 그녀는 어두운 빛점을 따라 심연에서 기어 나오는 복수자이다. 그녀는 여기 와서 모든 것에 해방을 가져온다.\n 운명의 그물이 너희 주위에서 무너지고 있다. 너는 극장의 무대에 서 있으며, 네프레아와는 그리 멀지 않은 거리다."
  },
  Event_125758_Name = {
    Text = "운명의 거미줄 막이 내리다"
  },
  Event_125759_ChoiceDesc1 = {
    Text = "[이해할 수 없음]백은 유물 [(RelicConfig.Arg1)] 획득"
  },
  Event_125759_ChoiceDesc2 = {
    Text = "[깊이 공감함]황금 유물 「(RelicConfig.Arg1)」 획득, 「(Skill.Arg2)」 감염"
  },
  Event_125759_Desc = {
    Text = "무대 위에서 찢어지는 듯한 울부짖음이 들려왔다. 유일한 조명이 외로운 그림자 위에 내려앉았다.\n그는 당신에게 가장 진심 어린 연기를 바치고 있었다——자신의 내장을 갈라, 모든 관객에게 보여주는 것이었다.\n무엇이 이 인물을 이토록 고통스럽게 만든 것일까?"
  },
  Event_125759_Name = {
    Text = "배우의 고백"
  },
  Event_125760_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125760_Desc = {
    Text = "당신의 손이 오른쪽으로 향했다.\n그것은 당신의 미래, 가장 강렬한 갈망, 당신의 귀착지, 당신이 도달할 곳.\n당신의 존재는 앞에 놓인 태양을 쫓기 위함이었다."
  },
  Event_125760_Name = {
    Text = "과거, 미래"
  },
  Event_125761_ChoiceDesc1 = {
    Text = "【세 점】"
  },
  Event_125761_ChoiceDesc2 = {
    Text = "【여섯 시】"
  },
  Event_125761_ChoiceDesc3 = {
    Text = "【한 점】"
  },
  Event_125761_Desc = {
    Text = "물론 그냥 떠날 수도 있었지만, 그 정교한 주사위가 당신을 완전히 사로잡았다.\n당신은 뒤쫓아 오는 추격자를 잊고, 경건하게 그것을 집어 들어 모자 안에 던졌다——"
  },
  Event_125761_Name = {
    Text = "거리의 도박"
  },
  Event_125762_ChoiceDesc1 = {
    Text = "[떠나다]획득 백은 유물 [(RelicConfig.Arg1)]"
  },
  Event_125762_Desc = {
    Text = "데구르르, 주사위가 주사위통 안에서 신나게 춤을 추다가, 기진맥진해질 때까지 굴렀다.\n\n「왜……왜 아무도 이길 수 없는 거야!……」"
  },
  Event_125762_Name = {
    Text = "거리의 도박"
  },
  Event_125763_ChoiceDesc1 = {
    Text = "[운명을 수용]3장의 지령 카드 중 1장을 선택하여 각인 획득: [(EnchantConfig.Arg1)]"
  },
  Event_125763_ChoiceDesc2 = {
    Text = "[운명에 저항][(Skill.Arg1)]에 감염, 다시 무작위 각인"
  },
  Event_125763_Desc = {
    Text = "「아, 장난꾸러기. 운명은 언제나 자비롭지……하지만 모든 저항에는 대가가 따르는 법. 이제, 그것을 받아들일 준비가 되었니?」"
  },
  Event_125763_Name = {
    Text = "숙명의 새장"
  },
  Event_125764_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125764_Desc = {
    Text = "너는 그 시선들을 둘러보며 손을 흔들어 인사한다.\n머지않아, 이야기의 클라이맥스를 그들에게 선사할 것이다."
  },
  Event_125764_Name = {Text = "관객"},
  Event_125765_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125765_Desc = {
    Text = "\"사랑하는 아라크네 양, 오늘은 당신의 생일입니다. 저는 주인님과 부인님, 그리고 당신을 위해 기쁨을 느낍니다. 이 아름다운 세계에 오신 것을 환영합니다. 저는 이 부드러운 자장가를 당신께 바칩니다. 당신이 태어난 이 날부터 걱정 없는 삶을 살기를 바랍니다……\""
  },
  Event_125765_Name = {
    Text = "안녕히, 에드가 씨"
  },
  Event_125766_ChoiceDesc1 = {
    Text = "[사진 찍기] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_125766_ChoiceDesc2 = {
    Text = "[다시 찍자] 「(Skill.Arg1)」에 감염되고, 선택지 1에서 획득한 각인으로 변경하기, 이제 1회만 사용 가능"
  },
  Event_125766_Desc = {
    Text = "렌즈 앞에 선 당신은 약간 불안해졌다. 이 포즈를 취하는 게 더 잘 나올까? 아니면 저 포즈를 취하는 게 낫나?"
  },
  Event_125766_Name = {
    Text = "관객석의 사진"
  },
  Event_125767_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125767_Desc = {
    Text = "그 위에 담긴 내용을 보고 싶었지만, 스크린에는 아무것도 비치지 않았고, 상영관 안에는 필름이 돌아가는 소리만 울려 퍼졌다.\n아마 한참 뒤에야, 필름 속 내용을 알 수 있는 기회가 올 것이다."
  },
  Event_125767_Name = {
    Text = "기억 상영관"
  },
  Event_125768_ChoiceDesc1 = {
    Text = "【회피 시선】무작위로 1명의 깨어남체를 깨어남시킵니다"
  },
  Event_125768_ChoiceDesc2 = {
    Text = "【직시 시선】1명의 깨어남체를 선택하여 그 깨어남 카드의 산출력 소모를 2점 감소시킵니다. 감염“(Skill.Arg1)”"
  },
  Event_125768_ChoiceDesc3 = {
    Text = "[떠나다]50 검은 인장을 획득"
  },
  Event_125768_Desc = {
    Text = "무대에 올라서자 속삭이는 소리가 들린다. 뒤를 돌아보니, 만 명의 관객의 눈이 무대 사방에 떠다니며 너를 응시하고 있다.\n이리 와! 그들이 말한다. 멋진 연극이, 설마 여기서 끝나는 건 아니겠지?\n춤춰! 그들이 말한다. 이 무곡의 클라이맥스를 우리에게 선사해!"
  },
  Event_125768_Name = {Text = "관객"},
  Event_125769_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125769_Desc = {
    Text = "당신은 그의 고통을 이해하지 못했고, 이해할 필요도 없었다.\n극장에는 수많은 무대가 있고, 무대 위에는 수많은 인형이 있으며, 당신도 그중 하나에 불과했다.\n당신에게는 더 중요한 일이 있었다."
  },
  Event_125769_Name = {
    Text = "배우의 고백"
  },
  Event_125770_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125770_Desc = {
    Text = "죽음, 소멸, 흘러감……예술은 고통을 가져오기 위해 존재하는 것이 아니다. 만약 아름다움이 고통 속에만 존재한다면, 그런 아름다움은 필요 없다.\n너는 힘껏 나비를 쫓아낸다. 나비가 흩어지고, 슬픈 시체 하나만이 남는다."
  },
  Event_125770_Name = {
    Text = "소멸 속에서 피어나다"
  },
  Event_125771_ChoiceDesc1 = {
    Text = "[노래 듣기]40개의 검은 인장 획득, 감염「(Skill.Arg2)」, 계속 선택"
  },
  Event_125771_ChoiceDesc2 = {
    Text = "[무관심하게 하기] 25개의 검은 인장을 획득하고, 떠나다"
  },
  Event_125771_Desc = {
    Text = "한때 당신과 만났던 까마귀 떼가 하나로 모였다. 그것은 당신 앞에 서서 노래했고, 노랫소리는 처량하여 마치 마지막 예언 같았다."
  },
  Event_125771_Name = {
    Text = "마지막 예언"
  },
  Event_125772_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125772_Desc = {
    Text = "당신의 손이 왼쪽으로 향했다.\n그것은 당신의 과거, 가장 소중한 기억, 당신이 걸어온 길, 당신이 돌아갈 곳.\n과거의 모든 것이 당신의 전부를 이루었다."
  },
  Event_125772_Name = {
    Text = "과거, 미래"
  },
  Event_125773_ChoiceDesc1 = {
    Text = "[사진 찍기] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_125773_Desc = {
    Text = "렌즈 앞에 선 당신은 약간 불안해졌다. 이 포즈를 취하는 게 더 잘 나올까? 아니면 저 포즈를 취하는 게 낫나?\n당신은 계속 망설이고 있지만, 반대로 카메라는 이미 매우 초조해하고 있다는 걸 알 수 있었다."
  },
  Event_125773_Name = {
    Text = "관객석의 사진"
  },
  Event_125774_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125774_Desc = {
    Text = "당신을 카메라 앞에 서서 포즈를 취했다. 마치 진정한 관객처럼 단정하고, 호기심 가득하게 몰입한다.\n찰칵——\n카메라가 셔터를 눌렀고, 검은 점액이 카메라에서 터져 나와 무대 전체에 튀었다.\n카메라의 잔해 한 가운데, 필름 위에는 아무것도 존재하지 않았다."
  },
  Event_125774_Name = {
    Text = "관객석의 사진"
  },
  Event_125775_ChoiceDesc1 = {
    Text = "[수락]3택 1 백은 유물 획득"
  },
  Event_125775_ChoiceDesc2 = {
    Text = "[도주]백은 유물 「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」 획득, 「(Skill.Arg3)」 2회 감염"
  },
  Event_125775_Desc = {
    Text = "딱딱, 딱딱……구두 굽과 나무판이 부딪히며 경쾌한 소리를 냈다.\n학생 교복을 입은 두 인형이 무대 위에서 춤을 추고 있었다. 갑자기, 그들은 춤을 멈추고 당신을 향해 손을 내밀었다."
  },
  Event_125775_Name = {Text = "3인무"},
  Event_125776_ChoiceDesc1 = {
    Text = "[고통을 견디다]최대 생명력 Arg1 포인트 증가"
  },
  Event_125776_ChoiceDesc2 = {
    Text = "[고통에 반박]무작위 1장의 커맨드 카드가 각인 획득: \"(EnchantConfig.Arg1)\", 1장 \"(Skill.Arg2)\" 감염"
  },
  Event_125776_Desc = {
    Text = "「너는 리즈의 죽음을 신경 쓴 적이 없어. 누구의 죽음도 신경 쓴 적이 없지.」\n「네가 신경 쓰는 건 오직 자기 자신뿐……네 곁의 모든 사람은 자유와 평온을 향한 도구에 불과해.」\n「아닌가……비밀지기?」\n해설자의 속삭임이 네 귓가에 울린다. 심장이 조여 오고, 수축하며, 강렬한 고통이 그녀의 말과 함께 온몸으로 퍼져 나간다……"
  },
  Event_125776_Name = {
    Text = "고통의 만연"
  },
  Event_125777_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125777_Desc = {
    Text = "의식의 추락에 몸을 맡겨라, 바닷물에는 부력이 있으니, 운명이 모든 것의 길을 가리켜 줄 것이다."
  },
  Event_125777_Name = {Text = "평온"},
  Event_125778_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125778_Desc = {
    Text = "그것은 당신 자신이었다. 힘의 원천, 책임의 담지자, 유일하게 충성할 대상.\n당신은 오직 당신만의 길 위를 걷고 있었다."
  },
  Event_125778_Name = {
    Text = "술잔 속 그림자"
  },
  Event_125779_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125779_Desc = {
    Text = "「정말 유감이야, 내 손님. 운명의 맛, 다시는 맛볼 기회가 없을 거야……」"
  },
  Event_125779_Name = {
    Text = "운명의 맛"
  },
  Event_125780_ChoiceDesc1 = {
    Text = "[그녀와 토론하기] 명령 카드 1장을 삭제하고, 검은 인장 Arg1 획득하기"
  },
  Event_125780_ChoiceDesc2 = {
    Text = "[침묵한다]"
  },
  Event_125780_Desc = {
    Text = "「정말 슬픈 연극이네요……그 불쌍한 소녀는 자신이 사랑하는 사람에게 버림받은 건가요, 언니?」\n이 익숙한 목소리에서 당신은 어떤 광기도 증오도 듣지 못했다. 그 목소리는 맑고 슬프며, 마치 숲속의 부드러운 시냇물 같았다.\n「그 노래하는 자, 무력하게 떠도는 마른 잎사귀, 운명의 유린에 속수무책……얼마나 불쌍한 사람인가……」\n「언니, 만약 내가 그 집필자라면……그녀에게 어떤 결말을 써줘야 할까요?」"
  },
  Event_125780_Name = {
    Text = "극작의 결말"
  },
  Event_125781_ChoiceDesc1 = {
    Text = "[쓰다듬기]50% 확률로 검은 인장 125 획득, 50% 확률로 [(Skill.Arg2)] 감염"
  },
  Event_125781_ChoiceDesc2 = {
    Text = "[설명하기]75% 확률로 검은 인장 100 획득, 25% 확률로 [(Skill.Arg2)] 감염"
  },
  Event_125781_ChoiceDesc3 = {
    Text = "[간파하기]검은 인장 50 획득"
  },
  Event_125781_Desc = {
    Text = "술집 뒷골목을 쫓아갔을 때, 괴물의 모습은 사라지고 한 무리의 검은 고양이가 앞을 가로막았다.\n「야, 너.」 한 마리의 검은 고양이가 자기 발을 핥으며 당신을 바라보았다.\n「우리 구역에 뭐 하러 온 거야?」"
  },
  Event_125781_Name = {
    Text = "환화역형"
  },
  Event_125782_ChoiceDesc1 = {
    Text = "[과거를 마주하자] 황금 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_125782_ChoiceDesc2 = {
    Text = "[미래를 마주하자] 황금 유물 3개 중 1개를 획득하고, 「(Skill.Arg1)」에 감염되기"
  },
  Event_125782_ChoiceDesc3 = {
    Text = "[떠나기] 백은 유물 「(RelicConfig.Arg1)」 획득하기"
  },
  Event_125782_Desc = {
    Text = "네프리아의 출현이 실타래타래를 교란시키고 있다. 어지러운 이 운명 속에서, 당신은 두 개의 흐릿한 환영을 마주한다.\n그것은 당신의 과거, 또 하나는 당신의 미래이다. 당신은 그것들로 나아가 손을 내밀었다……"
  },
  Event_125782_Name = {
    Text = "과거, 미래"
  },
  Event_125855_ChoiceDesc1 = {
    Text = "[감지] 유물 1개를 선택해 황금 유물 「(RelicConfig.Arg1)」(으)로 변환시키기"
  },
  Event_125855_ChoiceDesc2 = {
    Text = "[응시] 백은 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_125855_ChoiceDesc3 = {
    Text = "[무시] 검은 인장 25 획득하기"
  },
  Event_125855_Desc = {
    Text = "카살림의 거리에서, 한 수정 가게의 눈부신 빛이 당신의 시선을 끌었다. 당신은 가게 앞에 다가가 은심 모양의 수정 하나를 집어 들었다."
  },
  Event_125855_Name = {
    Text = "수정의 비밀"
  },
  Event_125856_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125856_Desc = {
    Text = "당신은 눈을 감고 그것을 세심하게 감지했다.\n한 줄기 미광이 당신의 의식 속에서 깜빡였다. 그것은 당신에게 무언가를 전하려 했다……"
  },
  Event_125856_Name = {
    Text = "수정의 비밀"
  },
  Event_125857_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125857_Desc = {
    Text = "운명에 대한 어떤 저항도, 엿봄도 헛된 것이다. 당신은 조용히 눈을 감고, 운명이 당신을 데려갈 곳으로 이끄는 대로 맡긴다."
  },
  Event_125857_Name = {
    Text = "속명의 거미줄"
  },
  Event_125858_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125858_Desc = {
    Text = "「감성은 존속의 의미이다. 부디 자신의 선택을 후회하지 않기를.」"
  },
  Event_125858_Name = {
    Text = "선택의 대가"
  },
  Event_125859_ChoiceDesc1 = {
    Text = "[감성] HP Arg1 회복하기"
  },
  Event_125859_ChoiceDesc2 = {
    Text = "[이성] 랜덤 명령 카드 1장에 각인 새기기: [(EnchantConfig.Arg1)]"
  },
  Event_125859_ChoiceDesc3 = {
    Text = "[선택 거부] 검은 인장 25 획득하기"
  },
  Event_125859_Desc = {
    Text = "무대 위에 천칭이 나타났다.\n「두뇌와 심장, 이성과 감성, 잿빛과 붉은빛……우리는 선택을 피할 수 없다, 이것이 우리의 운명이다.」\n「무대의 종착점은 이미 정해져 있다. 이제, 이 무대가 걸어갈 길을 선택하라.」"
  },
  Event_125859_Name = {
    Text = "선택의 대가"
  },
  Event_125860_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125860_Desc = {
    Text = "「고개를 들지 마. 이곳을 떠나.」\n당신은 운명의 목소리를 들었다. 하늘을 올려다보고 싶은 갈망이 간절했지만, 그녀가 옳다는 것을 알고 있었다."
  },
  Event_125860_Name = {
    Text = "올려다봄"
  },
  Event_125861_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125861_Desc = {
    Text = "당신은 결코 운명을 받아들이지 않는다. 결코 속박을 받아들이지 않는다.\n당신은 필사적으로 발버둥 치며, 나방의 사지 한 조각을 희생한 끝에, 마침내 탈출에 성공했다……"
  },
  Event_125861_Name = {
    Text = "속명의 거미줄"
  },
  Event_125862_ChoiceDesc1 = {
    Text = "[우정]검은 인장 50 획득"
  },
  Event_125862_ChoiceDesc2 = {
    Text = "[도움]검은 인장 75 획득, [(Skill.Arg2)]에 감염"
  },
  Event_125862_Desc = {
    Text = "술집 뒷골목에서 다시 그 검은 고양이들을 만났다.\n「들었어. 그 검은 점액이 우리 모습으로 변해서 꽤 곤란하게 했다며.」\n「사과의 의미로, 말해 봐. 뭘 원해?」\n검은 고양이가 네 다리 주위를 두 바퀴 돌더니 고개를 들어 너를 올려다본다."
  },
  Event_125862_Name = {
    Text = "첫 만남의 선물"
  },
  Event_125863_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125863_Desc = {
    Text = "무력으로는 운명을 풀 수 없지만, 어쩌면 지혜로는 가능할까?\n당신은 이 거미줄을 세심히 관찰하며, 그 속에서 운명의 궤적을 엿보려 한다……"
  },
  Event_125863_Name = {
    Text = "속명의 거미줄"
  },
  Event_125864_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125864_Desc = {
    Text = "당신은 다가가 그것을 자세히 응시했다.\n한 줄기 미광이 당신의 눈 속에서 깜빡였다. 그것은 당신에게 무언가를 전하려 했다……"
  },
  Event_125864_Name = {
    Text = "수정의 비밀"
  },
  Event_125865_ChoiceDesc1 = {
    Text = "[발버둥]덱에서 무작위로 지령 카드 3장을 가져와, 1장을 선택하여 삭제, 검은 인장 75 획득"
  },
  Event_125865_ChoiceDesc2 = {
    Text = "[사색]덱에서 무작위로 지령 카드 3장을 가져와, 1장의 원본 복제본을 덱에 추가, 검은 인장 25 획득"
  },
  Event_125865_ChoiceDesc3 = {
    Text = "[휴식]검은 인장 50 획득"
  },
  Event_125865_Desc = {
    Text = "익숙한 감각이 밀려온다. 다른 점이 있다면, 그 끈적한 촉감, 저항할 수 없다는 직감이 지난번보다 더 강렬하고, 더 치명적이라는 것.\n나방은 거미줄에 빠지고, 당신도 이미 무대에 발을 들였다."
  },
  Event_125865_Name = {
    Text = "속명의 거미줄"
  },
  Event_125866_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125866_Desc = {
    Text = "「이성은 존속의 수단이다. 부디 자신의 선택을 후회하지 않기를.」"
  },
  Event_125866_Name = {
    Text = "선택의 대가"
  },
  Event_125867_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125867_Desc = {
    Text = "호기심에 불이 붙었다. 당신은 인파 속으로 들어가 그들처럼 고개를 들었다.\n거기에는 아무것도 없었지만, 왜인지 모르게 시선을 내리고 싶지 않았다. 그저 이렇게 바라보고 싶었다, 계속 바라보고 싶었다……"
  },
  Event_125867_Name = {
    Text = "올려다봄"
  },
  Event_125868_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_125868_Desc = {
    Text = "「선택을 포기하는 것도 하나의 선택이다, 이것이 운명의 저주이지. 부디 자신의 선택을 후회하지 않기를.」"
  },
  Event_125868_Name = {
