  Event_125869_Desc = {
    Text = "「이제, 네 것이야.」\n검은 고양이가 네 종아리에 몸을 비비더니 금세 사라져 버렸다.\n그들이 사라진 자리에 선물 하나가 너를 기다리고 있다."
