  },
  Event_129177_Name = {
    Text = "별빛 이야기 제1장@"
  },
  Event_129178_ChoiceDesc1 = {
    Text = "[방향 지시]백은 유물 “(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_129178_ChoiceDesc2 = {
    Text = "[함께 기도하기]3선택 1 각인 두 번 획득"
  },
  Event_129178_Desc = {
    Text = "피아노와 파이프 오르간의 소리가 흐릿한 바람 속에서 얽혀 있습니다. 마치 마법 같은 멜로디가 사람이 없는 거리에서 떠돌고 있는 듯합니다.\n 한 무명의 수녀가 피아노 소리 속에서 기도합니다.\n “간단한 기도는 화려한 의식을 필요로 하지 않습니다. 위대한 아버지 신께서 우리에게 희망을 파종해 주실타래 것입니다. 그가 우리에게 성실타래한 가르침을 주셨던 것처럼.”"
  },
  Event_129178_Name = {
    Text = "관풍금의 기도"
  },
  Event_129179_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129179_Name = {
    Text = "별빛 이야기 제1장@"
  },
  Event_129180_ChoiceDesc1 = {
    Text = "【주동적으로 맞서다】저주받은 유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_129180_ChoiceDesc2 = {
    Text = "[저항을 포기하다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129180_ChoiceDesc3 = {
    Text = "[빨리 도망가기]획득: 50개의 검은 인장"
  },
  Event_129180_Desc = {
    Text = "몇 개의 왁스 조각 흙이 당신의 길을 막고 있다. \n그들은 비뚤어지고, 얼굴이 거칠며, 보기에 로저스가 만들었을 만한 수준이 아니다. \n“명령……대인의 명령……”"
  },
  Event_129180_Name = {Text = "습작"},
  Event_129181_ChoiceDesc1 = {
    Text = "【포기】저주받은 유물“(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염됩니다"
  },
  Event_129181_ChoiceDesc2 = {
    Text = "[영감 따라잡기]무작위 1장의 커맨드 카드에 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129181_Desc = {
    Text = "항구가 습격당하고, 돌아올 수 없는 신비로운 화물선과 지느러미가 있는 “새로운 친구”… 이것은 정교하게 준비된 함정인가? 아니면 또 다른 사고가 빈발하는 여행인가? \n 현실타래과 이성이 서로 끌어당기고 얽히며, 수많은 영감과 생각이 머릿속에서 쏟아져 나온다."
  },
  Event_129181_Name = {
    Text = "영감 폭발"
  },
  Event_129182_ChoiceDesc1 = {
    Text = "[합류]\"(Skill.Arg1)\" 감염 두 번, 무작위 카드 1장이 각인 획득: \"(EnchantConfig.Arg2)\" 두 번"
  },
  Event_129182_ChoiceDesc2 = {
    Text = "[쫓아내기]\"(Skill.Arg1)\" 감염 두 번, 무작위 카드 1장이 각인 획득: \"(EnchantConfig.Arg2)\" 두 번"
  },
  Event_129182_ChoiceDesc3 = {
    Text = "[무관심]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129182_Desc = {
    Text = "당신은 멀리서 희미하게 들려오는 뼈 나팔 소리를 듣습니다. \n 쥐 떼가 소리를 따라 검은 진흙 속에서 발현되어, 마른 강바닥에 누워 있는 무명 시체를 갉아먹고 있습니다. \n 그들은 원을 이루며, 원의 중심은 이미 비어 있는 유해이며, 원주변은 잊혀짐을 법으로 삼은 새로운 왕국입니다. \n 그리고 당신은 이 왕국의 입구에 서 있습니다."
  },
