  },
  Event_129186_ChoiceDesc1 = {
    Text = "[초상화 구하기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129186_ChoiceDesc2 = {
    Text = "[공백 받아들이기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129186_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_129186_Desc = {
    Text = "당신은 픽맨의 선물 앞에 서 있습니다. \n 그것은 피로 그려진 초상화이며, 칠흑 같은 불꽃이 조용히 타오르고 있습니다. \n 그림 속 인물의 텅 빈 눈구멍을 통해, 당신은—— \n 당신의 기억이 끓어오르며 타오르고, 길어지고, 왜곡되고, 빛나고 있습니다. 마치 어떤 무형의 불이 당신의 뇌 속 회랑을 핥고 있는 듯합니다. 멍하니 있을 때, 당신은 한 사람의 목소리를 듣습니다. \n “이제 냄비에 넣어야 해, 불이 딱 좋군.” \n 이것은 바로 당신이 그려낸 기억의 풍경으로, 당신은 불꽃 속에서 몸부림치며 변형되고 있습니다."
  },
  Event_129186_Name = {
    Text = "불타는 초상화"
  },
  Event_129187_ChoiceDesc1 = {
    Text = "[어떤 대가를 치르시겠습니까?]무작위로 1장의 카드의 각인 품질을 두 번 향상"
  },
  Event_129187_ChoiceDesc2 = {
    Text = "[그들에게 유통기한 지난 블러디 메리 한 잔을 대접하다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 두 번 감염"
  },
  Event_129187_Desc = {
    Text = "“환영합니다, 나의 소중한 손님. 마음껏 선택하세요, 이 모든 것들은 당신을 기다리기 위해 존재합니다.”\n“어, 실타래례합니다, 혹시 당신은… 다프다일 부인의 쌍둥이 자매인가요?”\n“저는 다프다일 본인입니다. 손님이 오늘 이곳에 오신 이유는 무엇인가요…?”\n“죄송합니다, 죄송합니다, 당신이 이전보다 더 매력적이어서 제가 알아보지 못했습니다. 기억하시나요? 20년 전, 당신이 제 바에서 한 괴물을 쫓아냈던… 어제, 악몽 재현이 되었고, 그것이 바를 점령했어요, 그것의 동족들과 함께, 떼 지어…”"
  },
  Event_129187_Name = {
    Text = "기억의 파편·옛 꿈 다시 보기"
  },
  Event_129188_ChoiceDesc1 = {
