  Event_129203_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129203_Name = {
    Text = "망각 제3장@"
  },
  Event_129204_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129204_Name = {
    Text = "망각 제6장@"
  },
  Event_129205_ChoiceDesc1 = {
    Text = "【그녀를 놓아주기】저주받은 유물 (RelicConfig.Arg1) 획득, (Skill.Arg2) 감염"
  },
  Event_129205_ChoiceDesc2 = {
    Text = "[그녀를 돕다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129205_ChoiceDesc3 = {
    Text = "[나는 나만의 길을 갈 거야]50개의 검은 인장 획득"
  },
  Event_129205_Desc = {
    Text = "세 사람의 그림자가 당신의 길을 막고 있습니다. \n “당신은 그녀를 놓아줄 수 있습니다,” 양손에 융식점액으로 더럽혀진 곰인형을 안고 있는 그림자가 말합니다, “그녀는 단지 겁이 많을 뿐, 악하지 않습니다. 그녀는 누구도 해치고 싶지 않아요.” \n “당신은 그녀를 도와줄 수 있습니다,” 양손에 정교하게 포장된 사탕을 쥐고 있는 그림자가 말합니다, “당신은 그녀가 할 수 없는 일을 할 수 있습니다, 당신은 이 모든 것을 끝낼 수 있습니다.” \n “당신은 우리의 말을 들을 필요가 없습니다,” 양손이 텅 빈 그림자가 말합니다, “당신은 당신만의 길이 있습니다.”"
  },
  Event_129205_Name = {
    Text = "분기된 작은 길"
  },
  Event_129206_ChoiceDesc1 = {
    Text = "[쥐에게 먹이 주기]백은 유물「(RelicConfig.Arg1)」을 획득하고, 1번 증상을 선택하여 감염합니다"
  },
  Event_129206_ChoiceDesc2 = {
    Text = "[쥐 쫓기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", 두 번 반복, \"(Skill.Arg2)\" 감염, 두 번 반복"
  },
  Event_129206_ChoiceDesc3 = {
    Text = "[쥐를 무시하기]25 검은 인장 획득"
  },
  Event_129206_Desc = {
    Text = "이 배 위의 모든 것은 윤회하고 있다.\n배 위에서 살아가는, 혐오스럽고 더러운 솜털로 뒤덮인 작은 것들도 자연히 이런 운명을 피할 수 없었다.\n한 번 또 한 번의 윤회 속에서, 그것들은 눈에 보이는 모든 것을 먹어치웠지만, 여전히 만족할 수 없었다.\n「배……고파……」\n쥐떼가 병적이고 귀를 찢는 듯한 비명을 질렀다.\n거듭되는 윤회가 그것들을 참을 수 없이 굶주리게 만들었고, 무언가를 먹어야만 했다.\n당장, 지금 즉시!"
  },
  Event_129206_Name = {
    Text = "굶주린 쥐떼"
  },
  Event_129207_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129207_Name = {
    Text = "망각 제8장@"
  },
  Event_129208_ChoiceDesc1 = {
    Text = "[뇌 만지기]무작위 커맨드 카드 1장이 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129208_ChoiceDesc2 = {
    Text = "【심장을 만지다】Arg1 포인트 최대 생명을 증가시키고, 감염「(Skill.Arg2)」"
  },
  Event_129208_Desc = {
    Text = "당신은 아무도 저어하지 않는 회색 홀로 들어갑니다. 그곳에는 검은 안개 속에서 희미하게 보이는 저울이 있습니다. \n 왼쪽에는 호수처럼 고요한 뇌가 있으며, 은백색의 골짜기가 희미하게 빛나고 있습니다; 오른쪽에는 불타는 듯한 붉은 심장이 열기를 뿜어내고 있습니다. \n 갑자기 당신은 향기를 맡습니다. 갈망하는 욕망이 계속해서 팽창하고, 이성은 그 무한한 어둠에 압도당합니다. \n 당신은 손을 내밀었습니다."
  },
  Event_129208_Name = {
    Text = "헝거 게임"
  },
  Event_129209_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129209_Name = {
    Text = "망각 제4장@"
  },
  Event_129210_ChoiceDesc1 = {
    Text = "[인영 베어 쓰러뜨리기]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129210_ChoiceDesc2 = {
    Text = "[배아 으스러뜨리기]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129210_ChoiceDesc3 = {
    Text = "[양 눈을 감다]25 검은 인장 획득"
  },
  Event_129210_Desc = {
    Text = "혼란스러운 가운데 당신은 아란에서 본 사람들을 가까이에서 보게 됩니다.\n 그들은 웃으며 당신에게 술을 마시고, 춤추고, 맛있는 음식을 맛보라고 초대합니다.\n 그 후 그들의 혈육이 겹겹이 벗겨지고, 떨어진 것들은 다시 새로운 배아로 기어 나옵니다.\n 그들은 당신에게 손을 내밀며 혈육과 신생의 환희에 참여하라고 초대합니다."
  },
  Event_129210_Name = {
    Text = "옛날의 그림자"
  },
  Event_129211_ChoiceDesc1 = {
    Text = "【그들에게 먹이 주기】은색 유물「(RelicConfig.Arg1)」를 획득하고, 1회 증상 감염 선택"
  },
  Event_129211_ChoiceDesc2 = {
    Text = "[신경 쓰지 않기]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129211_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_129211_Desc = {
    Text = "거주자는 오고 가지만, 쥐 떼는 오랫동안 지속됩니다.\n인간과 비교하면, 그들이 이 성의 “원주민”입니다.\n하지만 그들은 인간의 침입에 대해 이의를 제기하지 않습니다.\n왜냐하면 그 맛있고 부드러운, 하얗고 연약한 추한 것들이 그들에게 똑같이 맛있고 부드러운, 하얗고 연약한 추한 것들을 제공하기 때문입니다.\n“그리고 너, 추한 것, 어떤 종류에 속하니?”"
  },
  Event_129211_Name = {
    Text = "성의 비밀"
  },
