  },
  Event_129213_ChoiceDesc1 = {
    Text = "【남자의 목소리를 구분하기】덱에서 무작위로 3장의 명령 카드를 획득하고 1장을 선택하여 복제합니다"
  },
  Event_129213_ChoiceDesc2 = {
    Text = "[여자의 목소리 분별하기]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129213_ChoiceDesc3 = {
    Text = "[노인의 목소리를 구분하기]25개의 검은 인장을 획득"
  },
  Event_129213_Desc = {
    Text = "당신은 혼자서 한 무리의 다크 늪에 서 있습니다.\n 흐릿한 사이에 혼돈이 교차하는 꿈결의 속삭임이 밀려옵니다. 어떤 것은 노인으로부터, 어떤 것은 갓 말을 배우는 아이에게서, 어떤 것은 불안한 여자에게서, 어떤 것은 이유 없는 공포를 느끼는 남자에게서 옵니다…"
  },
  Event_129213_Name = {
    Text = "유언부언"
  },
  Event_129214_ChoiceDesc1 = {
    Text = "[자세히 살펴보다]3선1 각인 두 번 획득"
  },
  Event_129214_ChoiceDesc2 = {
    Text = "[포스터를 뜯다]무작위 1장의 커맨드 카드가 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 두 번 감염"
  },
  Event_129214_Desc = {
    Text = "왁스상관 내에서 흔히 볼 수 있는 촛대입니다. \n기괴한 주황빛을 빌려, 벽에 붙어있는 손그림 포스터를 발견했습니다."
  },
  Event_129214_Name = {
    Text = "어둠 속의 웃음소리"
  },
  Event_129215_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129215_Name = {
    Text = "망각 제4장@"
  },
  Event_129216_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
