  Event_129216_Name = {
    Text = "망각 제7장@"
  },
  Event_129217_ChoiceDesc1 = {
    Text = "[응시]백은 유물 「(RelicConfig.Arg1)」을 획득하고, 「(Skill.Arg2)」에 감염되었습니다"
  },
  Event_129217_ChoiceDesc2 = {
    Text = "[무시하기]3선택 1 각인 두 번 획득"
  },
  Event_129217_Desc = {
    Text = "아란인이 사막 폭풍 속에서 구복했다. \n폭풍이 그들의 외피를 차고, 모래가 그들의 경건한 마음을 휩쓸었다. \n모래 먼지의 소용돌이 속에는 수많은 거대한 눈이 왜곡된 대지를 내려다보는 것 같았다."
  },
  Event_129217_Name = {
    Text = "모래먼지 거인"
  },
  Event_129218_ChoiceDesc1 = {
    Text = "[나비 쫓기]무작위 커맨드 카드 1장이 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129218_ChoiceDesc2 = {
    Text = "[소원 듣기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129218_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_129218_Desc = {
    Text = "작고 귀여운 나비는 많은 꿈을 가지고 있습니다.\n이 꿈들은 꽃바다, 병실타래, 그리고 많은 혈육으로 가득 찬 @2 제단에 흩어져 있습니다.\n이제, 그것은 마침내 얽매인 사람을 기다리게 되었습니다. 당신이 그 작은, 작은 소원을 들어줄 의향이 있는지 모르겠습니다."
  },
  Event_129218_Name = {
    Text = "나비의 꿈"
  },
  Event_129219_ChoiceDesc1 = {
    Text = "[안내 따르기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", 두 번 반복, \"(Skill.Arg2)\" 감염, 두 번 반복"
  },
  Event_129219_ChoiceDesc2 = {
    Text = "[안내 무시]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", 두 번 반복, \"(Skill.Arg2)\" 감염, 두 번 반복"
  },
  Event_129219_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_129219_Desc = {
    Text = "제전이 이미 시작되었다.\n영의 불꽃과 피의 축도 아래, 셀 수 없는 신도들의 영혼이 항로표로 변했다——\n아련한 영들이 당신 주위에 흩어져, 마치 길을 인도하는 정령처럼 빛을 내며 당신의 선택을 기다린다."
  },
  Event_129219_Name = {
    Text = "영혼 항로표"
  },
  Event_129220_ChoiceDesc1 = {
    Text = "[벨소리 무시]3선택 1 고급 각인 두 번 획득"
  },
  Event_129220_ChoiceDesc2 = {
    Text = "【수화기를 들다】황금 유물「(RelicConfig.Arg1)」을 얻고, 감염「(Skill.Arg2)」"
  },
  Event_129220_ChoiceDesc3 = {
    Text = "[떠나다]50 검은 인장을 획득"
  },
  Event_129220_Desc = {
    Text = "그것은 울릴 이유가 없었다—— 그 전화는 캔버스 뒤에 웅크리고 있었다. \n 수화기의 선은 덩치 큰 본체에 포박되어 있었고, 마치 녹슨 제대줄처럼 당신의 뇌에서 뻗어나오는 듯했다. \n 당신은 진동의 주파수를 면밀히 구별하며, 기괴한 소리는 픽맨의 초현실타래적인 예술을 연상시켰다."
  },
  Event_129220_Name = {
    Text = "부재중 전화"
  },
  Event_129221_ChoiceDesc1 = {
    Text = "[우리는 모두 평안합니다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 두 번 감염"
  },
  Event_129221_ChoiceDesc2 = {
    Text = "[당신은 누구입니까?]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 두 번 감염"
  },
  Event_129221_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_129221_Desc = {
    Text = "타자기가 갑자기 잉크를 뿜어내고, 위에 있는 느낌표가 눈부실타래 정도로 많았다.\n“돌, 괜찮아??? 왜 수호자가 사라졌을 때 너도 사라졌어!!! 제발 안전하다는 메시지를 남겨줘!!! 더 기다리면 윌리엄의 머리카락이 다 빠질 거야!!!”"
  },
  Event_129221_Name = {
    Text = "긴급 통신"
  },
  Event_129222_ChoiceDesc1 = {
