  },
  Event_129227_ChoiceDesc1 = {
    Text = "[손 흔들어 쫓기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129227_ChoiceDesc2 = {
    Text = "[임의로 머물기]백은 유물 “(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염됩니다"
  },
  Event_129227_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_129227_Desc = {
    Text = "어둠 속에서 가벼운 소리가 들려왔다.\n그것은 한 마리 나비가 예의 바르게 묻는 소리였다.\n「당신의 손바닥에 내려앉아도 될까요?」\n「너무 지쳐서, 잠시 쉬고 싶을 뿐이에요……」\n그렇게 묻는 나비는 어둠을 뚫고 당신의 앞에서 맴돌았다.\n칠흑의 점액이 나비의 날개에서 떨어졌다—그것은 나비가 어둠을 통과할 때, 어둠이 준 선물이었다."
  },
