  },
  Event_129234_ChoiceDesc1 = {
    Text = "[손바닥 긋기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129234_ChoiceDesc2 = {
    Text = "【성장을 수용하다】은색 유물「(RelicConfig.Arg1)」을 얻고, 감염「(Skill.Arg2)」"
  },
  Event_129234_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_129234_Desc = {
    Text = "그 나비는 날아온 것이 아니라 당신의 손바닥에서 천천히 자라났습니다.\n당신은 처음에 그것이 단지 땀이라고 생각했지만, 손가락 사이에서 검은 액체가 혈관처럼 조용히 흘러나와 차갑고 맥박이 뛰는 날개로 응결되는 것을 보았습니다.\n매번 퍼덕일 때마다 당신의 피 속에서 잔물결이 일어났습니다."
  },
  Event_129234_Name = {
    Text = "기생상류"
  },
  Event_129235_ChoiceDesc1 = {
    Text = "[계속 넘기다]무작위 1장의 커맨드 카드가 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129235_ChoiceDesc2 = {
    Text = "【떠나다】Arg1 포인트 최대 생명 증가, 감염“(Skill.Arg2)”"
  },
  Event_129235_Desc = {
    Text = "무게를 재기 위한 저울입니다. \n그 뒤에는 수많은 장기가 붉은 포름알데히드에 담가져 있습니다. \n그들은 정갈하게 선반 위에 쌓여 있습니다. \n당신은 옆에 놓인 노트를 집어 들고 펼쳐봅니다: \n“심장: 226.8g, 뇌: 1417.5g……”"
  },
  Event_129235_Name = {
    Text = "기관 등록"
  },
  Event_129236_ChoiceDesc1 = {
    Text = "[우회 경로]1장의 명령 카드 삭제, [Arg1]개의 검은 인장 획득"
  },
  Event_129236_ChoiceDesc2 = {
    Text = "【질문을 묻다 왜 가라앉았는지】명령 카드 1장을 복제하고, “(Skill.Arg1)”에 감염합니다"
  },
  Event_129236_ChoiceDesc3 = {
    Text = "[선원에게 인사하기]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129236_Desc = {
    Text = "동력실타래로 향하는 길에서 다시금 몇몇 “기억”들을 만났다. \n그들은 유령이 아니요, 엘튼 선장이 사라진 선원들에 대한 애틋함이다."
  },
  Event_129236_Name = {
