  Event_129241_Name = {
    Text = "별빛 제4장@"
  },
  Event_129242_ChoiceDesc1 = {
    Text = "[그를 위해 연주하기]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129242_ChoiceDesc2 = {
    Text = "[피아노 소리 듣기]광기치가 50 이상인 깨어남체마다 15개의 검은 인장을 획득"
  },
  Event_129242_ChoiceDesc3 = {
    Text = "[떠나기]3선택 1 각인 두 번 획득"
  },
  Event_129242_Desc = {
    Text = "「사랑하는 존:\n    당신이 우리를 위해 피아노 연주를 한 지 수년이 흘렀다는 것을 최근에 갑자기 깨달았습니다.\n    올해 81세입니다. 나이가 들수록 젊은 시절의 회상이 얼마나 소중한지 더욱 느끼게 됩니다.\n    이 편지를 확인하셨다면, 다음에 렌티니언을 지나갈 때 제 아파트 앞에서 잠시 멈춰서 한 곡 연주해주실타래 수 있겠습니까?」"
  },
