  },
  Event_129244_Desc = {
    Text = "주황색 그물이 공중에서 조용히 떠다니고 있다. 그 구멍은 드물고, 벽 모서리에 사는 거미의 먼 친척보다 훨씬 정교하지 않다.\n 당신은 손을 뻗어 만지고 싶어지며, 손상된 그물은 순간적으로 용해되고, 아이들의 웃음소리가 당신의 귀에 울려 퍼진다.\n “금의 은의 노란색의 빨간색의, 모든 지갑은 우리의 것이다!”"
  },
  Event_129244_Name = {
    Text = "미로 네트워크"
  },
  Event_129245_ChoiceDesc1 = {
    Text = "【감성 선택하기】Arg1 생명 복구"
  },
  Event_129245_ChoiceDesc2 = {
    Text = "[이성 유지하기]무작위 1장의 커맨드 카드에 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129245_ChoiceDesc3 = {
    Text = "[선택 거부하기]25 검은 인장 획득"
  },
  Event_129245_Desc = {
    Text = "「선택해라, 선택해라.」\n질주하는 어둠 속에서 수많은 속삭임이 들려왔다.\n이 목소리는 부드럽고 최면적인 힘을 가진 듯하여, 당신에게 어떤 광기의 환상을 불러일으키며\n당신의 뇌는 광란에 빠져 몸에서 이탈하며, 심장은 어딘가에서 의식을 가진 듯이 당신을 향해 외쳤다.\n「선택해라, 선택해라.」\n「이성을 유지할 것인가 아니면 감성을 따를 것인가, 당신은 반드시 선택해야 한다.」"
  },
  Event_129245_Name = {
    Text = "인류의 대가"
  },
  Event_129246_ChoiceDesc1 = {
    Text = "【희생물 소멸】저주받은 유물「(RelicConfig.Arg1)」을 획득하고, 「(Skill.Arg2)」에 감염됩니다"
  },
  Event_129246_ChoiceDesc2 = {
    Text = "[밧줄 풀기]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129246_ChoiceDesc3 = {
    Text = "[계속 전진]50 검은 인장 획득"
  },
  Event_129246_Desc = {
    Text = "세 명의 아란인이 고대 위에 묶여 있었다.\n그들의 몸에는 당신이 영아의 몸에 보았던 나무 껍질 같은 어두운 무늬가 떠오르고 있었으며, 입으로 중얼중얼 말을 하고 있었다."
  },
  Event_129246_Name = {
    Text = "세 개의 제물"
  },
  Event_129247_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129247_Name = {
    Text = "별의 이야기 제3장@"
  },
  Event_129248_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129248_Name = {
    Text = "망각 제6장@"
  },
  Event_129249_ChoiceDesc1 = {
    Text = "[발버둥치며 앞으로]명령 카드 1장을 삭제, Arg1개의 검은 인장 획득"
  },
  Event_129249_ChoiceDesc2 = {
    Text = "【실타래을 끊다】복제 1장의 명령 카드, 감염 「(Skill.Arg1)」"
  },
  Event_129249_ChoiceDesc3 = {
    Text = "[참고 기다리기]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129249_Desc = {
    Text = "길을 따라 당신은 밀려서 나아가고, 당신의 모든 선택은 무형의 실타래에 의해 조종당하고 있습니다.\n 당신은 손을 힘껏 움직이며, 소중한 모든 것을 잡으려 합니다.\n 세계의 운명이 당신의 손끝에 걸려 있습니다.\n 수많은 실타래이 엉켜와 당신의 전신을 포박합니다."
  },
  Event_129249_Name = {
    Text = "조작당한 양손"
  },
  Event_129250_ChoiceDesc1 = {
    Text = "[길을 묻다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 두 번 감염"
  },
  Event_129250_ChoiceDesc2 = {
    Text = "[그것을 떠나기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_129250_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_129250_Desc = {
    Text = "그림자가 가늘고 긴 가로등 아래 서 있다. \n“불 좀 빌릴 수 있을까요, 선생님.” \n당신은 @2의 습관이 없지만, 작은 “마법”을 사용하는 것에 개의치 않는다. \n당신의 도움으로 그림자는 점화된 @2를 보이지 않는 깊은 검은 소용돌이 속으로 넣었다. \n잠시 후, 당신은 하얀 연기가 치솟는 것을 보았다. \n“아——” \n그림자는 기쁜 한숨을 내쉬었다."
  },
  Event_129250_Name = {
    Text = "가로등 아래의 그림자"
  },
  Event_129251_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129251_Name = {
    Text = "망각 제1장@"
  },
  Event_129252_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129252_Name = {
    Text = "망각 제8장@"
  },
  Event_129253_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129253_Name = {
    Text = "망각 제3장@"
  },
  Event_129254_ChoiceDesc1 = {
    Text = "[환각을 받아들이다]무작위 1장의 커맨드 카드가 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 두 번 감염"
  },
  Event_129254_ChoiceDesc2 = {
    Text = "[환각을 부정하다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129254_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_129254_Desc = {
    Text = "무거운 어둠의 철제 다리 아래, 갈대가 무성한 고요한 강가에서 갑자기 반짝이는 나비 한 마리가 날아올랐다.\n나비는 가볍게 당신의 손바닥에 내려앉았고, 끔찍한 울부짖음이 멈추고, 대신 기차가 녹슨 강철 구조물을 지나가는 굉음, 석탄이 타는 팝팝 소리, 바퀴축이 돌아가는 금속 마찰 소리가 들려왔다……"
  },
  Event_129254_Name = {
    Text = "철도의 환상"
  },
  Event_129255_ChoiceDesc1 = {
    Text = "[거부 선택하기]1장의 명령 카드를 삭제하고 Arg1 검은 인장 획득"
  },
  Event_129255_ChoiceDesc2 = {
    Text = "【준수 선택하기】1장의 명령 카드를 복사하고, 감염「(Skill.Arg1)」"
  },
  Event_129255_ChoiceDesc3 = {
    Text = "[포옹 선택]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129255_Desc = {
    Text = "“나는 여러 방이 가득한 마당에 갇힌 새다.”\n어둠 속에서 희미한 그림자가 떠돌고 있는데, 그것은 떠난 자들이 남긴 집착이다.\n“그들은 그것이 정신병원이라고 하지만, 나는 그것이 사회 규칙을 따르기를 거부하는 자유로운 새들을 가두는 인간의 특별한 감옥이라는 것을 안다.”\n“하지만 새가 날 수 없다면, 여전히 새라고 할 수 있을까?”\n집착들이 당신에게 다가와 구원을 간청한다.\n“내 날개를 부러뜨려 줘, 나는 날아다니는 것에 지쳤다.”"
  },
  Event_129255_Name = {
    Text = "마음이 허한 사람"
  },
  Event_129256_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129256_Name = {
    Text = "망각 제2장@"
  },
  Event_129257_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129257_Name = {
    Text = "별의 이야기 제2장@"
  },
  Event_129258_ChoiceDesc1 = {
    Text = "[나비 날려보내기]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129258_ChoiceDesc2 = {
    Text = "[나비가 되다]백은 유물“(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염됩니다"
  },
  Event_129258_ChoiceDesc3 = {
    Text = "[배로 삼키기]25개의 검은 인장을 획득"
  },
  Event_129258_Desc = {
    Text = "이 밤에는 너무 많은 일이 일어났습니다. \n 부두 습격, 유령 화물선, 해양도약자, 툴루, 머피, 라모나…… 모든 것이 소용돌이 속에서 회전하며, 미사그 레스토랑 아침 7시의 오트밀로 뒤섞였습니다. \n 눈앞의 깨어남체에게 질문하고 싶으나, 도대체 어떻게 시작해야 할지 모르겠고, 목에 걸린 것처럼—— 아니면, 위 속의 나비처럼."
  },
  Event_129258_Name = {
    Text = "버터플라이 이펙트"
  },
  Event_129259_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129259_Name = {
    Text = "망각 제8장@"
  },
  Event_129260_ChoiceDesc1 = {
    Text = "[그대로 머물게 두다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 두 번 감염"
  },
  Event_129260_ChoiceDesc2 = {
    Text = "[손을 흔들어 쫓아내기]백은 유물“(RelicConfig.Arg1)”을(를) 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_129260_ChoiceDesc3 = {
    Text = "[접근 나비]획득: 25개의 검은 인장"
  },
  Event_129260_Desc = {
    Text = "당신들은 차가운 바람이 휘몰아치는 요양원 안에서, 이 계절에 존재해서는 안 되는 검은색 나비가 날아왔습니다. \n 나비의 날개는 검은 슬라임을 끌며 높낮이로 흔들리며 날아갔고, 날개에서 흘러나온 층층의 검은 액체는 굳어진 후 바람에 의해 벗겨졌습니다. \n 그것은 지쳐서 당신의 손끝에 멈추었습니다."
  },
  Event_129260_Name = {
    Text = "존재하지 않아야 할 것"
  },
  Event_129261_ChoiceDesc1 = {
    Text = "[과거 회상]3개 중 1개 선택 고급 각인 획득, 두 번 반복"
  },
  Event_129261_ChoiceDesc2 = {
    Text = "[미래 엿보기]황금 유물 \"(RelicConfig.Arg1)\" 획득, \"(Skill.Arg2)\" 감염"
  },
  Event_129261_ChoiceDesc3 = {
    Text = "[떠나다]50 검은 인장을 획득"
  },
  Event_129261_Desc = {
    Text = "세상에 영원히 변하지 않는 것은 없다.\n신모가 만든 낙원이라 해도 마찬가지다.\n짧은 찰나, 당신은 시공 균열 속에서 무언가를 엿보았다.\n과거, 현재, 미래가 균열로 가득한 틈새 속에서 뒤얽히며 끊임없이 변화하고 있었다.\n당신의 호기심 어린 엿봄을 기다리며."
  },
  Event_129261_Name = {
    Text = "시공 균열"
  },
  Event_129262_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129262_Name = {
    Text = "망각 제7장@"
  },
  Event_129263_ChoiceDesc1 = {
    Text = "[무시하기]3선택 1 각인 두 번 획득"
  },
  Event_129263_ChoiceDesc2 = {
    Text = "[건드리기]무작위 커맨드 카드 1장이 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129263_Desc = {
    Text = "포자와 유사한 이상한 것이 당신의 주목을 끌었습니다.\n 그것은 혈육으로 이루어진 가느다란 해파리처럼 보이며, 또 뇌 깊숙한 곳에 신호를 저장하고 있는 신경 섬유 같습니다.\n “나를 만져봐.” 그것이 당신을 조용히 유혹하며 말합니다. “나는 당신에게 잔인한 기억을 보여줄 것입니다.”"
  },
  Event_129263_Name = {
    Text = "딥 메모리"
  },
  Event_129264_ChoiceDesc1 = {
    Text = "[환상에 빠지기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 감염 두 번"
  },
  Event_129264_ChoiceDesc2 = {
    Text = "[이성 유지]광기치가 50 이상인 깨어남체마다 15 검은 인장을 획득합니다"
  },
  Event_129264_ChoiceDesc3 = {
    Text = "[강제로 떠나기]3선택 1 각인 획득, 두 번 반복"
  },
  Event_129264_Desc = {
    Text = "아마도 오랜 전투가 당신을 몽롱하게 만든 것일 수도 있고, 단지 당신의 뇌가 몸을 배신한 것일 수도 있습니다.\n어떤 무중력감이 당신의 머릿속에 나타납니다.\n순간, 당신의 머릿속이 갑자기 만회경으로 변하며, 찬란하고, 화려하며, 오색찬란한 빛이 반짝입니다.\n셀 수 없는 영감, 미혹, 광상이 뇌 속으로 밀려들어, 당신 뇌의 구석구석을 차지합니다.\n이대로 계속되면, 당신의 머리는 곧 이 뒤죽박죽인 것들로 터져버릴 것입니다."
  },
  Event_129264_Name = {
    Text = "사고 만회경"
  },
  Event_129265_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129265_Name = {
    Text = "망각 제5장@"
  },
  Event_129266_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129266_Name = {
    Text = "망각 제4장@"
  },
  Event_129267_ChoiceDesc1 = {
    Text = "[듣기]3선택 1 고급 각인 두 번 획득"
  },
  Event_129267_ChoiceDesc2 = {
    Text = "[외침]황금 찍유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_129267_ChoiceDesc3 = {
    Text = "[떠나다]50 검은 인장을 획득"
  },
  Event_129267_Desc = {
    Text = "사고가 발생한 이후, 당신은 파트너의 소식을 더 이상 듣지 못했습니다.\n수많은 연락이 발신되었지만, 마치 돌이 바다에 가라앉듯 아무런 응답이 없었습니다.\n당신이 더 이상 희망을 품지 않을 때, 연락기가 갑자기 소리를 냈습니다.\n당신은 가방을 열고 전화기를 귀에 대었습니다.\n\"수호자……\"\n몽롱한 가운데, 당신은 그리워하던 목소리를 들었습니다. 마치 여러 겹의 허공을 가로질러 멀리서 회상처럼 들려왔습니다."
  },
  Event_129267_Name = {
    Text = "사랑의 여운"
  },
  Event_129268_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129268_Name = {
    Text = "망각 제1장@"
  },
  Event_129269_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129269_Name = {
    Text = "별빛 이야기 제1장@"
  },
  Event_129270_ChoiceDesc1 = {
    Text = "【헬독의 출처를 직시하다】황금 유물 「(RelicConfig.Arg1)」을 획득하고, 「(Skill.Arg2)」에 감염되다"
  },
  Event_129270_ChoiceDesc2 = {
    Text = "[전투에 집중하다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129270_Desc = {
    Text = "헬독의 윤곽이 변화하고 있다. \n그의 신체는 벽의 틈새와 연결되어 기이한 환상을 드러낸다."
  },
  Event_129270_Name = {
    Text = "각도에서"
  },
  Event_129271_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129271_Name = {
    Text = "망각 제2장@"
  },
  Event_129272_ChoiceDesc1 = {
    Text = "【종이 조합】황금 유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_129272_ChoiceDesc2 = {
    Text = "[읽다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번"
  },
  Event_129272_ChoiceDesc3 = {
    Text = "[버리기]50 검은 인장 획득"
  },
  Event_129272_Desc = {
    Text = "한 장의 누렇게 변색된 종이가 등불 교도들의 겉옷 아래에서 떨어졌다.\n종이 위에는 괴상한 텍스트가 빽빽하게 적혀 있었고, 일부는 상형 문자처럼 보였으며, 일부는 이상하게 위로 올라갔고, 일부 글자는 심지어 겹쳐져 있어서 겨우 몇 개의 글자만 알아볼 수 있었다.\n제목은 《@2 성자의 탄생》"
  },
  Event_129272_Name = {
    Text = "밀령·하"
  },
  Event_129273_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129273_Name = {
    Text = "망각 제2장@"
  },
  Event_129274_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129274_Name = {
    Text = "별의 이야기 제2장@"
  },
  Event_129275_ChoiceDesc1 = {
    Text = "[전투 준비]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", 두 번 반복, \"(Skill.Arg2)\" 감염, 두 번 반복"
  },
  Event_129275_ChoiceDesc2 = {
    Text = "[우회 시도]25개의 검은 인장 획득"
  },
  Event_129275_Desc = {
    Text = "별빛이 드리우는 심해 속에서, 답해자들은 수천 년의 세월을 잠복해왔다.\n무한한 바닷물은 그들의 광기를 목격했고, 그들의 인내를 목격했으며, 신에 대한 가장 경건한 신앙도 목격했다.\n아무도 신의 위대한 강림을 막을 수 없다.\n방해하는 자는 모두 답해자의 분노 속에서 잿더미로 변할 것이다."
  },
  Event_129275_Name = {
    Text = "별빛 아래의 기다림"
  },
  Event_129276_ChoiceDesc1 = {
    Text = "[몇 개의 음을 탄다]백은 유물“(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염됩니다"
  },
  Event_129276_ChoiceDesc2 = {
    Text = "[뚜껑 닫기]3선1 각인 2회 획득"
  },
  Event_129276_Desc = {
    Text = "벽 옆의 피아노는 뚜껑이 열려 있다. 노란색으로 변색된 건반과 나무 색깔이 드러난 갈라진 가장자리를 가지고 있지만, 각 건반은 매우 깨끗이 닦여 있다. \n그것은 많은 사람들의 행복의 원천이다."
  },
  Event_129276_Name = {
    Text = "어린 시절의 멜로디"
  },
  Event_129277_ChoiceDesc1 = {
    Text = "[환각을 받아들이다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 두 번 감염"
  },
  Event_129277_ChoiceDesc2 = {
    Text = "[부정의 환각]은 백은 유물“(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염됩니다"
  },
  Event_129277_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_129277_Desc = {
    Text = "무거운 어둠의 철제 다리 아래, 갈대가 무성한 고요한 강가에서 갑자기 반짝이는 나비 한 마리가 날아올랐다.\n나비는 가볍게 당신의 손바닥에 내려앉았고, 끔찍한 울부짖음이 멈추고, 대신 철근을 운반하는 노동자들의 규칙적인 구호 소리, 망치로 두드리는 소리, 리벳이 부딪히는 청명한 금속 소리가 들려왔다……"
  },
  Event_129277_Name = {
    Text = "강철 다리의 환각"
  },
  Event_129278_ChoiceDesc1 = {
    Text = "[저주를 보여주다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\" 두 번, \"(Skill.Arg2)\" 두 번 감염"
  },
  Event_129278_ChoiceDesc2 = {
    Text = "[까마귀를 거부하다]3선1 각인 두 번 획득"
  },
  Event_129278_ChoiceDesc3 = {
    Text = "【무시】"
  },
  Event_129278_Desc = {
    Text = "검은색이고 병든 여러 개의 머리를 가진 까마귀가 등불 교도의 검은 망토에서 날아나와 당신의 어깨에 앉는다. \n“내 머리 보이세요? 저주를 맛보면 새로운 머리가 생깁니다. 저주를 보여주세요!”"
  },
  Event_129278_Name = {
    Text = "저주받은 까마귀"
  },
  Event_129279_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129279_Name = {
    Text = "망각 제7장@"
  },
  Event_129280_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129280_Name = {
    Text = "망각 제3장@"
  },
  Event_129281_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129281_Name = {
    Text = "망각 제4장@"
  },
  Event_129282_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129282_Name = {
    Text = "망각 제2장@"
  },
  Event_129283_ChoiceDesc1 = {
    Text = "[자리 표시]임시 텍스트."
  },
  Event_129283_Name = {
    Text = "별의 이야기 제2장@"
  },
  Event_129900_ChoiceDesc1 = {
    Text = "[안장] HP를 Arg2[ExDesc1] 회복하고, 명령 카드 1장 선택 후 삭제하기"
  },
  Event_129900_ChoiceDesc2 = {
    Text = "[기도]황금 유물 「(RelicConfig.Arg1)」을/를 획득하고, 「(Skill.Arg2)」에 감염됩니다."
  },
  Event_129900_Desc = {
    Text = "창백한 뼈 한 무더기가 검은 융식액에 반쯤 묻혀있다."
  },
  Event_129900_Name = {
    Text = "빛바랜 유골"
  },
  Event_130337_ChoiceDesc1 = {
    Text = "[착석] [꼭두각시 인형]을 덱에 넣는다."
  },
  Event_130337_Desc = {
    Text = "두 발이 극장의 계단을 밟는 순간, 시선은 더 이상 이 무대에서 떠날 수 없게 되었다.\n운명의 실타래이 강의 모래알만큼 무수한 이야기를 이끌어 이곳에서 흘러간다—과거의 먼지, 지금 이 순간의 빛과 그림자, 미래의 안개가 모두 무대 앞에서 끊임없이 소용돌이친다.\n당신은 자신이 어디에서 왔는지, 어디로 가고 싶은지를 잊었고, 「자아」에 대한 흔적은 장막의 그림자 속에서 녹아 사라졌다. 이 순간, 당신은 객석의 침묵하는 관객이자, 무대 위에서 불타는 배우이다.\n당신 존재의 모든 의미가 두 줄기 각인으로 붕괴한다: 응시, 그리고 헌연."
  },
  Event_130337_Name = {
    Text = "숙명의 무대"
  },
  Event_131264_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_131264_Desc = {
    Text = "당신들은 힘을 선택했고, 굳건한 신념과 앞으로 나아가는 용기를 선택했다.\n하지만, 대가……대가가 존재하는 의미는 감당하기 위한 것, 그렇지 않은가?"
  },
  Event_131264_Name = {
    Text = "옛날의 응시"
  },
  Event_131265_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_131265_Desc = {
    Text = "당신은 머릿속의 고통을 견디며, 흩어지고 부서지는 기억들을 힘껏 움켜쥐었다. 당신의 힘겨운 인내 끝에 균열이 봉합되기 시작했다.\n당신은 기억하기 위해 떠났고, 기억하기 위해 싸운다. 어떤 기억도 자신을 떠나는 것을 허락하지 않을 것이다."
  },
  Event_131265_Name = {
    Text = "부서진 기억"
  },
  Event_131266_ChoiceDesc1 = {
    Text = "[기억을 보호]3택 1 각인 획득"
  },
  Event_131266_ChoiceDesc2 = {
    Text = "[균열을 저지]3장의 지령 카드 중 1장을 선택하여 각인 획득: 「(EnchantConfig.Arg1)」, 감염 「(Skill.Arg2)」"
  },
  Event_131266_Desc = {
    Text = "당신은 자신의 기억을 의심한 적이 없었다. 그것들은 따뜻하고 견고하며, 가장 믿을 수 있는 항구이자 가장 소중한 보물이었다.\n하지만 지금, 심연옥의 간섭 아래 그 기억들에 혼란스러운 균열이 나타나기 시작했다."
  },
  Event_131266_Name = {
    Text = "부서진 기억"
  },
  Event_131267_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_131267_Desc = {
    Text = "정신의 힘이 머릿속으로 밀려들어 그 무시무시한 틈새를 메웠다. 당신은 온 힘을 다해 마침내 균열을 완전히 복구했다.\n당신은 기억하기 위해 떠났고, 기억하기 위해 싸운다. 어떤 기억도 자신을 떠나는 것을 허락하지 않을 것이다."
  },
  Event_131267_Name = {
    Text = "부서진 기억"
  },
  Event_131268_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_131268_Desc = {
    Text = "「으흐흐흐흐……하하하하!!」\n아무도 당신의 물음을 알아듣지 못했다. 그들은 울부짖음과 날카로운 웃음으로 대답했다."
  },
  Event_131268_Name = {
    Text = "버림받은 자"
  },
  Event_131269_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_131269_Desc = {
    Text = "당신들은 그것들을 되돌아보았다. 실타래이 튕기고, 부드러운 시선이 기억을 품에 안았다.\n당신은 말없이 그 운명의 조종자를 바라보았다. 만약 다시 한번 기회가 주어진다면, 그녀는 어떤 선택을 할까?"
  },
  Event_131269_Name = {
    Text = "옛날의 응시"
  },
  Event_131270_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_131270_Desc = {
    Text = "「으흐흐흐흐……하하하하!!」\n울부짖음과 날카로운 웃음이 당신 앞에서 점차 사라져 갔다. 어떤 혼령도 당신을 해치러 오지 않았다——그들은 이미 무시당하는 것에 익숙해져 있었다."
  },
  Event_131270_Name = {
    Text = "버림받은 자"
  },
  Event_131271_ChoiceDesc1 = {
    Text = "[기억을 응시]황금 유물 「(RelicConfig.Arg1)」 획득, 감염 「(Skill.Arg2)」"
  },
  Event_131271_ChoiceDesc2 = {
    Text = "[기억을 잊음]무작위로 깨어남체 2명 깨어남, 감염 두 번 [(Skill.Arg1)]"
  },
  Event_131271_ChoiceDesc3 = {
    Text = "[떠나다]50 검은 인장을 획득"
  },
  Event_131271_Desc = {
    Text = "소녀의 몸속에서 항아리가 깨지는 소리가 들렸다. 기억들이 그릇을 떠나 당신들 곁으로 다가왔다.\n어린 시절의 놀이 친구, 부모님의 선물, 흰 구름과 새에 대한 가장 순수한 상상, 하늘처럼 하얀 이상……모든 기억이 눈을 뜨고 조용히 당신들을 바라보았다.\n그것들이 묻는다. 그것들이 운다. 그것들이 기다린다."
  },
  Event_131271_Name = {
    Text = "옛날의 응시"
  },
  Event_131272_ChoiceDesc1 = {
    Text = "[물어보다]3장의 커맨드 카드 중 1장을 선택해 각인 획득: \"(EnchantConfig.Arg1)\", 감염 \"(Skill.Arg2)\""
  },
  Event_131272_ChoiceDesc2 = {
    Text = "[무시하다]3장의 커맨드 카드 중 1장을 선택해 각인 획득: \"(EnchantConfig.Arg1)\", 감염 \"(Skill.Arg2)\""
  },
  Event_131272_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_131272_Desc = {
    Text = "날카로운 울부짖음이 귓가에 울려 퍼지고, 고통받는 혼령들이 눈앞에서 자신의 얼굴과 몸을 찢어발기고 있다……\n그들은 누구인가? 심연옥의 죄수? 버림받은 운명? 묻혀버린 기억?"
  },
  Event_131272_Name = {
    Text = "버림받은 자"
  },
  Event_133380_ChoiceDesc1 = {Text = "[확인]"},
  Event_133380_Desc = {
    Text = "당신은 당신만의 벨벳 좌석에 앉았고, 선홍빛 막이 조용히 열렸다.\n친애하는 관객이여, 무대는 당신의 기대에 응답할 것입니다.\n이 극의 주연은 이미 무대 위에 섰습니다."
  },
  Event_133380_Name = {
    Text = "숙명의 무대"
  },
  Event_141995_ChoiceDesc1 = {
    Text = "[간단한 시도]최대 5장의 임의 카드 삭제"
  },
  Event_141995_ChoiceDesc2 = {
    Text = "[그에게 맡기기]무작위로 커맨드 카드 5장 삭제, 축복 유물 「(RelicConfig.Arg1)」 획득."
  },
  Event_141995_ChoiceDesc3 = {
    Text = "[역발상?]최대 두 명의 깨어남체를 선택하여, 그들의 전체 기본 카드 한 세트를 생성해 덱에 추가"
  },
  Event_141995_Desc = {
    Text = "당신은 한 광장에 도착했습니다. 많은 사람들이 바쁘게 오가고 있어, 이곳에서 흥미로운 것을 찾을 수 있을지도 모릅니다.\n당신이 희미한 노란 불빛이 켜진 방문을 두드리자, 연구원 차림의 사람이 안에서 고개를 내밀었습니다. 정체를 알 수 없는 과학 기기들이 가득한 방에서, 그는 당신을 끌어 앉히고는 자신이 「진화학자」라고 주장했습니다. 그는 열광적인 표정으로 자신의 「과학적 방법」을 강력히 추천했습니다.\n「인간에게 있는 무의미한 잉여를 제거하는 것만이 진정한 진화의 길이다!」"
  },
  Event_141995_Name = {
    Text = "진화학자"
  },
  Event_141996_ChoiceDesc1 = {
    Text = "[공격에 집중한 특훈]각인이 없는 모든 기초 타격에 무작위 각인을 부여"
  },
  Event_141996_ChoiceDesc2 = {
    Text = "[방어에 집중한 특훈]각인이 없는 모든 기본 방어에 무작위 각인을 부여"
  },
  Event_141996_ChoiceDesc3 = {
    Text = "[무작정 특훈]무작위 커맨드 카드 15장에 무작위 각인을 부여하고, 무작위 증상 카드 5장을 획득"
  },
  Event_141996_Desc = {
    Text = "당신은 한 광장에 도착했습니다. 많은 사람들이 바쁘게 오가고 있어, 이곳에서 흥미로운 것을 찾을 수 있을지도 모릅니다.\n금속이 부딪히는 청명한 소리가 공터에 울려 퍼지고, 몇몇 사람들이 서로 겨루며 무예를 연마하고 있습니다. 낡은 갑옷을 입은 젊은이가 당신을 알아채고, 검 하나를 던져주며 함께 단련하자고 초대합니다."
  },
  Event_141996_Name = {
    Text = "특훈 시간"
  },
  Event_141997_ChoiceDesc1 = {
    Text = "[빅 배팅]50% 확률로 랜덤 각인 획득 후 재배팅, 50% 확률로 검은 인장 75 획득"
  },
  Event_141997_ChoiceDesc2 = {
    Text = "[스몰 배팅]50% 확률로 랜덤 각인 획득 후 재배팅, 50% 확률로 검은 인장 75 획득"
  },
  Event_141997_Desc = {
    Text = "웨이터는 변함없는 미소를 유지하며 주사위 컵을 들어 올렸고, 맑은 소리가 울려 퍼졌습니다. 다른 플레이어들도 각자의 선택을 했습니다. 「배팅 마감입니다.」 그가 말했습니다. 「배팅해 주세요——」"
  },
  Event_141997_Name = {
    Text = "시끌벅적한 카지노"
  },
  Event_141998_ChoiceDesc1 = {
    Text = "[솔직하게 배팅]커맨드 카드 한 장 삭제"
  },
  Event_141998_ChoiceDesc2 = {
    Text = "[속임수 써보기]증상 카드 한 장 삭제"
  },
  Event_141998_ChoiceDesc3 = {
    Text = "[떠나기]"
  },
  Event_141998_Desc = {
    Text = "당신은 매우 활기찬 곳에 도착했습니다. 모든 사람의 얼굴에 행복이 넘쳐흐르고, 마음껏 반짝이는 형형색색의 조명이 밤의 어둠을 몰아냅니다. 곳곳에 보이는 간판에는 이렇게 쓰여 있습니다: 「카니발에 오신 것을 환영합니다! 이곳의 꿈은 영원히 끝나지 않으며, 이곳의 환희는 영원히 아디오스가 없습니다!」\n붐비는 인파에 떠밀려 당신은 화려한 건물 안으로 들어섰습니다. 홀 안은 금빛으로 찬란하고 사람들의 소리로 가득하며, 공기 중에는 달콤한 술 향기가 가득합니다. 주사위 하나가 데굴데굴 굴러 당신의 발 앞에 멈추고, 웨이터는 아첨하는 미소를 띠며 이것이 행운의 상징이라고 말합니다. 호기심을 품은 채 당신은 한 발짝 앞으로 나아갑니다. 어쩌면, 이 게임에서 실타래력을 발휘할 수 있을지도 모릅니다."
  },
  Event_141998_Name = {
    Text = "시끌벅적한 카지노"
  },
  Event_141999_ChoiceDesc1 = {
    Text = "[물물교환]유물 1개를 제거하고, 50% 확률로 3개 중 1개의 황금 유물을 획득하거나, 50% 확률로 검은 인장 25개를 획득"
  },
  Event_141999_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_141999_Desc = {
    Text = "당신은 매우 활기찬 곳에 도착했습니다. 모든 사람의 얼굴에는 행복이 넘쳐흘렀고, 마음껏 반짝이는 형형색색의 조명이 밤의 어둠을 몰아냈습니다. 곳곳에 보이는 간판에는 이렇게 쓰여 있었습니다: 「카니발에 오신 것을 환영합니다! 이곳의 꿈은 영원히 끝나지 않으며, 이곳의 환희는 영원히 아디오스가 없습니다!」\n군중 속에서, 남루한 옷차림이지만 놀랍도록 큰 짐을 지닌 상인이 당신에게 손을 흔들었습니다. 그는 옆에 있는 짐을 두드리며 가까이 다가와 목소리를 낮추어 물물교환을 초대했고, 낡은 천 보따리는 그의 말소리에 맞춰 살랑살랑 흔들리며 이따금 딸깍딸깍 소리를 냈습니다."
  },
  Event_141999_Name = {
    Text = "남루한 행상"
  },
  Event_142000_ChoiceDesc1 = {
    Text = "[소원 빌기]현재 HP의 50%를 소모하고, 무작위 황금 유물 2개를 획득"
  },
  Event_142000_ChoiceDesc2 = {
    Text = "[온 마음을 다해 소원 빌기]현재 HP의 99%를 소모하고, 시계추 \"(RelicConfig.Arg2)\"를 획득"
  },
  Event_142000_ChoiceDesc3 = {
    Text = "[손을 뻗어 연못 바닥 더듬기]황금 유물 \"(RelicConfig.Arg1)\"를 획득"
  },
  Event_142000_Desc = {
    Text = "바람이 들판을 스치고, 사방은 고요하며, 단지 나무들의 바스락거리는 소리만 울려 퍼집니다.\n갑자기 당신은 무언가가 졸졸 흐르는 소리를 들었고, 소리를 따라가니 짙은 비릿한 단내가 먼저 코를 찔렀습니다. 마침내 당신은 그 물소리의 근원을 확인했습니다 — 소원을 비는 연못이었고, 붉은빛으로 가득 차 있었으며, 수많은 사람의 피가 연못 안에서 용동하고 있었습니다. 마치 수면 아래에서 무언가가 튀어오르려는 듯했습니다.\n소리가 당신의 마음 깊은 곳에서 울려 퍼졌습니다: 「당신의 피를 바치세요, 내가 은혜를 베풀겠습니다.」"
  },
  Event_142000_Name = {Text = "피의 샘"},
  Event_142001_ChoiceDesc1 = {
    Text = "[간단히 공양]유물 2개를 삭제하고, 죄악의 조물주 유물 \"(RelicConfig.Arg1)\"을 획득"
  },
  Event_142001_ChoiceDesc2 = {
    Text = "[경건하게 공양]유물 4개를 삭제하고, 축복 유물 \"(RelicConfig.Arg1)\"을 획득"
  },
  Event_142001_ChoiceDesc3 = {
    Text = "[공물을 살짝 훔치기, 아무도 모른다]황금 유물 \"(RelicConfig.Arg1)\"을 획득"
  },
  Event_142001_Desc = {
    Text = "바람이 들판을 스치고, 사방은 고요하며, 단지 나무들의 바스락거리는 소리만 울려 퍼집니다.\n어느새 당신은 오래된 제단 앞에 서 있었고, 거대한 조각상이 높은 곳에서 당신을 응시하며 당신의 손에서 무언가를 빼앗으려는 듯했습니다. 당신은 제단 바로 아래에 희미한 글자가 새겨진 것을 보았습니다 — 「득실타래상칭」."
  },
  Event_142001_Name = {
    Text = "득실타래의 제단"
  },
  Event_142002_ChoiceDesc1 = {
    Text = "[무료 체험]무작위 Arg2 개의 백은 유물 업그레이드"
  },
  Event_142002_ChoiceDesc2 = {
    Text = "[일반 서비스]Arg1 검은 인장 소모: 무작위 Arg2 개의 백은 유물 업그레이드"
  },
  Event_142002_ChoiceDesc3 = {
    Text = "[호화 서비스]Arg1 검은 인장 소모: 무작위 Arg2 개의 백은 유물 업그레이드"
  },
  Event_142002_Desc = {
    Text = "당신은 한 광장에 도착했습니다. 많은 사람들이 바쁘게 오가고 있어, 이곳에서 흥미로운 것을 찾을 수 있을지도 모릅니다.\n따뜻한 불빛이 켜진 작은 건물이 광장 한쪽 구석에 조용히 서 있습니다. 고급 회관처럼 보이지만, 벽에 걸린 짙은 색의 현판에는 「본 점은 생물 이외의 존재만을 위해 서비스합니다.」라고 선명하게 적혀 있습니다."
  },
  Event_142002_Name = {
    Text = "특별 회관"
  },
  Event_142003_ChoiceDesc1 = {
    Text = "[한 번 뽑기]증상 카드 한 장 획득"
  },
  Event_142003_ChoiceDesc2 = {
    Text = "[떠나기]검은 인장 75 획득"
  },
  Event_142003_Desc = {
    Text = "당신은 매우 활기찬 곳에 도착했습니다. 모든 사람의 얼굴에 행복이 넘쳐흐르고, 마음껏 반짝이는 형형색색의 조명이 밤의 어둠을 몰아냅니다. 곳곳에 보이는 간판에는 이렇게 쓰여 있습니다: 「카니발에 오신 것을 환영합니다! 이곳의 꿈은 영원히 끝나지 않으며, 이곳의 환희는 영원히 아디오스가 없습니다!」\n당신은 길가에 추첨 가판대가 있는 것을 발견했습니다. 사람들로 가득 차 있었고, 모든 사람의 시선이 꼼꼼히 가려진 대상에 집중되어 있었습니다——상인은 그것의 희귀함을 극구 선전하고, 사람들은 앞다투어 참여하려 했습니다."
  },
  Event_142003_Name = {
    Text = "추첨 도전"
  },
  Event_142004_ChoiceDesc1 = {
    Text = "[잠깐 빌려 쓰기]"
  },
  Event_142004_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_142004_Desc = {
    Text = "바람이 들판을 스쳐 지나가고, 사방이 고요한 가운데 나무들의 바스락거리는 소리만 들려옵니다.\n문득, 당신은 낡은 초가 헛간을 발견했습니다. 한가운데에는 모루가 놓여 있고, 한쪽에는 녹슨 금속 무기들이 잔뜩 쌓여 있어, 오래전에 폐허가 된 대장간처럼 보입니다. 모루 옆에는 상세한 사용 설명서가 놓여 있어, 유물을 여기에 올려놓고 개조할 수 있다고 알려주고 있습니다."
  },
  Event_142004_Name = {Text = "대장간"},
  Event_142005_ChoiceDesc1 = {
    Text = "[솔직하게 배팅]커맨드 카드 한 장 삭제"
  },
  Event_142005_ChoiceDesc2 = {
    Text = "[속임수 써보기]증상 카드 한 장 삭제"
  },
  Event_142005_ChoiceDesc3 = {
    Text = "[떠나기]"
  },
  Event_142005_Desc = {
    Text = "주변의 응원이 당신의 승리를 알렸습니다. 시끄러운 소리 속에서 당신도 마침내 그들과 같이 모든 것을 건 이 기묘하고 화려한 꿈에 빠져들었습니다. 손 안의 칩을 바라보니, 마치 그것들이 당신에게 영광을 가져다주는 가장 충실타래한 동반자인 것 같았습니다. 저어가 도박 테이블 깊은 곳에서 흘러나오며, 어떤 모호한 요청을 담아 속삭입니다: 「다시 한 번, 한 번 더 이겨봐요.」"
  },
  Event_142005_Name = {
    Text = "시끌벅적한 카지노"
  },
  Event_142013_ChoiceDesc1 = {
    Text = "[빅 배팅]50% 확률로 랜덤 백은 유물 획득 후 재배팅, 50% 확률로 검은 인장 75 획득 및 엘리트 전투 돌입"
  },
  Event_142013_ChoiceDesc2 = {
    Text = "[스몰 배팅]50% 확률로 랜덤 백은 유물 획득 후 재배팅, 50% 확률로 검은 인장 75 획득 및 엘리트 전투 돌입"
  },
  Event_142013_Desc = {
    Text = "웨이터는 변함없는 미소를 유지하며 주사위 컵을 들어 올렸고, 맑은 소리가 울려 퍼졌습니다. 다른 플레이어들도 각자의 선택을 했습니다. 「배팅 마감입니다.」 그가 말했습니다. 「배팅해 주세요——」"
  },
  Event_142013_Name = {
    Text = "시끌벅적한 카지노"
  },
  Event_142073_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142073_Desc = {
    Text = "웨이터가 주사위 컵을 들어 올렸고, 짧은 몇 초 동안 공기마저 정지된 것 같았습니다. 답이 밝혀지는 순간, 환호와 탄식이 뒤섞인 소리가 들렸습니다. 행운은 당신에게 가호을 내리지 않았고, 테이블 위에 조용히 놓인 주사위들은 당신과 반대되는 답을 내놓았습니다. 당신은 마지막으로 한 번 둘러보며 저 발광의 도박꾼들을 바라보았습니다. 이제 떠날 때가 됐습니다."
  },
  Event_142073_Name = {
    Text = "시끌벅적한 카지노"
  },
  Event_142074_ChoiceDesc1 = {
    Text = "[전투에 들어가기]"
  },
  Event_142074_Desc = {
    Text = "당신이 기대에 부풀어 도박 테이블을 뚫어지게 바라보고 있을 때, 갑자기 손목이 단단히 붙잡혔습니다. 고개를 들어보니, 카지노의 보스가 내려다보며 규칙을 어긴 손님을 내보낼 준비를 하고 있었습니다. 순식간에 모든 시선이 당신 한 사람에게 집중되었습니다. 놀란 시선, 적대적인 시선, 고소해하는 시선......당신은 깨달았습니다. 한 사람이 여러 번 속임수를 쓸 수는 있지만, 단 한 번만 발견되어도 완전한 파멸을 맞이하게 된다는 것을."
  },
  Event_142074_Name = {
    Text = "시끌벅적한 카지노"
  },
  Event_142103_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142103_Desc = {
    Text = "당신은 물리적인 수단으로 카지노에서 무사히 탈출했습니다. 군중의 소란스러운 소리를 뒤로 한 채 발걸음을 재촉해 떠났습니다——이 난장판은 누군가가 알아서 수습할 것입니다."
  },
  Event_142103_Name = {
    Text = "시끌벅적한 카지노"
  },
  Event_142105_ChoiceDesc1 = {
    Text = "[한 번 더 뽑기]증상 카드 한 장 획득"
  },
