  Event_142110_ChoiceDesc1 = {
    Text = "[한 번 더 뽑기]증상 카드 한 장 획득"
  },
  Event_142110_ChoiceDesc2 = {
    Text = "[떠나기]검은 인장 75 획득"
  },
  Event_142110_Desc = {
    Text = "한 번 뽑아봤지만 아무 일도 일어나지 않았습니다. 하지만 카드 뒷면에는 이렇게 쓰여 있었습니다: 「다음번엔 더 쉬워질 거예요」\n...한 번 더 시도해볼까요?"
  },
  Event_142110_Name = {
    Text = "추첨 도전"
  },
  Event_142118_ChoiceDesc1 = {
    Text = "[물물교환]유물 1개를 제거하고, 25% 확률로 3개 중 1개의 시계추를 획득하거나, 50% 확률로 무작위 황금 유물 2개를 획득하거나, 25% 확률로 검은 인장 25개를 획득"
  },
  Event_142118_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_142118_Desc = {
    Text = "상인은 당신이 건넨 물건을 받아 달빛에 이리저리 살펴보며 눈가 튀어나올 듯 바라보았습니다. 한참을 기다린 끝에 그는 입꼬리를 올리며 보따리에서 녹슨 철 상자를 꺼냈습니다. 「한번 열어보세요, 요즘 가장 유행하는 블라인드 박스랍니다.」\n당신이 열어보니, 안쪽에는 다소 실타래망스러운 블랙 인장만 조금 들어 있었습니다. 상인은 손을 비비며 미안한 눈빛으로 한 번 더 시도해볼 수 있다고 말했습니다."
  },
  Event_142118_Name = {
    Text = "남루한 행상"
  },
  Event_142119_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142119_Desc = {
    Text = "상인은 당신이 건넨 물건을 받아 달빛에 이리저리 살펴보며 눈가 튀어나올 듯 바라보았습니다. 한참을 기다린 끝에 그는 입꼬리를 올리며 보따리에서 녹슨 철 상자를 꺼냈습니다. 「한번 열어보세요, 요즘 가장 유행하는 블라인드 박스랍니다.」\n당신이 열어보니, 안쪽에 무언가가 들어 있었습니다."
  },
  Event_142119_Name = {
    Text = "남루한 행상"
  },
  Event_142120_ChoiceDesc1 = {
    Text = "[물물교환]황금 창조물 1개를 제거하고, 50% 확률로 3개 중 1개의 시계추를 획득하거나, 50% 확률로 3개 중 1개의 축복 유물을 획득"
  },
  Event_142120_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_142120_Desc = {
    Text = "당신이 다시 블라인드 박스를 열었지만, 여전히 원하는 물건이 없었습니다. 상인은 황급히 웃음을 지으며 또 다른 철 상자를 꺼내 두 손으로 받쳐 당신 앞에 내밀었습니다.\n「화내지 마세요, 손님! 맹세컨대, 이번엔 반드시 최고의 물건이 있을 겁니다...」 그렇게 말하면서도 그는 슬그머니 한 손을 빼내어 당신 앞에 펼쳐 보이며, 「물론, 보물에는 보물로 교환해야죠.」"
  },
  Event_142120_Name = {
    Text = "남루한 행상"
  },
  Event_142138_ChoiceDesc1 = {
    Text = "[잠깐 빌려 쓰기]"
  },
  Event_142138_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_142138_Desc = {
    Text = "당신은 이 도구들을 성공적으로 사용했습니다. 다소 손상되었지만, 아직 쓸 수 있을 것 같습니다."
  },
  Event_142138_Name = {Text = "대장간"},
  Event_142139_ChoiceDesc1 = {
    Text = "[파쇄 주조]황금 유물 1개를 선택해 삭제하고, 백은 제작물 2개를 획득하며, 검은 인장 50을 획득"
  },
  Event_142139_ChoiceDesc2 = {
    Text = "[담금질]유물 2개를 선택해 삭제하고, 황금 창조물 \"(RelicConfig.Arg1)\"를 획득."
  },
  Event_142139_ChoiceDesc3 = {
    Text = "[프리미엄 담금질]황금 유물 2개를 선택해 삭제하고, 시계추 \"(RelicConfig.Arg1)\"를 획득."
  },
  Event_142139_Desc = {
    Text = "당신은 옆에 있는 망치를 집어 들고, 무언가를 하려고 합니다......"
  },
