  Event_142142_Name = {Text = "대장간"},
  Event_142167_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142167_Desc = {
    Text = "세 번의 사용을 거친 후, 모루는 완전히 움푹 패였고 망치도 온통 마모되어, 더 이상 사용할 수 없을 것 같습니다."
  },
  Event_142167_Name = {Text = "대장간"},
  Event_142235_ChoiceDesc1 = {
    Text = "【나는 견고히 나아갈 것이다】「순수」 획득: 모든 명령 카드에 20층 영구 강화"
  },
  Event_142235_ChoiceDesc2 = {
    Text = "【나는 도망치지 않을 것이다】「증진」 획득: 은열쇠 상한, 광기 상한 영구 20% 감소"
  },
  Event_142235_Desc = {
    Text = "당신의 눈앞이 갑자기 안개로 뒤덮이며 세상이 흐릿해지기 시작했고, 몽롱한 가운데 한 목소리가 마음속 깊은 곳에서 울려 퍼졌습니다:\n「당신은 계속 나아가겠습니까?」"
  },
  Event_142235_Name = {
    Text = "종착역이 가까워지다"
  },
  Event_142925_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142925_Desc = {
    Text = "회관의 직원이 보수를 받고 기본 서비스를 제공했습니다. 그들은 당신이 맡긴 물건을 어두운 칸막이 방으로 가져갔고, 오래 기다리지 않아 그가 다시 나타났을 때, 물건은 이미 쟁반 위에 올려져 있었으며 원래와는 조금 달라 보였습니다."
  },
  Event_142925_Name = {
    Text = "특별 회관"
  },
  Event_142926_ChoiceDesc1 = {
    Text = "[황금 유물 하나 삭제](황금 유물 보유 필요)"
  },
  Event_142926_ChoiceDesc2 = {
    Text = "[강화(Forged) 유물 선택 가능]"
  },
  Event_142926_ChoiceDesc3 = {
    Text = "[떠나기]"
  },
  Event_142926_Desc = {
    Text = "「유물 수량」 「유물 목록 선택」 테스트"
  },
  Event_142927_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142927_Desc = {
    Text = "회관의 직원이 보수를 받고 호화 서비스를 제공했습니다. 그들은 당신의 물건을 정중하게 상자에 넣어 어두운 칸막이 방으로 가져갔습니다. 한참을 기다린 끝에 그가 다시 나타나 두 손으로 물건을 받쳐 올렸고, 표정은 여전히 평온했습니다."
  },
  Event_142927_Name = {
    Text = "특별 회관"
  },
  Event_142928_ChoiceDesc1 = {
    Text = "[최대 2개의 깨어남체를 선택해 광기를 가득 채우기]"
  },
  Event_142928_ChoiceDesc2 = {
    Text = "[반드시 깨어남체 2개를 선택하여 광기를 가득 채워야 함]"
  },
  Event_142928_ChoiceDesc3 = {
    Text = "[떠나기]"
  },
  Event_142928_Desc = {
    Text = "「조건부 깨어남체 선택」 테스트"
  },
  Event_142929_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142929_Desc = {
    Text = "연구원은 당신 주위를 몇 바퀴나 돌며 한참을 꼼꼼히 살펴본 뒤에야 작업을 시작했습니다. 그는 당신의 의견을 묻지 않았습니다. 시간이 지나 이 기묘한 연구소를 떠나려 할 때, 당신은 분명 많은 것을 잃었다는 것을 알았지만, 그는 손뼉을 치며 축하했습니다: 「이것이 바로 진화의 진수다!」"
  },
  Event_142929_Name = {
    Text = "진화학자"
  },
  Event_142930_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142930_Desc = {
    Text = "당신은 손을 뻗어 온통 진홍빛으로 물든 연못 속을 더듬어, 유용한 무언가를 찾아냈습니다."
  },
  Event_142930_Name = {Text = "피의 샘"},
  Event_142931_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142931_Desc = {
    Text = "목소리가 멀어지고, 당신의 마음은 결의로 가득 차며, 힘이 발현되는 것을 느낍니다."
  },
  Event_142931_Name = {
    Text = "종착역이 가까워지다"
  },
  Event_142932_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142932_Desc = {
    Text = "목소리가 멀어지고, 당신의 마음은 결의로 가득 차며, 머리가 더욱 맑아집니다."
  },
  Event_142932_Name = {
    Text = "종착역이 가까워지다"
  },
  Event_142933_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142933_Desc = {
    Text = "당신은 산더미처럼 쌓인 공물 더미에서 조금 집어 들고는 재빨리 자리를 떴습니다. 떠나는 순간, 조각상의 두 눈이 움직인 것 같았습니다."
  },
  Event_142933_Name = {
    Text = "득실타래의 제단"
  },
  Event_142934_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142934_Desc = {
    Text = "당신은 방어 방향에 초점을 맞춰 훈련을 진행했습니다. 상대방의 습격에 맞서 끊임없이 무기로 막아내며, 방어 능력과 반응 속도가 향상되었습니다."
  },
  Event_142934_Name = {
    Text = "특훈 시간"
  },
  Event_142935_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142935_Desc = {
    Text = "연구원은 장갑을 끼고 선반에서 모양이 기묘한 기기들을 꺼내 당신 앞에서 이리저리 움직였습니다. 그가 정확히 무엇을 했는지는 알 수 없지만, 확실타래히 조금 가벼워진 느낌이 들었습니다."
  },
  Event_142935_Name = {
    Text = "진화학자"
  },
  Event_142936_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142936_Desc = {
    Text = "당신은 특정 방향을 정하지 않고, 자신의 신체 한계를 무시한 채 상대와 대련을 계속하여 모든 사람이 지쳐 쓰러질 때까지 멈추지 않았습니다. 실타래력이 많이 늘었다는 것을 알지만, 그만큼 대가도 치렀습니다."
  },
  Event_142936_Name = {
    Text = "특훈 시간"
  },
  Event_142937_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142937_Desc = {
    Text = "당신은 가방에서 아무거나 꺼내 공양하고, 그에 상응하는 보상을 받았습니다."
  },
  Event_142937_Name = {
    Text = "득실타래의 제단"
  },
  Event_142938_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142938_Desc = {
    Text = "당신은 귀중한 공물을 바치고, 그에 상응하는 보상을 받았습니다."
  },
  Event_142938_Name = {
    Text = "득실타래의 제단"
  },
  Event_142939_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142939_Desc = {
    Text = "당신은 그의 연구 방법에 의심을 품었고, 한바탕 논쟁 끝에 그는 당신이 직접 이 기기들을 사용하여 다른 방식으로 「진화」를 추구하도록 허락했습니다.\n같은 도구를 사용했지만, 당신은 우연히 「삭제」되어야 할 것들을 대량으로 「증식」시켜 버렸고, 떠나기 직전 연구원의 비명 소리를 들었습니다."
  },
  Event_142939_Name = {
    Text = "진화학자"
  },
  Event_142940_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142940_Desc = {
    Text = "회관의 직원이 당신에게 무료 서비스를 제공했습니다. 그들은 당신이 맡긴 물건을 어두운 칸막이 방으로 가져갔고, 잠시 후 돌아와 아무 말 없이 물건을 당신의 손에 돌려주었습니다."
  },
  Event_142940_Name = {
    Text = "특별 회관"
  },
  Event_142941_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142941_Desc = {
    Text = "당신은 소원 연못에 대량의 피를 바쳤고, 귀중한 선물이 연못 속에서 떠올랐습니다."
  },
  Event_142941_Name = {Text = "피의 샘"},
  Event_142942_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142942_Desc = {
    Text = "당신은 공격 방향에 집중한 훈련을 펼쳤고, 강철이 부딪히는 가운데 타격 기술과 속도가 모두 향상되었습니다."
  },
  Event_142942_Name = {
    Text = "특훈 시간"
  },
  Event_142943_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_142943_Desc = {
    Text = "당신은 소원 연못에 약간의 피를 바쳤고, 연못 속에서 선물이 떠올랐습니다."
  },
  Event_142943_Name = {Text = "피의 샘"},
  Event_142944_ChoiceDesc1 = {
    Text = "[업그레이드할 유물 선택]"
  },
  Event_142944_ChoiceDesc2 = {
    Text = "[무작위 유물 업그레이드]"
  },
  Event_142944_ChoiceDesc3 = {
    Text = "[떠나다(테스트)]"
  },
  Event_142944_Desc = {
    Text = "「유물 업그레이드 기능」 테스트, 유물 자체 추가"
  },
  Event_146258_ChoiceDesc1 = {
    Text = "[그를 부른다] 저주 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146258_ChoiceDesc2 = {
    Text = "[그것들에 응답하다]3장의 커맨드 카드 중 1장을 선택해 각인 획득: \"(EnchantConfig.Arg1)\""
  },
  Event_146258_ChoiceDesc3 = {
    Text = "[그들을 무시하다]검은 인장 50개 획득"
  },
  Event_146258_Desc = {
    Text = "제단 위에 율리에트의 흰 예복이 짙은 연기에 젖은 채, 향재와 어떤 비린내 나는 달콤한 냄새가 섞여 코를 찌른다.\n「자애로운 어머니가 포대기에 싸인 아기를 가엾이 여기듯이, 등불을 든 자는 세상의 죄인을 가엾이 여기시나니.」 그녀의 목소리는 높지 않았지만, 전당 가득히 속삭이는 기도로 뚜렷이 압도시켰다.\n제단 위의 제물이 촛불 속에서 기름기를 발산하며, 한 줄기 푸른 연기가 그 윤곽을 따라 비틀리며 솟아올라, 아래에 있는 사람들의 얼굴을 흐릿하게 만들었다.\n카스토르는 신도들 사이에 서서, 눈을 내리깔며 자신에게 각인된 적절한 경건함을 얼굴에 담은 채 그 흔들리는 연기 너머로 폴룩스를 바라보았다."
  },
  Event_146258_Name = {Text = "옛꿈 Ⅲ"},
  Event_146259_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146259_Desc = {
    Text = "신경 쓰지 마라. 그저 눈보라가 부는 휘파람이고, 얼음 호수가 내는 한숨이며, 산무리들의 애도일 뿐이니.\n이미 썩어버린 마른 가지들이 서로 스치는 수근거림인 것이다.\n그것들은 한때 빙극 사이에 몸을 묻은 모든 선행자들을 위해 영원히 애절하게 중얼거린다."
  },
  Event_146259_Name = {
    Text = "얼음 호수의 아리아"
  },
  Event_146260_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146260_Desc = {
    Text = "떡이 별 떡 있고 사람은 별사람 없다하면, 혈쇄·히로는 당신들과 평등하게 소원을 빌 기회를 누리는가?\n그렇다면, 그녀가 선수를 쳐서 경쟁자들을 몰아내는 행동에 대해서는 당신은 그저 담담히 받아드려야만 하는가?\n「좀 헛생각만 하지 말고, 계속 올라가기나 하라구!」 귀가에 카라부의 외침이 울려 퍼졌다."
  },
  Event_146260_Name = {
    Text = "터무니없는 공평함"
  },
  Event_146261_ChoiceDesc1 = {
    Text = "[산은 허기을 두려워한다]"
  },
  Event_146261_ChoiceDesc2 = {
    Text = "[산은 상실타래을 두려워한다]"
  },
  Event_146261_ChoiceDesc3 = {
    Text = "[산은 죽음을 두려워한다]"
  },
  Event_146261_Desc = {
    Text = "당신은 산의 몸속을 걷고 있다.\n산의 떨림이 그 비밀을 드러낸다.\n산의 탐욕이, 산의 두려움을 결정한다."
  },
  Event_146261_Name = {
    Text = "산의 비밀"
  },
  Event_146262_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146262_Desc = {
    Text = "당신은 매끄럽고 부드러운 털을 만끽하며, 자신의 욕망에 갇혀 있다.\n당신은 그 감촉에 만족한다.\n표면 아래에 무엇이 있는지, 그게 정말 중요할까?"
  },
  Event_146262_Name = {
    Text = "기어다니는 검은 고양이"
  },
  Event_146263_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146263_Desc = {
    Text = "당신은 조용히 빨간 줄의 끝을 받아, 당신의 손목에 묶었다.\n폴룩스도 같은 방법으로, 두 아이의 손은 곧 가느다란 빨간 줄로 이어졌다.\n같은 시간 동안 탐색할 수 있는 면적은 줄어들었지만, 당신들은 함께 살고 함께 죽을 운명이지 않은가?\n남은 것은 운명에 맡기자."
  },
  Event_146263_Name = {Text = "옛꿈 Ⅰ"},
  Event_146264_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146264_Desc = {
    Text = "「물론 힘들다는 걸 알아, 사랑하는 아이야.」\n「하지만 세상은 누구에게도 결코 쉽지 않았어.」\n「언젠가 그 나비는 네 손바닥을 떠나, 영원히 사라질 거야.」"
  },
  Event_146264_Name = {
    Text = "환상인가 현실타래인가"
  },
  Event_146265_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146265_Desc = {
    Text = "윌리엄이 눈을 들고는, 시선이 당신을 빠르게 스치고서 먼 곳에 있는 눈 쌓인 산등성이에 닿았다.\n그가 무겁게 입을 열었다.「네가 사과할 일은 전혀 없어, 어떤 명제는 오직 나만이, 나 자신만이 정답을 찾아야 되는 풀이 과정이 존재하기도 하니까.」\n「하지만, 네 예리함과 통찰력에 놀랐어. 고마워.」"
  },
  Event_146265_Name = {
    Text = "부드러운 침몰"
  },
  Event_146266_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146266_Desc = {
    Text = "윌리엄의 눈빛에 빛이 났다.\n당신은 입을 열었다 닫았다 했지만, 결코 아무 말도 내뱉을 수 없었다. 침묵이 지금으로서 할 수 있는 최선의 선택이니까.\n당신과 윌리엄의 사이에는 여전히 약속하지는 않았지만, 무의식 중에 약속처럼 굳어진 무언가가 존재한다, 그것을 깨뜨려서는 안 된다."
  },
  Event_146266_Name = {
    Text = "부드러운 침몰"
  },
  Event_146267_ChoiceDesc1 = {
    Text = "[떠나다]획득 백은 유물 [(RelicConfig.Arg1)]"
  },
  Event_146267_Desc = {
    Text = "「돌려줘, 돌려줘, 그건 내 힘이야!」\n산이 울부짖고, 산이 애절히 울부짖는다.\n산은 자신이 가졌던 모든 것을 빼앗겼음을 견딜 수 없었다."
  },
  Event_146267_Name = {
    Text = "산의 비밀"
  },
  Event_146268_ChoiceDesc1 = {
    Text = "[계속 도망쳐] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146268_ChoiceDesc2 = {
    Text = "[때를 기다리자] 각인 3개 중 1개 선택하기"
  },
  Event_146268_ChoiceDesc3 = {
    Text = "[천천히 물러난다]"
  },
  Event_146268_Desc = {
    Text = "「형 조심해, 까마귀가 보고 있어.」\n소년 카스토르가 폴룩스를 업고 급히 달리며, 의심스러운 모든 구석을 불안한 눈빛으로 훑었지만, 아무것도 발견하지 못했다.\n「위에 있어.」\n당신은 몸을 떨며, 고개를 들어 올려다보았다.\n처마 끝 그림자 속에, 까마귀 한 마리가 조용히 웅크리고 있었고, 사방을 향한 괴이한 눈들이 모두 당신을 뚫어지게 응시하고 있었다."
  },
  Event_146268_Name = {Text = "옛꿈 Ⅱ"},
  Event_146269_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146269_Desc = {
    Text = "당신은 훈련 중에 들었던 당부를 다시 머릿속에 새겨본다. \"안전 로프에 의존해서는 안 된다.\"\n당신은 암벽을 걷어차며 간신히 몸을 안정시킨다.\n하지만 배낭 속 무언가가 암벽을 따라 굴러떨어지며, 그것은 작디 작은 하나의 점으로 변해갔다.\n하지만 중요하지 않다, 적어도 당신이 아직 숨이 붙어있으니."
  },
  Event_146269_Name = {
    Text = "소리 없는 추락"
  },
  Event_146270_ChoiceDesc1 = {
    Text = "[귀를 기울여 듣다]백은 유물“(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_146270_ChoiceDesc2 = {
    Text = "【귀를 막다】3개 중 1개의 각인 선택"
  },
  Event_146270_Desc = {
    Text = "눈보라가 암벽에 부딪히며, 얼음층 깊은 곳에서 갈라지는 소리가 들려오는 듯 마는 듯 섞여, 끊어지는 듯한 흐느낌과 함께 부서진다.\n당신은 아무도 없는 높은 곳에 서서, 갑자기 산의 선율을 귀담아 듣게 된다.\n그것은 쓸쓸하고 장엄하며, 낮은 목소리로 오직 죽은 자만을 위한 곡을 읊조리고 있을 뿐이었다."
  },
  Event_146270_Name = {
    Text = "자연의 환상곡"
  },
  Event_146271_ChoiceDesc1 = {
    Text = "[종소리] 「(Skill.Arg1)」에 감염되고, 랜덤 명령 카드 1장에 각인 「(EnchantConfig.Arg2)」을(를) 획득하기"
  },
  Event_146271_ChoiceDesc2 = {
    Text = "[먹이] 「(Skill.Arg1)」에 감염되고, 랜덤 명령 카드 1장에 각인 「(EnchantConfig.Arg2)」을(를) 획득하기"
  },
  Event_146271_ChoiceDesc3 = {
    Text = "[개의 기대] 랜덤 명령 카드 1장에 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_146271_Desc = {
    Text = "「파블로프는 종을 흔들고, 개에게 먹이를 주었다. 오랜 시간이 지나자, 종만 흔들어도 개는 침을 흘리게 되었다.」\n「그렇다면, 개가 침을 흘리게 만든 것은 대체 무엇일까?」"
  },
  Event_146271_Name = {
    Text = "파블로프의 반사"
  },
  Event_146272_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146272_Desc = {
    Text = "기억하지 마.\n윌리엄은 네 손이 닿는 거리에 있어.\n고통이 너를 삼키지 못하게 해.\n넌 많은 것을 놓쳤지만, 아직은 늦지 않았어."
  },
  Event_146272_Name = {
    Text = "저편에서 오다"
  },
  Event_146273_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146273_Desc = {
    Text = "「손을 모아봐.」\n「한때 아름다웠던 것도, 네 손안에서는 검은 진흙 덩어리로 남을 뿐이야.」"
  },
  Event_146273_Name = {
    Text = "환상인가 현실타래인가"
  },
  Event_146274_ChoiceDesc1 = {
    Text = "[돌아가자] 검은 인장 50 획득하기"
  },
  Event_146274_ChoiceDesc2 = {
    Text = "[어루만지기] 검은 인장 75 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146274_Desc = {
    Text = "「야옹~」 초록 눈를 한 검은 고양이가 부드러운 발걸음을 하며 당신의 종아리에 비빈다.\n동시에, 「N」이 사라졌다."
  },
  Event_146274_Name = {
    Text = "기어다니는 검은 고양이"
  },
  Event_146275_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146275_Desc = {
    Text = "당신은 소리를 내지 않았지만, 그저 한 치도 떼지 않고 그 시선이 연기를 뚫고 폴룩스의 눈에 닿도록 내버려 두었다.\n그도 피하지는 않았다. 동생은 항상 그랬다, 고집을 가장 깊은 곳에 가뒀더라도 먼저 고개를 숙이지 않는 법이다.\n예배당 안에 울리는 찬송가의 소리와 향재 냄새, 율리에트의 자비와 제사에 관한 말들이 갑자기 멀게 느껴졌다. 긴 시간을 너머로, 서로를 응시하고 있는 듯. 마치 오직 당신과 그, 이 둘만이 이 예배당에 가득 채워진 위선적인 연민을 사이에 둔 채."
  },
  Event_146275_Name = {Text = "옛꿈 Ⅲ"},
  Event_146276_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146276_Desc = {
    Text = "지금 이 순간, 당신은 자신의 창백하고 긴 기억의 유일한 수호자다.\n웬디고가 마른 나뭇가지 같은 손을 뻗어, 손끝이 당신의 심장을 겨누지만, 마지막 순간에 당신이 단단히 막아낸다.\n그것은 비틀거리며 안개 속으로 물러서고, 낮고 쉰 듯한 중얼거림만을 남긴다——\n「넌 언젠가 자진해서, 그것들을 모두 내게 넘겨줄 거야……」"
  },
  Event_146276_Name = {Text = "탐식자"},
  Event_146277_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146277_Desc = {
    Text = "그것은 머나먼 꿈, 어린 시절이라는 이름의 꿈이다.\n정신 차려. 너는 거기에 없어.\n너는 눈보라 속에, 층층이 둘러싼 등불 교회 신도들의 포위 속에 쌓인 채, 폴룩스의 칼날이 바로 네 가슴을 겨누고 있잖아."
  },
  Event_146277_Name = {Text = "옛꿈 Ⅰ"},
  Event_146278_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146278_Desc = {
    Text = "「나는 죽음의 발생을 받아들인다.」\n「나는 기꺼이 고난의 여정에 몸을 묻으리라.」\n「절벽 아래, 하늘과 땅이 나를 위해 비석을 세우리라.」"
  },
  Event_146278_Name = {
    Text = "다가오는 죽음의 징조"
  },
  Event_146279_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146279_Desc = {
    Text = "그림자는 빛의 반사된 현상에 불과하다.\n틴커트가 본 것도, 아마 그녀 자신의 그림자일 뿐일 것이다.\n그녀의 모행성은 수천만 광년 너머에 있고, 가던 중에 조그마한 항로 이탈이라도 나는 순간 그들을 서로 다른 은하계에 추락하게 만들 수 있기 때문이다.\n그렇게 스스로를 달래며, 당신은 더 이상 발밑의 그림자에 집착하지 않는다."
  },
  Event_146279_Name = {
    Text = "호수 바닥에 드리운 그림자"
  },
  Event_146280_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146280_Desc = {
    Text = "별들로부터. 태고로부터. 인류가 아직 알지 못하는, 어쩌면 영원히 알 수 없는 곳으로부터.\n그분께 답을 구하지 마라.\n당신은 대가를 알지 못한다."
  },
  Event_146280_Name = {
    Text = "얼음 호수의 아리아"
  },
  Event_146281_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146281_Desc = {
    Text = "당신은 발걸음을 멈춘 채, 그 쓸쓸한 선율이 귀가에 가득 차도록 내버려두었다.\n바람의 소리는 마치 바이올린의 선율처럼 들리고, 눈송이는 북소리같이 웅장하며, 먼 곳에서 얼음층이 갈라지는 굉음은 오랫동안 억눌려 있던 낮은 화음같이 들려왔다.\n당신은 그 주제에 대해서 이해를 못 하지만, 그것이 과거나 미래에, 이곳에 몸을 묻는 수많은 여행자들을 위해 반복해서 연주될 것임을 알고 있었다."
  },
  Event_146281_Name = {
    Text = "자연의 환상곡"
  },
  Event_146283_ChoiceDesc1 = {
    Text = "[하늘빛을 올려다본다] 모든 깨어남체의 광기를 Arg1 회복하기"
  },
  Event_146283_ChoiceDesc2 = {
    Text = "[얼음 봉우리를 디딘다] 깨어남체 2명을 선택해 깨어남하기"
  },
  Event_146283_Desc = {
    Text = "정상이 구름 속에서 조용히 빛난다.\n계곡, 암벽, 폭풍, 이곳에 자리한 것들은 결코 인간을 위해 존재한 것이 아니다.\n그 속에 서 있는 당신은, 이토록 나약한가."
  },
  Event_146283_Name = {
    Text = "정상에 닿다"
  },
  Event_146284_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146284_Desc = {
    Text = "「아니, 네 잘못이 아니야.」\n「너는 그저 태엽이 감긴, 운명의 장난감일 뿐이야.」"
  },
  Event_146284_Name = {
    Text = "탐욕스러운 쥐"
  },
  Event_146285_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146285_Desc = {
    Text = "「알겠어, 너는 객관적 경험을 정리하는 데 능숙한 타입이구나. 하지만 잊지 마. 때로는 비슷한 표면 아래에, 전혀 다른 가능성이 숨겨져 있을 수 있어.」 종소리가 웃으며 멀어져 갔다."
  },
  Event_146285_Name = {
    Text = "파블로프의 반사"
  },
  Event_146286_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146286_Desc = {
    Text = "콩 심은 데 콩 나고 팥 심은 데 팥 난다가 공평한 것이라면, 심은 것을 모를 경우 어떤 쪽이 콩이고 팥인지 누가 알겠는가?\n아누비스의 저울이 그걸 판단하나?\n저승의 중력이 물리학의 원리를 따른다면, 당신은 자신의 심장이 그 깃털보다 가볍다는 확신은 있다."
  },
  Event_146286_Name = {
    Text = "터무니없는 공평함"
  },
  Event_146287_ChoiceDesc1 = {
    Text = "[계속 추궁한다] 백은 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146287_ChoiceDesc2 = {
    Text = "[침묵한다] 백은 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146287_ChoiceDesc3 = {
    Text = "[사과한다] 검은 인장 25 획득하기"
  },
  Event_146287_Desc = {
    Text = "「윌리엄 선배, 모두가 웬디고의 유혹에 빠졌을 때, 선배가 처음 깨어났었던 것 같아요. 이제 곧 웬디고 무리들과 정면으로 맞서야 하는데, 혹시 관련된 족보 없나요?」\n윌리엄의 눈빛이 미세하게 흔들리면서, 그의 눈빛 속에는 당신이 포착하기 어려운 멍함과 슬픔, 고요함이 엿보였다.\n마치 빛이 스며드는 바닷물 속에 잠겨, 휘청거리며 심해 밑바닥으로 가라앉는 듯했다.\n「미안하지만, 내가 도와줄 수 있는 건 없는 것 같아.」"
  },
  Event_146287_Name = {
    Text = "부드러운 침몰"
  },
  Event_146288_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146288_Desc = {
    Text = "「인정사정없구나, 인정사정없어.」검은 그림자가 고개를 저으며 나타났다. 「진실타래은 뼛속까지 시린 독이 될 수 있어. 때로는 환상을 받아들이는 편이 현재의 행복을 유지하는 데 더 나을 수 있지 않을까?」"
  },
  Event_146288_Name = {
    Text = "기어다니는 검은 고양이"
  },
  Event_146290_ChoiceDesc1 = {
    Text = "[누가 범인인가] 「(Skill.Arg1)」에 감염되고, 랜덤 카드 1장에 각인 「(EnchantConfig.Arg2)」을(를) 획득하기"
  },
  Event_146290_ChoiceDesc2 = {
    Text = "[내 잘못이다] 「(Skill.Arg1)」에 감염되고, 랜덤 카드 1장에 각인 「(EnchantConfig.Arg2)」을(를) 획득하기"
  },
  Event_146290_ChoiceDesc3 = {
    Text = "[탐식의 대가] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_146290_Desc = {
    Text = "「꼬마 쥐야, 기어 올라가. 하수도는, 깜깜하고 길으니까. 그리고, 갑자기 치즈 냄새가 나더라.」\n「꼬마 쥐야, 치즈를 끌고, 집으로 달려가. 머리가 윙윙거려, 어지러워.」\n「문 열어, 문 열어 달라고, 집안은 조용하기만 해.」\n「형제자매들이 바닥에 누워 있고, 배에는 모두 구멍이 하나씩, 하나씩.」"
  },
  Event_146290_Name = {
    Text = "탐욕스러운 쥐"
  },
  Event_146291_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146291_Desc = {
    Text = "너는 몸을 낮추어, 그녀의 뺨에 맺힌 눈물 자국을 닦아주며, 그 눈물의 진위를 묻지 않았다.\n당신이 말했다. 「진짜든 가짜든, 누군가에게 증명할 필요까지는 없어.」\n카라부가 입을 열었다 닫았다, 준비해 두었던 농담 섞인 말은 결국 나오지 못했다.\n그녀의 눈물은 아무런 예고도 없이 터져 나와, 당신의 손등에 떨어졌다."
  },
  Event_146291_Name = {
    Text = "악어의 눈물"
  },
  Event_146292_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146292_Desc = {
    Text = "「묻지 않는 게 좋아. 어떤 질문은 답을 알 필요가 없으니까.」"
  },
  Event_146292_Name = {
    Text = "탐욕스러운 쥐"
  },
  Event_146293_ChoiceDesc1 = {
    Text = "[소리 내어 경고한다] 백은 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146293_ChoiceDesc2 = {
    Text = "[계속 귀를 기울인다] 모든 깨어남체가 광기를 50 회복하고, 「(Skill.Arg1)」에 감염되기"
  },
  Event_146293_ChoiceDesc3 = {
    Text = "[어깨를 으쓱하며 무시한다] 각인 3개 중 1개를 선택해 획득하기"
  },
  Event_146293_Desc = {
    Text = "나라카가 추락한 곳에는 오직 어둠만이 드리울 뿐이다.\n진흙 속에서 축축한 선율이 마치 창백하고 차가운 두 손이 간절히 당신의 뺨을 어루만지듯 흘러나오고 있다.\n낮은 목소리의 음색으로 「자, 밤의 고요 속에서 내게로 오라.」하며 노래하고 있다."
  },
  Event_146293_Name = {
    Text = "그리움의 목소리"
  },
  Event_146294_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146294_Desc = {
    Text = "당신은 고개를 숙인 채, 그 연기가 폴룩스의 윤곽을 흐리게 만들도록 내버려두었고, 결국 그의 표정까지 회백빛 안갯속에 감춰졌다.\n당신은 스스로에게 소리친다——이게 가장 안전해. 보면 안 돼, 생각해서는 안 돼.\n율리에트의 설교가 여전히 귀가에 흐르고 있고, 당신은 포개어진 자신의 두 손을 뚫어지게 바라본 채, 한 마디도 하지 않았다.\n의식의 종소리가 울릴 때, 당신은 겨우 다시 고개를 들었다.\n그리고 폴룩스는 여전히 경건한 자세를 유지하고 있었다.\n긴 시간과 환상을 넘어, 당신은 그 순간에 무언가가 빠져나갔는지 알 수 없었다."
  },
  Event_146294_Name = {Text = "옛꿈 Ⅲ"},
  Event_146295_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146295_Desc = {
    Text = "「폴룩스——」 당신의 목소리가 목구멍을 통과하려는 순간, 당신은 그걸 스스로 꾹 삼켜버렸고, 이 향연기 속에는 오직 숨소리 같은 미세한 잔향만이 남겨졌다.\n주변 신도들의 경전을 암송하는 소리의 물결은 멈출 기세가 안 보였지만, 몇몇 시선들이 눈에 띄지 않게 스쳐 지나갔다.\n폴룩스는 갑자기 굳어져서는 눈빛에 당혹감을 감추지 못한 듯 했지만, 다시 곧바로 각인된 순종적인 표정으로 얼굴을 덮었다.\n그는 응답하지 않았지만, 눈을 내리깔고, 손가락은 소매 속에서 조금씩 움켜쥐고 있었다—— 그렇다, 그는 분명 들었다."
  },
  Event_146295_Name = {Text = "옛꿈 Ⅲ"},
  Event_146297_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146297_Desc = {
    Text = "적어도 그 순간만큼은, 당신은 그녀가 혼자 등반대에서 쫓겨나는 것을 가만히 지켜보고만 있을 수는 없었다.\n지금 당장 해결해야 할 문제를 미래의 자신에게 맡기지는 말자."
  },
  Event_146297_Name = {
    Text = "계략 속의 계략"
  },
  Event_146298_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146298_Desc = {
    Text = "「폴룩스, 우리는 서로 다른 방향으로 가는 게 좋을 것 같아. 그러면 숲의 경계를 찾을 확률이 더 높아질 거야.」\n「그럼 형은 어떻게 나를 찾을 건데?」\n흐릿한 시간 너머로, 당신은 그의 실타래망한 표정을 바라본다. 고통이 당신의 심장을 조여 온다. 당신은 깊게 숨을 들이쉬고, 천천히 내쉰다.\n「우리는 쌍둥이야. 서로의 심장 소리를 읽을 수 있잖아.」\n「우리는 절대 헤어지지 않아.」"
  },
  Event_146298_Name = {Text = "옛꿈 Ⅰ"},
  Event_146299_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146299_Desc = {
    Text = "그것은 심판한다. 또한, 그것은 묻는다. 결국 돌아오지 못한 모든 도전자들에게 차가운 죽음을 선사한다."
  },
  Event_146299_Name = {
    Text = "설선의 심판"
  },
  Event_146300_ChoiceDesc1 = {
    Text = "[다시 시작하기] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146300_ChoiceDesc2 = {
    Text = "[이건 아무래도 힘들다] 백은 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146300_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_146300_Desc = {
    Text = "벌레가 그녀에게 거짓말을 가르쳤다.\n그 외에, 그녀는 어떻게 살아남아야 하는지 배운 적이 없다.\n하지만 거짓말은 결국 거짓말일 뿐, 어느 날부터인가 너는 그것의 지탱 없이 살아가야 한다."
  },
  Event_146300_Name = {
    Text = "환상인가 현실타래인가"
  },
  Event_146301_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146301_Desc = {
    Text = "「그래. 하지만 그렇게 작은 쥐가, 탐식의 대가가 무엇인지 어떻게 알았겠어?」"
  },
  Event_146301_Name = {
    Text = "탐욕스러운 쥐"
  },
  Event_146302_ChoiceDesc1 = {
    Text = "[빨간 줄 묶기] 명령 카드 1장 삭제 후, 검은 인장 Arg1 획득하기"
  },
  Event_146302_ChoiceDesc2 = {
    Text = "[빨간 줄을 뿌리치기] 명령 카드 1장 복제 후, 「(Skill.Arg1)」 감염되기"
  },
  Event_146302_ChoiceDesc3 = {
    Text = "[현실타래로 돌아가기] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_146302_Desc = {
    Text = "첫 번째 꿈. 숲 속의 꿈. 열 살도 채 되지 않은 두 아이가, 교주에 의해 깊은 숲 속에 버려졌다.\n「해가 지면, 잠든 야수들이 사냥을 시작할 거란다. 그전에 탈출하는 거다. 탈출하는 아이가 내 착한 아이다.」\n동생이 그의 손을 잡으며, 빨간 줄 한 가닥을 꺼냈다.\n「형, 손을 묶자. 그러면, 우리는 헤어지지 않을 거니까.」"
  },
  Event_146302_Name = {Text = "옛꿈 Ⅰ"},
  Event_146304_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146304_Desc = {
    Text = "당신은 기쁨, 도발, 그리고 흥미에 가득 찬 어떤 웃음소리를 듣는다.\n인류가 전력을 다해 우주를 탐험하는 것.\n그것은 그분들의 눈에는 그저 개미가 기어오르는 것에 불과했으니까."
  },
  Event_146304_Name = {
    Text = "내려다보는 자"
  },
  Event_146306_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146306_Desc = {
    Text = "그것은 정화시킬 것이다. 그것은 또한 녹여낼 것이다. 또한, 돌아오지 못한 모든 등반자들을 그 속에 품어 받아들일 것이다."
  },
  Event_146306_Name = {
    Text = "설선의 심판"
  },
  Event_146307_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146307_Desc = {
    Text = "당신과 까마귀는 대치 상태에 빠졌다.\n분명한 것은, 이 대치 속에서 당신은 최후의 승자가 될 수 없다는 것이다.\n율리에트와의 대항 속에서, 당신들은 결코 승자가 될 수 없는 것 같다."
  },
  Event_146307_Name = {Text = "옛꿈 Ⅱ"},
  Event_146308_ChoiceDesc1 = {
    Text = "[누가 나를 보고 있는 거지?] 랜덤으로 깨어남체 1명을 깨어남하고, 「(Skill.Arg1)」에 감염되기"
  },
  Event_146308_ChoiceDesc2 = {
    Text = "[다른 곳에 정신 팔리면 안 돼] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_146308_Desc = {
    Text = "얼음과 눈(雪)을 머금은 바람이 인간의 발자취가 닿은 가장 높은 곳을 휘감으며 불고 있다.\n당신은 고개를 들어 올려다보지만, 더 높은 곳에는 오직 영원히 꺼지지 않는 태양만이 비춰지고 있을 뿐이었다.\n하지만 당신은 더 높고 더 머나먼 어딘가에는, 셀 수 없는 수 많은 눈들이 뜨거나 감겨 있거나 둘 중 하나라는 것을 알고 있었다.\n그중 몇몇은, 고요히 당신의 발밑에 있는 온 세상을 내려다보고 있다는 것을."
  },
  Event_146308_Name = {
    Text = "내려다보는 자"
  },
  Event_146309_ChoiceDesc1 = {
    Text = "[아직 미련이 남아있어] 저주 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」 감염되기"
  },
  Event_146309_ChoiceDesc2 = {
    Text = "[이미 잊은지 오래야] 랜덤 카드 1장에 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_146309_Desc = {
    Text = "당신은 뇌 속에서 「기억」을 저장하는 모듈을 차단하려 한다.\n그 비밀 상자 속에는 당신을 구성하는 모든 답이, 당신이 입 밖에 내기 부끄러운 모든 생각이, 드러내고 싶지 않은 모든 상상이 숨겨져 있다.\n하지만 욕망은 잠재의식의 저주다, 당신은 저항할 수 없는 집착의 환몽에 빠져든다."
  },
  Event_146309_Name = {
    Text = "잠재의식의 저주"
  },
  Event_146310_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146310_Desc = {
    Text = "윌리엄이 당신의 시선을 피했다.\n「의식은 유혹에 맞서는 무장이야. 그리고 각자의 인생 경험들이 그의 의식을 결정해. 그건 대체할 수도 없어서 족보는 무용지물이지.」\n「내가 말해줄 수 있는 건, 연약함에 자신을 내맡기지 말라는 것뿐이야.」"
  },
  Event_146310_Name = {
    Text = "부드러운 침몰"
  },
  Event_146311_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146311_Desc = {
    Text = "「알겠어, 너는 철학자가 되고 싶어 하는 타입이구나. 하지만 잊지 마. 기대가 없다고 해서, 고통이 없는 건 아니니까.」 종소리가 웃으며 멀어져 갔다."
  },
  Event_146311_Name = {
    Text = "파블로프의 반사"
  },
  Event_146312_ChoiceDesc1 = {
    Text = "[떠나다]“(Skill.Arg1)” 감염, 50개 검은 인장 획득"
  },
  Event_146312_Desc = {
    Text = "「배고파, 배고파.」\n산이 울부짖고, 산이 애절히 울부짖는다.\n산은 자신의 배 속이 텅 비어있음을 견딜 수가 없었다."
  },
  Event_146312_Name = {
    Text = "산의 비밀"
  },
  Event_146313_ChoiceDesc1 = {
    Text = "[암벽을 걷어찬다] 명령 카드 1장을 삭제하고, HP를 Arg1 회복하기"
  },
  Event_146313_ChoiceDesc2 = {
    Text = "[안전 로프를 붙잡는다] 황금 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146313_Desc = {
    Text = "오색빛의 환각이 당신의 머릿속을 뒤흔든다.\n처음은 가벼운 가루 눈부터 시작해,\n그다음은 무너질 듯한 처마 눈까지.\n당신은 자신의 미끄러짐을 막지 못 하며, 안전 로프가 클립의 마찰로 인해 눈부신 불꽃을 튕겨낸다.\n하지만 산의 무리 한 가운데서,그것은 너무나 작고 나약하기만 할 뿐이었다."
  },
  Event_146313_Name = {
    Text = "소리 없는 추락"
  },
  Event_146314_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146314_Desc = {
    Text = "「꿈속에서 나를 찾아와, 내가 다시 내 삶을 살 수 있게 해다오.」\n하며 축음기가 한 번 흐느끼더니, 숨소리가 점차 어둠 속으로 사라졌다.\n이제 그곳은 오직 메아리만이 맴돌 뿐이었다."
  },
  Event_146314_Name = {
    Text = "그리움의 목소리"
  },
  Event_146315_ChoiceDesc1 = {
    Text = "[후회가 스쳐간다] 백은 유물 「(RelicConfig.Arg1)」을(를) 획득하기"
  },
  Event_146315_ChoiceDesc2 = {
    Text = "[모든 것은 운명에 맡기자] 황금 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146315_Desc = {
    Text = "당신은 이 여정이 생각만큼 그리 간단하지 않다는 것을 항상 인지하고 있다. 이 등반대의 있는 자들은 대부분 각자의 속내를 품고 있었으니까.\n하지만 당신은 카라부가 점차 광기에 빠져드는 듯 거만해진 웃음을 바라보기만 하며, 여전히 유리 조각이 깨지는 듯 째지는 소리가 당신의 가슴속에서 터져 나오는 것을 느꼈다.\n아마도 나라카가 그녀를 이 등반대에서 쫓아내려 할 때, 당신은 다른 선택을 했어야 할지도 모른다."
  },
  Event_146315_Name = {
    Text = "계략 속의 계략"
  },
  Event_146316_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146316_Desc = {
    Text = "얼마나 많은 이들이 이곳에 삼켜졌을까?\n끈적한 깊은 웅덩이 속에서 검은 손이 뻗어나와, 당신을 그들의 세계로 끌어들이려 한다.\n하지만 당신은 그저 앞으로 나아갈 뿐, 그것들도 당신을 붙잡으려 하지 않고 하나둘 물러난다.\n앞에는 아직 정상이 당신을 기다리고 있으리니."
  },
  Event_146316_Name = {
    Text = "그리움의 목소리"
  },
  Event_146317_ChoiceDesc1 = {
    Text = "[포기한다] 검은 인장 25 획득하기"
  },
  Event_146317_ChoiceDesc2 = {
    Text = "[몸을 굽혀 살펴본다] 백은 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146317_Desc = {
    Text = "틴커트의 시선을 따라, 당신은 참지 못하고 호수 바닥을 응시했다.\n그 그림자 속에는 도대체 무엇이 그녀를 끌어당기고 있는 것일까?\n하지만, 얼음 위에는 희미하게 당신의 그림자만이 비치고 있었을 뿐. 당신은 그걸 선명히 볼 수 없었다."
  },
  Event_146317_Name = {
    Text = "호수 바닥에 드리운 그림자"
  },
  Event_146318_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146318_Desc = {
    Text = "삼킴에 저항하는 유일한 방법은 버리는 것이다.\n누구도 자신이 가진 적 없던 것을 잃을 수는 없다.\n웬디고가 이를 드러내고, 목구멍에서 억울한 듯한 낮은 으르렁거림을 내뿜으며, 한 걸음 한 걸음 안개 속으로 물러난다."
  },
  Event_146318_Name = {
    Text = "잠재의식의 저주"
  },
  Event_146319_ChoiceDesc1 = {
    Text = "[눈(雪)이 나를 정화시키리라] 랜덤 카드 1장의 각인 품질 상승시키기"
  },
  Event_146319_ChoiceDesc2 = {
    Text = "[눈(雪)이 나를 심판하리라] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146319_Desc = {
    Text = "코앞이 바로 마지막 등반이다. 근데, 설선은 차갑고 끝없이 펼쳐져만 있다.\n쌓여진 눈(雪)은 죽음조차도 깨끗하게 보일 만큼 새하얗게 눈부시기만 하다."
  },
  Event_146319_Name = {
    Text = "설선의 심판"
  },
  Event_146320_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146320_Desc = {
    Text = "그 장면의 어떤 세부사항도 놓치지 마.\n그것들을 머릿속에 새겨.\n그 순간 스쳐간 멍함과 공허, 그리고 뒤따라 밀려든 고통까지도 각인시켜.\n절대 잊지 마."
  },
  Event_146320_Name = {
    Text = "저편에서 오다"
  },
  Event_146321_ChoiceDesc1 = {
    Text = "[공동 작전] 백은 유물 「(RelicConfig.Arg1)」을(를) 획득하기"
  },
  Event_146321_ChoiceDesc2 = {
    Text = "[진정하기] 황금 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」 감염되기"
  },
  Event_146321_Desc = {
    Text = "산이 격렬하게 떨린다, 마치 죽어가는 생명체처럼.\n마디마디의 창백한 살덩어리가 갈라진 암반 아래에서 솟아오르고, 한 마디씩 높이 자라며 서로 얽히고, 카라부를 거칠게 내팽개친다.\n다시 당신들 앞에 모습을 드러냈을 때, 그녀의 뺨에는 이미 눈물 자국이 흘러내리고 있었다.\n그것은 고통의 눈물일까?\n당신은 확신할 수 없다.\n수많은 거짓말이 그녀의 입에서 흘러나왔는데, 누가 악어의 눈물을 믿겠는가?"
  },
  Event_146321_Name = {
    Text = "악어의 눈물"
  },
  Event_146322_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146322_Desc = {
    Text = "당신은 답을 묻지 않고, 그저 그녀의 곁에 섰다.\n당신이 말했다. 「일어나. 연극은 아직 대본의 반 밖에 오지 못했는데, 중간에 그만두면 안 되지.」\n카라부는 잠시 멈칫하다가, 세게 얼굴을 문질렀다.\n그녀는 비틀거리며 일어나, 다시 무기를 단단히 쥐고, 어깨를 나란히 하고 다시 벌어진 거대한 주둥아리를 향해 나아갔다.\n거짓말을 너무 많이 해서, 그녀 자신조차 어느 눈물이 진짜인지 가짜인지 분간하기 어려울 정도다.\n하지만 적어도 이번만큼은, 누구도 진위를 따지지 않았다."
  },
  Event_146322_Name = {
    Text = "악어의 눈물"
  },
  Event_146323_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146323_Desc = {
    Text = "「알겠어, 너는 표면을 꿰뚫어 보는 데 능숙한 타입이구나. 하지만 잊지 마. 그 순간의 현실타래 속에서, 음식은 오직 네 경험과 환상 속에만 존재했어.」 종소리가 웃으며 멀어져 갔다."
  },
  Event_146323_Name = {
    Text = "파블로프의 반사"
  },
  Event_146324_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146324_Desc = {
    Text = "당신은 가볍고 느리게 발걸음을 옮겼다.\n조용히, 천천히, 소리 없이……\n그렇게 다음 모퉁이를 돌아서 빠져나갔다.\n그 까마귀가 결국 따라왔을까?\n당신은 이미 기억나지 않는다."
  },
  Event_146324_Name = {Text = "옛꿈 Ⅱ"},
  Event_146325_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146325_Desc = {
    Text = "선율이 갑자기 툭 끊겼다.\n검은 진흙 속에서 간절히 바라는 두 눈이 떠졌다.\n그 눈이 축축하게 당신을 바라보며, 당신이 분간하기 어려운 내용을 낮은 목소리로 속삭였다.\n그리고는 천천히, 다시 천천히 감겼다."
  },
  Event_146325_Name = {
    Text = "그리움의 목소리"
  },
  Event_146326_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146326_Desc = {
    Text = "당신은 오래 머물며 그 선율을 감상하는 걸 뒤로 한 채, 바람 소리보다 더 빠른 소리로 발걸음을 내며 눈을 밟기 시작했다.\n하지만 아무리 빨리 걸을 지라도, 그 쓸쓸한 선율은 한 걸음도 빠지지 않고, 여전히 당신을 집요하게 따라왔다.\n당신은 도망칠 수 없다—— 그것이 이 설산 자체의 숨결이며, 당신은 그저 우연히 지나가는 작은 청중일 뿐이니까."
  },
  Event_146326_Name = {
    Text = "자연의 환상곡"
  },
  Event_146327_ChoiceDesc1 = {
    Text = "[그것에 귀를 기울인다] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146327_ChoiceDesc2 = {
    Text = "[신경 쓰지 않는다] 광기 수치가 50 이상인 깨어남체 하나당 검은 인장 15 획득하기"
  },
  Event_146327_ChoiceDesc3 = {
    Text = "[강제 퇴장]3개 중에서 1개의 각인을 획득"
  },
  Event_146327_Desc = {
    Text = "바람 사이로 머나먼 노랫소리가 섞이며 귀에 들려오기 시작한다.\n노랫소리는 사방에서, 또는 땅속에서 오는 듯해 보였다.\n당신이 어느 방향으로 추적을 하든, 그것은 같은 강도로 귀에 메아리쳐 갔다."
  },
  Event_146327_Name = {
    Text = "얼음 호수의 아리아"
  },
  Event_146328_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146328_Desc = {
    Text = "「죽음의 징조의 별이여, 지금은 네가 빛날 때가 아니다.」\n「나의 여정에는 아직 닿지 못한 종점이 남아 있다.」\n「부디 잠시 불을 꺼주어, 오늘 밤 하늘이 다시 평온을 되찾게 해다오.」"
  },
  Event_146328_Name = {
    Text = "다가오는 죽음의 징조"
  },
  Event_146329_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146329_Desc = {
    Text = "쓸데없는 후회가 밀려온다.\n인간은 왜 항상 부득이하게 과거의 자신이 만든 아수라장을 수습해야만 할까."
  },
  Event_146329_Name = {
    Text = "계략 속의 계략"
  },
  Event_146330_ChoiceDesc1 = {
    Text = "[음미해볼까?] 랜덤으로 깨어남체 1명을 깨어남시키고, 「(Skill.Arg1)」에 감염되기"
  },
  Event_146330_ChoiceDesc2 = {
    Text = "[거부하기]3중에서 1개의 각인 획득"
  },
  Event_146330_Desc = {
    Text = "눈안개 깊은 곳에 앙상한 시신 하나가 엎드려 있다, 갈비뼈가 갈라진 가죽을 받치고 있고, 머리 위에는 두 개의 마른 나뭇가지 같은 뿔이 안개를 뚫고 솟아 있다.\n그 배 속에서 텅 빈 꼬르륵 소리가 울려 퍼진다.\n당신과 시선이 마주친 순간, 그 깊이 패인 눈구멍 속에서 부서진 장면들이 일렁인다—— 그것은 당신의 기억이다. 그것은 이미 그 맛을 보았다.\n「아직이야, 아직 모자라……」 쉰 목소리로 신음하며 마른 손을 당신에게 내미는데, 그 자세에는 간청조차 섞여 있다."
  },
  Event_146330_Name = {Text = "탐식자"},
  Event_146332_ChoiceDesc1 = {
    Text = "[천장] 백은 유물 「(RelicConfig.Arg1)」 획득하기"
  },
  Event_146332_ChoiceDesc2 = {
    Text = "[쫓아내기]75 검은 인장 획득, 감염 [(Skill.Arg2)]"
  },
  Event_146332_Desc = {
    Text = "수염독수리가 상승기류를 타고 높은 하늘을 선회하며 영토를 순찰한다.\n하지만, 등반가들 사이에서 이는 언제나 나쁜 징조로 여겨져 왔다.\n「저것들은 먹이를 찾고 있어. 독수리는 죽음의 냄새를 맡을 수 있으니까.」"
  },
  Event_146332_Name = {
    Text = "다가오는 죽음의 징조"
  },
  Event_146333_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146333_Desc = {
    Text = "자신의 두 다리를 믿어라.\n당신은 정상을 정복할 것이니."
  },
  Event_146333_Name = {
    Text = "정상에 닿다"
  },
  Event_146334_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146334_Desc = {
    Text = "미련이 머릿속에 스쳐 오르는 순간, 당신은 이미 저항할 힘이 없음을 깨닫고, 그것이 오랫동안 봉인된 당신의 기억 보물창고로 마음껏 침투하도록 내버려 둘 수밖에 없다.\n새하얀 송곳니가 당신의 관자놀이를 파고들며, 한 장면 한 장면의 장면이 뿌리째 뽑혀 나간다."
  },
  Event_146334_Name = {
    Text = "잠재의식의 저주"
  },
  Event_146335_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146335_Desc = {
    Text = "그것이 몸을 숙여 당신에게 다가오며, 코끝은 거의 당신의 이마에 닿을 듯하다. 그 표정은 마치 꿀 한 조각을 음미하듯 깊이 취해 있다.\n불안하게 출렁이던 감정들이 말끔히 핥아 먹힌다.\n그것은 흡족한 듯 웅얼거리며 물러서고, 눈에는 요염한 빛이 일렁인다.\n당신의 가슴에는 빈 구멍이 생겼지만, 묘하게도…… 한결 가벼워졌다."
  },
  Event_146335_Name = {Text = "탐식자"},
  Event_146336_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146336_Desc = {
    Text = "나라카의 목소리가 당신의 귀에 울려 퍼진다. 「발밑 조심해. 한 걸음 한 걸음 단단히 디뎌. 남이 너를 대신해 뒷감당해주길 바라지 마.」"
  },
  Event_146336_Name = {
    Text = "내려다보는 자"
  },
  Event_146337_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146337_Desc = {
    Text = "인간은 하늘에 닿아야 한다.\n목표는 사람으로 하여금 위험을 잊게 만든다.\n드넓은 하늘이 머리 위에서 당신을 기다리고 있다."
  },
  Event_146337_Name = {
    Text = "정상에 닿다"
  },
  Event_146338_ChoiceDesc1 = {
    Text = "[추억 되감기] 황금 유물 「(RelicConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」 감염되기"
  },
  Event_146338_ChoiceDesc2 = {
    Text = "[환상을 붙잡기] 황금 유물 3개 중 1개 선택하고, 「(Skill.Arg1)」 감염되기"
  },
  Event_146338_ChoiceDesc3 = {
    Text = "[떠나기] 백은 유물 「(RelicConfig.Arg1)」 획득하기"
  },
  Event_146338_Desc = {
    Text = "윌리엄을 죽인 범인이, 지금 바로 네 눈앞에 있다.\n아란의 텐트 안, 메스꺼운 공기 속에서, 윌리엄의 창백한 얼굴, 떠 있는 시신, 그리고 탁자 위에 해부된 그 작은 램프가 다시 네 기억에 떠오른다."
  },
  Event_146338_Name = {
    Text = "저편에서 오다"
  },
  Event_146339_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146339_Desc = {
    Text = "안전 로프가 끊어졌다.\n당신은 눈더미 속에 거칠게 추락하며, 오장육부가 둔한 통증 속에서 치명적인 경보를 울려댔다.\n어지럼증을 참으며 눈을 떠보니, 이름 모를 백골과 당신이 서로 마주한다.\n그의 텅 빈 동공 속에서, 무언가가 반짝이는 것 같다."
  },
  Event_146339_Name = {
    Text = "소리 없는 추락"
  },
  Event_146340_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146340_Desc = {
    Text = "피할 수 없어.\n당신은 이를 악물고, 몸을 날려 질주하는 속도로 감시자를 따돌리려 한다.\n까마귀가 괴이하게 울부짖으며 날개를 퍼덕이고, 여유롭게 당신들 위를 따라오면서 심지어 가볍게 한 바퀴 선회하기까지 한다.\n차가운 절망이 그 시선을 따라 당신의 몸속으로 스며든다.\n너희는 도망칠 수 없어."
  },
  Event_146340_Name = {Text = "옛꿈 Ⅱ"},
  Event_146341_ChoiceDesc1 = {
    Text = "[콩 심은 데 콩 나고 팥 심은 데 팥 난다] 랜덤 명령 카드 1장 및 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_146341_ChoiceDesc2 = {
    Text = "[떡이 별 떡 있지 사람은 별사람 없다] 최대 HP가 Arg1 증가하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_146341_Desc = {
    Text = "당신은 절벽에 매달려 있지만, 머릿속에 갑자기 뜬금없는 질문이 떠오르기 시작한다. 「무엇이 과연 공평인 걸까?」"
  },
  Event_146341_Name = {
    Text = "터무니없는 공평함"
  },
  Event_146342_ChoiceDesc1 = {
    Text = "[떠나다]“(Skill.Arg1)” 감염, 50개 검은 인장 획득"
  },
  Event_146342_Desc = {
    Text = "「나는 아직 죽을 수 없어!」\n산이 울부짖고, 산이 애절히 울부짖는다.\n산은 탐욕 때문에 내일의 가능성을 잃었음을 견딜 수 없었다."
  },
  Event_146342_Name = {
    Text = "산의 비밀"
  },
  Event_146343_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_146343_Desc = {
    Text = "당신은 뺨이 얼음면에 닿을 때까지 몸을 굽혀갔다.\n뼛속까지 시리는 서늘함이 피부를 통해 침투하며, 결국 견디지 못해 당신은 몸을 떨었다.\n분간하기 어려운 존재가 얼어붙은 얼음층 아래에서 천천히 뒤척이고 있다. 그건 물줄기일까, 아니면 어떠한 생명체일까?\n어느 쪽이든, 당신의 여정과는 무관하다."
  },
  Event_146343_Name = {
    Text = "호수 바닥에 드리운 그림자"
  },
  Event_148532_ChoiceDesc1 = {
    Text = "[축복을 받기] 전투 시작 시, 랜덤 「천변만화의 열매」 1장을 생성하여 덱에 넣는다."
  },
  Event_148532_Desc = {
    Text = "끝없이 펼쳐진 설원에 차가운 바람조차 소리 하나 일으키지 못하고, 어디서 왔는지 알 수 없는 환영이 소리 없이 나타나 따뜻한 과실 하나를 건네온다.\n달콤한 향기가 안개와 뒤섞여 얼어붙은 나그네의 코끝으로 스며든다. \n이 설원은 이미 죽음에 흠뻑 젖어, 공기 중에는 부패와 혹한의 역겨운 냄새가 떠돌고 있건만, 오직 손바닥 위의 이 과실만이 탐스럽게 영글어, 마치 소녀의 달콤한 유혹과도 같다."
  },
  Event_148532_Name = {
    Text = "하늘 위 신기루"
  },
  Event_20778_ChoiceDesc1 = {
    Text = "【그녀에게 맡겨요】모든 깨어남체가 Arg1의 광기를 회복합니다"
  },
  Event_20778_ChoiceDesc2 = {
    Text = "【지원 필요】2명의 깨어남체 선택"
  },
  Event_20778_Desc = {
    Text = "「미사그로부터의 통신입니다. \n깨어남체의 비정상적인 영성 지수 변동을 감지했습니다.\n 지원이 필요하십니까?」"
  },
  Event_20778_Name = {
    Text = "지원 통신"
  },
  Event_20779_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_20779_Desc = {
    Text = "“긴급 지원을 제공했습니다. 수령 후 브로치를 세 번 두드려 확인해 주세요.”"
  },
  Event_20779_Name = {
    Text = "지원 통신"
  },
  Event_20780_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_20780_Desc = {
    Text = "먼 미래에서 온 환영, 엘워스의 산악 지대에 사라지다."
  },
  Event_20780_Name = {
    Text = "화산 환영"
  },
  Event_20781_ChoiceDesc1 = {
    Text = "【원망 환영】모든 깨어남체가 Arg1 만큼의 광기를 회복합니다"
  },
  Event_20781_ChoiceDesc2 = {
    Text = "【가까이 다가가기】2명의 깨어남체 깨어남 선택"
  },
  Event_20781_Desc = {
    Text = "먼 곳에서 화산이 분출하고, 광풍이 휘몰아치는 하늘에서 사람 형상의 연기가 피어오르고 있다.\n이곳은 엘워스이며, 엘워스에는 끝없이 이어지는 높은 눈산과 석회암 지층의 용동만이 있을 뿐이다.\n연일의 이상이 너를 정신적으로 혼란스럽게 한 것인가?"
  },
  Event_20781_Name = {
    Text = "화산 환영"
  },
  Event_20782_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_20782_Desc = {
    Text = "환영이 당신에게 손을 흔들어 사라졌습니다. 당신에게 남은 것은 차가운 눈과 웅장한 산맥뿐입니다."
  },
  Event_20782_Name = {
    Text = "화산 환영"
  },
  Event_20783_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_20783_Desc = {
    Text = "“확인, 우리는 기본 자원을 전송할 것입니다. 수령에 주의해 주세요.”"
  },
  Event_20783_Name = {
    Text = "지원 통신"
  },
  Event_21398_ChoiceDesc1 = {
    Text = "【사진 줍기】3장의 명령 카드 중 1장을 선택하여 각인을 획득: “(EnchantConfig.Arg1)”"
  },
  Event_21398_Desc = {
    Text = "기계가 분해되고 진실타래이 드러났다. \n정열적인 삶이 흔적도 없이 사라졌고, 진실타래을 알게 된 충족감만이 남았다."
  },
  Event_21398_Name = {
    Text = "목격 증언"
  },
  Event_21399_ChoiceDesc1 = {
    Text = "【사진 줍기】3장의 명령 카드 중 1장을 선택하여 각인을 획득: “(EnchantConfig.Arg1)”"
  },
  Event_21399_ChoiceDesc2 = {
    Text = "【검사 필름】감염“(Skill.Arg1)”, 옵션 1에서 획득한 각인을 교체할 수 있으며, 한 번 더 사용 가능합니다"
  },
  Event_21399_Desc = {
    Text = "호기심이 당신을 이끌어, 시선을 현영지로 향하게 했습니다. \n그 이미지들은 진홍색 약수에 담겨 있었고, 온몸에 검은 때가 묻은 죄인은 당신과 똑같은 얼굴을 하고 있었습니다."
  },
  Event_21399_Name = {
    Text = "목격 증언"
  },
  Event_21400_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_21400_Desc = {
    Text = "기계가 분해되고 진실타래이 드러났다. \n정열적인 삶이 흔적도 없이 사라졌고, 진실타래을 알게 된 충족감만이 남았다."
  },
  Event_21400_Name = {
    Text = "목격 증언"
  },
  Event_21811_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_21811_Desc = {
    Text = "“25년… 맞아, 그녀가 나를 25년 동안 잠재웠어.”\n소녀는 음침하고 우울하게 당신에게 대답했다.\n단 한 번의 깨어남으로, 그녀를 어렸을 때부터 돌봐주던 하인들은 세월이 흐르면서 완전히 해양도약자가 되었다.\n더 이상 그녀의 괴로움을 이해하는 사람도 없고, 그녀의 고통을 걱정하는 사람도 없어, 그녀는 교단에서 홀로 남겨졌다.\n그녀는 잠들기 전의 그 하루가 “별의 정위 시”였으면 좋겠다고 생각한다."
  },
  Event_21811_Name = {
    Text = "갇힌 생명"
  },
  Event_22058_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22058_Desc = {
    Text = "“아니요, 저는 배가 고프지 않습니다.”\n당신은 이 화려한 잔치의 열정적인 초대를 예의를 지키며 거절했습니다.\n영혼을 빼앗는 대가로, 당신은 그것을 위해 가치를 내세우길 원하지 않았습니다."
  },
  Event_22058_Name = {
    Text = "체육 축제"
  },
  Event_22059_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22059_Desc = {
    Text = "너는 피가 흐르는 스콘을 무작정 씹어먹으며, 후추로 절인 심장과 반죽이 구워지는 냄새가 섞여 익숙한 냄새를 맡았다. \n「힘을 얻으려면 대가를 치러야 해.」\n너는 마지막 한 모금의 피를 마셨다."
  },
  Event_22059_Name = {
    Text = "체육 축제"
  },
  Event_22060_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22060_Desc = {
    Text = "너는 흰 국물과 으깬 고기를 그대로 삼키고 옷소매로 입술 주변의 자국을 닦아냈다. \n고기는 부드럽고 국물은 맛이 좋았다. 그것이 누구의 것이었는지는? \n그저 너가 잃어버린 것들의 일각에 불과하다."
  },
  Event_22060_Name = {
    Text = "체육 축제"
  },
  Event_22061_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22061_Desc = {
    Text = "너는 바람종에 각인된 고대의 문양을 세밀히 확인하기 한다. \n그것들은 상상할 수 없는 정도로 왜곡되어 있으며, 이해되기를 바라지 않는 듯하다. \n이해되지 않으면 방해받지 않는다."
  },
  Event_22061_Name = {
    Text = "녹슨 풍경종"
  },
  Event_22062_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22062_Desc = {
    Text = "“좋아, 당신은 매우 신중하구나.”\n바람 방울에서 갑자기 먼 곳에서 들려오는 목소리가 들렸다.\n“신중함이 당신에게 한 점의 작은 보상을 가져다줄 거야, 하지만 그것만으로는 부족할 거다.”"
  },
  Event_22062_Name = {
    Text = "녹슨 풍경종"
  },
  Event_22063_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22063_Desc = {
    Text = "당신은 바람개비에 각인된 고대의 각인을 무르기합니다. \n그들은 상상할 수 없는 정도로 왜곡되어 있으며，이해되기를 원하지 않는 것 같습니다. \n이해되지 않으면 방해받지 않습니다."
  },
  Event_22063_Name = {
    Text = "녹슨 풍경종"
  },
  Event_22064_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22064_Desc = {
    Text = "「아, 정말 아쉽다… 그럼 나는 외로운 독주를 계속해야겠군．」 당신은 하프와 손이 언제 사라졌는지 모릅니다． 하지만 시냇물 같은 하프 소리는 영원히 당신의 마음에 남아 있습니다．"
  },
  Event_22064_Name = {
    Text = "악기 옆 유령"
  },
  Event_22065_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22065_Desc = {
    Text = "“아, 이렇게 한 친구를 가질 수 있다니 정말 영광이야!” 그 손은 흥분하여 당신이 전혀 따라갈 수 없는 속도로 움직였다. 연주가 끝난 후에도 오랫동안 그 감동적인 소리는 여전히 당신의 마음을 달뜨게 했다."
  },
  Event_22065_Name = {
    Text = "악기 옆 유령"
  },
  Event_22175_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22175_Desc = {
    Text = "자판이 자신감에 차서 움직였고, 당신의 시선도 그에 따라 왔다 갔다 했다. \n하지만 그가 겨우 두 개의 글자를 가리켰을 때, 처참한 비명 소리와 함께 끈끈한 검은 액체로 변해버렸다."
  },
  Event_22175_Name = {Text = "통령판"},
  Event_22176_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22176_Desc = {
    Text = "“수학! 수학!!” \n 여자의 목소리가 이를 갈며, 점판이 숫자 사이를 빠르게 미끄러지며 날카로운 나무 마찰음을 냈다. \n “네 수학을 가지고 내 시야에서 사라져!”"
  },
  Event_22176_Name = {Text = "통령판"},
  Event_22177_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22177_Desc = {
    Text = "“잠깐, 잠깐!!” \n “나에게 물어봐! 왜 안 물어봐?”"
  },
  Event_22177_Name = {Text = "통령판"},
  Event_22178_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22178_Desc = {
    Text = "그것은 지금 이 순간만큼 뛰고 있지만, 반대로 마음의 구멍이 찢어지고 있다……"
  },
  Event_22178_Name = {
    Text = "저주 갈망"
  },
  Event_22179_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22179_Desc = {
    Text = "영혼과 정신이 당신의 폐를 채우며, 고요함 속에서 당신은 계속해서 상승합니다. \n세계의 소리들이 하나씩 울려 퍼지며, 생명의 교향곡을 연주합니다."
  },
  Event_22179_Name = {
    Text = "과거의 물"
  },
  Event_22180_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22180_Desc = {
    Text = "일상은 그대로 진행되고, 파괴는 예정대로 찾아왔으며, 타지 않은 잔해 속에는 소중한 물건이 묻혀 있으며, 그림자 속에서 빛난다."
  },
  Event_22180_Name = {
    Text = "바늘 끝 외에"
  },
  Event_22181_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22181_Desc = {
    Text = "만남, 이별, 스쳐 지나가다."
  },
  Event_22181_Name = {
    Text = "별빛 소리"
  },
  Event_22182_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22182_Desc = {
    Text = "심장의 고동이 느려지지만, 아마도 “양심”은 조금이나마 위로를 받았을 것이다…"
  },
  Event_22182_Name = {
    Text = "저주 갈망"
  },
  Event_22183_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22183_Desc = {
    Text = "당신은 눈을 감고 이 드문 공허와 자유의 순간을 즐깁니다. 서서히, 당신은 세계가 침묵 속에서 부화되는 것을 느끼며, 생명이 침묵 속에서 소리 없이 피어오르는 것을 느낍니다."
  },
  Event_22183_Name = {
    Text = "과거의 물"
  },
  Event_22184_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22184_Desc = {
    Text = "네가 바늘을 막아서, 은색 조각이 부드러운 손바닥을 베어내고, 파괴는 아직 강림하지 않았지만, 네 발아래의 그림자는 잉크처럼 진한 밤의 어둠에 삼켜졌다."
  },
  Event_22184_Name = {
    Text = "바늘 끝 외에"
  },
  Event_22185_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22185_Desc = {
    Text = "“당신은 도망칠 수 없습니다. 누구도 내면의 악에 저항할 수 없습니다.”\n악의가 신경을 찢어내며 당신을 심연으로 끌어내리려 합니다. 그러나 고통은 오히려 당신의 정신을 전례 없는 맑음으로 만듭니다.\n악의는 당신을 소유할 수 없으며, 당신은 오직 당신 자신일 뿐입니다."
  },
  Event_22185_Name = {
    Text = "무망지념"
  },
  Event_22186_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22186_Desc = {
    Text = "“왜 안 하겠나?” \n그 무서운 생각들을 받아들일 때, 모든 문제가 해결될 것이고, 세상에는 ‘윤리’라는 모순이 더 이상 존재하지 않을 것이다."
  },
  Event_22186_Name = {
    Text = "무망지념"
  },
  Event_22187_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22187_Desc = {
    Text = "은색 광막이 눈앞을 스치고, 무거운 바람이 모든 소리를 가져갔다."
  },
  Event_22187_Name = {
    Text = "무망지념"
  },
  Event_22188_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22188_Desc = {
    Text = "변덕스럽고, 차갑고, 가까우면서도 멀리 있는 듯함."
  },
  Event_22188_Name = {
    Text = "별빛 소리"
  },
  Event_22189_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22189_Desc = {
    Text = "팽창, 수축, 바로 터질 듯."
  },
  Event_22189_Name = {
    Text = "별빛 소리"
  },
  Event_22190_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22190_Desc = {
    Text = "비록 다소 무모하더라도, 왜 안 하겠나? \n모든 장벽을 깨고 결승점으로 향하자. \n마음의 호수를 뒤흔들어 거대한 파도를 일으키더라도, 태양을 향해 날아오르는 이카로스가 되더라도, 적어도 당신은 목표를 달성했어, 아니요?"
  },
  Event_22190_Name = {
    Text = "사고 미로"
  },
  Event_22191_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22191_Desc = {
    Text = "너의 뇌는 미로와 같고, 너는 그 미로의 아리아드네다. \n이 우주에서 너만큼 미로를 탈출하는 방법을 잘 아는 사람은 없다. \n아무도."
  },
  Event_22191_Name = {
    Text = "사고 미로"
  },
  Event_22192_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22192_Desc = {
    Text = "정확한 조율 아래에서 부조화음은 약간 부드러워졌습니다. \n하지만, 아직 당신이 할 수 있는 것이 있을지도 모릅니다."
  },
  Event_22192_Name = {Text = "불화음"},
  Event_22193_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22193_Desc = {
    Text = "당신은 음악의 대가이자, 보통의 음악 애호가입니다. \n음표는 당신의 생각에 따라 각각의 역할을 수행하고, 흐르는 생명이 마침내 미경에서 울려 퍼집니다."
  },
  Event_22193_Name = {Text = "불화음"},
  Event_22194_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22194_Desc = {
    Text = "당신의 소리가 고요 속에 묻혔다. 고요의 소리는 점점 더 커지다가 결국 완전히 부서져 잔해만 남겼다."
  },
  Event_22194_Name = {
    Text = "과거의 물"
  },
  Event_22195_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22195_Desc = {
    Text = "당신은 쉽게 속지 않고, 결연하게 몸을 돌려 이곳을 떠났습니다."
  },
  Event_22195_Name = {
    Text = "크롤링 크랙"
  },
  Event_22293_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22293_Desc = {
    Text = "펜을 든 순간, 서신지는 미경에서 타올랐고, 재가 손에 떨어졌다. \n정신을 차렸을 때, 무언가가 서신지와 함께 사라져버렸다."
  },
  Event_22293_Name = {
    Text = "단방향 고백"
  },
  Event_22294_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22294_Desc = {
    Text = "서신지가 미경에서 사라지는 순간, 당신은 부드럽고 허약한 걱정을 들었습니다.\n“이런 상황에서 나를 기억해 주다니, 나는 선생님으로서 영광입니다.\n하지만 내가 마지막으로 미경을 걸었던 것은 너무 오래 전의 일입니다. 지금의 나는 당신에게 이러한 것들만 도와줄 수 있습니다……”"
  },
  Event_22294_Name = {
    Text = "단방향 고백"
  },
  Event_22295_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22295_Desc = {
    Text = "서신지가 미경에서 사라지는 순간, 당신은 급한 비명을 들었다. \n“수호자, 만약 불편한 곳이 있다면 꼭 알려주세요. \n동료로서, 나는 당신을 돕기 위해 모든 노력을 아끼지 않을 것입니다.”"
  },
  Event_22295_Name = {
    Text = "단방향 고백"
  },
  Event_22296_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22296_Desc = {
    Text = "서신지가 미경에서 사라지는 순간, 당신은 차가운 한숨이 들었습니다. \n“시험에 불합격했을 때에도 이렇게 적극적으로 도움을 요청하면 좋겠어.”"
  },
  Event_22296_Name = {
    Text = "단방향 고백"
  },
  Event_22397_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22397_Desc = {
    Text = "당신의 등장으로 그림자들이 서로를 쳐다보았고, 신발 끝에서 별빛이 스치자 인파가 갑자기 사라졌으며, 당신의 손에는 가장 진한 그림자가 남았습니다."
  },
  Event_22397_Name = {
    Text = "별과 달의 약속"
  },
  Event_22398_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_22398_Desc = {
    Text = "시끄러운 속삭임이 갑자기 멈추고, 먹처럼 검은 그림자가 연달아 너를 향해 돌아서 너를 응시한다. 그 얼굴에 아무런 표정도 없음에도 불구하고, 너는 그 안에서 조롱하는 듯한 기색을 느꼈다……"
  },
  Event_22398_Name = {
    Text = "별과 달의 약속"
  },
  Event_22399_ChoiceDesc1 = {
    Text = "[냉정한 관찰]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_22399_ChoiceDesc2 = {
    Text = "[출성 문의]25개의 검은 인장 획득"
  },
  Event_22399_Desc = {
    Text = "별과 달의 엮임 속에서, 속삭임이 끊이지 않습니다.\n“바로 이 사람인가? @4의 존재……”\n“인간의 몸, 결국에는 @3…”"
  },
  Event_22399_Name = {
    Text = "별과 달의 약속"
  },
  Event_22411_ChoiceDesc1 = {
    Text = "【대성공】"
  },
  Event_22411_Desc = {
    Text = "저렴하지만 효과적인 덫!"
  },
  Event_22411_Name = {Text = "덫 제작"},
  Event_24254_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_24254_Desc = {
    Text = "영지의 폭풍이 툴루 주변을 둘러싸고, 당신은 그와 눈을 마주치며 서로 깊은 어둠으로 들어갑니다."
  },
  Event_24254_Name = {
    Text = "바다에서 왔다"
  },
  Event_24255_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_24255_Desc = {
    Text = "영지의 폭풍이 툴루 주변을 감싸고, 그 오래도록 사라지지 않는 슬픔과 죄책감은 공간 속에서 퍼져나갔다."
  },
  Event_24255_Name = {
    Text = "깊은 심연에 대면하다"
  },
  Event_24256_ChoiceDesc1 = {
    Text = "【촉수 잡기】툴루의 도움을 수락"
  },
  Event_24256_Desc = {
    Text = "그의 위엄은 거대한 물체가 바다에 떨어지는 것처럼, 눈앞의 미경을 흔들었다. \n그 힘은 고대하고 오래되었으며, 만고를 넘어서기에 충분하다. \n다행히도, 당신은 그와 적이 되지 않으며, 적어도 현재는 그렇지 않다."
  },
  Event_24256_Name = {
    Text = "바다에서 왔다"
  },
  Event_24257_ChoiceDesc1 = {
    Text = "【촉수를 잡아라】툴루와 함께"
  },
  Event_24257_Desc = {
    Text = "툴루는 깊게 숨을 쉬고 멀리서 미리암을 바라보았다.\n역사, 구인, 자신의 생명을 그리워하는 듯했다…\n그의 얼굴에 복잡한 표정이 잠깐 머물렀고, 그는 미리암의 얼굴에서 시선을 떼었다.\n“가자, 그녀를 떠나자.”"
  },
  Event_24257_Name = {
    Text = "깊은 심연에 대면하다"
  },
  Event_24277_ChoiceDesc1 = {
    Text = "【캐빈 문을 닫아주세요】"
  },
  Event_24277_Desc = {
    Text = "라모나가 문 밖에서 들어온 학생을 붙잡았습니다.\n그 무모하고 강한 수호자는 온몸이 엉망일 뿐 특별한 점은 없었지만, 그녀의 안경 너머 푸른 눈에서는 희미하게 보였습니다.\n손을 잡는 순간, 라모나는 당신들이 재회를 얻었다는 것을 확인할 수 있었습니다."
  },
  Event_24277_Name = {
    Text = "기쁜 재회"
  },
  Event_24278_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_24278_Desc = {
    Text = "라모나는 당신에게 설명할 기회를 주지 않았고, 그녀는 당신을 어두운 캐빈으로 끌고 들어가 조심스럽게 문을 닫았습니다…"
  },
  Event_24278_Name = {
    Text = "기쁜 재회"
  },
  Event_24540_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_24540_Desc = {
    Text = "“그녀는 당신의 견고한 방어막이며, 당신의 손에 든 날카로운 검입니다. \n그녀는 당신의 동료, 파트너, 당신이 신뢰하는 친구입니다—— 그녀가 어떻게 변하든 간에.”"
  },
  Event_24540_Name = {
    Text = "생소하면서도 익숙한 존재"
  },
  Event_24541_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_24541_Desc = {
    Text = "「너… 아니, 이럴 수 없어, 이 순환의 너는 이미… 나도 이미…」\n소리가 그림자와 함께 사라졌지만, 슬픔만은 안개 속에서 맴돌았다."
  },
  Event_24541_Name = {
    Text = "익숙하면서도 낯선 모습"
  },
  Event_24542_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_24542_Desc = {
    Text = "“세상을 위해, 인간을 위해, 우리가 소중히 여기는 모든 것을 위해. \n물론, 가장 중요한 것은——그녀는 당신을 위해.”"
  },
  Event_24542_Name = {
    Text = "생소하면서도 익숙한 존재"
  },
  Event_24543_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_24543_Desc = {
    Text = "당신이 그림자에 가까워지기도 전에 당신을 알아차렸다. 그분의 몸이 잠시 멈추었고, 충격과 동시에 큰 슬픔에 빠진 것 같았다. \n당신이 무언가를 말하기도 전에, 그분은 안개와 함께 사라졌다."
  },
  Event_24543_Name = {
    Text = "익숙하면서도 낯선 모습"
  },
  Event_24544_ChoiceDesc1 = {
    Text = "【그녀는 누구?】덱에서 무작위로 3장의 명령 카드를 가져와 1장을 선택하여 복제합니다"
  },
  Event_24544_ChoiceDesc2 = {
    Text = "[그녀는 왜 이렇게 됐을까?]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_24544_ChoiceDesc3 = {
    Text = "[떠나다]25 검은 인장 획득"
  },
  Event_24544_Desc = {
    Text = "또 다른 안개, 또 다른 그림자. 이전과는 다르게, 이번에는 상대방을 뚜렷하게 볼 수 있었습니다. \n 당신과 똑같은 몸매, 당신과 똑같은 제복, 당신과 똑같은 얼굴. \n “너는 왜 여기 있는지 알고 있지,” 그 사람이 말했습니다, “마치 네가 그녀가 왜 그런 모습이 되었는지를 아는 것처럼.”"
  },
  Event_24544_Name = {
    Text = "생소하면서도 익숙한 존재"
  },
  Event_24545_ChoiceDesc1 = {
    Text = "[출성 위로]백은 유물 “(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_24545_ChoiceDesc2 = {
    Text = "[시도 접근]백은 유물 “(RelicConfig.Arg1)”을(를) 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_24545_ChoiceDesc3 = {
    Text = "[돌아서 떠나다]획득 25 검은 인장"
  },
  Event_24545_Desc = {
    Text = "안개가 당신의 앞길을 가리고 있습니다. \n 흐릿한 빛과 그림자 속에서 한 형체가 나타나고, 당신은 눈을 가늘게 뜨지만 그 얼굴을 도무지 알 수 없으며, 간헐적인 저어 소리만 들을 수 있습니다. \n “왜… 왜 구할 수 없는 거지… 운명, 정말로 바꿀 수 없는 건가…”"
  },
  Event_24545_Name = {
    Text = "익숙하면서도 낯선 모습"
  },
  Event_35039_ChoiceDesc1 = {
    Text = "[파트너에게 도움 요청]3선1 고급 각인 획득"
  },
  Event_35039_ChoiceDesc2 = {
    Text = "【현장 조정자】“(RelicConfig.Arg1)” 황금 유물 획득"
  },
  Event_35039_ChoiceDesc3 = {
    Text = "[유도 현상급 열풍]유물 획득 “(RelicConfig.Arg1)”"
  },
  Event_35039_Desc = {
    Text = "\"《후디니 마스터의 촬영 가이드》에서 명확히 밝혔듯이, 카시아, 즉 본인으로서, 프로듀서이자 감독으로서 전체 영화에 대한 의무와 권한이 있습니다. 그러므로 카시아의 용감한 직원이여, 당신의 다음 행동 일정을 선택하세요!\"\n\"일정, 일정? 잠깐만, 내가 언제 당신의 직원이 되었죠?!\"\n\"기회를 놓치면 다시 오지 않으니, 더 이상 망설이지 마세요!\""
  },
  Event_35039_Name = {
    Text = "프로듀서의 딜레마"
  },
  Event_35103_ChoiceDesc1 = {
    Text = "[연결] HP를 Arg2 회복 [ExDesc1][ExDesc2]."
  },
  Event_35103_ChoiceDesc2 = {
    Text = "【명상】깨어남체 1명을 깨어남시킵니다."
  },
  Event_35103_ChoiceDesc3 = {
    Text = "【추방】최대 3장의 증상 카드를 제거하고, 검은 인장 Arg2개를 획득합니다."
  },
  Event_35103_Desc = {
    Text = "안개 속을 탐색하던 중, 갑자기 가슴에 단 배지가 희미한 은빛을 발했다. 통신기 너머에서 누군가 당신을 부르고 있는 걸까?"
  },
  Event_35103_Name = {
    Text = "연락 지점"
  },
  Event_35103_Tips3 = {
    Text = "현재 증상 카드를 소유하고 있지 않습니다."
  },
  Event_35165_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35165_Desc = {
    Text = "망설임 속에서, 당신은 신비한 후원자에게 통신 요청을 먼저 보냈습니다.\n\"이쯤 오니 이제는 물러날 수 없네요. 후원자님께서 관대히 도움을 주시기를 바라며...\"\n실타래버 코어 통신기 너머에서 매우 쾌활한 웃음소리가 들렸고, 상대방은 결국 웃으며 당신의 요청에 응했습니다.\n\"참, 그리고... 이 일은 반드시 라모나에게 비밀로 해주세요.\""
  },
  Event_35165_Name = {
    Text = "프로듀서의 딜레마"
  },
  Event_35236_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35236_Desc = {
    Text = "현장 조정자는 무엇을 하는 건가요? 당신은 카시아가 언제 넣었는지 모르게 영지 전사기 안에 넣어둔 서류 뭉치를 꺼내어 자세히 살펴보았습니다. \n 그러고 나서, 당신은 머리가 아파오기 시작했습니다. \n 촬영 현장 배치 과정에서 로탄이 초래한 손실타래, 오레타와 브라운이 먹어 치운 간식, 카시아가 구매한 마법 구슬의 경비 청구서…… 하나하나 정산 항목이 당신 앞에 놓여 있었고, 당신은 어쩔 수 없이 고통스럽게 땅에 쪼그려 앉아 계산을 해야 했습니다. \n 그런데, 카시아의 마법 구슬은 무엇인가요?"
  },
  Event_35236_Name = {
    Text = "프로듀서의 딜레마"
  },
  Event_35259_ChoiceDesc1 = {
    Text = "【환상 해제】감염 증상[ExDesc1][ExDesc2]."
  },
  Event_35259_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_35259_Desc = {
    Text = "모호한 얼굴들이 갑자기 나타나 당신 주변을 둘러싸고, 실타래체 없는 성대를 통해 절망적으로 신음합니다."
  },
  Event_35259_Name = {Text = "환각"},
  Event_35497_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35497_Desc = {
    Text = "현상급 열풍의 뒤에는 추진력이 필요하고, '추진력'에 대해 이야기할 때, 초록색 단발머리 소녀의 모습이 떠오릅니다. \n \"미사그 대학의 1호 중개인, 한나 피즐리가 진심으로 당신을 위해 서비스합니다!\" \n \"수호자의 첫 서비스 요청이라면, 식당 카레 세트 3끼의 보상만 있으면 됩니다!\""
  },
  Event_35497_Name = {
    Text = "프로듀서의 딜레마"
  },
  Event_35887_ChoiceDesc1 = {
    Text = "【전진】"
  },
  Event_35887_Desc = {
    Text = "당신은 배의 돛을 들어올렸지만, 그 아래에는 아무것도 없었다. 정신을 차렸을 때, 그 배의 돛도 이미 사라졌다.\n순백의 돛과 소녀의 희미한 얼굴이 하나의 메시지가 되어, 앞길이 어떻든 당신은 혼자가 아니라는 것을 상기시켜준다."
  },
  Event_35887_Name = {
    Text = "순백의 돛"
  },
  Event_35888_ChoiceDesc1 = {
    Text = "【배의 돛을 펼치다】"
  },
  Event_35888_Desc = {
    Text = "여기에는 바람이 없지만, 흠잡을 데 없는 하얀 돛배가 하나 있다. 그 돛은 힘차게 솟아올라 조용한 푸른 바다 위에 우뚝 서 있다. \n 당신은 희미하게 소녀의 얼굴을 보았다. 그녀의 이목구비는 흐릿하여 마치 얇은 안개나 흐르는 물결을 통해 보는 듯하다. 그녀의 존재는 주변의 모든 것과 격리된 듯하지만, 이 장면의 핵심이다. \n 그녀의 형상은 계속해서 파동 속에서 선명해지거나 흐릿해지지만, 의심할 여지 없이 당신은 그녀가 누구인지 안다."
  },
  Event_35888_Name = {
    Text = "순백의 돛"
  },
  Event_35894_ChoiceDesc1 = {
    Text = "[아래로 떨어짐]35개의 검은 인장을 획득, “(Skill.Arg2)” 감염, 계속 선택"
  },
  Event_35894_ChoiceDesc2 = {
    Text = "【멀리 떨어지다】"
  },
  Event_35894_Desc = {
    Text = "소녀의 목소리가 공기 중에 분산되며, 포영처럼 흐릿하고 아득하게 퍼져나갔다."
  },
  Event_35894_Name = {
    Text = "생사의 경계"
  },
  Event_35895_ChoiceDesc1 = {
    Text = "[주복시]30개의 검은 인장을 획득하고, “(Skill.Arg2)”에 감염되었습니다. 계속 선택해"
  },
  Event_35895_ChoiceDesc2 = {
    Text = "【멀리 떨어지다】"
  },
  Event_35895_Desc = {
    Text = "사지가 매우 무거우며, 안개가 약한 신체를 단단히 옥죄고 있다."
  },
  Event_35895_Name = {
    Text = "생사의 경계"
  },
  Event_35896_ChoiceDesc1 = {
    Text = "[선인의 길 읽기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_35896_ChoiceDesc2 = {
    Text = "[자신만의 길을 쓰다]백은 유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_35896_ChoiceDesc3 = {
    Text = "[다크 시야]25개의 검은 인장 획득"
  },
  Event_35896_Desc = {
    Text = "만약 당신이 혼자서 미경을 더듬어 더 전진한다면, 지금처럼 자신의 앞길에 대해 확신을 가질 수는 없을 것입니다. \n미경의 발자국은 세 갈래로 나뉘었으며, 남겨진 각 발자국은 보이지 않는 미래를 쓰고 있습니다."
  },
  Event_35896_Name = {Text = "출구"},
  Event_35897_ChoiceDesc1 = {
    Text = "【그녀를 부축해 주세요】"
  },
  Event_35897_ChoiceDesc2 = {
    Text = "【그녀를 보며】"
  },
  Event_35897_Desc = {
    Text = "그녀는 나지막이 말하며, 당신 앞에 쓰러져 멈추었습니다. \n누군가 그녀의 안식을 방해했고, 그녀의 의식은 현실타래에 속박되었지만, 영혼은 잃어버린 나라에 머물렀습니다."
  },
  Event_35897_Name = {
    Text = "실타래종된 환영"
  },
  Event_35898_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35898_Desc = {
    Text = "이 카오스의 어둠 속에서, 흐릿한 발자국들이 길게 이어져 있으며 마치 보이지 않는 사막을 걸어가는 밤의 여행자가 남긴 깊은 흔적처럼 보인다."
  },
  Event_35898_Name = {Text = "출구"},
  Event_35899_ChoiceDesc1 = {
    Text = "[떠나다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_35899_Desc = {
    Text = "눈에 멀리 있는 등대가 비춰집니다. 그녀는 다크의 가장자리에 외롭게 서 있으며, 미약하지만 견고한 빛을 발산하고 있습니다. 마치 밤바다의 안내자처럼, 방황하는 영혼들을 불러 안식의 저편으로 이끌고 있습니다. \n 당신은 참지 못하고 쫓아갔지만, 발 아래는 갑자기 더 이상 단단하지 않았습니다. \n 당신은 어둠 속에 숨겨진 수역에 발을 디딘 것입니다. 물결은 부드럽고 조용하게 당신의 발걸음을 포식하고 있습니다."
  },
  Event_35899_Name = {Text = "반짝임"},
  Event_35900_ChoiceDesc1 = {
    Text = "【그녀의 말을 들어줘】"
  },
  Event_35900_ChoiceDesc2 = {
    Text = "【무시해】"
  },
  Event_35900_Desc = {
    Text = "당신은 불빛의 원점을 분명히 볼 수 있었는데, 그곳에는 여성의 모습을 한 캐릭터가 있었습니다. \n이상한 형태의 머리에서 유려한 빛이 쏟아져 나와 미지의 길을 향해 이어졌습니다. \n「리@2아로 돌아가세요……」"
  },
  Event_35900_Name = {
    Text = "장명등화"
  },
  Event_35901_ChoiceDesc1 = {
    Text = "【등대에 가까워지기】"
  },
  Event_35901_ChoiceDesc2 = {
    Text = "【등대에서 멀리 떨어지세요】"
  },
  Event_35901_Desc = {
    Text = "현실타래과 꿈이 얽힌 모퉁이를 돌자, 그 찰나에 눈앞에 폭풍의 무서운 장면이 펼쳐졌습니다. \n 마치 거대한 보이지 않는 손에 의해 뒤집힌 듯, 광풍이 맹수처럼 포효하며, 먼지와 희망을 휘말아 올렸고, 하늘은 어둡고 극도로 억압적이었습니다. \n 폭풍의 중심에서, 존재해서는 안 될 등대가 우뚝 서 있었고, 마치 환상의 산물 같기도 하고, 고대 전설에 나오는 유적 같기도 했습니다. 그것은 광풍이 휘몰아치는 무대에서 외롭게 그리고 강하게 희미한 빛을 발산하고 있었습니다."
  },
  Event_35901_Name = {
    Text = "폭풍의 중심"
  },
  Event_35902_ChoiceDesc1 = {
    Text = "[떠나다] 50 개 검은 인장 획득"
  },
  Event_35902_Desc = {
    Text = "“미경 중, 등불이 항상 밝고, 몸에 달린 촉수를 가진 환영……”\n툴루는 눈을 감고 생각하다가, 곧 깊은 한숨을 내쉬었다.\n“리모리아의 문지기……나의 서번트 중 하나. 그녀도 결국 집착의 속박에서 벗어나지 못했다.”"
  },
  Event_35902_Name = {
    Text = "소나니르 호의 침몰"
  },
  Event_35903_ChoiceDesc1 = {
    Text = "【은빛을 만진다】검은 인장 25개 획득"
  },
  Event_35903_ChoiceDesc2 = {
    Text = "[은빛과 대화]백은 유물“(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_35903_Desc = {
    Text = "밀착된 통신기가 살짝 벌어져 틈이 생겼고, 어두운 빛이 그 사이로 흘러나왔다—이는 은심이 통신기 중앙에 봉인된 이후로 외부 세계와 처음으로 대화를 한 것이리라."
  },
  Event_35903_Name = {
    Text = "미스릴 비석"
  },
  Event_35904_ChoiceDesc1 = {
    Text = "[떠나기] 유물 획득「(RelicConfig.Arg1)」"
  },
  Event_35904_Desc = {
    Text = "“머리가 빛나는 여자?” 엘튼은 놀라움을 감추지 못했으며, 분명히 그는 화물선 미경에서 가끔 나타나는 그림자에 대해 들어본 적이 있었다. 다만——\n“소나니르 호가 침몰한 그 밤…… 바로 내가 셀레스트를 깨어남시킨 그 밤, 나는 폭풍 속에서 그런 그림자를 본 적이 있다.”\n“나는 절대 잘못 보지 않았다.”"
  },
  Event_35904_Name = {
    Text = "소나니르 호의 침몰"
  },
  Event_35905_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35905_Desc = {
    Text = "미경 앞길은 위험으로 가득 차 있으며, 깊이를 알 수 없다. \n당신의 눈은 보이지 않는 카오스를 굳게 응시하고 있지만, 카오스에 흡수되기 전 추격자 라모나가 당신을 잡아 다른 방향으로 데려갔다."
  },
  Event_35905_Name = {Text = "출구"},
  Event_35906_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35906_Desc = {
    Text = "그것은 당신의 신비로운 영혼이 잉태한 열매인가요? 지금 겪고 있는 모든 것은 자아와 초자아의 충돌인가요? \n생각할수록, 머릿속의 잡음은 점점 더 선명해집니다. 시선이 안개 속으로 들어가고, 당신이 안개 속의 사람을 바로 볼 수 있을 것 같은 순간, 영혼이 당신을 거부했습니다."
  },
  Event_35906_Name = {
    Text = "역전의 운명"
  },
  Event_35907_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35907_Desc = {
    Text = "그것은 체내에서 솟아나와 무서움 없는 힘으로 변해, 당신이 안개를 뚫고 두려움을 찢을 수 있도록 지탱합니다."
  },
  Event_35907_Name = {
    Text = "빛을 쫓아"
  },
  Event_35908_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35908_Desc = {
    Text = "의식이 집중되고 마음의 평온이 찾아오면서 혼란스러운 환상이 천천히 용해되기 시작하고, 결국 물결처럼 사라집니다.\n 결국, 뇌 속의 잡음도 흔적 없이 사라졌습니다—— 하지만, 당신은 얼마나 그리울까요? 알 수 없습니다."
  },
  Event_35908_Name = {
    Text = "미래 경고"
  },
  Event_35909_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35909_Desc = {
    Text = "영혼이 귀울림 속에서 헤매고, 당신은 이를 벗어나려 애쓰며 고통을 해석하려 하지만, 무론 어떻게 해도 의식의 가장자리를 벗어나지 못합니다…"
  },
  Event_35909_Name = {
    Text = "생사의 경계"
  },
  Event_35910_ChoiceDesc1 = {
    Text = "【떠나다】3개 중 1개 선택 황금 유물 획득, “(Skill.Arg1)” 감염"
  },
  Event_35910_Desc = {
    Text = "당신은 그 등대에서 발산되는 모든 빛점을 느낄 수 있습니다. 그것들은 폭풍 속에서 타오르고 뛰어오르며, 마치 영혼 깊은 곳의 호출처럼, 가장 격렬한 공포 속에서도 귀향의 사명을 포기하지 않았습니다."
  },
  Event_35910_Name = {
    Text = "폭풍의 중심"
  },
  Event_35911_ChoiceDesc1 = {
    Text = "【떠나다】3개 중에서 1개 고급 각인 획득"
  },
  Event_35911_Desc = {
    Text = "희망의 상징일까, 아니면 파멸의 전조일까?\n당신은 더 이상 그것을 바라보지 않으며, 마치 그것의 존재가 정교하게 꾸며진 환상일 뿐인 것처럼 느낍니다."
  },
  Event_35911_Name = {
    Text = "폭풍의 중심"
  },
  Event_35912_ChoiceDesc1 = {
    Text = "[침륜미리]20개의 검은 인장 획득, 감염 “(Skill.Arg2)”"
  },
  Event_35912_ChoiceDesc2 = {
    Text = "【멀리 떨어지다】"
  },
  Event_35912_Desc = {
    Text = "그런 다음, 당신의 눈앞에 이상한 회색 안개가 드리워졌습니다. 잠시 후, 그것이 반투명한 상안검임을 깨달았습니다."
  },
  Event_35912_Name = {
    Text = "생사의 경계"
  },
  Event_35913_ChoiceDesc1 = {
    Text = "【떠나다】무작위로 1명의 깨어남체를 깨어남시키고, “(Skill.Arg1)”에 감염되게 합니다"
  },
  Event_35913_Desc = {
    Text = "당신의 마음에 설명할 수 없는 공명이 일어났습니다. \n하지만 이성은 당신에게 말했습니다: 그녀를 무시해."
  },
  Event_35913_Name = {
    Text = "장명등화"
  },
  Event_35914_ChoiceDesc1 = {
    Text = "[떠나다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_35914_Desc = {
    Text = "그녀의 언어는 어떤 알려진 비문에도 새겨지지 않았지만, 공기 중에 가장 깊은 후회의 부름으로 응결되었습니다. 마치 시간의 다른 끝에서 날아와, 세월의 침전을 통과하여, 먼 고향에 대한 깊은 애정을 담고 있습니다."
  },
  Event_35914_Name = {
    Text = "장명등화"
  },
  Event_35915_ChoiceDesc1 = {
    Text = "[그녀의 손을 잡아]랜덤 1개의 백은 유물이 황금 유물 “(RelicConfig.Arg1)”로 업그레이드"
  },
  Event_35915_ChoiceDesc2 = {
    Text = "[출성관심]백은 유물 “(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_35915_ChoiceDesc3 = {
    Text = "[그녀를 주시해]획득 25 검은 인장"
  },
  Event_35915_Desc = {
    Text = "머피는 팀의 맨 뒤에 있었고, 그녀는 힐레스트와 나란히 걸었다.\n당신은 자꾸 그녀를 돌아보게 되었지만, 머피는 항상 자신의 신발 끝을 내려다보며 표정을 미지 속에 숨기고 있었다."
  },
  Event_35915_Name = {
    Text = "통증 관리"
  },
  Event_35915_Tips1 = {
    Text = "아직 백은 유물이 없습니다"
  },
  Event_35916_ChoiceDesc1 = {
    Text = "[탈출 불가]40개의 검은 인장을 획득하고, “(Skill.Arg2)”에 감염되었습니다. 계속 선택"
  },
  Event_35916_ChoiceDesc2 = {
    Text = "[현실타래을 포옹하다]25개의 검은 인장 획득"
  },
  Event_35916_Desc = {
    Text = "@1@1새로운 삶을 되찾고, 영혼이 @2의 경계를 넘어섰지만, 아직 육체를 완전히 포용하지 못했습니다.\n머피의 걱정 어린 말이 당신의 의식과 점점 멀어져 가고, 마치 까마귀의 애가처럼 귀에 맴돌지만, 마음의 장벽에 의해 창밖으로 차단되고 있습니다."
  },
  Event_35916_Name = {
    Text = "생사의 경계"
  },
  Event_35917_ChoiceDesc1 = {
    Text = "【떠나다】1장의 명령 카드를 선택하고 복제합니다, “(Skill.Arg1)”에 감염됩니다"
  },
  Event_35917_Desc = {
    Text = "그녀는 현실타래에 남겨진 유령일 뿐, 닿을 수 없으면서도 쉽게 사라지지 않는 고대의 잔존물이다."
  },
  Event_35917_Name = {
    Text = "실타래종된 환영"
  },
  Event_35918_ChoiceDesc1 = {
    Text = "【떠나다】3장의 명령 카드 중 1장을 선택하여 각인 획득:“(EnchantConfig.Arg1)”"
  },
  Event_35918_Desc = {
    Text = "그 순간, 당신은 영혼 깊숙한 곳에서 미세한 깨지는 소리를 들었습니다. 서서히 사라지는 연기처럼, 그녀의 모습은 번져가며 점점 더 비현실타래적으로 변해갔습니다. \n 그녀는 여기 존재하지 않으며, 이것은 엘튼 선장의 기억의 투사일 뿐입니다. \n 그러나 마음에 남아 있는 그녀의 상실타래과 혼란은 거짓이 아닙니다."
  },
  Event_35918_Name = {
    Text = "실타래종된 환영"
  },
  Event_35919_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35919_Desc = {
    Text = "손끝이 닿는 순간, 복잡한 감정이 갑자기 마음에 밀려왔다—그것은 뜨겁고 차가웠다. \n세계에 잊힌 영혼이 영원을 찾아 울부짖으며 울부짖고 있다."
  },
  Event_35919_Name = {
    Text = "미스릴 비석"
  },
  Event_35920_ChoiceDesc1 = {
    Text = "【불씨를 쥐다】최대 생명을 Arg1 높임"
  },
  Event_35920_ChoiceDesc2 = {
    Text = "[내면과 직면]무작위 2장의 커맨드 카드가 각인 획득: \"(EnchantConfig.Arg1)\", 2장 \"(Skill.Arg2)\" 감염"
  },
  Event_35920_Desc = {
    Text = "이 거대한 사냥에서, 고리아의 추격은 어두운 밤의 맹수처럼 모든 희망의 빛을 포식하려 했다. 그러나 이 무정한 추격은 당신을 빙결시키지 않았고, 오히려 마음 깊은 곳의 화종을 점화시켰다. 그것은 가슴 속에서 확산되고, 번영하며 점점 더 뜨거워졌다."
  },
  Event_35920_Name = {
    Text = "빛을 쫓아"
  },
  Event_35921_ChoiceDesc1 = {
    Text = "【해석하기】덱에서 무작위로 3장의 명령 카드를 획득하여 1장을 선택하여 복제"
  },
  Event_35921_ChoiceDesc2 = {
    Text = "[그것이 되기]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_35921_ChoiceDesc3 = {
    Text = "[무시해]획득 25 검은 인장"
  },
  Event_35921_Desc = {
    Text = "걸음을 내딛는 순간, 무형의 진동이 당신의 의식을 확실타래하게 끌어당겨, 당신의 두 눈을 미경 카오스 공허의 경계로 향하게 만듭니다."
  },
  Event_35921_Name = {
    Text = "미래 경고"
  },
  Event_35922_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35922_Desc = {
    Text = "눈앞에서 기괴한 색채가 춤추고, 귀 옆에서 소리가 저어하며, 스쳐 지나가는 장면과 흐릿한 얼굴들이 얽혀져 마치 하나의 또 다른 미지의 이야기를 들려주는 것 같습니다. 이러한 환상들은 당신이 점차 현실타래에서 분리되어, 익숙하면서도 낯선 꿈속에 빠져드는 듯한 느낌을 줍니다."
  },
  Event_35922_Name = {
    Text = "미래 경고"
  },
  Event_35923_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35923_Desc = {
    Text = "진전은 외부의 소음이나 촉각적인 진동이 아니라, 설명할 수 없는 내면 깊은 곳의 예감이다. 마치 미래의 목소리가 당신의 감각을 자극하는 듯하다."
  },
  Event_35923_Name = {
    Text = "미래 경고"
  },
  Event_35924_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35924_Desc = {
    Text = "그녀의 손이 저절로 가슴을 만지며, 질식할 듯한 감정을 통제하려고 애썼다.\n이런 공포는 그녀를 이를 악물게 하여, 가슴 속에서 휘몰아치는 통증을 무시하도록 강요했다. 머피의 얼굴에서 일어나는 작은 왜곡은 그녀가 재빨리 가려버렸고, 고통을 숨기기 위해 서투른 위장으로 덮었다.\n—— 당신이 그녀의 손을 잡을 때, 놀람은 그녀의 얼굴 색이 되었다."
  },
  Event_35924_Name = {
    Text = "통증 관리"
  },
  Event_35925_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35925_Desc = {
    Text = "“머피? 괜찮아?” \n — 그녀는 당신의 말에 대답하지 않았다. \n유형의 기괴함이 그녀의 마음을 부식하여 숨 쉬기조차 힘들게 만들었다."
  },
  Event_35925_Name = {
    Text = "통증 관리"
  },
  Event_35926_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35926_Desc = {
    Text = "당신은 더 이상 유예하지 않고, 한 발을 검은 미지로 내디뎠습니다. 걸어간 곳마다, 아닌 빛으로 향하는 경로가 그려졌습니다."
  },
  Event_35926_Name = {Text = "출구"},
  Event_35927_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35927_Desc = {
    Text = "당신의 눈앞에는 뛰는 불꽃이 있습니다. \n 그것은 열렬하고 생기 넘치며, 흔들리는 차가운 불꽃을 감싸고 있어, 그 불빛이 불협화음을 환하게 쫓아냅니다. \n 당신은 정신을 차리고, 눈앞에서 의아하게 당신을 바라보는 머피만을 발견했습니다—— \n “정말 괜찮아?”"
  },
  Event_35927_Name = {
    Text = "생사의 경계"
  },
  Event_35928_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35928_Desc = {
    Text = "의식이 분리되기 시작하고 천천히 몸에서 끌려나갑니다. \n마치 자신의 영혼이 이 은심 잔존 의식과 함께 춤을 추는 것 같고, 그 후에는 보이지 않는 깊은 심연으로 무겁게 떨어져 들어갑니다…… \n그곳은 순수한 공허입니다."
  },
  Event_35928_Name = {
    Text = "미스릴 비석"
  },
  Event_35929_ChoiceDesc1 = {
    Text = "[떠나다]25 검은 인장을 획득"
  },
  Event_35929_Desc = {
    Text = "당신이 조명의 원천을 계속 추적하기도 전에, 그것이 갑자기 떨리며 공기 중에서 흩어졌다. \n조명이 미경에서 층층이 물결치며 사방으로 퍼져나갔다. \n그리고 아무것도 남지 않았다."
  },
  Event_35929_Name = {Text = "반짝임"},
  Event_35930_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35930_Desc = {
    Text = "그것이 어떻게 네가 될 수 있겠니? \n만일 그것이 너라면, 왜 슬픔이 강림할 때 하느님이 너를 구원하지 않았을까? \n만일 그것이 너라면, 왜 고난을 겪을 때 하느님이 너를 도와주지 않았을까? \n그래서, 모두 착각이다."
  },
  Event_35930_Name = {
    Text = "역전의 운명"
  },
  Event_35931_ChoiceDesc1 = {
    Text = "【선장에게 문의하기】"
  },
  Event_35931_ChoiceDesc2 = {
    Text = "【툴루에게 묻다】"
  },
  Event_35931_Desc = {
    Text = "또 한 번, 당신은 그 신비로운 그림자가 선실타래 벽으로 걸어 들어가, 흔적도 없이 사라지는 것을 보았습니다. 형광빛 긴 머리가 어딘가에서 시작되어, 바닥에 떨어진 여러 개의 촉수로 변했습니다. \n 당신은 그녀가 해양도약자의 일원이 아니더라도, 그녀의 신분이 잃어버린 나라와 천 가지의 관계가 있을 것임을 확실타래히 알고 있습니다."
  },
  Event_35931_Name = {
    Text = "소나니르 호의 침몰"
  },
  Event_35932_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35932_Desc = {
    Text = "당신은 두려워하며, 모든 것은 아드레날린 때문입니다. \n당신은 자신의 결정이 어둠을 함께 나누는 영혼들을 상처 입힐까 봐 두려워합니다."
  },
  Event_35932_Name = {
    Text = "빛을 쫓아"
  },
  Event_35933_ChoiceDesc1 = {
    Text = "[무처히도 도망칠 곳이 없다]25개의 검은 인장 획득, 감염 “(Skill.Arg2)”, 계속 선택"
  },
  Event_35933_ChoiceDesc2 = {
    Text = "【멀리 떨어지다】"
  },
  Event_35933_Desc = {
    Text = "각 신경이 @2에 대한 갈망으로 휘파람을 울리고 있다."
  },
  Event_35933_Name = {
    Text = "생사의 경계"
  },
  Event_35934_ChoiceDesc1 = {
    Text = "【추적】"
  },
  Event_35934_ChoiceDesc2 = {
    Text = "【무시해】"
  },
  Event_35934_Desc = {
    Text = "미경의 먼 곳에서 미세하고 매혹적인 빛이 켜졌습니다. \n 그것은 물결 위에 비친 햇빛처럼 반짝이며, 흔들리는 별빛 같기도 하고, 혹은 한 점의 촛불 같기도 합니다… \n 당신이 그 빛에 가까이 가고 싶을 때, 그 빛은 갑자기 사라졌습니다. \n 그것은 당신을 유혹하는 것 같고, 본능적으로 살아가는 나방을 유혹하는 듯합니다."
  },
  Event_35934_Name = {Text = "반짝임"},
  Event_35935_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_35935_Desc = {
    Text = "그걸 걱정해봤자 무슨 소용이겠나? \n너는 공중에 떠 있는 낙엽일 뿐, 운명의 바람이 너를 밀어가게 놔두는 것뿐이다."
  },
  Event_35935_Name = {
    Text = "역전의 운명"
  },
  Event_35936_ChoiceDesc1 = {
    Text = "[자조]백은 유물“(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_35936_ChoiceDesc2 = {
    Text = "【질문을 끝까지 추적】황금 유물“(RelicConfig.Arg1)” 획득, “(Skill.Arg2)”, “(Skill.Arg3)”에 감염"
  },
  Event_35936_ChoiceDesc3 = {
    Text = "[더 이상 생각하지 않음]25 검은 인장 획득"
  },
  Event_35936_Desc = {
    Text = "생명의 바람이 당신의 영혼을 스치며, 현실타래의 소용돌이 속에서 당신을 휘감고 미지로 가득한 안개 속으로 끌어들입니다. \n당신은 머릿속에 울리는 소리에 물을 수밖에 없습니다: “그게 저인가요?”"
  },
  Event_35936_Name = {
    Text = "역전의 운명"
  },
  Event_36146_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36146_Desc = {
    Text = "머피는 마침내 당신의 시선을 알아차렸고, 아마도 그것이 너무 뜨거웠던 것일지도 모릅니다. \n 그녀는 몇 번 깊게 숨을 쉬며 코에서 가볍게 “흥” 소리를 냈습니다. 결국 그녀는 셀레스트를 끌고 당신 뒤에 꼭 붙어 따라왔습니다."
  },
  Event_36146_Name = {
    Text = "통증 관리"
  },
  Event_36722_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36722_Desc = {
    Text = "손끝이 닿는 순간, 복잡한 감정이 갑자기 마음에 밀려왔다—그것은 뜨겁고 차가웠다. \n세계에 잊힌 영혼이 영원을 찾아 울부짖으며 울부짖고 있다."
  },
  Event_36722_Name = {
    Text = "영지의 비석"
  },
  Event_36723_ChoiceDesc1 = {
    Text = "【만져본다】무작위 깨어남체 1명 깨어남, 「(Skill.Arg1)」 감염"
  },
  Event_36723_ChoiceDesc2 = {
    Text = "【회전 추가】3개 중 1개의 각인 획득"
  },
  Event_36723_Desc = {
    Text = "걸음을 떼는 순간, 정신의 가장 깊은 곳에서 조용히 틈이 벌어졌다. 이해할 수 없는 깊은 기운이 틈을 통해 흘러들어 머릿속을 부채질한다. \n너는 내면에서 은색의 카오스 행성이 조용히 회전하고 성장하고 있다는 것을 느낀다."
  },
  Event_36723_Name = {
    Text = "영지의 비석"
  },
  Event_36724_ChoiceDesc1 = {
    Text = "[그들을 따라가세요]백은 유물 “(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_36724_ChoiceDesc2 = {
    Text = "【그들을 무르기】황금 유물 “(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”와 “(Skill.Arg3)”에 감염됩니다."
  },
  Event_36724_ChoiceDesc3 = {
    Text = "[깨우치지 않고 간직]25개의 검은 인장을 획득하다"
  },
  Event_36724_Desc = {
    Text = "의외의 모퉁이를 돌고 나서, 당신의 시야에 이상한 광경이 나타났습니다.\n몇 마리 고양이의 그림자가 흐릿하게 보이며 차가운 선체 벽을 따라 어른거렸습니다."
  },
  Event_36724_Name = {
    Text = "배고양이"
  },
  Event_36725_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36725_Desc = {
    Text = "“기억”은 대답하지 않았고, 그들은 선체에 붙어 당신을 빤히 쳐다보며 당신이 다음 모퉁이를 지나갈 때까지 쳐다봤습니다."
  },
  Event_36725_Name = {
    Text = "소나니르 호의 주인"
  },
  Event_36726_ChoiceDesc1 = {
    Text = "[우회 경로]1장의 명령 카드 삭제, [Arg1]개의 검은 인장 획득"
  },
  Event_36726_ChoiceDesc2 = {
    Text = "【질문을 묻다 왜 가라앉았는지】명령 카드 1장을 복제하고, “(Skill.Arg1)”에 감염합니다"
  },
  Event_36726_ChoiceDesc3 = {
    Text = "【선원에게 인사하기】3장의 명령 카드 중 1장을 선택하여 각인을 획득:“(EnchantConfig.Arg1)”"
  },
  Event_36726_Desc = {
    Text = "동력실타래로 향하는 길에서 다시금 몇몇 “기억”들을 만났다. \n그들은 유령이 아니요, 엘튼 선장이 사라진 선원들에 대한 애틋함이다."
  },
  Event_36726_Name = {
    Text = "소나니르 호의 주인"
  },
  Event_36727_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36727_Desc = {
    Text = "“기억”이 선체에서 떨어져 나가며, 그는 얼굴을 일그러뜨리고 목에서 비명을 내질렀다. \n——등대. \n——고립된 등대, 그들을 폭풍으로 인도했다."
  },
  Event_36727_Name = {
    Text = "소나니르 호의 주인"
  },
  Event_36728_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36728_Desc = {
    Text = "당신은 따르기로 선택했습니다. 따뜻하고 자유로운 영혼들이 그린 궤적을 따르는 것, 앞이 어둠이 남긴 함정이라도."
  },
  Event_36728_Name = {
    Text = "배고양이"
  },
  Event_36729_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36729_Desc = {
    Text = "고인을 방해하지 마세요、깊은 잠의 기억을 건드리지 마세요."
  },
  Event_36729_Name = {
    Text = "소나니르 호의 주인"
  },
  Event_36730_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36730_Desc = {
    Text = "의식이 분리되기 시작하고 천천히 몸에서 끌려나갑니다. \n자신의 영혼이 행성과 함께 춤을 추는 것 같고, 그 후에 보이지 않는 심연으로 무겁게 떨어지는 것 같습니다… \n그곳은 순수한 공허입니다."
  },
  Event_36730_Name = {
    Text = "영지의 비석"
  },
  Event_36731_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36731_Desc = {
    Text = "부드러운 생명체로서, 그것들은 이 미경에서 허락되지 않는 사치일 뿐, 단지 환영일 뿐이다. \n당신은 그것을 알면서도 마음속에서는 따뜻한 물결이 일어났다."
  },
  Event_36731_Name = {
    Text = "배고양이"
  },
  Event_36732_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36732_Desc = {
    Text = "그들의 모습은 마치 시간과 공간의 홍수에 씻긴 유화처럼 흐릿합니다. 깊은 검은 점들은 마치 밤하늘에 떠다니는 구름 같고, 그들의 눈은 오히려 먼 별들의 빛나는 반짝임처럼 신비롭고 깊은 빛을 발산합니다. \n 당신은 그들의 유혹을 저항할 수 없고, 손을 내밀어 공허 속으로 들어갑니다."
  },
  Event_36732_Name = {
    Text = "배고양이"
  },
  Event_36733_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36733_Desc = {
    Text = "당신은 계속 전진해야 한다는 것을 알고 있어, 비록 비틀거리더라도, 비록 넘어져도."
  },
  Event_36733_Name = {
    Text = "육체적 고통"
  },
  Event_36734_ChoiceDesc1 = {
    Text = "【그를 호출해 보세요】Arg1 포인트 생명 증가시킵니다"
  },
  Event_36734_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_36734_Desc = {
    Text = "여기는 은폐된 소망과 아직 접하지 않은 공포가 가득한 곳으로, 그의 꿈과 기억이 얽혀 만들어진 풍부한 그림이다."
  },
  Event_36734_Name = {
    Text = "진화의 변화"
  },
  Event_36735_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36735_Desc = {
    Text = "“수호자, 만약 견딜 수 없다면 혼자서 고통을 참지 마세요.”\n당신은 고통을 피할 수 없으며, 그것들은 덧없는 생명의 일부입니다.\n당신은 밤의 그림자를 피할 수 없으며, 그 안의 다크에 의해 포식당하는 것이 두렵지 않기 때문입니다."
  },
  Event_36735_Name = {
    Text = "육체적 고통"
  },
  Event_36736_ChoiceDesc1 = {
    Text = "【계속 호출】Arg1 포인트 생명을 증가시켜, “(Skill.Arg2)” 감염"
  },
  Event_36736_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_36736_Desc = {
    Text = "천진난만한 낙서가 이 세계를 이루고 있습니다."
  },
  Event_36736_Name = {
    Text = "진화의 변화"
  },
  Event_36737_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36737_Desc = {
    Text = "해양도약자의 기도가 귓가에 맴돌며, 광기에 찬 질식감을 불러일으킨다. \n하지만 그것들은 당신의 의지를 흔들지 못할 것이다, 절대."
  },
  Event_36737_Name = {
    Text = "자 바다에서"
  },
  Event_36738_ChoiceDesc1 = {
    Text = "[사진 줍기] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_36738_Desc = {
    Text = "이들 시선은 깊고 맑아서, 깊은 바다의 빛처럼 밝고 따뜻합니다. \n그들은 말을 하지 않고, 형태를 나타내지도 않지만, 당신은 그들의 존재를 느낄 수 있습니다. 마치 여름밤에 부드럽게 불어오는 바람의 달콤한 위안처럼."
  },
  Event_36738_Name = {
    Text = "선의의 엿보기"
  },
  Event_36739_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36739_Desc = {
    Text = "당신은 주의를 현재의 위기로 집중시키고, 고통을 무시하라고 자신에게 강하게 요구합니다."
  },
  Event_36739_Name = {
    Text = "육체적 고통"
  },
  Event_36740_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36740_Desc = {
    Text = "그것은 생명의 인장, 존재의 증명입니다. 그것은 스토리를 전하지만, 이 폭풍의 난폭함 속에서 점차 소리를 잃어가고 있습니다."
  },
  Event_36740_Name = {
    Text = "안녕, 이카로스"
  },
  Event_36741_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36741_Desc = {
    Text = "이들 시선은 깊고 맑아서, 깊은 바다의 빛처럼 밝고 따뜻합니다. \n그들은 말을 하지 않고, 형태를 나타내지도 않지만, 당신은 그들의 존재를 느낄 수 있습니다. 마치 여름밤에 부드럽게 불어오는 바람의 달콤한 위안처럼."
  },
  Event_36741_Name = {
    Text = "선의의 엿보기"
  },
  Event_36742_ChoiceDesc1 = {
    Text = "【마지막으로 그를 부르다】Arg1 포인트 생명 증가, “(Skill.Arg2)” 감염"
  },
  Event_36742_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_36742_Desc = {
    Text = "고통의 균열이 이 세계를 이루고 있다."
  },
  Event_36742_Name = {
    Text = "진화의 변화"
  },
  Event_36743_ChoiceDesc1 = {
    Text = "[통증을 안아라]백은 유물 “(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염됩니다"
  },
  Event_36743_ChoiceDesc2 = {
    Text = "【거절된 통증】황금 유물「(RelicConfig.Arg1)」을 획득하고, 「(Skill.Arg2)」와 「(Skill.Arg3)」에 감염됩니다"
  },
  Event_36743_ChoiceDesc3 = {
    Text = "[통증 무시]25 검은 인장 획득"
  },
  Event_36743_Desc = {
    Text = "통증은 마치 완고한 돌처럼 뇌에 뿌리를 내린다. 퍼져나가는 고통은 덩굴처럼 모든 신경을 감싸기 하고, 당신의 의식을 왜곡한다."
  },
  Event_36743_Name = {
    Text = "육체적 고통"
  },
  Event_36744_ChoiceDesc1 = {
    Text = "【견고하게 호출】Arg1 포인트 생명 증가시켜, “(Skill.Arg2)” 감염"
  },
  Event_36744_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_36744_Desc = {
    Text = "승인에 대한 갈망이 이 세상을 구성하고 있다."
  },
  Event_36744_Name = {
    Text = "진화의 변화"
  },
  Event_36745_ChoiceDesc1 = {
    Text = "[그들을 감시하자] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_36745_ChoiceDesc2 = {
    Text = "[그들에게 도움을 청하자] 「(Skill.Arg1)」에 감염되고, 선택지 1에서 획득한 각인으로 변경하기, 2회 사용 가능"
  },
  Event_36745_Desc = {
    Text = "미경의 흐르는 색채 속에서 당신은 신비로운 시선을 느꼈습니다. 그것들은 형체 없는 눈들로, 이 미경의 신비한 주름 속에 숨겨져 있습니다. \n그들이 당신을 바라본 순간, 당신의 내면에서는 강렬한 욕망이 우러나왔습니다."
  },
  Event_36745_Name = {
    Text = "선의의 엿보기"
  },
  Event_36746_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36746_Desc = {
    Text = "그것들을 이해하지 않으면, 당신은 이 혼란의 지옥에서 벗어날 수 없습니다.\n별들이 수면에 비칠 때, 그 뛰는 소망과 간청, 그 기도는 마치 거품처럼 천천히 바다 표면으로 올라가지만, 어느새 다크에 의해 흡수됩니다."
  },
  Event_36746_Name = {
    Text = "자 바다에서"
  },
  Event_36747_ChoiceDesc1 = {
    Text = "【급하게 그를 호출하며】Arg1 포인트 생명력 증가, “(Skill.Arg2)” 감염"
  },
  Event_36747_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_36747_Desc = {
    Text = "추악한 말이 이 세상을 이루고 있다."
  },
  Event_36747_Name = {
    Text = "진화의 변화"
  },
  Event_36748_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36748_Desc = {
    Text = "당신은 그의 앞에 서서 그의 영혼이 기묘한 회상으로 흡수되는 것을 목격합니다."
  },
  Event_36748_Name = {
    Text = "진화의 변화"
  },
  Event_36749_ChoiceDesc1 = {
    Text = "【그것은 눈물】1장의 카드를 삭제합니다"
  },
  Event_36749_ChoiceDesc2 = {
    Text = "【그것은 핏빛】『(RelicConfig.Arg1)』을 획득하고, 『(Skill.Arg2)』에 감염되었습니다"
  },
  Event_36749_Desc = {
    Text = "몇 방울의 액체가 갑판 위에서 자유롭게 번져나가며, 갑판의 틈새를 따라 조용히 사방으로 확산되었다.\n 그 흔적은 부드럽고 견고하며, 각 젖은 자국은 단호한 의미를 지니고 있고, 바닷바람의 포효와 범선의 신음 속에서 생과 사, 고요와 소란의 그림을 엮어낸다."
  },
  Event_36749_Name = {
    Text = "안녕, 이카로스"
  },
  Event_36750_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36750_Desc = {
    Text = "당신은 천천히 퍼져가는 점들을 응시하며 그들의 본질을 알아보려고 하지만, 이 하늘과 땅이 만나는 경계에서 비와 피의 차이가 모호해집니다. \n그것은 비인가? 바다의 눈물인가? \n당신은 모릅니다."
  },
  Event_36750_Name = {
    Text = "안녕, 이카로스"
  },
  Event_36751_ChoiceDesc1 = {
    Text = "[거절 동주파]3개 중 1개 선택 백은 유물 획득"
  },
  Event_36751_ChoiceDesc2 = {
    Text = "[동주파 참여]백은 유물 “(RelicConfig.Arg1)”“(RelicConfig.Arg2)” 획득, 두 번 “(Skill.Arg3)”에 감염"
  },
  Event_36751_Desc = {
    Text = "해양도약자의 속삭임과 “성아”의 심장박동이 은밀한 교향곡을 이루며, 매번 진동할 때마다 무연한 액체 우주가 울음소리를 일으킨다."
  },
  Event_36751_Name = {
    Text = "자 바다에서"
  },
  Event_36752_ChoiceDesc1 = {
    Text = "[사진 줍기] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하기"
  },
  Event_36752_ChoiceDesc2 = {
    Text = "[필름 검사] 「(Skill.Arg1)」에 감염되고, 선택지 1에서 획득한 각인으로 변경하기, 이제 1회만 사용 가능"
  },
  Event_36752_Desc = {
    Text = "그들은 악의가 없으며, 이러한 느낌은 직관처럼 당신의 뼈와 피 속에 뿌리내리고 있습니다.\n그래서 당신은 경계를 내려놓고, 이러한 은밀한 수호자들에게 도움을 요청하려고 합니다: 희미한 존재에게 당신의 혼란과 갈망을 털어놓는 것처럼, 오랜 친구에게 마음속 이야기를 진솔하게 나누는 것처럼."
  },
  Event_36752_Name = {
    Text = "선의의 엿보기"
  },
  Event_36874_ChoiceDesc1 = {
    Text = "[학교의 재미있는 일]백은 유물 “(RelicConfig.Arg1)” 획득"
  },
  Event_36874_ChoiceDesc2 = {
    Text = "[학교를 다니지 않음]75개의 검은 인장 획득, “(Skill.Arg2)”에 감염됨"
  },
  Event_36874_Desc = {
    Text = "폐허를 지나칠 때 오레타의 눈이 갑자기 반짝였습니다. \n “할머니가 여기 예전에는 학교였다고 하셨는데, 학생이 없어서 벌써 폐허가 되었대요!” \n “오레타는 학교에 다녀본 적이 없는데, 친구는요? 너는 학교에 가본 적이 있어?”"
  },
  Event_36874_Name = {
    Text = "잃어버린 기쁨"
  },
  Event_36875_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36875_Desc = {
    Text = "당신의 입에서 부정적인 답변을 듣고 오레타는 우울한 표정으로 고개를 저었습니다. \n“원래, 바깥 세상에도 학생이 없었나…… 그럼 처음에 학교를 지은 이유는 무엇이었을까?”"
  },
  Event_36875_Name = {
    Text = "잃어버린 기쁨"
  },
  Event_36876_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36876_Desc = {
    Text = "“빈민원, 쥐, 왁스상…… 좋았어! 탐험, 탐험이야!”\n오레타가 말하며 머리 위에 보이지 않는 물음표가 떠올랐습니다.\n“하지만, 할머니가 학교는 오레타를 똑똑하게 만들어 줄 곳이라고 하셨는데, 그런데……”\n오레타가 계속 생각하기 전에 당신은 그녀를 밀어 또 다른 모퉁이를 지나쳤습니다."
  },
  Event_36876_Name = {
    Text = "잃어버린 기쁨"
  },
  Event_36877_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36877_Desc = {
    Text = "“왜? 왜요?” \n오레타는 당신에게 놀라서 얼굴을 찡그리며 계속 지시했습니다. \n“여기는 오레타의 집이에요, 오레타가 알아요, 광장은 바로 그 안에 있어요!”"
  },
  Event_36877_Name = {
    Text = "보이지 않는 어둠"
  },
  Event_36878_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36878_Desc = {
    Text = "“이 길로 가고 싶지 않아요, 오레타가 광장으로 가는 다른 방법을 알고 있을까요?”\n오레타는 입을 삐죽이며 당황한 표정을 지었지만, 결국 당신의 망토를 잡아당겨 다른 방향으로 안내했습니다."
  },
  Event_36878_Name = {
    Text = "보이지 않는 어둠"
  },
  Event_36879_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_36879_Desc = {
    Text = "이것은 꿈입니다. 이건 단지 꿈일 뿐입니다. \n당신은 반복해서 스스로를 타이르거나 위로하며, 오레타를 이끌고 보이지 않는 어둠 속으로 돌진합니다."
  },
  Event_36879_Name = {
    Text = "보이지 않는 어둠"
  },
  Event_36880_ChoiceDesc1 = {
    Text = "[일리가 있네] 명령 카드 3장 중 1장을 선택해 각인 「(EnchantConfig.Arg1)」을(를) 획득하고, 「(Skill.Arg2)」에 감염되기"
  },
  Event_36880_ChoiceDesc2 = {
    Text = "[그건 아닌 거 같아] 깨어남체 1명을 선택해 깨어남시키고, 「(Skill.Arg1)」에 감염되기"
  },
  Event_36880_ChoiceDesc3 = {
    Text = "[합의점을 찾아보자] 검은 인장 25 획득하기"
  },
  Event_36880_Desc = {
    Text = "오레타가 당신의 망토를 잡으며 한 걸음씩 당신의 발자국을 함께 밟으며 앞으로 나아간다.\n「어…… 틀렸어! 광장은 저쪽이라구!」\n당신은 오레타가 가리킨 방향으로 돌아봤지만, 이미 미경의 골목은 마치 한 치 앞도 보이지 않는 어둠으로 가득 차 있었다. 융식의 점액과 뮤탄트가 서로 얽히고 꿈틀거리며, 현실타래 세계마저 함께 추락의 심연으로 끌어들이고 있었다."
  },
  Event_36880_Name = {
    Text = "보이지 않는 어둠"
  },
  Event_37983_ChoiceDesc1 = {
    Text = "[경비 획득]Arg1 개의 검은 인장을 획득"
  },
  Event_37983_ChoiceDesc2 = {
    Text = "[경비 획득]Arg1 개 검은 인장[ExDesc1]를 획득했습니다."
  },
  Event_37983_Desc = {
    Text = "“어떤 영주도 출처가 불분명한 자를 방치하지 않을 것이고, 수도사라면 더욱 그렇습니다.”\n여왕은 높은 왕좌에 앉아 있으며, 눈에는 예상치 못한 폭력이 스치고 지나갔습니다.\n“네가 다른 쓸모가 있다는 것을 증명해, 그렇지 않으면…”\n다른 쓸모? 너는 창밖의 황폐한 밭을 바라보며, 한 가지 생각이 갑자기 떠올랐습니다: 아마도 배운 경제학 지식을 활용하여 완다의 저택을 관리하는 데 도움을 줄 수 있을까요?\n너는 메마르고 매끄러운 뇌 속에서 애써 긁어모으려 했습니다—미사그에서는 경제학이 그저 눈에 띄지 않는 선택 과목일 뿐이라는 것을 알아야 합니다…\n인내심이 소진되었습니다. 여왕은 하품을 했습니다.\n“실타래망스럽군. 놓아—”\n그런데 단두대가 떨어지는 순간, 아담 스미스, 말서스, 데이비드 리카도 등 위대한 선조들의 영혼이 너의 작은 머릿속에 나타났습니다.\n노동 분업! 세금 부과! 인구, 젠장할 인구!\n너는 아마도, 어쩌면 생각해냈습니다."
  },
  Event_37983_Name = {
    Text = "비밀 대행 명령"
  },
  Event_37984_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_37984_Desc = {
    Text = "당신은 억지로 정령을 제안했습니다. \n여왕은 대충 읽고 차가운 미소를 지었습니다: \n“만약 쓸모없다면, 당신이 어떤 일이 일어날지 알고 있을 거야.”"
  },
  Event_37984_Name = {
    Text = "비밀 대행 명령"
  },
  Event_37985_ChoiceDesc1 = {
    Text = "[제안된 정책 명령]백은 유물 “(RelicConfig.Arg1)” 획득"
  },
  Event_37985_ChoiceDesc2 = {
    Text = "【제안된 정령】저주받은 유물「(RelicConfig.Arg1)」을 획득했습니다"
  },
  Event_37985_ChoiceDesc3 = {
    Text = "【제안된 정령】황금 유물 “(RelicConfig.Arg1)” 획득"
  },
  Event_37985_Desc = {
    Text = "“내 돈을 받았으니 내 대신 일해야 해.”\n여왕은 한 손으로 턱을 괸 채 무심하게 당신을 바라봅니다.\n인정하든 부정하든, 그녀는 확실타래히 이에 대해 호기심을 가지고 있습니다.\n“그럼, 당신의 계획을 말해 줘, 대개혁가.”"
  },
  Event_37985_Name = {
    Text = "비밀 대행 명령"
  },
  Event_38700_ChoiceDesc1 = {
    Text = "[연결] HP를 Arg2 회복 [ExDesc1]"
  },
  Event_38700_ChoiceDesc2 = {
    Text = "【명상】깨어남체 1명을 깨어남시킵니다."
  },
  Event_38700_ChoiceDesc3 = {
    Text = "【추방】최대 3장의 증상 카드를 제거하고, 검은 인장 Arg2개를 획득합니다."
  },
  Event_38700_Desc = {
    Text = "안개 속을 탐색하던 중, 갑자기 가슴에 단 배지가 희미한 은빛을 발했다. 통신기 너머에서 누군가 당신을 부르고 있는 걸까?"
  },
  Event_38700_Name = {
    Text = "연락 지점"
  },
  Event_38700_Tips3 = {
    Text = "현재 증상 카드를 소유하고 있지 않습니다."
  },
  Event_38707_ChoiceDesc1 = {
    Text = "【환상 제거】 증상 감염"
  },
  Event_38707_ChoiceDesc2 = {
    Text = "[흡수 환상]Arg1 생명을 잃고，Arg2 검은 인장을 획득합니다"
  },
  Event_38707_ChoiceDesc3 = {
    Text = "[떠나기]"
  },
  Event_38707_Desc = {
    Text = "모호한 얼굴들이 갑자기 나타나 당신 주변을 둘러싸고, 실타래체 없는 성대를 통해 절망적으로 신음합니다."
  },
  Event_38707_Name = {Text = "환각"},
  Event_38715_ChoiceDesc1 = {
    Text = "[제안된 정령]은 백은 유물 “(RelicConfig.Arg1)”“(RelicConfig.Arg2)”을 획득했습니다"
  },
  Event_38715_ChoiceDesc2 = {
    Text = "【제안된 정령】저주받은 유물「(RelicConfig.Arg1)」을 획득했습니다"
  },
  Event_38715_ChoiceDesc3 = {
    Text = "【제안된 정령】황금 유물 “(RelicConfig.Arg1)” 획득"
  },
  Event_38715_Desc = {
    Text = "“내 돈을 받았다면, 나를 위해 일해야 해.”\n여왕은 한 손으로 턱을 괸 채, 무관심하게 당신을 바라보았다. \n인정하든 아니든, 그녀는 확실타래히 이에 대해 호기심을 가지고 있다. \n“그렇다면, 당신의 계획을 말해줘, 대개혁가.”"
  },
  Event_38715_Name = {
    Text = "비밀 대행 명령"
  },
  Event_40452_ChoiceDesc1 = {
    Text = "[신분 묻기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\""
  },
  Event_40452_ChoiceDesc2 = {
    Text = "【떠나다】랜덤 3장의 명령 카드 획득 각인: “ (EnchantConfig.Arg1) ”, 감염 “ (Skill.Arg2) ”"
  },
  Event_40452_Desc = {
    Text = "세 개의 유령이 전진을 막았다. \n그들은 도박판 앞에 모여 주사위의 움직임을 집중적으로 지켜보고 있었다. \n“굴러, 굴러.” \n주사위는 수없이 던져지고 떨어졌다. \n이는 결말이 없는 영원한 도박이었다."
  },
  Event_40452_Name = {
    Text = "무한한 도박"
  },
  Event_40453_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_40453_Desc = {
    Text = "“안녕하세요, 우리는 완다의 첫 번째, 두 번째 그리고 세 번째 남편입니다.”\n“뭐요, 당신이 네 번째 남편이 어디 있는지 물어봤다고요? \n음… 솔직히 말하자면, 존은 유머 감각이 좀 부족해서 부인에게 맹안의 시종으로 변해버렸습니다.”\n“그를 잃은 것이 우리 모두에게 안타깝습니다. 물론, 조금만요.”"
  },
  Event_40453_Name = {
    Text = "무한한 도박"
  },
  Event_40454_ChoiceDesc1 = {
    Text = "【그와 악수하기】무작위로 1명의 깨어남체를 깨어남시키고, “(Skill.Arg1)”에 전염시킵니다"
  },
  Event_40454_ChoiceDesc2 = {
    Text = "【떠나다】3개 중에서 1개의 각인을 획득"
  },
  Event_40454_Desc = {
    Text = "감옥을 지나갈 때, 손이 안에서 나왔다. \n“리베카, 나를 떠나지 마……” \n소리는 늙고 메말라, 오래된 풍상처럼 들렸다."
  },
  Event_40454_Name = {Text = "죄수"},
  Event_40455_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_40455_Desc = {
    Text = "손바닥에서 끈적한 감각이 전해졌다——융해진흙이다. \n소리의 주인은 언제부터인지 이미 사라지고, 어두운 그늘 속에 은폐되어 있었다."
  },
  Event_40455_Name = {Text = "죄수"},
  Event_40456_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_40456_Desc = {
    Text = "당신은 아랑곳하지 않고 떠났고, 그로 인해 서신지 뒷편의 드라마틱한 과거를 놓쳤습니다.\n하지만 그게 무슨 상관일까요?\n광활한 바다, 여명과 황혼, 적도 사막……\n당신은 더 많은 것을 만나게 될 것이고, 더 많은 것을 놓치게 될 것입니다."
  },
  Event_40456_Name = {
    Text = "사랑하는 부인에게"
  },
  Event_40457_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_40457_Desc = {
    Text = "어떤 의미에서는 당신과 이 수인은 별반 다르지 않다. \n지금은 경솔하게 행동할 때가 아니다. \n당신은 수인의 애원을 무시한 채 돌아서서 떠났다."
  },
  Event_40457_Name = {Text = "죄수"},
  Event_40458_ChoiceDesc1 = {
    Text = "【서신 찢기】1개의 유물이 저주받은 유물“(RelicConfig.Arg1)”로 변화합니다"
  },
  Event_40458_ChoiceDesc2 = {
    Text = "[무시한 편지]백은 유물“(RelicConfig.Arg1)”을(를) 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_40458_ChoiceDesc3 = {
    Text = "[답장]25 검은 인장 획득"
  },
  Event_40458_Desc = {
    Text = "Ⅰ. 서신  존 캄베리안 주완다에게(홍적전 @2년) \n\n남편은 자신의 아내를 다룰 권리가 있다. 적어도 캄베리안에서는 그렇다. \n하지만 나는 분명히 당신의 광기 정도를 과소평가했다. 지금 내 두 눈은 거의 모두 멀었고, 내 사지는 곧 잘려나갈 것이다. \n악마의 딸. 악마의 딸…… 아니, 당신은 악마 그 자체다. \n나는 당신을 저주한다@1 당신을 저주한다@2 당신을 저주한다 저주한다……"
  },
  Event_40458_Name = {
    Text = "사랑하는 부인에게"
  },
  Event_40459_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_40459_Desc = {
    Text = "당신은 가장 단순한 방법으로 저주를 풀었습니다. \n아무 일도 일어나지 않았습니다. 종이 조각이 무기력하게 바닥에 떨어졌습니다. \n당신은 어깨를 으쓱하고 떠났지만, 마음속으로는 뭔가 이상하다는 느낌이 들었습니다."
  },
  Event_40459_Name = {
    Text = "사랑하는 부인에게"
  },
  Event_40460_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_40460_Desc = {
    Text = "당신은 마음을 분산시키지 않고 도박장 옆을 지나갔습니다. \n떠나기 전, 유령들이 함께 말했습니다: \n“우리의 공통된 전 부인인 완다 여사에게 안부를 전해주시기 바랍니다.”"
  },
  Event_40460_Name = {
    Text = "무한한 도박"
  },
  Event_40461_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_40461_Desc = {
    Text = "너는 서신지 끝에 공손하게 답장을 쓴다: \n“저주를 받았다, 모든 것이 잘 되길 바란다.”\n마지막 필획이 내려가는 순간, 서신지에 분노한 청색 불꽃이 피어오른다.\n너는 재를 수확했다."
  },
  Event_40461_Name = {
    Text = "사랑하는 부인에게"
  },
  Event_44187_ChoiceDesc1 = {
    Text = "【어둠에 대응】[ExDesc1][ExDesc2]"
  },
  Event_44187_ChoiceDesc2 = {
    Text = "【어둠에 대응】[ExDesc1][ExDesc2]"
  },
  Event_44187_ChoiceDesc3 = {
    Text = "【다크 회피】무작위 황금 유물 획득"
  },
  Event_44187_Desc = {
    Text = "당신 앞의 영혼은 어둡고 불결합니다——빛과 다크가 동시에 그것에 존재합니다. 그것들은 주도권을 쟁취하려 하고, 영혼은 혼란에 빠졌습니다. \n “나는 모든 것을 잃은 불쌍한 사람들에 대해 동정합니다. 하지만 이 세상이란 원래 이런 것 아닌가요? \n “누군가는 얻고, 누군가는 잃습니다. \n “다른 사람의 행복을 위해서 내 행복을 포기해야 하나요?”"
  },
  Event_44187_Name = {
    Text = "내면의 어둠"
  },
  Event_44188_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_44188_Desc = {
    Text = "“이것은 나의 죄악, 나의 짐이다. 어떻게 너를 구원할 수 있을까, 나의 모순된 영혼?”"
  },
  Event_44188_Name = {
    Text = "내면의 어둠"
  },
  Event_44299_ChoiceDesc1 = {
    Text = "【주교에게 기도】죄악의 유물을 정화합니다. 유물이 없으면 무작위 황금 유물을 획득합니다."
  },
  Event_44299_Desc = {
    Text = "“나는 속이고, 사기치고, 내가 원하는 삶을 얻었다——돈은 숫자로 변하고, 진미는 일상으로 변했다. 상업에서는 내가 말 한 마디로 모든 것이 결정되고, 정치에서는 내가 강경한 손목을 가지고 있다. 하지만 왜, 왜 나는 그 사람들, 내가 모든 것을 빼앗아 간 사람들을 잊을 수 없는가? 왜 그들의 얼굴에 나타난 절망을 잊을 수 없는가? \n “알코올은 단지 잠깐의 도피만을 제공할 뿐, 내 영혼은 스스로 찢어지고 있으며, 고통이 나를 거의 잠식하고 있다. \n “나는 도대체 어떻게 해야 하는가?”"
  },
  Event_44299_Name = {
    Text = "죄책감과 용서"
  },
  Event_44301_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_44301_Desc = {
    Text = "“당신은 고난의 길을 걷고 있으며, 당신은 아버지 신의 영광에서 벗어났습니다. \n“돌아오세요, 길을 잃은 양아, 아버지 신의 가르침에 따르고 올바른 길로 나아가세요.”"
  },
  Event_44301_Name = {
    Text = "죄책감과 용서"
  },
  Event_44395_ChoiceDesc1 = {
    Text = "[외물 구하기]주교가 당신의 1장의 증상을 부담합니다. 당신은 Arg1 검은 인장을 획득합니다. 만약 증상이 없다면, 바로 검은 인장을 획득합니다."
  },
  Event_44395_ChoiceDesc2 = {
    Text = "【피를 구하다】주교가 당신의 2장의 증상을 받고, 당신은 각인「(EnchantConfig.Arg1)」을 획득합니다."
  },
  Event_44395_ChoiceDesc3 = {
    Text = "【더 많은 증상 요구】주교가 더 많은 증상을 겪음(최소 4장)"
  },
  Event_44395_Desc = {
    Text = "환상적인 영혼이 모호한 윤곽을 드러내며, 비숍 앞에서 무릎을 꿇고 부서진 육체와 남아있는 검은 마음을 보여주었다. \n “당신은 나에게 길을 제시하고, 용서를 주며, 구원을 주었지만 자비로운 비숍이여, 이것은 결코 충분하지 않습니다. \n “나는 가난에 허덕이고, 병마의 포위에 시달리고 있습니다. 내 생명이 위태롭고, 당신이 나의 유일한 구원입니다. 구해주세요, 비숍, 더 이상 고통받지 않게 해주세요.”"
  },
  Event_44395_Name = {
    Text = "주교의“축복”"
  },
  Event_44396_ChoiceDesc1 = {
    Text = "【인사하고 떠나다】"
  },
  Event_44396_Desc = {
    Text = "비숍이 반지를 벗고 가슴핀을 제거했다. 아버지 신을 상징하는 푸른 보석들이 하나씩 영혼의 손에 놓였다. 비숍은 허리를 굽혀 불쌍한 영혼의 두 손을 잡았다. \n “내 몸에서 금은 보화를 가져가세요, 내가 가진 모든 재산을 가져가세요—— 그게 당신이 필요한 것이라면. 나는 아버지 신의 가르침이 있으면 충분히 살 수 있습니다.”"
  },
  Event_44396_Name = {
    Text = "주교의“축복”"
  },
  Event_44400_ChoiceDesc1 = {
    Text = "【중독】“(Skill.Arg1)” 감염, 임의의 깨어남체를 깨우다"
  },
  Event_44400_ChoiceDesc2 = {
    Text = "【포기】"
  },
  Event_44400_Desc = {
    Text = "길 잃은 영혼은 어둠을 포기하지 않으려 합니다. \n당신은 그것이 무엇을 기다리고 있는지 알고 있습니다. 부조리한 인생이 곧 펼쳐질 것이며, 당신은 유일한 관객입니다."
  },
  Event_44400_Name = {
    Text = "내면의 어둠"
  },
  Event_44401_ChoiceDesc1 = {
    Text = "[눈이 빠르고 손이 빠름] 획득 Arg1 검은 인장"
  },
  Event_44401_ChoiceDesc2 = {
    Text = "【무분별한 착취】3개 중 1개의 고급 각인을 획득, “(Skill.Arg1)”에 감염됩니다."
  },
  Event_44401_Desc = {
    Text = "밀경에서 발견된 검은 인장으로, 융흔에 희생하여 유물 등의 정신 프로젝션과 교환할 수 있습니다. 현재 지역을 떠난 후에는 곧 검은 진흙으로 소산됩니다."
  },
  Event_44401_Name = {
    Text = "검은 인장"
  },
  Event_44407_ChoiceDesc1 = {
    Text = "【환상 제거】 증상 감염"
  },
  Event_44407_ChoiceDesc2 = {
    Text = "[망상 포옹]무작위 증상 2장을 획득하고, Arg1 개의 검은 인장을 얻습니다."
  },
  Event_44407_ChoiceDesc3 = {
    Text = "[떠나기]"
  },
  Event_44407_Desc = {
    Text = "모호한 얼굴들이 갑자기 나타나 당신 주변을 둘러싸고, 실타래체 없는 성대를 통해 절망적으로 신음합니다."
  },
  Event_44407_Name = {Text = "환각"},
  Event_44445_ChoiceDesc1 = {
    Text = "[떠나기] 조명등 찾기"
  },
  Event_44445_ChoiceDesc2 = {
    Text = "【안개 진입】 HP Arg2 손실타래"
  },
  Event_44445_ChoiceDesc3 = {
    Text = "[외부 물건 버리기]5개의 검은 인장 차감, “영감” 1장 획득"
  },
  Event_44445_Desc = {
    Text = "전방에 짙고 검은 안개가 드리워져 있다. 무턱대고 들어가면 재앙을 불러올 것이다. \n「조명등」을 찾아 안개를 걷어내야 한다."
  },
  Event_44445_Name = {Text = "미지"},
  Event_44469_ChoiceDesc1 = {
    Text = "【뼈와 고기 구하기】주교가 당신의 4장의 증상을 당하고, 당신은 3개 중 1개의 황금 유물+를 획득합니다."
  },
  Event_44469_ChoiceDesc2 = {
    Text = "【축복을 구하다】주교가 당신의 6장의 증상을 받아들이고, 당신은 3중 1을 선택할 때 시령배를 획득합니다."
  },
  Event_44469_ChoiceDesc3 = {
    Text = "【반환】"
  },
  Event_44469_Desc = {
    Text = "희미한 윤곽으로 형체를 드러낸 허무의 영혼은 주교 앞에 무릎 꿇고 자신이 부서진 육체와 검게 물든 마음을 드러냈다.\n「당신은 나에게 방향을 제시해 주셨고, 나를 용서해 주셨으며, 나를 구원해 주셨지만, 자비로운 주교님, 그것만으로는 충분하지 않습니다.\n「저는 가난과 불행에 시달리고 있으며, 병마에 사로잡혀 있습니다. 제 운명은 위태롭고, 당신만이 제 유일한 구원자입니다. 제발 저를 구원해 주세요, 주교님, 제가 더 이상 고통받지 않게 해주세요.」"
  },
  Event_44469_Name = {
    Text = "주교의“축복”"
  },
  Event_44474_ChoiceDesc1 = {
    Text = "【소구】주교의 축복을 획득하다"
  },
  Event_44474_ChoiceDesc2 = {
    Text = "【소구】주교의 축복을 획득하다"
  },
  Event_44474_ChoiceDesc3 = {
    Text = "[떠나기]"
  },
  Event_44474_Desc = {
    Text = "“이것은 나의 죄악, 나의 짐이다. 어떻게 너를 구원할 수 있을까, 나의 모순된 영혼?”"
  },
  Event_44474_Name = {
    Text = "내면의 어둠"
  },
  Event_44911_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_44911_Desc = {
    Text = "“모든, 모든…… 맞아, 나는 모든 것을 원해……!” \n영혼이 손을 뻗어 공중에서 헛될히 잡으려고 했다. \n그것은 무엇인가를 얻었지만, 실타래제로는 아무것도 얻지 못했다."
  },
  Event_44911_Name = {
    Text = "당신이 얻은 것은 무엇인가요"
  },
  Event_44913_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_44913_Desc = {
    Text = "“그렇다면 가장 중요한 것만, 가장 중요한 것……”\n영혼은 공허의 흙에서 밝은 소망을 파내어 손바닥에 올렸다."
  },
  Event_44913_Name = {
    Text = "당신이 얻은 것은 무엇인가요"
  },
  Event_44916_ChoiceDesc1 = {
    Text = "[모두 붙잡기]커맨드 카드 3장 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\""
  },
  Event_44916_ChoiceDesc2 = {
    Text = "【학회 내려놓기】랜덤 3장의 명령 카드 획득 각인: “(EnchantConfig.Arg1)”, 감염 “(Skill.Arg2)”"
  },
  Event_44916_Desc = {
    Text = "어두운 영혼이 고통에 빠졌다. \n 그것은 제자리에서 맴돌며 모든 가능한 선택과 결과에 대해 혼란스러워 했다. \n “어떻게 선택해야 할까?” 그것은 나지막이 밀담하며, “무엇을 해야 할까?” \n “나는 어떻게 모든 것을 가질 수 있을까?”"
  },
  Event_44916_Name = {
    Text = "당신이 얻은 것은 무엇인가요"
  },
  Event_44919_ChoiceDesc1 = {
    Text = "【내면을 성찰하다】무작위로 1명의 깨어남체를 깨어남시키고, “(Skill.Arg1)”에 감염되게 하다"
  },
  Event_44919_ChoiceDesc2 = {
    Text = "【외부 관찰자】3개 중 1개의 각인 획득"
  },
  Event_44919_Desc = {
    Text = "부유하는 영혼이 딜레마에 빠졌다. \n그것은 걸음을 멈추고, 욕망 사이에서 망설였다. \n“어떻게 선택해야 할까?” 그것은 나지막이 말했다, “무엇을 해야 할까?” \n“도대체 무엇이 내가 진정으로 원하는 것일까?”"
  },
  Event_44919_Name = {
    Text = "너의 의도는 무엇인가"
  },
  Event_44920_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_44920_Desc = {
    Text = "“네가 맞아, 봐야 해, 봐야 해…”\n그는 고개를 숙이고, 양손을 가슴 안으로 넣어 그 안에서 한 개의 환영의 심장을 꺼냈다: 절반은 먹물처럼 검고, 절반은 별처럼 밝다."
  },
  Event_44920_Name = {
    Text = "너의 의도는 무엇인가"
  },
  Event_44921_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_44921_Desc = {
    Text = "「그렇지, 그렇지… 사람들이 서로를 거울로 삼는다고 하지… 봐야겠어…」\n그것이 네 앞에 다가와 얼굴 없는 얼굴로 너를 바라본다.\n「왜 그렇게 힘들어하지 않는 거야? 부럽다, 정말 부럽다…」"
  },
  Event_44921_Name = {
    Text = "너의 의도는 무엇인가"
  },
  Event_44998_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_44998_Desc = {
    Text = "“그들은 말합니다, 지금의 고통은 일시적이며, 죽은 후에 우리는 아버지 신의 품에서 영원한 기쁨을 누릴 것입니다.”\n“나는 죽은 후까지 기다리고 싶지 않다.”\n그림자가 탐욕스럽게 모든 것을 삼키고, 영혼은 어두워지며, 거의 주변의 다크와 하나로 합쳐졌습니다.\n당신은 무엇을 하고 싶지만, 무능력합니다."
  },
  Event_44998_Name = {
    Text = "내면의 어둠"
  },
  Event_45000_ChoiceDesc1 = {
    Text = "【인사하고 떠나다】"
  },
  Event_45000_Desc = {
    Text = "비숍이 날카로운 칼날로 손바닥을 베어, 석판 위로 떨어진 피가 치유의 블루 라이트로 변해 영혼이 결핍된 피를 보완했다. \n “내 피를 가져가서 당신의 생명을 채우세요—— 그게 당신이 필요한 것이라면. 이것이 아버지 신이 내가 행하기를 바라는 일입니다.”"
  },
  Event_45000_Name = {
    Text = "주교의“축복”"
  },
  Event_45001_ChoiceDesc1 = {
    Text = "【인사하고 떠나다】"
  },
  Event_45001_Desc = {
    Text = "비숍이 가슴 깊은 곳에서 자신의 영혼을 꺼내었다. 부드러운 빛점이 석판에 녹아 치유의 블루 라이트로 변해 영혼의 모든 균열을 메웠다. \n “받으세요, 이것은 아버지 신의 선물이며, 그분의 사랑의 증거입니다. 당신의 육체가 건강하고, 영혼이 완전해져 더 이상 어떤 고통도 받지 않기를 바랍니다.”"
  },
  Event_45001_Name = {
    Text = "주교의“축복”"
  },
  Event_45002_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_45002_Desc = {
    Text = "당신은 그 얼굴들 향해 걸어가고, 다시 눈을 뜰 때에는 눈앞이 이미 다크해졌습니다. 오직 출처를 알 수 없는 웃음소리만 주변에서 울려 퍼집니다."
  },
  Event_45002_Name = {Text = "환각"},
  Event_45036_ChoiceDesc1 = {
