  },
  Event_45036_Desc = {
    Text = "“이것은 나의 죄악, 나의 짐이다. 어떻게 너를 구원할 수 있을까, 나의 모순된 영혼?”"
  },
  Event_45036_Name = {
    Text = "내면의 어둠"
  },
  Event_45196_ChoiceDesc1 = {
    Text = "【인사하고 떠나다】"
  },
  Event_45196_Desc = {
    Text = "비숍이 날카로운 칼날로 뼈와 고기를 도려내어, 창백한 뼈와 진홍의 고기가 석판에 녹아 치유의 블루 라이트로 변해 영혼이 부서진 뼈를 보완했다.\n “내 뼈와 고기를 가져가서 당신이 결핍한 육체를 채우세요—— 그게 당신이 필요한 것이라면. 이것이 아버지 신이 내가 행하기를 바라는 일입니다.”"
  },
  Event_45196_Name = {
    Text = "주교의“축복”"
  },
  Event_46144_ChoiceDesc1 = {
    Text = "[떠나기]3개 중 1개의 백은 유물을 획득하고, “(Skill.Arg1)”에 감염되다"
  },
  Event_46144_Desc = {
    Text = "희미한 인영이 점차 선명해졌습니다. 그것은 융식체도, 재앙도 아닌, 날개가 없고 평범한 표정을 짓고 있는 클레멘타인이었습니다. \n “정말 우연이네, 너도 달빛을 감상하러 왔니?” 그녀가 웃으며 말했습니다. 그러나 당신은 어지러움을 느꼈습니다. “짙은 안개가 낀 밤이니, 조심해야 해.” \n “여기 작은 녀석들은, 별로 가만히 있지 않아.”"
  },
  Event_46144_Name = {
    Text = "안개 속의 모습"
  },
  Event_46145_ChoiceDesc1 = {
    Text = "【떠나다】3개 중 1개 선택 황금 유물 획득, “(Skill.Arg1)” 감염"
  },
  Event_46145_Desc = {
    Text = "당신은 아무렇지도 않은 척한다. 한 귀부인이 갑자기 무대로 달려온다. \n 그녀는 미친 듯이 소년의 입을 벌리고 손에 들고 있는 나무막대를 세게 찔렀다. \n “말해, 나에게 말해.” \n 소년의 입에서 검은 피가 흐른다. 그는 불분명하게 계속 읽어나갔다. \n “엄마에게 바치는 노래……”"
  },
  Event_46145_Name = {
    Text = "종막의 예 Ⅲ"
  },
  Event_47309_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47309_Desc = {
    Text = "그 날에 하나님은 그의 단단하고 강력한 칼로 페리시테인들을 벌하실타래 것입니다. \n그들이 “범한” 살육의 죄 때문입니다. \n뭐라고? 이것이 불공평하다고? \n아니, 이것이야말로 포식자의 운명입니다."
  },
  Event_47309_Name = {
    Text = "해적 노래"
  },
  Event_47310_ChoiceDesc1 = {
    Text = "【계속 듣기】저주받은 유물「(RelicConfig.Arg1)」을 획득하고, 「(Skill.Arg2)」에 감염되었습니다"
  },
  Event_47310_ChoiceDesc2 = {
    Text = "[떠나기]무작위 커맨드 카드 1장이 각인 획득: \"(EnchantConfig.Arg1)\""
  },
  Event_47310_Desc = {
    Text = "하나님이 말씀하셨다: 그를 필리스티아인이라고 하라.\n그가 살육의 책임을 지고, 욕심의 저주를 짊어지게 하라.\n그의 길이 빛을 발하게 하여, 심연이 마치 백발처럼 느껴지게 하라.\n광활한 바다에서 이보다 더 위대한 거대한 상어는 없다.\n그가 모든 생명체에게 두려움과 존경을 받게 하여,\n재판이 임하는 순간까지."
  },
  Event_47310_Name = {
    Text = "해적 노래"
  },
  Event_47311_ChoiceDesc1 = {
    Text = "【떠나다】감염“(Skill.Arg1)”"
  },
  Event_47311_ChoiceDesc2 = {
    Text = "【떠나다】감염“(Skill.Arg1)”"
  },
  Event_47311_ChoiceDesc3 = {
    Text = "【떠나다】감염“(Skill.Arg1)”"
  },
  Event_47311_Desc = {
    Text = "소년은 비천한 노예이다. \n 주인은 그를 아버지처럼 대했지만 침대에서 칼에 찔려 죽었다. \n “아버지, 사랑합니다. 저는 더 이상 노예가 되고 싶지 않습니다.” \n 후에, 소년은 “아버지”의 무덤 앞에 서서 사제의 말을 떠올렸다: \n <Small:당신을 낳은 고향을 떠나지 마십시오. \n 그때 당신의 두 손은 피로 물들고, 당신은 존엄 없이 죽게 될 것입니다. \n 들개, 독수리, 바다 물고기 모두 당신을 경멸할 것입니다.> \n 이 그렌이라는 이름을 가진 소년은 결국 떠나게 되었다. \n 그는 자신만의 추악한 이야기를 써내려 갈 것이다."
  },
  Event_47311_Name = {
    Text = "통 안의 소년"
  },
  Event_47312_ChoiceDesc1 = {
    Text = "[앞으로 페이지 넘기기]백은 유물 “(RelicConfig.Arg1)”을 획득하고, 1번의 증상을 선택하여 감염합니다"
  },
  Event_47312_ChoiceDesc2 = {
    Text = "【뒤로 페이지 넘기기】3장의 명령 카드 중 1장을 선택하여 각인을 획득:“(EnchantConfig.Arg1)”, 감염“(Skill.Arg2)”"
  },
  Event_47312_ChoiceDesc3 = {
    Text = "[버리기]25 검은 인장 획득"
  },
  Event_47312_Desc = {
    Text = "당신은 갈대 종이로 제본된 책을 주웠다: \n……\n소년은 통 안에 숨어 있었고, 필리스티아인의 작은 섬으로 떠내려왔다. \n그는 여위고, 비열하며, 야망이 넘친다. \n불멸의 거인의 영광이 모든 사람을 감탄하게 할 때, \n오직 소년만이 그 그림자 속에 숨어 그 빛이 자신에게 다가오지 못하게 한다. \n후에, 그는 골리아에게 중임을 맡게 된다. \n그 이유는……"
  },
  Event_47312_Name = {
    Text = "통 안의 소년"
  },
  Event_47313_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47313_Desc = {
    Text = "거인은 계속 말했다: \n“나는 그를 내 곁에 두었는데, 그는 우울하면서도 재미있기 때문이다. \n그리고 그는 영원히 나를 죽일 수 없다.”"
  },
  Event_47313_Name = {
    Text = "통 안의 소년"
  },
  Event_47314_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47314_Desc = {
    Text = "당신은 뒷부분을 듣지 못했지만, 그 가사는 당신에게 다른 노래를 떠올리게 했다: \n “이 희귀한 거대한 상어여, 폭풍우 속에 서 있다, \n 바다가 바로 그의 집, \n 힘이 곧 진리라면, 그는 힘의 거인, \n 끝없는 바다의 왕이다.”"
  },
  Event_47314_Name = {
    Text = "해적 노래"
  },
  Event_47315_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47315_Desc = {
    Text = "지금은 읽기에 좋은 시점이 아니다. \n 당신은 서둘러 책을 던져버렸고, 마지막 내용을 보지 못했다: \n …… \n 그가 그림자에 숨은 이유는 질투 때문이 아니다. \n 순전히 두려움 때문이다. \n 한 번 빛 아래 서게 되면, 비열한 영혼은 완전히 사라질 것이다. \n 재조차 남지 않을 것이다."
  },
  Event_47315_Name = {
    Text = "통 안의 소년"
  },
  Event_47463_ChoiceDesc1 = {
    Text = "【입면 유도】지정된 깨어남체를 정신분열병 상태로 만들어 초기의 네 장의 명령 카드를 잃게 합니다."
  },
  Event_47463_Desc = {
    Text = "의사가 방대한 책들 속에서 고개를 들었다: \n“당신은 드문 샘플이기 때문에 저는 당신에게 요금을 청구하지 않을 것입니다. \n하지만 저는 다른 보상을 필요로 합니다: 한 번의 최면. \n이것은 새로운 치료 방법으로, 전혀 숨김없이 완전히 맨 정신의 의식을 가져옵니다. \n어떻게, 시도해 볼래요?”"
  },
  Event_47463_Name = {
    Text = "「최면의 뱀」"
  },
  Event_47464_ChoiceDesc1 = {
    Text = "【빛나는 기억】[ExDesc1][ExDesc2]"
  },
  Event_47464_ChoiceDesc2 = {
    Text = "【어두운 기억】덱에서 모든 합주 각인을 고급 앙상블 각인으로 업그레이드합니다"
  },
  Event_47464_Desc = {
    Text = "그녀는 의식의 바다 해변을 떠돌고 있다.\n파도의 치마가 그녀의 발을 핥으며 흩어진 기억들을 해변으로 가져온다.\n그 기억들은 어떤 것은 반짝이고, 어떤 것은 흐릿하며, 또 어떤 것은 렌티니언의 우기에 냄새가 난다.\n너는 어떤 기억을 주워야 할까? 그녀는 의식의 바다 해변을 떠돌고 있다."
  },
  Event_47464_Name = {
    Text = "「주체 융합」"
  },
  Event_47465_ChoiceDesc1 = {
    Text = "[시도 거부]무작위 1장의 커맨드 카드가 각인 획득: \"(EnchantConfig.Arg1)\""
  },
  Event_47465_ChoiceDesc2 = {
    Text = "[부수어진 용매]죄책감의 유물 정화"
  },
  Event_47465_ChoiceDesc3 = {
    Text = "【실타래험 수락】“(RelicConfig.Arg1)” 시령배를 1개 획득했습니다"
  },
  Event_47465_Desc = {
    Text = "의사가 푸른 용액을 흔들며 흥분한 목소리로 그녀에게 말했다: \n“한 모금을 마시면, 당신은 깨어 있는 꿈의 세계에 들어갈 수 있어요. \n그것은 집단 잠재의식의 염력이 재현된 것입니다. \n지금 당신은 수많은 생명체와 같은 의식의 바다를 공유하게 될 것입니다. \n한 번 맛보아 볼래요?”"
  },
  Event_47465_Name = {
    Text = "「자각몽」"
  },
  Event_47466_ChoiceDesc1 = {
    Text = "【응답 소리】정신분열 깨어남체의 1장 명령 카드를 획득하다"
  },
  Event_47466_Desc = {
    Text = "육체는 감옥이며, 분열된 인격들을 갇히게 한다. \n “24”라는 이름의 감옥은 지금 가득 차 있다. \n “하지 말아요, 마음을 편하게 가지지 마.” \n 어둠 속에서 누군가가 조용히 말했다."
  },
  Event_47466_Name = {
    Text = "「자아 지각」"
  },
  Event_47848_ChoiceDesc1 = {
    Text = "【양 눈을 감으세요】3개 중에서 1개의 황금 유물을 획득"
  },
  Event_47848_ChoiceDesc2 = {
    Text = "【furtive glance】2 명의 깨어남체를 선택하고, 그들의 깨어남 카드 산출력 소모를 1 줄입니다."
  },
  Event_47848_ChoiceDesc3 = {
    Text = "[두 눈을 뜨다]백은 유물 “(RelicConfig.Arg1)”, “(RelicConfig.Arg2)”, “(RelicConfig.Arg3)” 획득"
  },
  Event_47848_Desc = {
    Text = "최면에 들어가기 전에, 의사가 말했다: \n“내 허락 없이는 눈을 뜨지 마세요.” \n그래서 그녀는 두 눈을 꼭 감고, 숨을 들이쉬고… 내쉬었다… \n반쯤 자고 반쯤 깬 상태에서, 그녀는 “쉬이쉬이”라는 숨소리를 들은 것 같았다. \n그 후 그녀는 차가운 시선 아래에 있었다—— \n무언가가 그녀를 바라보고 있었다. \n눈을 뜨고 살짝 확인해 볼까요?"
  },
  Event_47848_Name = {
    Text = "「최면의 뱀」"
  },
  Event_47876_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47876_Desc = {
    Text = "그녀가 허리를 굽혀 반짝이는 기억을 주웠다. \n하나, 둘…… 무수한 행복이 쏟아져 들어왔다. \n그녀는 양팔을 벌리고 그것들 주변을 돌기 시작했다."
  },
  Event_47876_Name = {
    Text = "「주체 융합」"
  },
  Event_47877_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47877_Desc = {
    Text = "그녀는 허리를 굽혀 희미한 기억들을 주워 올렸습니다.\n하나, 둘……수많은 하찮은 것들이 밀려들어 왔고,\n그녀는 두 팔을 벌려 그것들 모두를 품에 안았습니다."
  },
  Event_47877_Name = {
    Text = "「주체 융합」"
  },
  Event_47878_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47878_Desc = {
    Text = "당신은 이 기괴한 용매의 희생품이 되는 것을 거절합니다. \n의사는 약간 실타래망했지만, 당신을 억지로 하지 않습니다. \n“나는 인간의 비겁함과 단견을 용서합니다.”"
  },
  Event_47878_Name = {
    Text = "「자각몽」"
  },
  Event_47879_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47879_Desc = {
    Text = "화라! 당신이 병을 부수었습니다. \n초록색 용액이 바닥을 빠르게 부식했습니다. \n“아주 좋았어，무지한 충동이었지만 다음에는 없었으면 좋겠어. \n아니면 나는 슬퍼서 눈물을 흘릴 거야.”"
  },
  Event_47879_Name = {
    Text = "「자각몽」"
  },
  Event_47880_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47880_Desc = {
    Text = "당신은 꿀꺽 한 모금 마십니다. \n 꿀꺽꿀꺽…… 당신의 뇌와 목에서 동시에 수많은 거품이 솟아납니다. \n 마치 팝팝 소리를 내는 작은 불꽃놀이처럼. \n “당신을 찬양합니다, 용감한 인간이여. 당신은 무한에 접촉할 기회를 가질 것입니다. \n 그리고 나는 무한을 증언할 것입니다.”"
  },
  Event_47880_Name = {
    Text = "「자각몽」"
  },
  Event_47881_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47881_Desc = {
    Text = "그녀가 양 눈을 떠서 말했다:\n“네, 이 모든 것이 옳지 않습니다. \n눈물 흘려야 하고, 저항해야 합니다.”\n어둠 속에서 소리가 들렸고, 그녀는 친절한 응답을 받았다."
  },
  Event_47881_Name = {
    Text = "「자아 지각」"
  },
  Event_47900_ChoiceDesc1 = {
    Text = "【뱀을 발견하다】황금 유물+“(RelicConfig.Arg1)”"
  },
  Event_47900_ChoiceDesc2 = {
    Text = "[당신을 보다]죄책감의 유물 “(RelicConfig.Arg1)”을 획득했습니다"
  },
  Event_47900_Desc = {
    Text = "박. \n가볍게 튕기는 손가락 소리에 그녀는 현실타래로 돌아왔다. \n의사가 어느새 얼굴을 가까이 가져왔고, 코발트 옐로우빛 눈은 흥분으로 가늘게 떠졌다. \n“말해봐, 방금 뭐가 보였는지?”"
  },
  Event_47900_Name = {
    Text = "「최면의 뱀」"
  },
  Event_47901_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47901_Desc = {
    Text = "그녀는 두 눈을 떴다.\n빛과 그림자가 어지러운 사이, 그녀는 어둠 속에서 조용히 얽히고 천천히 꿈틀거리는 하얀 거대한 뱀을 본 것 같았다.\n아, 그리고 그것의 눈—\n그것은 한 점의 불순물도 섞이지 않은 순수한 금색이었다.\n슬픔도 기쁨도 없이, 어떤 판단도 없이,\n여름의 악몽에서 잠자는 다람쥐를 깨우기에 충분했다."
  },
  Event_47901_Name = {
    Text = "「최면의 뱀」"
  },
  Event_47909_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47909_Desc = {
    Text = "그녀는 조용히 한쪽 눈을 떴다.\n시선이 닿는 곳에는 흐릿한 흰색 빛의 그림자가 어둠 속에서 천천히 꿈틀거리고 있었다.\n연한 금색이 빛의 그림자 속에서 스치듯 지나가며 그녀의 위반을 경고하는 듯했다.\n그녀는 계속 바라보는 것을 두려워했다."
  },
  Event_47909_Name = {
    Text = "「최면의 뱀」"
  },
  Event_47910_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47910_Desc = {
    Text = "그녀는 의사의 지시에 따라 한 순간도 눈을 뜨지 않았다.\n차가운 숨결이 그녀 주위의 공기를 스치고, 그녀의 얼굴에 오랫동안 머물렀다.\n얼마나 시간이 지났는지 모르겠지만, 모든 것이 정상으로 돌아왔다.\n마치 아무 일도 일어나지 않은 것처럼."
  },
  Event_47910_Name = {
    Text = "「최면의 뱀」"
  },
  Event_47911_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47911_Desc = {
    Text = "“나는… 아주 예쁜 뱀을 봤어.”\n의사가 펜을 쥔 손이 잠시 멈췄다.\n“어떤 뱀이었어?”\n“아주 예뻐! 온몸이 하얗고, 위에는 금색 무늬가 있어…”\n의사는 더 이상 말을 하지 않았고, 입가가 미세하게 올라갔다.\n“고마워.”"
  },
  Event_47911_Name = {
    Text = "「최면의 뱀」"
  },
  Event_47912_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47912_Desc = {
    Text = "그녀는 의사의 코발트 옐로우빛 눈을 똑바로 바라보았다. \n “나는 네가 뱀이 되는 걸 봤어.” \n “오. 왜 그렇게 확신해?” \n 그것은 신비롭고, 정지해 있으며, 복잡했다. \n 그리고… \n 그것은 매우 지쳐 보였고, 마치 천 년의 겨울잠에서 깨어난 것처럼 보였다."
  },
  Event_47912_Name = {
    Text = "「최면의 뱀」"
  },
  Event_47992_ChoiceDesc1 = {
    Text = "[연결] HP를 Arg2 회복"
  },
  Event_47992_ChoiceDesc2 = {
    Text = "【명상】깨어남체 1명을 깨어남시킵니다."
  },
  Event_47992_ChoiceDesc3 = {
    Text = "【추방】최대 3장의 증상 카드를 제거하고, 검은 인장 Arg2개를 획득합니다."
  },
  Event_47992_Desc = {
    Text = "안개 속을 탐색하던 중, 갑자기 가슴에 단 배지가 희미한 은빛을 발했다. 통신기 너머에서 누군가 당신을 부르고 있는 걸까?"
  },
  Event_47992_Name = {
    Text = "연락 지점"
  },
  Event_47992_Tips3 = {
    Text = "현재 증상 카드를 소유하고 있지 않습니다."
  },
  Event_47993_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_47993_ChoiceDesc2 = {
    Text = "【떠나다】무작위 1장의 명령 카드에 각인을 부여:“(EnchantConfig.Arg1)” 그리고 해당 카드의 원본을 1장 복제"
  },
  Event_47993_Desc = {
    Text = "당신은 학교로부터 온 연락을 받았습니다. 익숙한 목소리가 당신의 마음을 안정시킵니다. 당신은 다시 집중하여 계속 앞으로 나아갑니다."
  },
  Event_47993_Name = {
    Text = "연락 지점"
  },
  Event_48225_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_48225_Desc = {
    Text = "고양이가 기쁘게 당신의 손등을 핥았습니다. \n“감사합니다. 저를 위해 슬퍼하지 마세요. \n여기의 인격은 언제나 죽음과 신생을 반복하고, \n저는 반드시 돌아올 거예요! \n야옹, 야옹야옹!”"
  },
  Event_48225_Name = {
    Text = "임종부탁"
  },
  Event_48226_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_48226_Desc = {
    Text = "고양이는 당신이 자신의 뜻을 이해하지 못했다고 생각하여, 애교 있게 당신의 손등을 비비고 있습니다. \n “당신이 약속해 주기만 한다면, 고양이는 자신이 소중히 간직한 간식을 모두 당신에게 바칠 거예요. \n 그것들은 캉브레 거리 @2호에 안전하게 보관되어 있어요…”"
  },
  Event_48226_Name = {
    Text = "임종부탁"
  },
  Event_48227_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_48227_Desc = {
    Text = "당신은 조지에게 진심으로 사과했습니다. \n“흥, 넌 예의를 아는 놈이긴 하군.\n조지는 저주 강도를 10% 낮추는 것을 고려할 거야,\n최대 15%—— 이건 조지의 마지노선이다.”"
  },
  Event_48227_Name = {
    Text = "조지의 유령"
  },
  Event_48228_ChoiceDesc1 = {
    Text = "【그의 요청에 응하다】황금 유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_48228_ChoiceDesc2 = {
    Text = "【거절하기】3개 중 1개의 황금 유물을 획득, “(Skill.Arg1)” 감염"
  },
  Event_48228_ChoiceDesc3 = {
    Text = "[침묵 유지]“(RelicConfig.Arg1)” 백은 유물을 획득했습니다"
  },
  Event_48228_Desc = {
    Text = "“고양이24” 심각한 부상을 입었습니다. 그것은 힘겹게 당신에게 말합니다: \n“우우, 곧 죽을 거예요. \n저에게 친구가 있는데, 은코다리예요. \n어느 날 그것을 만나면, 제가 먼 곳에 나갔다고 전해주세요. \n오래오래 떠날 거예요. \n튀김 생선 없는 감자튀김을 많이 가져올 거예요. \n꼭 그것에게 전해줘요!”"
  },
  Event_48228_Name = {
    Text = "임종부탁"
  },
  Event_48229_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_48229_Desc = {
    Text = "고양이는 조금 실타래망했습니다. \n하지만 그것은 항상 순종적이고 착한 고양이였기 때문에 다른 사람을 강요하지 않았습니다. \n마지막으로 그것은 아쉬움을 띠고 눈을 감았습니다."
  },
  Event_48229_Name = {
    Text = "임종부탁"
  },
  Event_48230_ChoiceDesc1 = {
    Text = "[그에게 사과하기]백은 유물 “(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)” 감염"
  },
  Event_48230_ChoiceDesc2 = {
    Text = "[도발]백은 유물 “(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염됩니다"
  },
  Event_48230_ChoiceDesc3 = {
    Text = "[무시해]획득 25 검은 인장"
  },
  Event_48230_Desc = {
    Text = "유령 하나, 조지의 유령이 너희들 상공을 맴돌고 있다. \n“조지는 전혀 존엄성 없이 죽었다.\n하지만 괜찮아, 조지는 이 굴욕을 영원히 기억할 것이다.\n수호자, 당신은 심각한 곤경에 처하게 될 거야, 흠흠……”"
  },
  Event_48230_Name = {
    Text = "조지의 유령"
  },
  Event_48231_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_48231_Desc = {
    Text = "“헤헤, 감히 조지를 도발하다니. \n 걱정하지 마, 네가 밥 먹을 때, 잘 때, 노래 부를 때…… \n 조지는 옆에서 떠다니며 너를 상기시키고, 괴롭힐 거야. \n 너의 죄를 영원히 기억하게 하려고. \n 너는 영원히 유령을 잡지 못할 거야, 라라라~”"
  },
  Event_48231_Name = {
    Text = "조지의 유령"
  },
  Event_48232_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_48232_Desc = {
    Text = "당신은 큰 걸음으로 앞으로 나아가 조지의 저주를 잊어버렸다.\n 뒤에서 흐느끼는 소리가 들리고 조지는 울기 시작했다.\n “웁웁…… 이렇게 사랑스러운 내가, 네 엉덩이에——\n 역겹다! 역겹다!\n 조지는 판디아의 채찍 아래에서 죽는 게 낫다!”"
  },
  Event_48232_Name = {
    Text = "조지의 유령"
  },
  Event_49055_ChoiceDesc1 = {
    Text = "[깨어남체 부르기] 모든 깨어남체의 광기를 100 잃고, 증상 카드 1장을 삭제하기"
  },
  Event_49055_ChoiceDesc2 = {
    Text = "[저항하기] HP를 Arg1 회복하고, 「(Skill.Arg2)」 2장에 감염되기"
  },
  Event_49055_ChoiceDesc3 = {
    Text = "[은열쇠 삽입하기] 모든 은열쇠 에너지 비우기"
  },
  Event_49055_Desc = {
    Text = "어렴풋이 보이는 피 웅덩이가 당신이 발을 디디는 순간 진짜 모습을 드러냈다. \n적흑색의 피가 수 없이 많은 팔로 변해 당신의 발목을 붙잡고 끊임없이 위로 기어오르며, 당신을 가늠할 수 없는 심연으로 끌어들이려 한다."
  },
  Event_49055_Name = {
    Text = "피의 웅덩이"
  },
  Event_49097_ChoiceDesc1 = {
    Text = "【전진】"
  },
  Event_49097_Desc = {
    Text = "복강 내에서 강물이 뒤집히는 듯 요동쳤다가, 몇 초 후 기적적으로 평온을 되찾았다. 어떤 이유에서인지, 당신은 체내에서 또 다른 심장의 선동을 듣는 것만 같았다……"
  },
  Event_49097_Name = {
    Text = "잉태의 어머니"
  },
  Event_49098_ChoiceDesc1 = {
    Text = "[단숨에 들이키다][ExDesc3][ExDesc4]장의 커맨드 카드를 선택해 각인 획득: \"(EnchantConfig.Arg1)\"[ExDesc1][ExDesc2]"
  },
  Event_49098_Desc = {
    Text = "낡은 도자기 항아리가 낮은 바위 벽의 틈새에서 당신을 바라보고 있다.\n수원은 사막에서 가장 귀중한 자원이며, 알코올은 광란과 몽환의 세계로 이끄는 약이다.\n이 불모의 지역에서, 아직 이성을 지닌 사람이 그것의 유혹을 거부하기는 어렵다."
  },
  Event_49098_Name = {
    Text = "잉태의 어머니"
  },
  Event_49312_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_49312_Desc = {
    Text = "은 열쇠의 휘광이 반짝였다. 팔들이 마치 어떤 힘에 위협받아 연못으로 숨어들어가고, 사라졌다."
  },
  Event_49312_Name = {
    Text = "피의 웅덩이"
  },
  Event_49313_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_49313_Desc = {
    Text = "당신은 필사적으로 싸우지만, 점점 더 깊이 빠져들고, 뇌리에서는 저주 같은 꿈결의 속삭임이 울려 퍼집니다. \n 정신을 차렸을 때, 피빛 촉수들이 만족스러운 듯 물러났습니다. 당신은 온몸이 개운하다고 느끼지만, 어딘가 모르게 이미 잃어버린 것이 있는 듯합니다…"
  },
  Event_49313_Name = {
    Text = "피의 웅덩이"
  },
  Event_49314_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_49314_Desc = {
    Text = "응답하여 다가온 깨어남체는 망설임 없이 너를 피비린내 나는 구덩이에서 끌어냈다. 연결된 너의 팔이 찢겨지고, 탁한 진흙 물이 튀어 오르며, 물속에서는 눈으로 분간하기 어려운 수많은 생명체가 꿈틀거렸다. 마치 무엇인가를 갈망하며 삼키려는 것처럼 보였다."
  },
  Event_49314_Name = {
    Text = "피의 웅덩이"
  },
  Event_49867_ChoiceDesc1 = {
    Text = "무작위 깨어남체가 50 광기 획득"
  },
  Event_49867_Name = {Text = "이벤트"},
  Event_49907_ChoiceDesc1 = {
    Text = "【진위를 묻다】"
  },
  Event_49907_ChoiceDesc2 = {
    Text = "【요청 쓰다듬기】"
  },
  Event_49907_Desc = {
    Text = "“너는 항상 내 뿔을 신기한 듯이 쳐다보는 거야, 무슨 문제가 있어?” \n테이스가 갑자기 네 어깨에 다가가며 꿀색의 비즈가 너의 볼을 가볍게 스치며 흔들렸다."
  },
  Event_49907_Name = {
    Text = "뿔이 있는 사람"
  },
  Event_49908_ChoiceDesc1 = {
    Text = "【위로 보아】"
  },
  Event_49908_ChoiceDesc2 = {
    Text = "【테이스로 가기】"
  },
  Event_49908_Desc = {
    Text = "폐허 속에 먼지가 사방으로 흩날리는 가운데, 한쪽 구석의 깨진 창문 밖으로 갑자기 타이스의 모습이 나타났습니다. 그녀는 거리낌 없이 먼지가 가득 쌓인 창틀에 몸을 기댄 채, 신비롭게 지붕 들보 위를 가리켰습니다."
  },
  Event_49908_Name = {Text = "잠입자"},
  Event_49909_ChoiceDesc1 = {
    Text = "【떠나다】3장의 명령 카드 중 1장을 선택하여 각인 획득:“(EnchantConfig.Arg1)”"
  },
  Event_49909_Desc = {
    Text = "당신은 고개를 들어 올리고, 녹슨 구리관이 사방으로 뻗어 있으며, 마치 거대한 거미줄처럼 머리 위를 덮고 있습니다. 그림자가 스쳐 지나가는데, 그것은 먹이를 찾는 야생 고양이일까요, 아니면 그림자 속에 숨어 있는 몬스터일까요? \n 다시 돌아보니 타이스의 모습은 사라지고 없었습니다."
  },
  Event_49909_Name = {Text = "잠입자"},
  Event_49910_ChoiceDesc1 = {
    Text = "【그녀를 주시해】"
  },
  Event_49910_ChoiceDesc2 = {
    Text = "【그녀를 부르세요】"
  },
  Event_49910_Desc = {
    Text = "당신은 또다시 그 '환영'을 보았다.\n이번에는 그녀의 이름을 이미 알고 있었다.\n타이이스는 먼 어머니 나무 아래에서 경건하게 나무에게 기도하고 있었다.\n그녀의 윤곽은 희미하게 어머니 나무의 환영과 하나가 된 것처럼 보였다."
  },
  Event_49910_Name = {
    Text = "기원하는 사람"
  },
  Event_49911_ChoiceDesc1 = {
    Text = "【떠나다】3장의 명령 카드 중 1장을 선택하여 각인 획득:“(EnchantConfig.Arg1)”"
  },
  Event_49911_Desc = {
    Text = "저 멀리 타이이쓰의 모습을 바라보니, 그녀의 실타래루엣은 마치 종말 같은 폭풍 속에서 신성하고 장엄한 외로운 봉우리처럼 보였습니다. 모래바람이 거세게 휘몰아쳐도 그녀의 위엄은 전혀 손상되지 않았습니다.\n그녀의 발걸음은 느리지만 확고하며, 그녀의 몸짓은 우아하고 범접할 수 없는 위엄을 풍겨, 당신은 그 모습에 매료되었습니다."
  },
  Event_49911_Name = {
    Text = "불멸의 사람"
  },
  Event_49912_ChoiceDesc1 = {
    Text = "【떠나다】1장의 명령 카드를 복제합니다"
  },
  Event_49912_Desc = {
    Text = "“당신이 알아보세요?”\n그녀는 “쉿”하고 소리를 내며 몸을 더 가까이 숙여서 당신의 뺨에 뿔의 끝이 닿았고, 시원하면서 간지러운 느낌이 들었습니다…"
  },
  Event_49912_Name = {
    Text = "뿔이 있는 사람"
  },
  Event_49913_ChoiceDesc1 = {
    Text = "[떠나다]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_49913_Desc = {
    Text = "“만지고 싶으면 솔직히 말해봐, 내가 거절할까?” \n그녀는 가볍게 웃으며 당신의 손을 잡고, 손끝이 닿는 감촉은 따뜻하고 매끄럽고, 당신은 거의 그 속으로 깊이 빠져들고 싶어졌습니다……"
  },
  Event_49913_Name = {
    Text = "뿔이 있는 사람"
  },
  Event_49914_ChoiceDesc1 = {
    Text = "【떠나다】1명의 깨어남체를 선택하여 깨어남 카드 비용을 -1하고, “(Skill.Arg1)”에 감염시킵니다"
  },
  Event_49914_Desc = {
    Text = "너는 여럿이와 함께 땅에 무릎을 꿇고 있다. \n “나는 알았다, 나는 알았다, 여왕, 여왕님께서 항상 우리를 지켜주고 계신다!” \n 기쁨에 겨워 흐느끼는 절규와 긴 호출 소리가 바람의 울부짖기와 섞여 너의 뇌와 공명하며 진동한다. \n 희미하게, 어떤 중요한 생각이 스쳐 지나가지만, 잡을 수 없다."
  },
  Event_49914_Name = {
    Text = "불멸의 사람"
  },
  Event_49915_ChoiceDesc1 = {
    Text = "[떠나기]3개 중 1개의 백은 유물을 획득하고, “(Skill.Arg1)”에 감염되다"
  },
  Event_49915_Desc = {
    Text = "당신은 그녀에게 손을 흔들었다.\n“무엇을 하고 있니?” 라모나가 의혹어린 눈빛으로 당신을 바라보았다.\n“저기……”\n말이 끝나기도 전에, 저 멀리 그 여인은 이미 모습을 감추었다.\n혹시 착각이었을까?"
  },
  Event_49915_Name = {
    Text = "물 뿌리는 사람"
  },
  Event_49916_ChoiceDesc1 = {
    Text = "【그녀에게 응답하라】"
  },
  Event_49916_ChoiceDesc2 = {
    Text = "【유예】"
  },
  Event_49916_Desc = {
    Text = "멀리서 보니 한 여성이 강가에서 물을 길어올리고 있다. \n당신의 시선을 눈치챈 듯 그녀는 몸을 돌려 당신에게 손을 흔든다. \n당신은 그녀가 몸을 돌리는 방식이 어딘가 이상하다는 것을 알아차립니다."
  },
  Event_49916_Name = {
    Text = "물 뿌리는 사람"
  },
  Event_49917_ChoiceDesc1 = {
    Text = "【떠나다】3장의 명령 카드 중 1장을 선택하여 각인「(EnchantConfig.Arg1)」을 획득"
  },
  Event_49917_Desc = {
    Text = "당신이 유예하는 사이, 여자가 돌아서서 오아시스로 사라졌다. \n당신은 자신의 눈을 완전히 믿지 못한다…… 그녀는 양의 발굽을 가지고 있는 것인가?"
  },
  Event_49917_Name = {
    Text = "물 뿌리는 사람"
  },
  Event_49918_ChoiceDesc1 = {
    Text = "【떠나다】3장의 명령 카드 중 1장을 선택하여 각인「(EnchantConfig.Arg1)」을 획득"
  },
  Event_49918_Desc = {
    Text = "「나무여, @1인의 소원을 들어주소서, 저는 당신의 젖을 받아 부활하여, 당신의 집행자가 되어, 황금빛 모래 사이를 당신을 위해 걷고, 당신의 뿌리가 레무바시의 모든 구석에 접촉하게 하리이다……」\n\n여기저기서 울려 퍼지는 어린 기도 소리가 공간 속에 메아리쳤습니다."
  },
  Event_49918_Name = {
    Text = "기원하는 사람"
  },
  Event_49919_ChoiceDesc1 = {
    Text = "【떠나다】무작위로 1명의 깨어남체를 깨어남"
  },
  Event_49919_Desc = {
    Text = "타이스의 애매모호한 시선이 당신의 주의를 끌었고, 어떤 기교활한 힘이 당신을 의도치 않게 혼란스럽게 만들었습니다. 당신은 그녀에게 끌리는 듯, 저절로 그녀에게로 다가가고 있었습니다. \n “사실타래, 보이지 않는 것들도 여전히 존재해.” \n 그녀가 부드럽게 당신의 귀에 속삭였고, 당신은 깨달은 듯했지만, 마치 하얀 베일로 가려진 것처럼 명확히 알 수 없었습니다. \n 이것은 어떤 예언인가요? 문득, 타이스는 이미 자취를 감추었습니다."
  },
  Event_49919_Name = {Text = "잠입자"},
  Event_49920_ChoiceDesc1 = {
    Text = "【전망】"
  },
  Event_49920_ChoiceDesc2 = {
    Text = "【구복】"
  },
  Event_49920_Desc = {
    Text = "양의 검은 발굽이 모래바람이 휘날리는 대지에 내려선다. \n테이스는 알 수 없는 기도문을 읊조리며, 수많은 아란인들이 그녀가 모래를 밟고 온 방향으로 구복한다."
  },
  Event_49920_Name = {
    Text = "불멸의 사람"
  },
  Event_49921_ChoiceDesc1 = {
    Text = "【떠나다】3개 중 1개 선택 황금 유물 획득, “(Skill.Arg1)” 감염"
  },
  Event_49921_Desc = {
    Text = "거대한 나무는 수천 개의 굵은 가지를 내밀어, 얽히고설킨 촉수처럼 타이이스의 손목과 발목을 꽉 묶고, 그녀의 저항과 투쟁을 무시한 채, 거칠게 그녀의 몸통을 부풀어 오른 나무 줄기의 배관 안으로 집어넣었다……\n\n비록 단지 먼 환영일 뿐이지만, 그녀의 고통은 여전히 물결의 진동을 따라 당신의 마음 깊이 전해졌다."
  },
  Event_49921_Name = {
    Text = "기원하는 사람"
  },
  Event_49922_ChoiceDesc1 = {
    Text = "[떠나기] 유물 획득「(RelicConfig.Arg1)」"
  },
  Event_49922_Desc = {
    Text = "힘없이 늘어진 사지가 나무의 수액과 함께 줄기를 따라 흐르고, 그녀는 온 힘을 다해 저항했지만, 사지는 마치 흐트러진 왜곡된 벌레처럼 제멋대로였다. \n “뼈는 완전히 용해되었어,” 타이스의 눈가와 미소가 슬픔에 물들며, “그녀는 이미 나무의 일부가 되었어.” \n “우리는 되돌릴 힘이 필요해…… 시간을 초월하는 힘.”"
  },
  Event_49922_Name = {
    Text = "부식된 자"
  },
  Event_49923_ChoiceDesc1 = {
    Text = "【떠나다】3장의 명령 카드 중 1장을 선택하여 각인 획득:“(EnchantConfig.Arg1)”"
  },
  Event_49923_Desc = {
    Text = "“그리고, 그 ‘무눈의 눈’은 어쩐지 모르게 가슴 깊은 곳에서부터 강렬한 부름을 느끼게 했다……”\n“아이고, 나에 대한 이야기를 하고 있나요?”\n“메디나이트가 당신의 스토리텔링 능력을 칭찬하고 있어요.”\n\n그 캠프파이어가 조용히 타오르던 밤, 그녀는 당신에게 술 한 잔을 더해주었던 적이 있다."
  },
  Event_49923_Name = {
    Text = "부식된 자"
  },
  Event_49924_ChoiceDesc1 = {
    Text = "【나무 혹을 베어내다】"
  },
  Event_49924_ChoiceDesc2 = {
    Text = "【회상】"
  },
  Event_49924_Desc = {
    Text = "나무혹 하나. \n 그것은 사악하고 부풀어 오르며 뛰고 있고, 손상하고 투명한 피색 표피 안쪽에서 기이하고 고통스러운 얼굴이 비치고 있어, 언제든지 껍질을 뚫고 나올 것 같았다. \n “메디나이트.” 타이스는 슬픈 표정을 지으며 그 얼굴의 이름을 부드럽게 호출했다."
  },
  Event_49924_Name = {
    Text = "부식된 자"
  },
  Event_49939_ChoiceDesc1 = {
    Text = "[라이커를 믿기] 모든 깨어남체의 광기를 Arg1 회복하기"
  },
  Event_49939_ChoiceDesc2 = {
    Text = "[라이커를 의심하기] 깨어남체 2명을 선택하기"
  },
  Event_49939_Desc = {
    Text = "「내 행운을 믿어줘.」"
  },
  Event_49939_Name = {
    Text = "운 좋은 탐정"
  },
  Event_49940_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_49940_Desc = {
    Text = "레이크가 잘하는 일은 세 가지뿐이다: 정찰, 청취, 주사위. \n다시 말해, 전투에는 능하지 않다. \n당신의 마음속 걱정은 억제할 수 없고 광기가 자라난다."
  },
  Event_49940_Name = {
    Text = "운 좋은 탐정"
  },
  Event_49941_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_49941_Desc = {
    Text = "믿는 마음은 마법이다. 그는 분명히 눈앞의 모든 장애물을 극복할 것이다."
  },
  Event_49941_Name = {
    Text = "운 좋은 탐정"
  },
  Event_49943_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_49943_Desc = {
    Text = "당신은 매우 부끄러워하면서도 여전히 병에 걸린 라모나를 향해 기대에 차서 눈빛을 보냈습니다. \n\"내가 하겠어요.\" \n그녀는 얼굴이 발개지며, 그 무한한 용량의 손가방에서 새 채집병을 꺼내 손쉽게 거미를 덮었습니다."
  },
  Event_49943_Name = {Text = "독거미"},
  Event_49944_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_49944_Desc = {
    Text = "레이크가 손가락을 튕기고, 그 후 털이 보송보송한 검지손가락을 높이 들고 있는 큰 거미를 향해 뻗었다. \n 이런 무늬가 화려한 종은 대개 독이 강하다. 당신은 그에게 조심하라고 경고하려고 했지만, 방금 전까지 적대적이었던 거미는 그의 관절 위로 가볍게 뛰어올라 몸을 웅크렸다. \n 그만 둬, 사람마다 운명이 다르니까."
  },
  Event_49944_Name = {Text = "독거미"},
  Event_49945_ChoiceDesc1 = {
    Text = "【라모나 쪽을 보다】3개 중에서 1개의 각인 획득"
  },
  Event_49945_ChoiceDesc2 = {
    Text = "【레이크를 바라보며】3장의 명령 카드 중 1장을 선택하여 각인 획득:“(EnchantConfig.Arg1)”, 감염 “(Skill.Arg2)”"
  },
  Event_49945_Desc = {
    Text = "다수의 복안이 너와 서로 마주보고 있다. \n 복안의 주인이 한 걸음 뒤로 물러나며, 너에게 위협을 가하며 발톱을 드러낸다. \n 높이 들린 다리와 더듬이, 그리고 몸을 지탱하는 두 쌍의 다리로 보아, 이 생물은 확실타래히 드문 거미강 생물이다. \n 출발하기 전에 코르트의 경고가 귓가에 맴돈다: \"추가 임무, 현지 종 샘플을 채집하여 현지 조사소에 보관하십시오.\" \n 너는 배낭 속의 채집병을 흔들어 보았고, 수주간의 여정 끝에 그 안에는 벌레가 가득 차 있다."
  },
  Event_49945_Name = {Text = "독거미"},
  Event_49946_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_49946_Desc = {
    Text = "“시기적절하지 않은 욕심은 병이다.”"
  },
  Event_49946_Name = {
    Text = "당신의 답변"
  },
  Event_49947_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_49947_Desc = {
    Text = "“본문을 그대로 읽는다고 당신이 호감을 얻을 수는 없어요, 자식.”"
  },
  Event_49947_Name = {
    Text = "당신의 답변"
  },
  Event_49948_ChoiceDesc1 = {
    Text = "【금열쇠】황금 유물“(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염되었습니다."
  },
  Event_49948_ChoiceDesc2 = {
    Text = "【철 키】3개 중 1개의 황금 유물 획득, 감염 “(Skill.Arg1)”"
  },
  Event_49948_ChoiceDesc3 = {
    Text = "[은 열쇠]백은 유물“(RelicConfig.Arg1)”을 획득"
  },
  Event_49948_Desc = {
    Text = "정오에, 성하에서 피어오르는 수증기가 두 개의 허공에 떠오르는 환영을 형성했습니다. \n환영의 흐릿한 소리가 당신에게 묻습니다: 이것이 당신이 잃은 금키, 은키, 아니면 철키인가요?"
  },
  Event_49948_Name = {
    Text = "당신의 답변"
  },
  Event_49949_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_49949_Desc = {
    Text = "“정직함은 종종 더 안전한 결과를 가져오지만, 동시에 당신은 무엇인가를 놓칠 수도 있습니다.”"
  },
  Event_49949_Name = {
    Text = "당신의 답변"
  },
  Event_50013_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50013_Desc = {
    Text = "당신은 그 사람의 얼굴을 자세히 식별하려 했지만, 물결에 따라 흐릿하게 흔들리며 선명하지 않았습니다. \n\n 당신이 더욱 집중하고 숨을 참을수록, 뇌는 산소 부족처럼 환각적인 느낌이 들기 시작했고, 라모나가 당신을 호출하는 목소리를 듣고 나서야 간신히 현실타래로 돌아올 수 있었습니다. \n 수면에 비친 태양은 유난히 눈부셨지만, 수면 아래에는 무언가 반짝이는 것이 있는 듯했습니다."
  },
  Event_50013_Name = {
    Text = "죽음의 환영"
  },
  Event_50014_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50014_Desc = {
    Text = "환영은 한 번의 접촉으로 무너지고, 당신의 손엔 아무것도 없습니다. 오직 태양혈에서 갑자기 폭발하는 극심한 통증만이 느껴집니다.\n수면에 비친 뜨거운 태양은 유난히 눈부시지만, 수면 아래에는 무언가 반짝거리는 것이 있는 듯합니다."
  },
  Event_50014_Name = {
    Text = "죽음의 환영"
  },
  Event_50015_ChoiceDesc1 = {
    Text = "[노력하여 식별]백은 유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_50015_ChoiceDesc2 = {
    Text = "[손을 뻗어 만지기]백은 유물“(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염됨"
  },
  Event_50015_ChoiceDesc3 = {
    Text = "[눈을 비비다]획득 25개의 검은 인장"
  },
  Event_50015_Desc = {
    Text = "당신은 누비아에게 밀려 반쪽 다리가 성하에 빠졌다.\n당신은 힘겹게 균형을 잡으려 했지만, 흔들리는 물결 속에서 보지 말아야 할 반영을 보았다.\n그것은 미사그 교복을 입고 키가 큰 청년으로, 그의 힘없이 무너진 몸이 성하의 흐름 속에 누워 있었다."
  },
  Event_50015_Name = {
    Text = "죽음의 환영"
  },
  Event_50016_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50016_Desc = {
    Text = "공황이 당신의 정신을 부식시키고, 고통이 의식을 흐릿하게 만듭니다. 당신은 필사적으로 찢어내지만, 덩굴은 점점 더 조여오고, 코 안으로는 이상한 냄새가 나는 끈적한 액체가 스며들어 매번 숨을 쉴 때마다 끈적한 절망을 느낍니다.\n라모나가 한 칼을 내리치자, 누비아는 다리를 잘라 도망쳤고, 당신은 얼굴 옆에 붙어 있던 마지막 촉수를 잡아당기자 그 위에 모호한 혈육이 묻어 있었습니다."
  },
  Event_50016_Name = {
    Text = "얼굴을 향해 다가오다"
  },
  Event_50017_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50017_Desc = {
    Text = "은빛이 누비아의 몸에 박히고, 혈육이 폭발하는 느낌이 은 열쇠를 따라 당신의 손끝과 손목으로 전달된다.\n누비아의 왜곡된 촉수가 하늘로 높이 치켜들리며 날카로운 포효처럼 공포스럽고 애처로운 비명을 지르며, 온몸이 끈적끈적한 불명의 액체로 변해버린다."
  },
  Event_50017_Name = {
    Text = "얼굴을 향해 다가오다"
  },
  Event_50018_ChoiceDesc1 = {
    Text = "【찢어짐】저주받은 유물“(RelicConfig.Arg1)”을 획득하고, 감염“(Skill.Arg2)”"
  },
  Event_50018_ChoiceDesc2 = {
    Text = "[관통]무작위 커맨드 카드 1장이 각인 획득: \"(EnchantConfig.Arg1)\""
  },
  Event_50018_Desc = {
    Text = "누비아의 덩굴 같은 촉수가 왜곡되며 날아다니다가 틈을 타 당신의 얼굴에 달라붙어, 광포하게 당신의 입과 코로 침입했다."
  },
  Event_50018_Name = {
    Text = "얼굴을 향해 다가오다"
  },
  Event_50019_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50019_Desc = {
    Text = "물 위에는 오직 반짝이는 파동만 있다.\n당신은 젖은 다리를 들어 올려 신발 속의 습기 찬 모래를 털어냈다.\n방금 본 영상이 여전히 머릿속을 맴돌고 있다."
  },
  Event_50019_Name = {
    Text = "죽음의 환영"
  },
  Event_50029_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50029_Desc = {
    Text = "“그가 돌아올까요? 아니면 영원히 당신을 이 무한한 모래 바다에 남겨두고 갈까요?”\n“그가 당신을 찾을 수 있을까요? 아니면 바람 방향과 모래 언덕의 변화로 당신의 좌표를 잃어버릴까요?”\n“당신이 다른 사람에게 의지하는 희망, 정말 그렇게 믿을 수 있을까요?”"
  },
  Event_50029_Name = {
    Text = "실타래종된 사주"
  },
  Event_50030_ChoiceDesc1 = {
    Text = "【구조 요청】무작위로 1명의 깨어남체를 깨어남시키고, “(Skill.Arg1)”에 감염시킵니다"
  },
  Event_50030_ChoiceDesc2 = {
    Text = "【공동 전진】3장의 명령 카드 중 1장을 선택하여 각인을 획득:“(EnchantConfig.Arg1)”"
  },
  Event_50030_Desc = {
    Text = "오래되고 멀리서 들리는 목소리가 졸졸 흐르는 물소리 속에서 당신에게 질문합니다. \n “당신은 끝없는 황사 속에 길을 잃었습니다.” \n “당신 앞에는 두 가지 선택이 있습니다. 당신의 동료는 발걸음이 더 빠르니 그가 음식과 물을 가지고 구조를 요청하러 가게 하고, 당신들은 최소한의 소모로 제자리에 남아 있습니다.” \n “아니면 당신들은 모든 것을 나누고 계속 나아갑니다.”"
  },
  Event_50030_Name = {
    Text = "실타래종된 사주"
  },
  Event_50031_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50031_Desc = {
    Text = "“너희들이 더 멀리 갈 수는 없을지라도, 너희의 영과 육체는 긴밀히 결합되어 서로를 격려하는 힘을 얻는다.”\n“이것이 바로 네가 한 선택이다.”\n말을 마치며, 높은 하늘에 있는 태양이 눈을 감았다."
  },
  Event_50031_Name = {
    Text = "실타래종된 사주"
  },
  Event_50064_ChoiceDesc1 = {
    Text = "[빨간 실타래크 끊기]1장의 명령 카드를 삭제하고, Arg1 개의 검은 인장을 획득합니다"
  },
  Event_50064_ChoiceDesc2 = {
    Text = "【대항】명령 카드 1장을 복제하고, “(Skill.Arg1)”에 감염됩니다"
  },
  Event_50064_ChoiceDesc3 = {
    Text = "【라모나 호출】3장의 명령 카드 중 1장을 선택하여 각인 획득:\"(EnchantConfig.Arg1)\""
  },
  Event_50064_Desc = {
    Text = "카시아가 빨간 실타래크를 휘두르자 순간적으로 당신의 가방을 감쌌다."
  },
  Event_50064_Name = {
    Text = "얽힌 실타래크"
  },
  Event_50065_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50065_Desc = {
    Text = "간헐적으로 맑고 경쾌한 두드림 소리가 당신들 머리 위에서 얽히고 설킨 파이프 사이를 회오리치며, 혼자서 춤추는 유령처럼 이 고요한 공간에서 힘없는 두 팔을 흔듭니다.\n 이러한 상상이 당신의 마음속에서 고대의 공포의 엄숙한 한기를 소환합니다."
  },
  Event_50065_Name = {
    Text = "이상한 음계"
  },
  Event_50066_ChoiceDesc1 = {
    Text = "[동굴 입구 탐색]백은 유물“(RelicConfig.Arg1)” 획득"
  },
  Event_50066_ChoiceDesc2 = {
    Text = "【깊은 암굴】황금 유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_50066_Desc = {
    Text = "“여기 동굴이 있습니다.” \n 타이스가 당신에게 초대를 합니다. \n “들어가서 볼까요?” \n 좁고 어두운 동굴은 마치 악마의 거대한 입처럼 끝없는 어둠으로 뻗어 있다. 이 황량한 곳에 발을 들여놓는 누구도 척수 깊은 곳에서 솟아오르는 불길한 예감에서 벗어날 수 없다. 마치 이 동굴의 모든 구석에 태양빛을 바라보지 못하는 고대 생물들이 숨어 있어 침입자의 도착을 기다리는 듯하다."
  },
  Event_50066_Name = {
    Text = "어두운 동굴"
  },
  Event_50067_ChoiceDesc1 = {
    Text = "【각각 격파】랜덤 1개의 백은 제작물이 황금 유물로 업그레이드됨“(RelicConfig.Arg1)”"
  },
  Event_50067_ChoiceDesc2 = {
    Text = "[두 사람을 포위]백은 유물“(RelicConfig.Arg1)”을 획득, “(Skill.Arg2)”에 감염"
  },
  Event_50067_ChoiceDesc3 = {
    Text = "[대화 도청]25 검은 인장 획득"
  },
  Event_50067_Desc = {
    Text = "두 명의 아란인이 공장 문을 지키고 있다. \n 그 중 한 명은 아무것도 하지 않고 배회하며 다른 한 명에게 말을 건넨다. \n “누군가는 유리에트 대인이 다시 스톰월드를 돌파하려는 팀을 점검하고 있다고 말하더군.” \n “나는 절대 선택받지 않기를 바래.”"
  },
  Event_50067_Name = {
    Text = "한가로운 문지기"
  },
  Event_50067_Tips1 = {
    Text = "아직 백은 유물이 없습니다"
  },
  Event_50068_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50068_Desc = {
    Text = "보지 않고, 듣지 않고, 생각하지 않는다. \n부적절한 음색이 어디서 왔는지 상상하지 않고, 당신은 모나무 유해가 있는 곳으로 직행한다."
  },
  Event_50068_Name = {
    Text = "이상한 음계"
  },
  Event_50069_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50069_Desc = {
    Text = "라모나가 붉은 비단을 휘두르는 카시아를 향해 검을 찔렀다. 카시아는 급히 피했고, 당신을 얽어매던 붉은 비단도 순식간에 풀렸다."
  },
  Event_50069_Name = {
    Text = "얽힌 실타래크"
  },
  Event_50070_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50070_Desc = {
    Text = "너희들이 두 길로 나뉘어, 너와 라모나는 왼쪽, 레이크는 오른쪽에서 양쪽에서 포위 공격을 한다. \n너는 손을 들어 신호를 보내고, 라모나와 레이크가 동시에 공격하여 두 명의 아란 수비수가 소리 없이 도지한다."
  },
  Event_50070_Name = {
    Text = "한가로운 문지기"
  },
  Event_50071_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50071_Desc = {
    Text = "이때 트랩으로 깊이 들어가는 것은 적절하지 않습니다. 여러분이 동굴 입구에서 맴돌기만 해도 암석의 맥박 속에 숨겨진 사악한 떨림을 거의 느낄 수 있습니다."
  },
  Event_50071_Name = {
    Text = "어두운 동굴"
  },
  Event_50072_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50072_Desc = {
    Text = "당신의 신호에 따라, 라이커가 조용히 있던 아란 경비원을 주사위로 가격해 기절시키고, 계속 떠들고 있는 다른 자에게 조용히 다가갔다.\n“야, 형님, 만약 그 무슨 유리에트 대인이 사기꾼이라면, 어떻게 할 거야?”\n“나도 어떻게 할지 모르겠어.”\n라이커가 기쁘게 이를 드러내자, 경비원이 몸을 움찔하며 비명을 지르려 했지만, 라이커가 그의 입과 코를 막았다."
  },
  Event_50072_Name = {
    Text = "한가로운 문지기"
  },
  Event_50073_ChoiceDesc1 = {
    Text = "[주의 깊게 경청]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\", \"(Skill.Arg2)\" 감염"
  },
  Event_50073_ChoiceDesc2 = {
    Text = "[손으로 귀를 막다]50 이상의 광기치를 가진 깨어남체마다 15개의 검은 인장을 획득"
  },
  Event_50073_ChoiceDesc3 = {
    Text = "【확인하기】3개 중 1개의 각인 선택"
  },
  Event_50073_Desc = {
    Text = "당신들이 유해가 있는 층에 들어갔을 때, 텅 빈 폐공장 안에서 갑자기 맑고 아름다운 딩동 소리가 들려왔다. 피아노의 맑고 차가운 울림은 녹슨 강철 폐허와 어울리지 않았다."
  },
  Event_50073_Name = {
    Text = "이상한 음계"
  },
  Event_50074_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50074_Desc = {
    Text = "“야, 형, 만약 그 유리에트님이 사기꾼이라면, 어떻게 해야 할까?”\n“헛소리 하지 마, 유리에트가 온 이후로 모든 것이 잘 정리되었어. 그녀가 사기꾼이라면 왜 아란인들을 그렇게 도와주겠어?”\n그들이 잡담하는 사이, 라이커는 조용히 매복할 위치를 정하고, 쾅쾅 두 개의 주사위를 던져 두 사람을 땅에 쓰러뜨렸다."
  },
  Event_50074_Name = {
    Text = "한가로운 문지기"
  },
  Event_50075_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50075_Desc = {
    Text = "당신은 용기를 내어 노려봅니다. \n무대 커튼의 거대한 눈이 갑자기 왜곡되며 악마적으로 웃습니다. 당신의 강한 저항이 동요하고 무너집니다."
  },
  Event_50075_Name = {
    Text = "마법의 눈"
  },
  Event_50076_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50076_Desc = {
    Text = "너는 분심 없이 리프트로 막을 찢는다. \n거대한 눈이 네 손아래에서 입체감 없는 부서진 천으로 변한다."
  },
  Event_50076_Name = {
    Text = "마법의 눈"
  },
  Event_50077_ChoiceDesc1 = {
    Text = "【회정】황금 유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_50077_ChoiceDesc2 = {
    Text = "【리프트 커튼】3장의 명령 카드 중 1장을 선택하여 각인을 획득: 「(EnchantConfig.Arg1)」"
  },
  Event_50077_Desc = {
    Text = "커튼이 수많은 왜곡된 거대한 눈을 드러냈다. \n눈 뒤에 숨은 거대한 존재가 이상한 갈망을 드러내며 움직이려고 한다."
  },
  Event_50077_Name = {
    Text = "마법의 눈"
  },
  Event_50078_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50078_Desc = {
    Text = "원래는 폐기된 긴 조각 부품이 당신들의 움직임에 진동으로 흔들리며 철제 파이프를 두드렸습니다."
  },
  Event_50078_Name = {
    Text = "이상한 음계"
  },
  Event_50079_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50079_Desc = {
    Text = "타이스는 태연하게 동굴 안으로 들어섰고, 당신은 뒤따라 조심스럽게 탐험하고 있었습니다. \n “조심해!” 당신은 갑자기 끌려 나와 부드러운 품에 주저앉았습니다. 당신들 앞에는, 한 마리의 새까만 거대한 짐승이 맹렬하게 동굴에서 뛰쳐나왔습니다. \n “여기 봐,” 당신이 아직도 혼란스러워하는 사이, 타이스가 입을 열었습니다. 그녀의 눈은 다크 속에서 미약한 형광을 발하고 있었고, “아마도 그것의 보물이 아닐까 해.”"
  },
  Event_50079_Name = {
    Text = "어두운 동굴"
  },
  Event_50080_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50080_Desc = {
    Text = "당신은 필사적으로 손잡이를 잡고 붉은 비단과 대항했습니다. \n하지만 그 붉은 비단은 힘이 너무 강해, 당신의 수화물 가방이 손에서 빠져나가 물건들이 바닥에 산재했습니다."
  },
  Event_50080_Name = {
    Text = "얽힌 실타래크"
  },
  Event_50081_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50081_Desc = {
    Text = "너는 속박되는 느낌을 싫어한다. \n 너는 빨간 비단을 붙잡고 찢어지는 소리와 함께 반으로 찢는다. \n 남은 반쪽의 빨간 비단은 빨간 뱀처럼 기어간다."
  },
  Event_50081_Name = {
    Text = "얽힌 실타래크"
  },
  Event_50276_ChoiceDesc1 = {
    Text = "【희생물 소멸】저주받은 유물「(RelicConfig.Arg1)」을 획득하고, 「(Skill.Arg2)」에 감염됩니다"
  },
  Event_50276_ChoiceDesc2 = {
    Text = "[밧줄을 풀다]3장의 커맨드 카드 중 1장을 선택해 각인 획득: \"(EnchantConfig.Arg1)\""
  },
  Event_50276_ChoiceDesc3 = {
    Text = "[계속 전진]50 검은 인장 획득"
  },
  Event_50276_Desc = {
    Text = "세 명의 아란인이 고대 위에 묶여 있었다.\n그들의 몸에는 당신이 영아의 몸에 보았던 나무 껍질 같은 어두운 무늬가 떠오르고 있었으며, 입으로 중얼중얼 말을 하고 있었다."
  },
  Event_50276_Name = {
    Text = "세 개의 제물"
  },
  Event_50277_ChoiceDesc1 = {
    Text = "[응시]백은 유물 “(RelicConfig.Arg1)”을 획득하고, “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_50277_ChoiceDesc2 = {
    Text = "【무시】3개 중 1개의 각인을 획득"
  },
  Event_50277_Desc = {
    Text = "아란인이 사막 폭풍 속에서 구복했다. \n폭풍이 그들의 외피를 차고, 모래가 그들의 경건한 마음을 휩쓸었다. \n모래 먼지의 소용돌이 속에는 수많은 거대한 눈이 왜곡된 대지를 내려다보는 것 같았다."
  },
  Event_50277_Name = {
    Text = "모래먼지 거인"
  },
  Event_50278_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50278_Desc = {
    Text = "당신이 회상하고 싶지 않은 화면이 다시 눈앞에 떠오릅니다. \n흔들거리는 촉수, 유리 파편에 베인 피가 흐르는 상처…… \n당신은 구토를 합니다."
  },
  Event_50278_Name = {
    Text = "고독한 여행Ⅱ"
  },
  Event_50279_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50279_Desc = {
    Text = "그녀는 여기에 있지 않고, 가장 위험한 열기 속에도 있지 않아. \n그렇게 당신이 안심할 수 있을 거야."
  },
  Event_50279_Name = {
    Text = "고독한 여행Ⅰ"
  },
  Event_50280_ChoiceDesc1 = {
    Text = "[기습]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\""
  },
  Event_50280_ChoiceDesc2 = {
    Text = "【공격】랜덤 3장의 명령 카드 획득 각인: “(EnchantConfig.Arg1)”, 감염 “(Skill.Arg2)”"
  },
  Event_50280_Desc = {
    Text = "한 마리의 누비아가 격렬한 사막 폭풍 속에서 투쟁 중이다. \n그것의 네 발굽이 깊이 황사에 박혀 있으며, 소용돌이에 빨려 들어가는 것을 피하기 위해 절 vọng적으로 노력하고 있다."
  },
  Event_50280_Name = {
    Text = "자연 사막 폭풍"
  },
  Event_50281_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50281_Desc = {
    Text = "당신은 과감하게 뛰어들어, 아란인들의 경악의 소리 속에서 밧줄을 끊었습니다. \n한 명의 아란 전사가 시도하며 다가오자, 당신은 그의 손에서 창을 낚아채 인파를 향해 겨누었습니다."
  },
  Event_50281_Name = {
    Text = "세 개의 제물"
  },
  Event_50282_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50282_Desc = {
    Text = "이성이 당신에게 그가 오지 않을 거라고 말합니다. \n그래, 누가 도박사를 믿고 그가 약속을 지킬 거라 기대하겠습니까? \n당신은 외로울 수밖에 없습니다. 당신에게는 고독만이 남아 있습니다."
  },
  Event_50282_Name = {
    Text = "고독한 여행 Ⅲ"
  },
  Event_50283_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50283_Desc = {
    Text = "그 이상한 고열은 모나무의 부활로 인해 더욱 심해질까요? \n라모나가 스톰월드 밖에서 혼자서 잘 돌볼 수 있을까요? \n지금은 산만해질 때가 아니지만, 파트너가 걱정된다."
  },
  Event_50283_Name = {
    Text = "고독한 여행Ⅰ"
  },
  Event_50284_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50284_Desc = {
    Text = "당신은 정면으로 맞서기로 결의하였고, 누비아는 오히려 드문 발판을 찾은 듯 당신의 머리에 뛰어올랐습니다.\n당신은 모래 폭풍과 누비아의 이중 얽힘 속에 빠져버렸습니다.\n“무작정 용감함이 승리의 방법은 아니다,” 윌리엄의 차가운 목소리가 귀를 막고 있는 당신에게는 천사의 복음처럼 들렸습니다, “기회를 잡는 법을 배워라.”"
  },
  Event_50284_Name = {
    Text = "자연 사막 폭풍"
  },
  Event_50285_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50285_Desc = {
    Text = "지금은 여유롭게 신문을 읽을 때가 아니다."
  },
  Event_50285_Name = {
    Text = "그녀의 당부"
  },
  Event_50286_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50286_Desc = {
    Text = "당신은 생각하지 않고, 기억하지 않습니다.\n당신은 생각하고 싶지 않고, 기억하고 싶지 않습니다.\n미사그의 전설은 막을 내리겠지만, 미사그의 여정은 중단되지 않을 것입니다.\n당신은 계속 나아가야 합니다. 당신은 계속 나아가야 합니다."
  },
  Event_50286_Name = {
    Text = "고독한 여행Ⅱ"
  },
  Event_50287_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50287_Desc = {
    Text = "“사랑하는 수호자: \n 편지 잘 받았습니다. \n 이번 레무바시 여행에서 자신의 몸을 잘 돌보지 못해 당신 곁에 계속 있을 수 없었던 점 사과드립니다. \n 하지만 중요한 순간에는 당신의 유일한 조수를 믿어 주세요. \n 당신이 필요할 때, 저는 항상 여기 있습니다.” \n 시간 관계로 더 이상 읽을 수 없습니다. \n 그러나 익숙한 글씨체가 당신에게 마음을 평화롭게 하는 안정감을 줍니다."
  },
  Event_50287_Name = {
    Text = "그녀의 당부"
  },
  Event_50288_ChoiceDesc1 = {
    Text = "[그는 다시 올 것입니다]백은 유물“(RelicConfig.Arg1)”을 획득했습니다"
  },
  Event_50288_ChoiceDesc2 = {
    Text = "【그는 오지 않을 것이다】황금 유물 “(RelicConfig.Arg1)” 획득, “(Skill.Arg2)” 감염"
  },
  Event_50288_Desc = {
    Text = "마지막으로 떠난 사람은 라이커다.\n카시아를 막기 위해 그는 영막에 남기로 선택했다.\n그는 예전에 당신에게 마지막에 의식 현장에 들어가 모나무를 소각하겠다고 약속했으며, 그 또한 절대 함께할 것이라고 말했다.\n하지만 그는 지금도 당신 곁에 오지 않았다.\n오직 당신만 혼자 남았다."
  },
  Event_50288_Name = {
    Text = "고독한 여행 Ⅲ"
  },
  Event_50289_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50289_Desc = {
    Text = "구르구르, 세 개의 둥근 공포의 물건이 의식 현장에서 굴러다닌다. \n자신이 자신 같지 않다고 느껴진다. 병적인 열광의 의식 분위기가 당신을 이해할 수 없는 공허 속으로 끌어들인다."
  },
  Event_50289_Name = {
    Text = "세 개의 제물"
  },
  Event_50290_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50290_Desc = {
    Text = "아란의 신앙은 그렇게 성실타래하여 사막의 모래에 매몰되는 것을 자원합니다. \n그런데 당신이 고개를 들어 올려다보면, 폭풍 속에는 태양이 없습니다."
  },
  Event_50290_Name = {
    Text = "모래먼지 거인"
  },
  Event_50291_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50291_Desc = {
    Text = "모래바다가 그들의 성실타래에 응답하라."
  },
  Event_50291_Name = {
    Text = "모래먼지 거인"
  },
  Event_50292_ChoiceDesc1 = {
    Text = "【회상에서 벗어나기】무작위로 1장의 카드 각인 품질을 향상"
  },
  Event_50292_ChoiceDesc2 = {
    Text = "[추억을 포착하다]3장의 커맨드 카드 중 1장을 선택해 각인 획득: \"(EnchantConfig.Arg1)\", 감염 \"(Skill.Arg2)\""
  },
  Event_50292_Desc = {
    Text = "두 번째로 떠난 사람은 윌리엄입니다."
  },
  Event_50292_Name = {
    Text = "고독한 여행Ⅱ"
  },
  Event_50293_ChoiceDesc1 = {
    Text = "[안심]검은 인장 25개 획득"
  },
  Event_50293_ChoiceDesc2 = {
    Text = "[우려]백은 유물 ‘(RelicConfig.Arg1)’을 획득하고, ‘(Skill.Arg2)’에 감염되었습니다"
  },
  Event_50293_Desc = {
    Text = "당신은 갑자기 여행을 시작한 날을 회상합니다. \n 라모나가 당신에게 짐을 챙기라고 상기시키고, 윌리엄이 당신을 위해 여정의 기록을 담은 매뉴얼을 준비했습니다. 라이커는 몰래 당신의 가방에 위스키 한 병을 넣었습니다. \n 이제 그들은 모두 떠났습니다. \n\n 첫 번째로 떠난 사람은 라모나며, 타비의 힘과 폭풍의 벽의 권능이 서로 배척되어 그녀는 여정 중에 고열로 무너졌습니다."
  },
  Event_50293_Name = {
    Text = "고독한 여행Ⅰ"
  },
  Event_50294_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50294_Desc = {
    Text = "당신이 누비아의 다리를 기습하여, 그것이 서지 못하고 몇 개의 덩굴 모양의 촉수가 공중에서 급하게 그리고 어지럽게 움직이다 결국 먼지 폭풍 속으로 휘말려 들어갔습니다."
  },
  Event_50294_Name = {
    Text = "자연 사막 폭풍"
  },
  Event_50295_ChoiceDesc1 = {
    Text = "【읽기】1장의 카드 삭제"
  },
  Event_50295_ChoiceDesc2 = {
    Text = "【접기】“(RelicConfig.Arg1)”을 획득하고 “(Skill.Arg2)”에 감염되었습니다"
  },
  Event_50295_Desc = {
    Text = "딸깍딸깍.\n이 인간 세상과는 다른 열광의 제단 아래에서, 무거운 북소리가 모래바람을 따라 굴러옵니다. 끊임없이 들리는 성가 소리 속에서, 당신은 타자기의 미세한 소리를 들었습니다—— 그것은 미사그의 호출로, 당신의 불안한 마음을 위로합니다."
  },
  Event_50295_Name = {
    Text = "그녀의 당부"
  },
  Event_50296_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50296_Desc = {
    Text = "레이크는 세속을 뛰어넘는 행운을 가지고 있습니다. \n그가 당신에게 약속한 일은 반드시 지킬 것입니다. \n반드시."
  },
  Event_50296_Name = {
    Text = "고독한 여행 Ⅲ"
  },
  Event_50297_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_50297_Desc = {
    Text = "당신과 상관없어요. \n지금 당신이 가장 필요한 것은 가능한 한 빨리 모나무 유해를 접촉하고 파괴하는 것입니다."
  },
  Event_50297_Name = {
    Text = "세 개의 제물"
  },
  Event_52373_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_52373_Desc = {
    Text = "당신은 살아남았습니다. 당신은 무수히 많은 흙더미와 불에 탄 육체들을 보았습니다. \n당신은 무엇인가를 태운 것 같지만, 그것은 이미 중요하지 않습니다. \n당신은 신국의 종소리를 들었습니다."
  },
  Event_52373_Name = {
    Text = "역병의 침략"
  },
  Event_52374_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_52374_Desc = {
    Text = "당신은 살아남았습니다. 당신은 무수히 많은 흙더미와 불에 탄 육체들을 보았습니다.\n당신은 소중히 여기는 것들을 보호하기 위해 힘을 다했으며, 그로 인해 끔찍한 대가를 치렀습니다. 그러나 그것은 이미 중요하지 않습니다.\n당신은 신국의 종소리를 들었습니다."
  },
  Event_52374_Name = {
    Text = "역병의 침략"
  },
  Event_52375_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_52375_Desc = {
    Text = "거인의 분노는 잠시 가라앉았다. 구름이 사라지고 비가 그치며, 바람은 잠잠해졌다. 바다는 영원한 어머니처럼 부드러운 파도로 리모리아의 등을 살며시 어루만졌다. 리모리아는 온몸에 쌓인 시체와 폐허만을 남긴 채로.\n당신은 소중히 여기는 것들을 지키기 위해 필사적으로 싸웠고, 그 결과 끔찍한 대가를 치렀다. 하지만 이제 그것은 중요하지 않다.\n바다 속에서, 당신은 신국의 윤곽을 엿보았다."
  },
  Event_52375_Name = {
    Text = "해양의 포효"
  },
  Event_52376_ChoiceDesc1 = {
    Text = "【추가 제물 바치기】1장의 명령 카드를 삭제하고, 3종류의 “신국환영” 각 1장을 데크에 추가합니다."
  },
  Event_52376_Desc = {
    Text = "리모리아의 무너진 왕좌 앞에 서서, 당신은 마지막 희생물을 바칩니다. \n 끝없는 심연이 당신 앞에 드러납니다. 당신은 무릎을 꿇고, 미소를 지으며, 눈물이 흐릅니다. \n \"봐요, 아버지, 데보라. 봐요, 나의 최고의 왕——신국이 나의 앞에 강림했습니다!\""
  },
  Event_52376_Name = {
    Text = "환영해라, 신의 나라"
  },
  Event_52377_ChoiceDesc2 = {
    Text = "【보호해야 할 소중한 물건】Arg1 생명을 잃고, 1장의 무작위 증상 카드를 획득합니다."
  },
  Event_52377_Desc = {
    Text = "대지. 침묵하는 대지, 평온한 대지. 인류를 지탱하는 대지, 영원히 불멸한 대지. 그러나 대지는 떨고 있다. 그것은 깊이를 알 수 없는 틈을 갈라내고, 지탱하고 있는 모든 것이 위태롭다. \n 당신은 모든 희망을 대지에 맡기고, 대지가 떨기 시작할 때, 당신은 어디로 가겠는가? \n 헌신의 제사를 드리라, 리모리아의 국민들이 당신을 호출한다. 당신의 모든 것을 헌신하여 무재의 신국이 강림하게 하라."
  },
  Event_52377_Name = {
    Text = "대지의 전율"
  },
  Event_52378_ChoiceDesc2 = {
    Text = "【보호해야 할 소중한 물건】Arg1 생명을 잃고, 1장의 무작위 증상 카드를 획득합니다."
  },
  Event_52378_Desc = {
    Text = "바다. 바다는 리모리아를 잉태한 어머니이며, 당신의 삶, 당신의 믿음입니다. 그리고 지금, 바다는 전설 속의 분노한 거신처럼 일어섭니다. 그가 소리치고, 호출하며, 부드러운 바닷물을 단단한 거암과 가시로 변형시켜 앞에 있는 모든 것에 내리칩니다. 그는 무관심하게 발치에서 떨고 있는 리모리아를 내려다보며, 곤충처럼 놀라 도망치는 리모리아인들을 바라봅니다. 그는 리모리아를 파멸시킬 것입니다. 이는 리모리아와는 관련이 없습니다. \n 헌신의 제사를 드리세요, 리모리아의 백성들이 당신을 호출합니다. 당신의 모든 것을 헌신하여 무재의 신국이 강림하게 하십시오."
  },
  Event_52378_Name = {
    Text = "해양의 포효"
  },
  Event_52379_ChoiceDesc2 = {
    Text = "【보호해야 할 소중한 물건】Arg1 생명을 잃고, 1장의 무작위 증상 카드를 획득합니다."
  },
  Event_52379_Desc = {
    Text = "역병. 역병은 어디에나 있다. 역병은 가장 뻔뻔한 하인으로, 대지와 바다의 신의 징벌이 지나간 후, 신이 입에 담을 수 없는 죽음을 선고한다. 친척의 시신을 묻고, 친척의 시신을 태우고, 자신을 보호하기 위해 죽은 가까운 이들을 위해 기도하라, 그들이 나와 멀어질수록 좋다. 생명과 인성은 역병 앞에서 무너진다. \n 헌신의 제사여, 리모리아의 백성들이 너를 호출한다. 너의 모든 것을 헌신하라, 재난이 없는 신국이 강림하게 하라."
  },
  Event_52379_Name = {
    Text = "역병의 침략"
  },
  Event_52380_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_52380_Desc = {
    Text = "강한 진동이 가라앉았습니다. 거리는 진홍색의 피 자국으로 물들어 있었고, 무너진 집 아래에는 수많은 사람들이 묻혀 있었습니다. \n 당신은 소중히 여기는 것들을 보호하기 위해 힘을 다했으며, 그로 인해 끔찍한 대가를 치렀습니다. 그러나 그것은 이미 중요하지 않습니다. \n 유일하게 중요한 것은, 당신이 신국에 한 걸음 더 가까워졌다는 것입니다."
  },
  Event_52380_Name = {
    Text = "대지의 전율"
  },
  Event_52381_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_52381_Desc = {
    Text = "리모리아의 무너진 왕좌 앞에 서서, 당신은 마지막 기도문을 읊습니다. \n 끝없는 심연이 당신 앞에 드러납니다. 당신은 무릎을 꿇고, 미소를 지으며, 눈물이 흐릅니다. \n \"봐요, 아버지, 데보라. 봐요, 나의 최고의 왕——신국이 나의 앞에 강림했습니다!\""
  },
  Event_52381_Name = {
    Text = "환영해라, 신의 나라"
  },
  Event_52382_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_52382_Desc = {
    Text = "강한 진동이 가라앉았습니다. 거리는 진홍색의 피 자국으로 물들어 있었고, 무너진 집 아래에는 수많은 사람들이 묻혀 있었습니다. \n 당신의 어떤 것도 폐허 아래에 묻힌 것 같지만, 그것은 이미 중요하지 않습니다. \n 유일하게 중요한 것은, 당신이 신국에 한 걸음 더 가까워졌다는 것입니다."
  },
  Event_52382_Name = {
    Text = "대지의 전율"
  },
  Event_52383_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_52383_Desc = {
    Text = "거인의 분노는 잠시 사라졌다. 구름이 걷히고 비가 그치며 바람이 잔잔해졌다. 바다는 마치 영원한 어머니처럼 부드러운 조수로 리모리아의 등을 가만히 어루만졌다. 오직 리모리아의 몸에는 온통 난잡한 시체와 폐허만이 남아 있었다. \n당신의 어떤 것이 대해에 묻힌 것처럼 보이지만, 그것은 더 이상 중요하지 않다. \n바다 속에서 당신은 신국의 윤곽을 엿보았다."
  },
  Event_52383_Name = {
    Text = "해양의 포효"
  },
  Event_52384_ChoiceDesc1 = {
    Text = "【성심으로 기도】덱의 모든 보통 증상 카드를 각각 1장씩 “신국 환영”으로 변환하고 2장의 “신국 환영”을 추가로 획득합니다."
  },
  Event_52384_ChoiceDesc2 = {
    Text = "【성심으로 기도】덱의 모든 보통 증상 카드를 각각 1장씩 “신국 환영”으로 변환하고 2장의 “신국 환영”을 추가로 획득합니다."
  },
  Event_52384_Desc = {
    Text = "대지는 더 이상 떨리지 않고, 바다는 더 이상 요동치지 않으며, 전염병은 더 이상 습격하지 않습니다. 천재가 리모리아를 파멸시켰고, 당신만 남겼습니다. 당신은 고개를 들어 주위를 둘러보며, 처참한 광경을 목격합니다. 당신은 고개를 숙여 두 손을 바라보았으나, 텅 비어 있습니다. \n 그러나 그게 무슨 상관일까요, 존경하는 주제님? 리모리아의 잔해와 시체를 밟으며, 계속 앞으로 기어가세요. \n 당신은 신국에 한 걸음 차이입니다."
  },
  Event_52384_Name = {
    Text = "환영해라, 신의 나라"
  },
  Event_53140_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_53140_Desc = {
    Text = "당신은 학교로부터 온 연락을 받았습니다. 익숙한 목소리가 당신의 마음을 안정시킵니다. 당신은 다시 집중하여 계속 앞으로 나아갑니다."
  },
  Event_53140_Name = {
    Text = "연락 지점"
  },
  Event_53141_ChoiceDesc1 = {
    Text = "[연결] HP를 Arg2 회복"
  },
  Event_53141_ChoiceDesc2 = {
    Text = "【명상】깨어남체 1명을 깨어남시킵니다."
  },
  Event_53141_ChoiceDesc3 = {
    Text = "【추방】최대 3장의 증상 카드를 제거하고, 검은 인장 Arg2개를 획득합니다."
  },
  Event_53141_ChoiceDesc4 = {
    Text = "【광기에 빠짐】무작위로 2명의 깨어남체를 깨어남시키고, 1개의 무작위 증상을 획득합니다"
  },
  Event_53141_ChoiceDesc5 = {
    Text = "【주저】기타"
  },
  Event_53141_Desc = {
    Text = "안개 속을 탐색하던 중, 갑자기 가슴에 단 배지가 희미한 은빛을 발했다. 통신기 너머에서 누군가 당신을 부르고 있는 걸까?"
  },
