  },
  Event_53148_Desc = {
    Text = "당신이 통신을 연결했습니다. 통신기에서 들리는 것은 황홀하게 만드는 광기 어린 소리였습니다. \n\"기억하라. 이는 신국이 너에게 주는 은혜이다.\""
  },
  Event_53148_Name = {
    Text = "연락 지점"
  },
  Event_55782_ChoiceDesc1 = {
    Text = "【가시 잘라내기】다음 전투에서 적의 HP가 30%, 피해량이 15% 증가, 이미지 「(Skill.Arg2)」 Arg1장 획득."
  },
  Event_55782_ChoiceDesc2 = {
    Text = "【가시 잘라내기】다음 전투에서 적의 HP가 30%, 피해량이 15% 증가, 이미지 「(Skill.Arg2)」 Arg1장 획득."
  },
  Event_55782_ChoiceDesc3 = {
    Text = "【가시 밀어내기】(Skill.Arg3) 감염, 이미지 「(Skill.Arg2)」 Arg1장을 덱에 추가."
  },
  Event_55782_ChoiceDesc4 = {
    Text = "【가시 밀어내기】(Skill.Arg3) 감염, 이미지 「(Skill.Arg2)」 Arg1장을 덱에 추가."
  },
  Event_55782_ChoiceDesc5 = {
    Text = "【가시에서 떨어지기】 「오를라의 펜과 잉크」가 「펜과 잉크」 Arg1스택 획득"
  },
  Event_55782_Desc = {
    Text = "어떤 것이 당신의 마음을 울렸습니다. 당신은 발걸음을 멈추고 정원의 모퉁이를 바라봅니다. 여러 겹의 가시덤불 아래에서, 하나의 빛의 점이 뛰어오르며 몸에 감긴 속박을 풀어내려 하고 있습니다.\n그것은 무엇일까요? 나비? 새? 당신은 그것에 가까이 다가갑니다."
  },
  Event_55782_Name = {
    Text = "뮤즈의 은총"
  },
  Event_55782_Tips1 = {
    Text = "다음 전투의 적은 강화되었으며, 다시 선택할 수 없습니다"
  },
  Event_55783_ChoiceDesc1 = {
    Text = "【헌시 바치기】「이미지」 카드 3장을 선택하여, 오를라가 당신을 위한 「헌시」를 창작."
  },
  Event_55783_ChoiceDesc2 = {
    Text = "[떠나기]"
  },
  Event_55783_Desc = {
    Text = "당신은 아름다운 꽃방 앞에 도착했습니다. 창문을 통해 꽃방 안을 들여다보지만, 아무것도 보이지 않습니다. \n 바람이 불어와, 꽃방 안의 꽃잎과 떨어진 잎들이 바람에 휘날리며 공중에서 춤추고 모여듭니다. 꽃과 잎 사이에서, 당신은 한 소녀의 모습을 보았습니다. \n \"아! 꽃, 꽃밭에 손님이 왔어요!\" 소녀가 놀라움과 긴장감으로 당신을 바라보며 말했습니다. \"죄송해요, 코레트는 외출했어요… 꽃을 사려면, 이 꽃들의 가격은 잘 모르겠어요…\" \n 소녀는 갑자기 멈추고 가까이 다가와 당신을 두 번 살펴보았습니다. \"아, 이 손님, 당신에게서 시의 이미지를 느꼈어요… 어쩌면, 우리 함께 시를 창작할 수 있을까요?\""
  },
  Event_55783_Name = {
    Text = "봄의 선물"
  },
  Event_55783_Tips1 = {
    Text = "「이미지」의 수량이 3장 미만이어서 합성할 수 없습니다"
  },
  Event_55799_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_55799_Desc = {
    Text = "살아난 가시가 약간 불안해 보이지만, 이러한 대가는 무시할 만하다—그 빛점에서 당신은 뮤즈의 호출을 들었다."
  },
  Event_55799_Name = {
    Text = "뮤즈의 은총"
  },
  Event_55819_ChoiceDesc1 = {
    Text = "【순응한 육체의 기억】전투를 건너뛰고 즉시 승리하지만, Arg1 포인트의 생명력을 잃습니다."
  },
  Event_55819_ChoiceDesc2 = {
    Text = "【떠나다】 전투에 진입"
  },
  Event_55819_Desc = {
    Text = "익숙한 적을 마주하면, 다음 전투는 이미 손에 익은 상태입니다."
  },
  Event_55819_Name = {
    Text = "전투 생략"
  },
  Event_55997_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_55997_Desc = {
    Text = "수집한 이미지 중 몇 개를 선택하여 소녀의 손에 건넸습니다.\n\"정말 아름다운 이미지예요! 이 손님, 잠시만 기다려 주세요…… 드릴게요. 이것은 봄이 가져온, 오직 당신을 위한 헌시입니다!\"\n한 편의 시가 당신의 손에 나타났고, 마치 당신을 위해 피어난 꽃처럼 보였습니다.\n당신은 소녀에게 감사하고 싶었습니다. 그러나 고개를 들었을 때, 소녀의 모습은 이미 사라졌습니다. 외로운 꽃방에는 시든 꽃과 잎사귀만 가득 남아 있었습니다.\n—— 그것은 봄이 다 타고 난 후 남겨진 재입니다."
  },
  Event_55997_Name = {
    Text = "봄의 선물"
  },
  Event_55999_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_55999_Desc = {
    Text = "무거운 가시밭길은 당신을 주저하게 만들었다. 당신은 빛의 점을 떠났지만, 잠시 동안의 응시는 여전히 당신의 마음에 새로운 영감을 불러일으켰다—— 그 빛의 점에서, 당신은 창조의 소리를 들었다."
  },
  Event_55999_Name = {
    Text = "뮤즈의 은총"
  },
  Event_56000_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_56000_Desc = {
    Text = "당신은 손으로 가시를 밀쳐냈습니다. 이로 인해 당신은 약간의 상처를 입었지만, 이러한 대가는 무시할 수 있습니다—그 빛점에서 당신은 뮤즈의 호출을 들었습니다."
  },
  Event_56000_Name = {
    Text = "뮤즈의 은총"
  },
  Event_56024_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_56024_Desc = {
    Text = "아직 부족해…… 계속 그 빛점에 가까워져. 가시덤불이 격앙되어 당신에게 날카로운 가시를 드러냈습니다. 하지만 모든 것이 가치가 있습니다. \n 그 빛점이 손바닥에서 퍼져나가며 하늘 가득한 빛의 막 속에서 당신은 뮤즈의 축복을 분명히 느꼈습니다."
