  Event_91507_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_91507_Desc = {
    Text = "너는 눈을 감고 끝없고 부드러운 먼지 안으로 발을 들여놓는다. 성운이 너를 감싸고, 너는 형태를 잃고, 몸보다 더 확고한 존재가 너의 몸속에 가라앉는다.\n그 밤, 별들은 계속 회전하고, 예전처럼 밝게 빛난다.\n장생자에게 별빛은 무엇을 의미할까? 어쩌면 두레인에게 물어보는 것이 좋겠다."
