    Text = "【점화하다】감염「(Skill.Arg1)」, 은색 유물「(RelicConfig.Arg2)」을 얻다"
  },
  Event_91509_ChoiceDesc2 = {
    Text = "【기다리다】감염「(Skill.Arg1)」, 은색 유물「(RelicConfig.Arg2)」을 얻다"
  },
  Event_91509_ChoiceDesc3 = {
    Text = "[보존하기]25검은 인장을 획득합니다"
  },
  Event_91509_Desc = {
    Text = "당신은 피크만의 그림을 응시하고, 구역질 나는 썩은 내음이 당신을 혼미하게 만듭니다.\n생각이 천천히 올라오고, 처음에는 열기, 나중에는 안개, 그리고 그 후에는——"
  },
  Event_91509_Name = {
