  },
  Event_91510_Desc = {
    Text = "당신은 아무도 저어하지 않는 회색 홀로 들어갑니다. 그곳에는 검은 안개 속에서 희미하게 보이는 저울이 있습니다. \n 왼쪽에는 호수처럼 고요한 뇌가 있으며, 은백색의 골짜기가 희미하게 빛나고 있습니다; 오른쪽에는 불타는 듯한 붉은 심장이 열기를 뿜어내고 있습니다. \n 갑자기 당신은 향기를 맡습니다. 갈망하는 욕망이 계속해서 팽창하고, 이성은 그 무한한 어둠에 압도당합니다. \n 당신은 손을 내밀었습니다."
  },
  Event_91510_Name = {
    Text = "헝거 게임"
