  Event_91511_ChoiceDesc1 = {
    Text = "[떠나기]"
  },
  Event_91511_Desc = {
    Text = "이것은 분명 꿈일 것입니다. 당신은 반복해서 자신을 설득합니다. \n 무의식중에, 당신은 정말로 꿈나라에 빠져버렸습니다. \n 아마 최근에 너무 많은 소통을 했기 때문에, 당신은 두레인—자신의 혈육을 먹게 하려는 두레인을 꿈꾸었습니다? 무슨 공포 이야기인가요?"
  },
  Event_91511_Name = {
    Text = "거의 정상"
  },
  Event_91660_ChoiceDesc1 = {
    Text = "[다른 길 찾기]3장의 커맨드 카드 중 1장을 선택하여 각인 획득: \"(EnchantConfig.Arg1)\""
  },
  Event_91660_ChoiceDesc2 = {
    Text = "【그냥 두세요】무작위로 3장의 명령 카드에서 각인을 획득하세요:「(EnchantConfig.Arg1)」, 감염「(Skill.Arg2)」"
  },
  Event_91660_Desc = {
    Text = "“영혼을 이끌려면, 당신은 죽은 자를 끝까지 인도해야 합니다.”\n두레인이의 말과 함께, 당신은 계시를 느낍니다. \n그것은 지식도, 기억도 아닙니다—그것은 마치 당신의 눈구멍으로 들어와, 홍수처럼 당신의 뇌에 쏟아져 들어오는 무게와 같습니다. \n당신의 감정은 더 이상 현재와 여기에 속하지 않는 것처럼 보이며, 그것은 물러나 우주가 소홀히 한 틈을 드러냅니다. \n당신이 인식할 수 있는 모든 것은 그곳에서 멈추고, 마치 길의 끝에 도달한 것처럼 느껴집니다."
